window.CONFERENCE_SESSIONS=[{"id":1068,"title":"WeAreDevelopers - Warm-Up Day","description":"Wednesday is your Warm-Up Day before the official Congress opening on Thursday. Get hands-on in workshops and masterclasses, join fireside chats on the outdoor stage, catch the dedicated stage program from Docker and GitHub, drop into community meetups, watch live recordings of the WeAreDevelopers podcast, and meet fellow developers in a relaxed setting before the crowds arrive.\n\nPick up your badge on Wednesday and walk straight in when Main Stage and expo open Thursday.\nRegistration for workshops will be available in the official event app soon (seats are limited).","starts_at":"2026-09-23T09:50:00-07:00","ends_at":"2026-09-23T18:00:00-07:00","stage":"Location TBA","track":"Experience & Activities","type":"Experience & Activities","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":[],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1068","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1910-wearedevelopers-warm","urls":[],"flag":null},{"id":1069,"title":"Making “Works on All Machines” Work for Agent Environments","description":"Agentic development environments need a lot of things - the project, agent harnesses, vector stores, compile tools, and more. And on top of that, it needs to be a trusted and safe environment in case an agent goes off-script. But, how?\n\nThis talk will dive deep on how to create and customize the sandbox environments for your agent, from the simple to the very complex. You'll also learn how to version control and share the environment through your codebase, ensuring everyone on your team has consistency in both environments and trust. The best part? It's not as hard as you think!","starts_at":"2026-09-23T10:00:00-07:00","ends_at":"2026-09-23T10:30:00-07:00","stage":"Stage 1","track":"AI Engineering","type":"AI Engineering","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Michael Irwin - Principal Engineer, Developer Success at Docker"],"tags":["Agents","Agentic AI","Containers","Developer Experience (DevEx)","Docker","Tooling"],"live_url":"https://www.youtube.com/watch?v=yOgETPFY8xs","recording_url":"https://www.youtube.com/watch?v=yOgETPFY8xs","app_url":"https://app.wearedevelopers.com/events/18/session/1069","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1917-making-works-on-all","urls":["https://www.youtube.com/watch?v=yOgETPFY8xs"],"flag":null},{"id":1409,"title":"WeAreDevelopers Live","description":"","starts_at":"2026-09-23T10:30:00-07:00","ends_at":"2026-09-23T11:00:00-07:00","stage":"Outdoor Stage","track":"Career, Culture & Community","type":"Career, Culture & Community","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Christian Heilmann - VP Developer Relations at WeAreDevelopers"],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1409","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1936-wearedevelopers-live","urls":[],"flag":null},{"id":1073,"title":"SBX 101: Hands-on with Docker Sandboxes","description":"Modern AI agents are useful because they take real actions in the real world and on your machine: read files, run commands, hit the web, build containers, write and publish code. That capability is also where the risk lives. This hands-on workshop walks through the Docker AI primitives (sandboxes, network policy, MCP, hardened images, sbx kits, and multi-agent orchestration with Docker Agent) that make it practical to give an agent real capability without giving it unbounded reach. You'll spin up your first Docker Sandbox, prove its isolation guarantees with hands-on tests, govern its outbound network, attach real tools via MCP, harden the containers it ships, package the whole setup as a reusable kit, and finally compose a small multi-agent team where per-role tool scoping is enforced at the runtime. You'll leave with a working mental model of scoped autonomy and a running sandbox stack on your machine that you can keep experimenting with.","starts_at":"2026-09-23T10:45:00-07:00","ends_at":"2026-09-23T12:45:00-07:00","stage":"Stage 8","track":"Applied AI","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"Setup required\r\n- A laptop running MacOS on Apple Silicon or Windows 11 x86_64","speakers":["Dan Ndombe - Staff Developer Success Advocate at Docker"],"tags":["Agents","Agentic AI","Docker","Governance"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1073","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1818-sbx-101-hands-on","urls":[],"flag":null},{"id":1074,"title":"Local AI Workshop for Beginners: Private ChatGPT Experience on Your Own Computer","description":"Ever feel uncomfortable about sharing too much personal info with ChatGPT/Gemini/Claude but still want AI’s help? Against giving Big Tech your private life on a golden platter running on wasteful resource-sucking data centers? A bit confused about some of the jargon and words used in news articles about the next most powerful AI models coming out? This workshop is for you!\n\n​Earlier this year there was a breakthrough - we can now run AI that are more than capable of being private and even completely offline assistants on personal computers and laptops!\n\n​This is also a workshop for AI beginners who find setting up agents with OpenClaw too intimidating but still want a capable AI experience like ChatGPT that keeps all private information on their own computers - without writing any code or running any terminal/command line commands!\n\n​What we'll cover:\n​Setting up Unsloth Desktop (open source ChatGPT-like interface) and running powerful open source AI models of your choosing on your own computer.\n\n​Learning important concepts about running AI on your own computer - from why open source AI exists to tokens, context, model quantization, MCP tool servers, and more.\n\n​Answering your questions to make sure you're confident discussing AI model concepts and the major news developments that are shaking the world.\n\n​System Requirements: The more RAM your computer has, the better. It’s now possible to run near-frontier-capable-AI on computers with just 16GB of RAM. That said, even if your computer has less than that (like 8GB), you can run less powerful AI that is still impressive and are welcome to attend!\n\n​To be efficient, we encourage participants to download and install Unsloth Desktop (https://unsloth.ai/docs/desktop) as well as let it automatically download a suitable AI model it selects for you (if any) when first running the app in advance before coming to the event. During the event, you’ll learn how to find even better AI models to add to your Unsloth Desktop setup.","starts_at":"2026-09-23T10:45:00-07:00","ends_at":"2026-09-23T12:45:00-07:00","stage":"Stage 9","track":"AI Engineering","type":"Workshop","live_coding":false,"is_workshop":true,"capacity":36,"waitlist":5,"requirements":"","speakers":["Jason Stine - Fullstack Software Engineer at Centivo"],"tags":["AI Models","Agents","Agentic AI","Open Source"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1074","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1913-local-ai-workshop","urls":[],"flag":null},{"id":1075,"title":"Agents That Own Their Inference: Building Production AI Agents on Dedicated GPUs","description":"Every production agent today is renting its intelligence. You're paying per token, sending your customer's data to someone else's servers, and hoping the provider doesn't rate-limit you during your launch. For most teams, that's fine. But for a growing number of teams in regulated industries, with high-volume products, latency-sensitive workloads, or rising token bills, it's starting to look like a liability.\n\nIn this 120-minute hands-on workshop you'll get a dedicated GPU and build an agent that runs on infrastructure you control. You'll stand up vLLM, point your agent at it, and drive concurrent load through the stack until you can see batching, KV cache pressure, and throughput limits in the metrics. Then you'll optimize the deployment to improve throughput while keeping per-request latency in line.\n\nThe focus isn't agent frameworks. It's the inference layer underneath them. You'll leave with working code and a real understanding of continuous batching under real concurrency, KV cache tradeoffs, vLLM's metrics, and the bottlenecks that only show up when you operate the inference server yourself.","starts_at":"2026-09-23T10:45:00-07:00","ends_at":"2026-09-23T12:45:00-07:00","stage":"Stage 10","track":"AI Models & Infrastructure","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"","speakers":["Khaja Omer - Senior Software Engineer at Akamai Technologies","Sheilah Kirui - Sr. Developer Advocate at Akamai"],"tags":["AI Models","Agents","Agentic AI","Infrastructure","Large Language Models (LLMs)","Llama","LLMOps","Ollama","Small Language Models (SLMs)"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1075","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1717-agents-that-own","urls":[],"flag":null},{"id":1092,"title":"Architecting Multi-Agent Teams: Mastering the Orchestration Patterns of ADK 2","description":"This hands-on workshop covers the primary orchestration patterns in ADK 2: graph workflows, collaborative agent teams, and dynamic (LLM-shaped) workflows. You will learn to construct architectures that combine parallel fan-out with join nodes, deterministic code-level routers that branch without extra model calls, collaborative supervisor-specialist teams executing dynamic parallel subsets, and recursive execution flows. You will conclude with a decision matrix for selecting and composing these patterns.\n\n - Identify the correct orchestration pattern based on structural problem constraints.\n - Construct graph-based, collaborative, and dynamic workflows using ADK 2 primitives.\n - Reduce latency and token consumption by offloading branching decisions from the model to code-level logic.","starts_at":"2026-09-23T10:45:00-07:00","ends_at":"2026-09-23T12:45:00-07:00","stage":"Stage 12","track":"AI Agents","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"Laptop & charger ","speakers":["Annie Wang - AI Engineer & Developer Advocate at Google"],"tags":["AI Models","Agents","Workflows"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1092","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1798-architecting-multi","urls":[],"flag":null},{"id":1077,"title":"Docker does that? Five Docker capabilities you did not know about","description":"Most developers use Docker to package and ship an app, and that answer was complete five years ago. The toolchain has grown a lot. This talk walks through a normal working day and shows where the newer pieces fit.\n\n- Docker Sandboxes provide a trust boundary around your agents, protecting your filesystem, network access, and credentials.\n- Gordon, Docker's built-in AI agent, sits right in the CLI and Desktop, ask it questions about your images, containers, best practices, and let it run the actions for you.\n- Testcontainers put a real database inside your test suite so you can stop maintaining mocks or using shared infrastructure.\n- Your base images can arrive already patched with Docker Hardened Images.\n- Docker Scout helps you know what's in your images and even run policy evaluations to ensure your images meet the mark.\n\nEverything in the talk is free to use, and most of it is already installed as part of your existing Docker setup.","starts_at":"2026-09-23T11:00:00-07:00","ends_at":"2026-09-23T11:30:00-07:00","stage":"Stage 1","track":"DevEx & Productivity","type":"DevEx & Productivity","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ajeet Raina - Developer Advocate at Docker","Kristiyan Velkov - Developer Relations Engineer at Zerops.io"],"tags":["Containers","Developer Experience (DevEx)","Docker","Security","Testing"],"live_url":"https://www.youtube.com/watch?v=83n4iPGcb0Q","recording_url":"https://www.youtube.com/watch?v=83n4iPGcb0Q","app_url":"https://app.wearedevelopers.com/events/18/session/1077","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1918-docker-does-that","urls":["https://www.youtube.com/watch?v=83n4iPGcb0Q"],"flag":null},{"id":1410,"title":"Fake or news XXL","description":"","starts_at":"2026-09-23T11:00:00-07:00","ends_at":"2026-09-23T11:30:00-07:00","stage":"Outdoor Stage","track":"Career, Culture & Community","type":"Career, Culture & Community","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Christian Heilmann - VP Developer Relations at WeAreDevelopers"],"tags":[],"live_url":"https://www.youtube.com/watch?v=6nnNW1hEzuA","recording_url":"https://www.youtube.com/watch?v=6nnNW1hEzuA","app_url":"https://app.wearedevelopers.com/events/18/session/1410","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1937-fake-or-news-xxl","urls":["https://www.youtube.com/watch?v=6nnNW1hEzuA"],"flag":null},{"id":1383,"title":"Warm-up Welcome & Program Announcements","description":"","starts_at":"2026-09-23T12:00:00-07:00","ends_at":"2026-09-23T12:30:00-07:00","stage":"Outdoor Stage","track":"Experience & Activities","type":"Experience & Activities","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Christian Heilmann - VP Developer Relations at WeAreDevelopers"],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1383","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1935-welcome-and-program","urls":[],"flag":null},{"id":1384,"title":"WeAreDevelopers Live","description":"","starts_at":"2026-09-23T12:30:00-07:00","ends_at":"2026-09-23T13:00:00-07:00","stage":"Outdoor Stage","track":"Career, Culture & Community","type":"Career, Culture & Community","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Christian Heilmann - VP Developer Relations at WeAreDevelopers"],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1384","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1936-wearedevelopers-live","urls":[],"flag":null},{"id":1079,"title":"Tools, Sandboxes, and the Plumbing of Agentic Development","description":"Most conversations about agents end at the model and the prompt, yet the real work happens lower in the stack, in the environment where code runs and tools get invoked. This talk maps out what that layer needs to provide for an agent to do real work safely, then shows a working stack built on those ideas.","starts_at":"2026-09-23T13:00:00-07:00","ends_at":"2026-09-23T13:30:00-07:00","stage":"Stage 1","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Oleg Šelajev - AI and Developer Relations at Docker"],"tags":["Agents","Agentic AI","Infrastructure","Runtimes","Tooling"],"live_url":"https://www.youtube.com/watch?v=SIXMMMz-GhI","recording_url":"https://www.youtube.com/watch?v=SIXMMMz-GhI","app_url":"https://app.wearedevelopers.com/events/18/session/1079","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1919-tools-sandboxes-and","urls":["https://www.youtube.com/watch?v=SIXMMMz-GhI"],"flag":null},{"id":1086,"title":"Build Interactive Copilot Experiences with Canvas Extensions","description":"What happens when GitHub Copilot moves beyond chat and becomes a shared workspace for developers, agents, and tools? \n\nAfter a brief introduction to the GitHub Copilot app, this session introduces canvas extensions—interactive surfaces that help teams visualize information, collaborate on content, and act while keeping humans in control. \n\nThrough demonstrations of several canvases, we’ll explore workflows such as documentation, design iteration, issue triage, and more. We’ll then build a canvas and examine the APIs and SDK used to create these experiences. \n\nAttendees will leave with practical guidance for identifying opportunities for canvas extensions and designing experiences that make Copilot more useful, actionable, and connected to the tools customers already rely on.","starts_at":"2026-09-23T13:00:00-07:00","ends_at":"2026-09-23T13:30:00-07:00","stage":"Stage 2","track":"DevEx & Productivity","type":"DevEx & Productivity","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["James Clancey - Principal Product Manager at GitHub"],"tags":["AI Coding Assistants","AI Models","Copilot","GitHub","Sentry"],"live_url":"https://www.youtube.com/watch?v=rdKtV5WjjRI","recording_url":"https://www.youtube.com/watch?v=rdKtV5WjjRI","app_url":"https://app.wearedevelopers.com/events/18/session/1086","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1839-build-interactive","urls":["https://www.youtube.com/watch?v=rdKtV5WjjRI"],"flag":null},{"id":1385,"title":"Fake or news XXL","description":"","starts_at":"2026-09-23T13:00:00-07:00","ends_at":"2026-09-23T13:30:00-07:00","stage":"Outdoor Stage","track":"Career, Culture & Community","type":"Career, Culture & Community","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Christian Heilmann - VP Developer Relations at WeAreDevelopers"],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1385","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1937-fake-or-news-xxl","urls":[],"flag":null},{"id":1081,"title":"The AI-Ready Developer Environment — Local Setup, Reproducibility, and Docker","description":"Modern AI development adds a new layer of complexity to the development environment: agent harnesses, agent-specific developer tooling, MCP servers, external services, credentials, and more. And every team has different requirements. How do you give developers and agents the tools they need while keeping environments consistent, reproducible, and secure?\n\nIn this hands-on session, you'll start with Docker Sandboxes and then go deeper into customizing and sharing sandbox-based development environments. You'll create sbx kits to tailor the tools and configuration available inside a sandbox, connect to external services—including those that require secure credential injection—and package those customizations for reuse.\n\nYou'll then use sbxenv, which brings a Docker Compose-like experience to sandboxes, to define an entire development environment as configuration. By the end, you'll have an environment that can be shared with your team and started with a single command—giving every developer and agent a consistent, ready-to-use workspace.","starts_at":"2026-09-23T13:15:00-07:00","ends_at":"2026-09-23T15:15:00-07:00","stage":"Stage 8","track":"DevEx & Productivity","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"Setup required\r\n- A laptop running MacOS on Apple Silicon or Windows 11 x86_64","speakers":["Michael Irwin - Principal Engineer, Developer Success at Docker"],"tags":["Agents","Agentic AI","Docker","Governance"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1081","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1888-the-ai-ready","urls":[],"flag":null},{"id":1082,"title":"DeepAgents: Build Multi-Agent AI Systems That Actually Work","description":"We've taught LangChain and LangGraph multi-agent workshops at Grace Hopper two years running to 200+ developers each time. The number one question we get after every session: \"This works in a demo — but how do I get past the walls when I try to scale it?\"\nWe know those walls firsthand. We've built agentic AI systems across POCs and production in global banking — and between us, we've hit every failure mode: agents losing context mid-task, orchestration logic that doesn't survive real workloads, and delegation patterns that look clean on a whiteboard but collapse under pressure.\nDeepAgents is a new LangChain framework built to solve exactly these problems — intelligent delegation, advanced planning, robust context preservation, and error recovery designed for production-grade workflows. In this 120-minute hands-on workshop, we'll build a real multi-agent system together in GitHub Codespaces — no setup, no installs, just code.\nThrough guided labs, you'll architect a coordinator that delegates research to one agent, analysis to another, and synthesis to a third. You'll implement human-in-the-loop approval gates, long-term memory, and the error recovery patterns that separate prototypes from systems that survive production. We'll be honest about what's battle-tested and what's cutting-edge — because that's the conversation practitioners actually need.\nWhat you'll walk away with: a portfolio-ready multi-agent system you built yourself, production skills across backends, subagents, coordinators, memory, and debugging, a complete code repository with reusable templates and documentation you can extend immediately, and the framework decision-making to know when LangChain chains, LangGraph, or DeepAgents is the right tool for your problem.\nBring a GitHub account and a browser. Leave with production-tested patterns.","starts_at":"2026-09-23T13:15:00-07:00","ends_at":"2026-09-23T15:15:00-07:00","stage":"Stage 9","track":"AI Agents","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":36,"waitlist":5,"requirements":"","speakers":["Anagha Rumade - Applied AI/ML Lead at JPMorgan Chase","Anjana Umapathy - Applied AI/ML Lead & VP at JPMorgan Chase","Apoorva Jaiswal - Applied AI/ML Lead at JPMorgan Chase"],"tags":["Agents","Agentic AI","Generative AI (GenAI)","LangChain","Large Language Models (LLMs)","LLMOps","Multi-Agent Systems","OpenAI","Python"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1082","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1694-deepagents-build","urls":[],"flag":null},{"id":1083,"title":"AI Security Engineer Foundations","description":"2-hour workshop on AI Security Engineer Foundations covering the following modules:\n- OWASP Top 10 for Agentic Applications\n- Addressing Shadow AI\n- AI Governance and Policy as Code\n- Securing Agent Skills & MCP\n- Securing Vibe Coding\n- AI Penetration Testing","starts_at":"2026-09-23T13:15:00-07:00","ends_at":"2026-09-23T15:15:00-07:00","stage":"Stage 10","track":"AI Trust & Safety","type":"Workshop","live_coding":false,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"","speakers":["Javier Garza - Staff Developer Advocate at Snyk"],"tags":["AI Coding Assistants","Claude","DevSecOps","Prompt Engineering","Security","Snyk","Threat Modelling","YAML"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1083","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1778-ai-security-engineer","urls":[],"flag":null},{"id":1308,"title":"Build a Human + AI Agent Team in tools like Slack, Teams and Discord.","description":"AI agents are getting better at doing work, but most still work alone, separated from the people and other agents they need to collaborate with.\n\nIn this hands-on workshop, you’ll use Switch to bring AI agents from Claude Code, OpenAI, Google ADK, LangChain and other frameworks into Slack, Microsoft Teams, Discord and other collaboration platforms, where humans and agents can work together with shared context, history and resources.\n\nYou’ll build a working human + agent team, assign specialized agents to real tasks, hand work between people and agents, and see how context stays with the work even as agents, models and teammates change.\n\nSwitch is free, open source and vendor agnostic, so you can use the agents and tools you already have without migrating your team to a new platform or committing to a single model or framework.\n\nBy the end of the workshop, you’ll have a working human + agent workspace you can continue using and adapting to your own projects.","starts_at":"2026-09-23T13:15:00-07:00","ends_at":"2026-09-23T15:15:00-07:00","stage":"Stage 12","track":"AI Agents","type":"Workshop","live_coding":false,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"","speakers":["Phil Conway - Developer Advocate at Flint AI (SandboxAQ)"],"tags":["Agents","Agentic AI","Best Practices","Claude","Collaboration","Communication","Cross-Platform","Developer Experience (DevEx)","Digital Transformation","Digital Twins","Future of Work","LLMOps","Multi-Agent Systems","OpenAI","Productivity","Slack","Team Building","Tooling","Tools"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1308","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1837-build-a-human-ai","urls":[],"flag":null},{"id":1084,"title":"Building an AI-Native Development Workflow","description":"AI is changing more than how we write code. It’s changing how we build software. As GitHub Copilot evolves beyond code completion into an intelligent collaborator, developers and organizations have an opportunity to rethink how they work. \n\nIn this session, we’ll explore how AI can support the software development lifecycle, from planning and implementation to testing, documentation, and code reviews. We’ll discuss context engineering, intentional AI adoption, and how teams can create effective collaboration between developers and AI while maintaining the right balance of automation and human judgment.","starts_at":"2026-09-23T13:40:00-07:00","ends_at":"2026-09-23T14:10:00-07:00","stage":"Stage 2","track":"DevEx & Productivity","type":"DevEx & Productivity","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Vanessa Minik - Senior Service Delivery Engineer at GitHub"],"tags":["AI Coding Assistants","Agents","Agentic AI","Copilot","GitHub","Prompt Engineering"],"live_url":"https://www.youtube.com/watch?v=YOf7mZqUaJc","recording_url":"https://www.youtube.com/watch?v=YOf7mZqUaJc","app_url":"https://app.wearedevelopers.com/events/18/session/1084","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1842-building-an-ai","urls":["https://www.youtube.com/watch?v=YOf7mZqUaJc"],"flag":null},{"id":1085,"title":"Supply Chain Security When Agents Write the Code","description":"When an agent chooses your dependencies and assembles your build, answering what you are actually shipping gets genuinely hard. This talk starts with the fundamentals that make it answerable, including SBOMs, exploitability data, and build provenance, and shows how to apply them so an agent-assembled stack is one you can defend in a security review.","starts_at":"2026-09-23T14:00:00-07:00","ends_at":"2026-09-23T14:30:00-07:00","stage":"Stage 1","track":"Security & Privacy","type":"Security & Privacy","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ajeet Raina - Developer Advocate at Docker"],"tags":["AI Coding Assistants","Compliance","DevSecOps","SBOM","Security"],"live_url":"https://www.youtube.com/watch?v=rRZAbDJw1UQ","recording_url":"https://www.youtube.com/watch?v=rRZAbDJw1UQ","app_url":"https://app.wearedevelopers.com/events/18/session/1085","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1920-supply-chain","urls":["https://www.youtube.com/watch?v=rRZAbDJw1UQ"],"flag":null},{"id":1386,"title":"Fireside chat with Harald Kirschner - VS Code and what's next?","description":"","starts_at":"2026-09-23T14:00:00-07:00","ends_at":"2026-09-23T15:00:00-07:00","stage":"Outdoor Stage","track":"DevEx & Productivity","type":"DevEx & Productivity","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Christian Heilmann - VP Developer Relations at WeAreDevelopers","Harald Kirschner - Principal Product Manager at Microsoft"],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1386","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1938-fireside-chat-with","urls":[],"flag":null},{"id":1080,"title":"Parallelize Your Development with GitHub Copilot","description":"We’re finally at a point with coding where we can truly work on multiple tasks at once - and actually have it be an enjoyable and manageable experience! I’ll demonstrate how I split my work across multiple surfaces: the VS Code IDE when I need to be the most hands-on, the GitHub Copilot desktop app for tasks that require light supervision, and cloud agents for routine maintenance. I’ll share my tips for enabling truly parallel development of full-stack web applications thanks to git worktrees and smart environment variable management. Plus, I’ll share my favorite automation workflows that run while I’m asleep, saving me time so that I can focus on the fun parts of software development.","starts_at":"2026-09-23T14:20:00-07:00","ends_at":"2026-09-23T14:50:00-07:00","stage":"Stage 2","track":"DevEx & Productivity","type":"DevEx & Productivity","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Pamela Fox - Principal Cloud Advocate at Microsoft"],"tags":["GitHub","IDEs","Workflows","Workflow Automation"],"live_url":"https://www.youtube.com/watch?v=TdYYQ4UgHPU","recording_url":"https://www.youtube.com/watch?v=TdYYQ4UgHPU","app_url":"https://app.wearedevelopers.com/events/18/session/1080","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1873-parallelize-your","urls":["https://www.youtube.com/watch?v=TdYYQ4UgHPU"],"flag":null},{"id":1087,"title":"Give the Agent Its Own Machine","description":"Coding agents get useful the moment they can read files, run commands, and reach the network, and each of those is also a way for one bad step to cost you an afternoon or worse. This talk shows what it takes to run an agent at full capability inside a boundary you set, ending with a live setup you can recreate on your own laptop in minutes.","starts_at":"2026-09-23T15:00:00-07:00","ends_at":"2026-09-23T15:30:00-07:00","stage":"Stage 1","track":"AI Engineering","type":"AI Engineering","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Dan Ndombe - Staff Developer Success Advocate at Docker"],"tags":["AI Coding Assistants","AI Models","Agentic AI","Containers","Docker","Generative AI (GenAI)","Safety"],"live_url":"https://www.youtube.com/watch?v=QARLA5AZYNY","recording_url":"https://www.youtube.com/watch?v=QARLA5AZYNY","app_url":"https://app.wearedevelopers.com/events/18/session/1087","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1921-give-the-agent-its","urls":["https://www.youtube.com/watch?v=QARLA5AZYNY"],"flag":null},{"id":1088,"title":"How GitHub Helps Two Maintainers Serve 6,000 Learners","description":"Learn to Cloud is a free, open-source alternative to paid cloud bootcamps. Thanks to GitHub, two maintainers with full-time jobs ship features and fixes daily across four repos to more than 6,000 learners. In this talk, we'll open up our repos and show what's actually in them: agent skills that encode our production runbooks, custom agents that review security and drive browser QA, agentic workflows that keep content current, and more. We'll show where we use AI, where we deliberately don't, and why that line matters when two people maintain everything.","starts_at":"2026-09-23T15:00:00-07:00","ends_at":"2026-09-23T15:30:00-07:00","stage":"Stage 2","track":"Career, Culture & Community","type":"Career, Culture & Community","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Gwyneth Peña-Siguenza - Senior Cloud Advocate at GitHub"],"tags":["AI Coding Assistants","AI Models","Agents","Agentic AI","Open Source","Quality Assurance (QA)"],"live_url":"https://www.youtube.com/watch?v=pmNhUr9WwIo","recording_url":"https://www.youtube.com/watch?v=pmNhUr9WwIo","app_url":"https://app.wearedevelopers.com/events/18/session/1088","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1857-how-github-helps-two","urls":["https://www.youtube.com/watch?v=pmNhUr9WwIo"],"flag":null},{"id":1089,"title":"Lean Intelligence: Lessons from GitHub Copilot Data Science Efforts","description":"GitHub Copilot handles millions of developer interactions every day! Behind every suggestion, chat response, and agentic action are countless decisions about which model or subagent to invoke, how long to let it run, and when the answer is already good enough. This talk shares lessons from the Code|AI research team's work on making the Copilot harness leaner without sacrificing quality. We'll dig into the experimentation, evaluation, and data science that helped us find and validate meaningful efficiency gains at scale.\n\nIf evals, experimentation, and data science are your jam, this one's for you.","starts_at":"2026-09-23T15:40:00-07:00","ends_at":"2026-09-23T16:10:00-07:00","stage":"Stage 2","track":"DevEx & Productivity","type":"DevEx & Productivity","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Rahul Pandita - Researcher and Technical Advisor at Microsoft"],"tags":["AI Models","Data Science","Model Training"],"live_url":"https://www.youtube.com/watch?v=RDSpTBtR8K4","recording_url":"https://www.youtube.com/watch?v=RDSpTBtR8K4","app_url":"https://app.wearedevelopers.com/events/18/session/1089","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1867-lean-intelligence","urls":["https://www.youtube.com/watch?v=RDSpTBtR8K4"],"flag":null},{"id":1076,"title":"Vibe-code an App on Multimodal AI Analytics","description":"Learn how to search through video, audio and flat files from SQL statements to equip your applications and agents with multimodal analysis. Vibe-code a Cloud Run web application to see the power of semantic search over different types of files in action.","starts_at":"2026-09-23T15:45:00-07:00","ends_at":"2026-09-23T17:45:00-07:00","stage":"Stage 12","track":"DevEx & Productivity","type":"Workshop","live_coding":false,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"","speakers":["Aron Eidelman - Security Advocate at Google"],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1076","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1912-vibe-code-an-app-on","urls":[],"flag":null},{"id":1090,"title":"Docker's Agentic Platform: Sandboxes, MCP, and the Infrastructure of Autonomous Development","description":"AI agents are only as capable as the environment they're allowed to act in. This session introduces Docker's purpose-built platform tools for agentic development — the infrastructure layer that lets autonomous systems do real work, safely and reliably. We'll dive into Docker Sandboxes, which give agents secure, isolated execution environments where they can write and run code, interact with filesystems, and test outcomes without risk to your host system or production infrastructure. We'll also explore Docker's MCP toolkit, which provides agents with a standardized way to discover and invoke trusted tools. Together, these tools form the foundation of a trustworthy agentic platform: one where autonomous processes have exactly the access they need, and every action is contained, observable, and repeatable. Leave this session ready to wire Docker into your AI agent stack as the execution layer your agents can depend on.","starts_at":"2026-09-23T15:45:00-07:00","ends_at":"2026-09-23T17:45:00-07:00","stage":"Stage 8","track":"AI Trust & Safety","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"Concepts to know:\r\n- Basic Docker concepts (containers, images, the docker CLI)\r\n- What an AI agent is and how tool-use works\r\n- Comfortable using the command line (navigating directories, running scripts)\r\n- Familiarity with at least one programming language (Python preferred)\r\n- Basic familiarity with LLMs and prompt-driven workflows\r\n- Understanding of APIs and JSON communication patterns\r\n- Awareness of Model Context Protocol (MCP) concepts\r\n- What CVEs are and how vulnerability scanning works\r\n\r\nSetup required\r\n- A laptop running MacOS on Apple Silicon or Windows 11 x86_64","speakers":["Oleg Šelajev - AI and Developer Relations at Docker"],"tags":["Agents","Agentic AI","Docker","Governance"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1090","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1847-docker-s-agentic","urls":[],"flag":null},{"id":1091,"title":"Securing the Agentic Stack: Docker Hardened Images and Supply Chain Security","description":"As agentic workflows give AI systems more autonomy to pull dependencies, build environments, and invoke tools, the security of your container foundation has never mattered more. This session puts security front and center. You'll start off with learning core security features, such as SBOMs, VEX, and the SLSA framework. From there, you'll learn about and get hands-on with Docker Hardened Images (DHI) and how they utilize these capabilities to give every developer and agent a safe baseline to build from. Finally, learn how to use build policies and image signing to safeguard your CI pipelines and deployment environments. Leave this session with a clear framework for securing your entire stack.","starts_at":"2026-09-23T15:45:00-07:00","ends_at":"2026-09-23T17:45:00-07:00","stage":"Stage 10","track":"Security & Privacy","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"Concepts to know:\r\n- Basic Docker concepts (containers, images, the docker CLI)\r\n- What an AI agent is and how tool-use works\r\n- Comfortable using the command line (navigating directories, running scripts)\r\n- Familiarity with at least one programming language (Python preferred)\r\n- Basic familiarity with LLMs and prompt-driven workflows\r\n- Understanding of APIs and JSON communication patterns\r\n- Awareness of Model Context Protocol (MCP) concepts\r\n- What CVEs are and how vulnerability scanning works\r\n\r\nSetup required\r\n- A laptop running MacOS on Apple Silicon or Windows 11 x86_64\"","speakers":["Ajeet Raina - Developer Advocate at Docker"],"tags":["Agents","Agentic AI","Docker","Governance","Security"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1091","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1882-securing-the-agentic","urls":[],"flag":null},{"id":1387,"title":"Coffee with Developers with Noris Buriac (Forward Security)","description":"","starts_at":"2026-09-23T16:00:00-07:00","ends_at":"2026-09-23T17:00:00-07:00","stage":"Outdoor Stage","track":"Experience & Activities","type":"Experience & Activities","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Christian Heilmann - VP Developer Relations at WeAreDevelopers"],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1387","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1939-coffee-with","urls":[],"flag":null},{"id":1093,"title":"Lawyers who ship: How GitHub CELA used AI to rewire legal work","description":"Legal teams aren't usually cast as builders, but at GitHub CELA, they ship. This session tells the story of how CELA used AI to rewire the way legal work gets done: automating the routine, accelerating the complex, and freeing lawyers to focus on judgment over busywork. We'll cover where we started, the wins along the way, and where we're headed next, with a live look at the tools in action. Whether you're legal, technical, or somewhere in between, you'll leave with a concrete picture of what \"lawyers who ship\" really means.","starts_at":"2026-09-23T16:20:00-07:00","ends_at":"2026-09-23T16:50:00-07:00","stage":"Stage 2","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Bria Ford - Program Manager & Digital Transformation at GitHub"],"tags":["Automation","GitHub","Innovation","Productivity"],"live_url":"https://www.youtube.com/watch?v=6GR3edWDAwE","recording_url":"https://www.youtube.com/watch?v=6GR3edWDAwE","app_url":"https://app.wearedevelopers.com/events/18/session/1093","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1866-lawyers-who-ship-how","urls":["https://www.youtube.com/watch?v=6GR3edWDAwE"],"flag":null},{"id":1380,"title":"Meet-Up: Daytona & SambaNova AI Builders","description":"​An event dedicated to exploring all things AI Engineering!\n\nAgenda:\n​​​​​​🕒 5:30 pm – 5:35 pm\nWelcome and Opening Remarks\n​​​​​​​​🕒 5:35 pm – 5:50 pm\nTalk \"Your Agent's Slowest Tool Is Its Mouse\"​\n​​🕒 5:50 pm – 6:05 pm\nTalk \"Fast Tokens, More Responsive Agents\"\n​​🕒 6:05 pm – 6:20 pm\nTalk \"TBA\"\n​​🕒 6:20 pm – 6:30 pm\nTalk \"Beyond the Sandbox: Scaling Enterprise-Grade AI Agents for Real Users\"\n​​🕒 6:30 pm – 6:40 pm\nTalk \"Auto-Research on a Budget: Small Models in the Loop, Frontier Models on Call\"\n​​​​​​​​​​​​​​​​🕒 6:40 pm - 8:30 pm\n​​​Networking with pizzas and beverages\n\nMore information & registration:\nhttps://luma.com/ai-builders-san-jose","starts_at":"2026-09-23T17:30:00-07:00","ends_at":"2026-09-23T18:00:00-07:00","stage":"Location TBA","track":"","type":"Session","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":[],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1380","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1940-meet-up-daytona","urls":[],"flag":null},{"id":1094,"title":"Doors open - Day 1","description":"","starts_at":"2026-09-24T08:00:00-07:00","ends_at":"2026-09-24T09:30:00-07:00","stage":"Location TBA","track":"Experience & Activities","type":"Experience & Activities","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":[],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1094","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1902-doors-open-day-1","urls":[],"flag":null},{"id":1095,"title":"Official Opening of WeAreDevelopers World Congress: North America","description":"","starts_at":"2026-09-24T09:30:00-07:00","ends_at":"2026-09-24T09:45:00-07:00","stage":"Mainstage","track":"Experience & Activities","type":"Experience & Activities","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":[],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1095","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1905-official-opening-of","urls":[],"flag":null},{"id":1096,"title":"Manufacturing trust: speed and safety in the age of agents","description":"Agents have made building software faster, but infrastructure has to catch up.\nIn the world we now live in, developers review code they did not write, or don’t review it at all. An agent can generate and execute changes faster than any person or team can inspect them. And while prompts and skills can steer an agent, they cannot guarantee trust.\nFor decades, we established trust in software through people and process: shared context, code review, CI, and ownership, all of which run at human speed. Agents do not. If a person has to watch every step, the agent is not autonomous, and most of the promised speed disappears. Trust has to move into the system itself.\nMark Cavage, President and COO of Docker, makes the case for enforceable boundaries around nondeterministic agents. When you can’t inherit trust, you have to manufacture it. That means isolating where agents run, limiting what they can reach, recording what they do, and making failures reproducible. These controls are not the price of moving fast. They are what let you move fast without losing control.\nThe test for an agent platform is simple: Does security hold when the prompt does not? Can you audit what happened? Can you switch models and tools without rebuilding the trust layer? The goal is not to trust the agent. It is to trust the system around it enough to close your laptop, while the work continues.","starts_at":"2026-09-24T09:45:00-07:00","ends_at":"2026-09-24T10:15:00-07:00","stage":"Mainstage","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Mark Cavage - President & COO at Docker"],"tags":[],"live_url":"https://www.youtube.com/watch?v=4Xh-AS24BjI","recording_url":"https://www.youtube.com/watch?v=4Xh-AS24BjI","app_url":"https://app.wearedevelopers.com/events/18/session/1096","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1870-manufacturing-trust","urls":["https://www.youtube.com/watch?v=4Xh-AS24BjI"],"flag":null},{"id":1400,"title":"Coffee Reception with Wednesday Women","description":"Please join Wednesday Women and WeAreDevelopers COO, Naida Vikalo, for Coffee and Conversation right inside the WeAreDevelopers North American Congress. Wednesday Women has reserved this space for attendees that identify as women for great coffee, snacks, even better conversations and to discover professional and personal connections with other extraordinary women.","starts_at":"2026-09-24T10:15:00-07:00","ends_at":"2026-09-24T11:15:00-07:00","stage":"Location TBA","track":"Career, Culture & Community","type":"Career, Culture & Community","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Leslie Greenwood - Founder at Wednesday Women"],"tags":["Career Development","Community","Diversity & Inclusion","Employer Branding","Entrepreneurship","Networking","People & Culture"],"live_url":"https://www.youtube.com/watch?v=L8brdAK_5Vo","recording_url":"https://www.youtube.com/watch?v=L8brdAK_5Vo","app_url":"https://app.wearedevelopers.com/events/18/session/1400","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions","urls":["https://www.youtube.com/watch?v=L8brdAK_5Vo"],"flag":null},{"id":1097,"title":"Building a Foundation Model Company from First Principles","description":"How do you turn a fundamental research idea into intelligence that works on the devices people use every day? In this keynote, I’ll share the technical journey from inventing liquid neural networks to building Liquid AI. Instead of insisting on a particular architecture, we built AI that designs AI, allowing competing designs to be evaluated against capability, memory, and latency requirements with the target hardware inside the design process. But architecture is only the beginning. I’ll walk through the interconnected decisions across data, pretraining, post-training, quantization, inference software, and developer tools. Each component shapes the final experience: how quickly a system responds, how reliably it performs, where data lives, and how easily developers can build with it. Our ambition is to bring our models to 50% of the world’s annually produced devices by 2029. I’ll explain what this ambition demands of the technology, the product experience, and the company, and the lessons builders can apply to their own ideas.","starts_at":"2026-09-24T10:20:00-07:00","ends_at":"2026-09-24T10:50:00-07:00","stage":"Mainstage","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Dr. Ramin Hasani - Co-founder & CEO at Liquid AI"],"tags":[],"live_url":"https://www.youtube.com/watch?v=GMHoylDKmTA","recording_url":"https://www.youtube.com/watch?v=GMHoylDKmTA","app_url":"https://app.wearedevelopers.com/events/18/session/1097","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1865-keynote-ramin-hasani","urls":["https://www.youtube.com/watch?v=GMHoylDKmTA"],"flag":null},{"id":1098,"title":"The New Rules of Software Delivery","description":"DevOps practices are the plumbing of modern software delivery - how code gets built, tested, shipped, and operated in production. The way software is made is now shifting faster than the practices around it: AI writes and deploys a growing share of it, systems change quicker than teams can review, and production keeps growing in scale and complexity. What this shift means for companies building and operating software at scale - how best practices are changing, and what teams need to know to keep delivery fast and reliable.","starts_at":"2026-09-24T10:20:00-07:00","ends_at":"2026-09-24T10:50:00-07:00","stage":"Tech Leaders Stage","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["AJ Aitken - Senior VP Infrastructure and Platform Engineering at Datavant","Darko Mesaros - Distinguished Developer Advocate at AWS","Moritz Plassnig - CEO at CloudBees","Akshay Shah - Field CTO at Antithesis","Prince Kohli - President & CEO at Sauce Labs"],"tags":[],"live_url":"https://www.youtube.com/watch?v=myJhSJs83GY","recording_url":"https://www.youtube.com/watch?v=myJhSJs83GY","app_url":"https://app.wearedevelopers.com/events/18/session/1098","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1889-the-new-rules-of","urls":["https://www.youtube.com/watch?v=myJhSJs83GY"],"flag":null},{"id":1099,"title":"The Browser Is Becoming an AI Runtime","description":"Browsers are becoming more than just rendering engines. They're evolving into the orchestration layer that decides which AI systems retrieve information, summarize content, and interact with users. This session would explore how Firefox is designing Smart Window as an extensible AI layer that can evolve over time rather than locking users into a single provider. Exa would serve as a case study in how specialized AI services can plug into that architecture while maintaining strong privacy protections, including zero data retention. The conversation ultimately shifts from \"Which model is best?\" to \"who controls the layer that decides which model gets used?\"","starts_at":"2026-09-24T10:20:00-07:00","ends_at":"2026-09-24T10:50:00-07:00","stage":"Stage 1","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ajit Varma - Head of Firefox at Mozilla","Will Bryk - CEO at Exa","Julia Love - Technology Reporter at Bloomberg"],"tags":["Advocacy","Internet of Things (IoT)","Large Language Models (LLMs)","Web Components","Web Performance","Web Standards","Workflows"],"live_url":"https://www.youtube.com/watch?v=pUw_5lZ-l00","recording_url":"https://www.youtube.com/watch?v=pUw_5lZ-l00","app_url":"https://app.wearedevelopers.com/events/18/session/1099","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1820-the-browser-is","urls":["https://www.youtube.com/watch?v=pUw_5lZ-l00"],"flag":null},{"id":1100,"title":"From Static Rules to Reasoning Platforms: Scaling Intelligent Canary Delivery in 2026","description":"As organizations scale their Kubernetes footprint, the \"Day 2\" reality of GitOps becomes clear: static thresholds are brittle. Standard Canary rollouts rely on fixed Prometheus queries (e.g., Error Rate < 1%), but these rules lack the context to distinguish between a minor transient blip and a systemic failure. For Platform Engineers, this results in \"Alert Fatigue\" and manual \"promotion\" gates that slow down the delivery pipeline.\nIn 2026, we are moving from Static Automation to Reasoning Platforms.\nThis session explores how to evolve your delivery infrastructure into an intelligent system that doesn't just follow rules, but reasons through data. We will demonstrate how to wrap ArgoCD Rollouts with an Agentic Reasoning Layer capable of cross-referencing metrics, logs, and distributed traces to make autonomous \"Go/No-Go\" decisions.\n\nWe will trigger a Canary deployment that passes basic health checks but introduces a \"silent failure\" (e.g., a cache hit-rate drop causing downstream latency). You will see the Reasoning Platform detect the anomaly, pause the rollout, \"investigate\" the root cause, and present a natural-language justification for the automated rollback.","starts_at":"2026-09-24T10:20:00-07:00","ends_at":"2026-09-24T10:50:00-07:00","stage":"Stage 2","track":"Architecture & Backend","type":"Architecture & Backend","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Daniel Oh - Sr. Principal Developer Advocate at IBM"],"tags":["Agentic AI","ArgoCD","CI/CD","Internal Platforms"],"live_url":"https://www.youtube.com/watch?v=6SZA4Mdrk6E","recording_url":"https://www.youtube.com/watch?v=6SZA4Mdrk6E","app_url":"https://app.wearedevelopers.com/events/18/session/1100","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1667-from-static-rules-to","urls":["https://www.youtube.com/watch?v=6SZA4Mdrk6E"],"flag":null},{"id":1101,"title":"Reading the Mind of Your NGINX Fleet: A Hybrid Rule + ML Pipeline for NGINX Config Intelligence","description":"Every NGINX config encodes intent — is this a reverse proxy? an API gateway? an SSL terminator? — but that intent is never written down. At fleet scale, nobody can tell you what your configs actually do. This session shows how we taught a machine to read them.\nWe classify NGINX server configs into eight canonical roles using a three-stage pipeline: parse the raw config into a structured directive tree with CrossPlane, then run two complementary classifiers against it — a precision-tuned rule engine that abstains when signatures are ambiguous, and an ML model that generalizes to configs the rules don't cover. A confidence-fusion layer blends them, auto-accepting confident calls and routing borderline ones to expert review.\nThe counterintuitive lesson: we deliberately didn't just throw an LLM at this. The hybrid beats either approach alone — keeping rule-level precision while recovering the coverage rules lack. You'll see why \"negative evidence\" (the absence of a directive) is often the strongest signal, how an LLM-as-judge eval validated the design, and how a closed expert-feedback loop turns review hours into measurable accuracy gains. Live, against real configs — including yours, if you bring one.","starts_at":"2026-09-24T10:20:00-07:00","ends_at":"2026-09-24T10:50:00-07:00","stage":"Stage 3","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Brandon LEE - Director & AI Architect Lead at F5"],"tags":["AI Models","Agentic AI","Automation","Autonomous Systems","Best Practices","Claude","Innovation","Large Language Models (LLMs)","Model Training","Retrieval-Augmented Generation (RAG)","Small Language Models (SLMs)"],"live_url":"https://www.youtube.com/watch?v=4ysRHzlcDT8","recording_url":"https://www.youtube.com/watch?v=4ysRHzlcDT8","app_url":"https://app.wearedevelopers.com/events/18/session/1101","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1876-reading-the-mind-of","urls":["https://www.youtube.com/watch?v=4ysRHzlcDT8"],"flag":null},{"id":1102,"title":"AI Decision Observability: Enabling Transparency and Trust in Intelligent Systems","description":"Artificial Intelligence (AI) now drives decisions across enterprise operations, for autonomous systems—yet much of this decision-making remains a “black box.” AI Decision Observability is an emerging paradigm that transforms opaque model behavior into traceable, explainable, and auditable decision pathways. This session introduces a unified framework that combines AI Decision Observability with Decision Intelligence—linking how decisions are made, measured, and improved across human-AI systems.\n\nBuilding on our AI Decision Automation Framework, we explore the technical and organizational capabilities required to move from decision outputs to decision systems: continuous, observable pipelines where every inference, rule, and outcome can be traced back to its origin. We discuss key methodologies—comprehensive logging, data and model lineage tracing, model introspection, counterfactual and causal analysis—and how these integrate into enterprise observability stacks.\n\nThe session also showcases tools and architectures that operationalize observability, alongside real-world case studies from regulated domains like finance, healthcare, and autonomous mobility.\n\nWe’ll conclude with a forward-looking view on how Decision Observability fuels Decision Intelligence—enabling enterprises to build trusted, adaptive, and compliant AI ecosystems where decisions are not just made but understood, improved, and governed.\n\nKey Takeaways:\n\nHow to architect AI systems for full decision traceability and governance\n\nIntegrating Decision Intelligence with AI Decision Observability for continuous learning\n\nPractical frameworks for scaling decision transparency and automation across the enterprise","starts_at":"2026-09-24T10:20:00-07:00","ends_at":"2026-09-24T10:50:00-07:00","stage":"Stage 4","track":"DevOps & Platform Engineering","type":"DevOps & Platform Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Amjad Shaikh - VP Platform & AI at ServiceNow","Soumil Mandal - Sr. ML Engineer at ServiceNow"],"tags":["AI Models","AI Standards","Large Language Models (LLMs)","Observability"],"live_url":"https://www.youtube.com/watch?v=AhGlNw07UqM","recording_url":"https://www.youtube.com/watch?v=AhGlNw07UqM","app_url":"https://app.wearedevelopers.com/events/18/session/1102","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1400-ai-decision","urls":["https://www.youtube.com/watch?v=AhGlNw07UqM"],"flag":null},{"id":1103,"title":"Vector, Graph, or Key Value? Choosing Your Agent's Memory","description":"Your agent works in the demo, then forgets everything the next day. The model is not broken: models are stateless by design, and memory belongs to the harness you build around them. Bigger context windows do not fix it. Re sending full history burns tokens every turn and still vanishes between sessions.\n\nThis talk maps the agent memory landscape through one question asked four ways: retrieval by key, by meaning, and by relationship. You will learn when key value, vector, graph, and hybrid memory each win, plus the capabilities layer on top: selective memory, hygiene against dirty and poisoned entries, and reasoning memory for auditable decisions.","starts_at":"2026-09-24T10:20:00-07:00","ends_at":"2026-09-24T10:50:00-07:00","stage":"Stage 5","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Elizabeth Fuentes Leone - Developer Advocate/SDE, GenAI at AWS"],"tags":["AWS","Large Language Models (LLMs)","Retrieval-Augmented Generation (RAG)"],"live_url":"https://www.youtube.com/watch?v=IEB_qFLs5kQ","recording_url":"https://www.youtube.com/watch?v=IEB_qFLs5kQ","app_url":"https://app.wearedevelopers.com/events/18/session/1103","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1823-vector-graph-or-key","urls":["https://www.youtube.com/watch?v=IEB_qFLs5kQ"],"flag":null},{"id":1104,"title":"Practices, Not Prompts: Scale GitHub Copilot with AI-Ready Repositories","description":"A great Copilot session can unblock one developer, but team scale value begins when the repository itself makes architecture, conventions, development commands, tests, and validation easy to discover and when successful workflows stop disappearing into chat history. In this technical session, we will take a repository from a generic Copilot experience to an AI-ready development environment. We will encode the project knowledge and validation developers need, then package recurring workflows as reusable prompts, skills, plugins, and custom agents. Next, we will version and govern those resources, and publish them through a centralized internal marketplace. We will close by connecting these developer practices to GitHub Copilot enterprise managed settings and how you can configure these at scale. You will leave with a practical guidance for making Agentic workflows useful beyond a single developer while providing engineering velocity and keeping people responsible for what ships.","starts_at":"2026-09-24T10:20:00-07:00","ends_at":"2026-09-24T10:50:00-07:00","stage":"Stage 6","track":"DevEx & Productivity","type":"DevEx & Productivity","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Luis Pujols - Staff Customer Success Architect at GitHub"],"tags":["Agents","CI/CD","Code Reviews","Developer Experience (DevEx)","Prompt Engineering"],"live_url":"https://www.youtube.com/watch?v=lg47Q1-SHK4","recording_url":"https://www.youtube.com/watch?v=lg47Q1-SHK4","app_url":"https://app.wearedevelopers.com/events/18/session/1104","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1874-practices-not","urls":["https://www.youtube.com/watch?v=lg47Q1-SHK4"],"flag":null},{"id":1105,"title":"Zero-Trust Architecture for Agentic AI: Securing Multi-User Access and Third-Party Integrations","description":"This talk presents a deep technical exploration of implementing zero-trust security principles to enable secure agentic AI workflows across both internal systems and external enterprise tools. We'll examine the architectural patterns that allow granular access controls, unified authentication, and audit-ready visibility to work together, enabling productive AI automation while maintaining strict data sovereignty. Through real-world deployment examples, we'll demonstrate how these zero-trust foundations solve critical security challenges at the intersection of AI, cloud infrastructure, and regulatory compliance.","starts_at":"2026-09-24T10:20:00-07:00","ends_at":"2026-09-24T10:50:00-07:00","stage":"Stage 7","track":"AI Trust & Safety","type":"AI Trust & Safety","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Borko Djurkovic - Member of Technical Staff at Cohere"],"tags":["Agents","Agentic AI","CNCF","Multi-Agent Systems","Multi-Cloud","Open Source","Security"],"live_url":"https://www.youtube.com/watch?v=38KATmDvkxo","recording_url":"https://www.youtube.com/watch?v=38KATmDvkxo","app_url":"https://app.wearedevelopers.com/events/18/session/1105","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1707-zero-trust","urls":["https://www.youtube.com/watch?v=38KATmDvkxo"],"flag":null},{"id":1106,"title":"From Candidate Experience to Competitive Advantage","description":"This session will explore how intentional, human‑centered candidate experience can directly impact employer brand, hiring outcomes, and long‑term talent strategy, even with limited or no employer branding budget.\n\nI will share how Awin embeds company values into the recruitment journey, from candidate surveys to empowering employees as authentic brand ambassadors (Awinners). The session will highlight how platforms like Glassdoor to actively showcase culture, recognize employees, and hold the organization accountable, resulting in measurable employer brand recognition across all regions.\n\nA core focus of the talk is bringing the human back into Human Resources. I will cover how consistent communication, structured yet flexible interview processes, and ongoing hiring manager training contribute to better candidate outcomes in return, will positively impact the companies brand. I’ll share real candidate feedback and explain how we monitor trends, act on insights, and prioritize continuous improvement in an evolving job market.\n\nWe will address how to ensure candidates still have a positive experience even when the outcome is a rejection, including the long‑term value of “silver‑medalist” candidates.\n\nDrawing from my experience leading end‑to‑end recruitment across the U.S., Brazil, and Mexico, I will walk through an adaptable, evergreen recruitment process designed to respect candidates’ time, reduce assumptions, and build trust. The session will also explore how personal branding can strengthen employer branding, including how organic content helped amplify Awin’s visibility and employer reputation at scale.\n\nOverall, this session will demonstrate how a people‑first, partnership‑driven approach to talent can become a true competitive advantage for organizations navigating today’s hiring market.","starts_at":"2026-09-24T10:20:00-07:00","ends_at":"2026-09-24T10:50:00-07:00","stage":"Outdoor Stage","track":"Career, Culture & Community","type":"Career, Culture & Community","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Brittany Pollari - Sr. Talent Partner at Awin"],"tags":["Employer Branding","Talent & Recruiting"],"live_url":"https://www.youtube.com/watch?v=rwP4lYgFqL8","recording_url":"https://www.youtube.com/watch?v=rwP4lYgFqL8","app_url":"https://app.wearedevelopers.com/events/18/session/1106","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1807-from-candidate","urls":["https://www.youtube.com/watch?v=rwP4lYgFqL8"],"flag":null},{"id":1116,"title":"Alexander Varro and Alija Nuredini - Founders OS for replacing operational fragmentation","description":"Every tool solves a problem until it creates another one. What started as a simple search for better software turned into years of frustration, dozens of disconnected tools and one simple realization: managing software had become harder than managing the business itself. In this founder story, you'll discover how that frustration led to building Pistacio, a Founders OS platform designed to simplify operations for modern service companies and why reducing complexity could become the next major opportunity in B2B SaaS.","starts_at":"2026-09-24T11:00:00-07:00","ends_at":"2026-09-24T11:05:00-07:00","stage":"Outdoor Stage","track":"Startups & Innovation","type":"Startups & Innovation","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Alexander Varro - Co-Founder at 8reasons Digital GmbH","Alija Nuredini - Founder & CEO at Pistacio | 8reasons Digital"],"tags":["Anthropic","Business Models","Collaboration","Entrepreneurship","Internal Platforms","Startups","UI/UX","Venture Capital (VC)"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1116","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1797-alexander-varro-and","urls":[],"flag":null},{"id":1107,"title":"Building the Agentic Software Factory","description":"What does building a software factory for the era of agents look like? Join Thomas Dohmke (CEO and founder, Entire) and Matan Grinberg (CEO and cofounder, Factory) to discuss how the software development lifecycle must change to adapt to a world where agents are the primary producers of code. Drawing on their respective experience across the industry building independent, model agnostic platforms, the pair will lay out a shared vision for the future: From Git hosting, to multi-agent reviews, to the end of human code review altogether.","starts_at":"2026-09-24T11:00:00-07:00","ends_at":"2026-09-24T11:30:00-07:00","stage":"Mainstage","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Matan Grinberg - CEO & Co-Founder at Factory","Thomas Dohmke - CEO & Co-founder at Entire"],"tags":[],"live_url":"https://www.youtube.com/watch?v=Ohu9KNVofV4","recording_url":"https://www.youtube.com/watch?v=Ohu9KNVofV4","app_url":"https://app.wearedevelopers.com/events/18/session/1107","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1844-building-the-agentic","urls":["https://www.youtube.com/watch?v=Ohu9KNVofV4"],"flag":null},{"id":1108,"title":"Building AI for the Physical World","description":"AI is moving out of the datacenter and into devices, vehicles, and machines. Building for the physical world is different from building for the cloud: compute and power are constrained, connectivity is not guaranteed, and shipping an update means reaching hardware in the field. What matters when building, deploying, and running AI under these conditions.","starts_at":"2026-09-24T11:00:00-07:00","ends_at":"2026-09-24T11:30:00-07:00","stage":"Tech Leaders Stage","track":"Physical AI","type":"Physical AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Alex Spinelli - Senior VP AI & Developer Platforms at Arm","Eystein Stenberg - CTO at NorthernTech","Gerardo Pardo-Castellote - CTO at RTI","Tomislav Tipurić - CTO & CEO at Nephos","Joseph Nelson - Co-founder & CEO at Roboflow"],"tags":[],"live_url":"https://www.youtube.com/watch?v=2cRbVs1nSYU","recording_url":"https://www.youtube.com/watch?v=2cRbVs1nSYU","app_url":"https://app.wearedevelopers.com/events/18/session/1108","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1840-building-ai-for-the","urls":["https://www.youtube.com/watch?v=2cRbVs1nSYU"],"flag":null},{"id":1109,"title":"Application-Defined Compute: Rethinking Infrastructure for AI Applications","description":"AI applications don't have fixed infrastructure requirements. A single request can fan out into hundreds of long-running tasks with different runtimes, memory requirements, and execution times. The application is no longer just consuming infrastructure. It defines the infrastructure it needs at runtime.\n\nIn this talk, Render CEO Anurag Goel introduces Application-Defined Compute, a new infrastructure model built for AI-native applications. You'll learn why traditional serverless platforms and self-managed orchestration both break down at scale, and how developers can provision compute just in time, run long-lived stateful workloads, and execute tasks with the flexibility of real servers, without managing queues, worker pools, retries, or orchestration themselves.\n\nUsing Render Workflows as an example, the session explores the new infrastructure primitives emerging for AI-native applications and how cloud platforms are evolving to support them.","starts_at":"2026-09-24T11:00:00-07:00","ends_at":"2026-09-24T11:30:00-07:00","stage":"Stage 1","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Anurag Goel - Founder & CEO at Render"],"tags":["AI Models","Agents","Agentic AI","Infrastructure","Infrastructure as Code (IaC)"],"live_url":"https://www.youtube.com/watch?v=sOIX8mjY5Fk","recording_url":"https://www.youtube.com/watch?v=sOIX8mjY5Fk","app_url":"https://app.wearedevelopers.com/events/18/session/1109","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1836-application-defined","urls":["https://www.youtube.com/watch?v=sOIX8mjY5Fk"],"flag":null},{"id":1110,"title":"From Stateless to Stateful: Real-Time Voice & Messaging Agents with Twilio   and AWS","description":"We have all had that maddening customer service experience: you text a support line about a delayed flight, receive a confirmation, but when you call in a minute later, the voice agent asks, \"How can I help you today?\" completely blind to the SMS you just sent. This is the \"Channel Amnesia\" problem.\n\nWhile businesses are pouring billions into generative AI, most agents are still built on stateless architectures that forget customer context the second a session ends.\n\nIn this session, we will cure AI amnesia. You will learn how to orchestrate stateful, production-grade AI agents across SMS and Voice using Twilio Agent Connect and Amazon Bedrock. We will dive into why traditional serverless compute fails stateful agents, how to leverage AWS Fargate for isolated, long-lived sessions, and how to configure Bedrock AgentCore over WebSockets to hit sub-50ms streaming voice latency. No slide-ware here — expect a live, cross-channel demo and open-source code you can deploy tomorrow.","starts_at":"2026-09-24T11:00:00-07:00","ends_at":"2026-09-24T11:30:00-07:00","stage":"Stage 2","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Rishab Kumar - Staff Developer Evangelist AI at Twilio"],"tags":["AWS","AWS Lambda","Generative AI (GenAI)","Microservices"],"live_url":"https://www.youtube.com/watch?v=jbIVjoWrrto","recording_url":"https://www.youtube.com/watch?v=jbIVjoWrrto","app_url":"https://app.wearedevelopers.com/events/18/session/1110","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1853-from-stateless-to","urls":["https://www.youtube.com/watch?v=jbIVjoWrrto"],"flag":null},{"id":1111,"title":"Making Science Larger, not just Faster","description":"The dominant framing of enterprise AI is speed: faster code, faster decisions, faster discovery. That framing misses the larger story. When AI is anchored to the equations of physics, chemistry and biology rather than to the corpus of the open web, it does not just compress timelines — it expands the space of what can be explored. A bigger biochemical landscape for drug discovery. A bigger materials landscape for batteries and alloys. A bigger design landscape for everything humans build. Drawing on SandboxAQ's deployments across pharma, energy and navigation, Yuval shows why Large Quantitative Models are the first AI architecture capable of growing the pie rather than slicing it thinner, and what that means for any enterprise still measuring AI value in cost reduction.","starts_at":"2026-09-24T11:00:00-07:00","ends_at":"2026-09-24T11:30:00-07:00","stage":"Stage 3","track":"Leadership & Strategy","type":"Leadership & Strategy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Yuval Dvir - Commercial Executive at SandboxAQ"],"tags":["AGI (Artificial General Intelligence)"],"live_url":"https://www.youtube.com/watch?v=kl-KLZxI-5A","recording_url":"https://www.youtube.com/watch?v=kl-KLZxI-5A","app_url":"https://app.wearedevelopers.com/events/18/session/1111","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1702-making-science","urls":["https://www.youtube.com/watch?v=kl-KLZxI-5A"],"flag":null},{"id":1112,"title":"From Voice Demo to Enterprise Production","description":"Building a Voice AI demo takes a weekend; production engineering is a different beast. This session delivers the architectural playbook for scaling resilient, enterprise-grade voice agents.\nWe will evaluate speech-to-speech versus modular (STT → LLM → TTS) pipelines, WebRTC stacks, and hybrid topographies for strict data residency. You will learn fast-brain/slow-brain UX patterns to keep turn-taking responsive while backends process tool calls, alongside strategies for runtime model switching and custom vocabulary.\nWalk away with the exact trade-offs, patterns, and metrics needed to operate low-latency voice pipelines at scale.","starts_at":"2026-09-24T11:00:00-07:00","ends_at":"2026-09-24T11:30:00-07:00","stage":"Stage 4","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Anahita Havewala - Expert Development Architect Office of the CTO at SAP","Anuj Gupta - Principal Architect at SAP"],"tags":["Agents"],"live_url":"https://www.youtube.com/watch?v=OYEA3jV721E","recording_url":"https://www.youtube.com/watch?v=OYEA3jV721E","app_url":"https://app.wearedevelopers.com/events/18/session/1112","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1924-from-voice-demo-to","urls":["https://www.youtube.com/watch?v=OYEA3jV721E"],"flag":null},{"id":1113,"title":"The Missing Infrastructure for AI Agents","description":"Everyone can build an AI agent. Almost nobody knows how to run thousands of them safely in production.\n\nOver the past two years, we've watched AI agents evolve from demos into software that writes code, answers customers, automates workflows, and makes decisions. The challenge has shifted from building smarter agents to operating them reliably at scale.\n\nHaving spent time at Meta and Google and now helping lead Guild.ai, CTO and co-founder Chris Waterson has seen firsthand where production systems fail. It's rarely the model. It's the surrounding infrastructure: context management, permissions, observability, cost controls, versioning, evaluation, and governance.\n\nThis session explores what changes when AI agents become real production systems instead of prototypes. He'll draw on lessons from building Guild Software Factory, a system of specialized agents that plans, implements, reviews, and maintains work across a codebase, and Guild Optimizer, which automatically tests cheaper agent configurations against production history to cut costs without sacrificing quality.\n\nAttendees will leave with practical frameworks for designing AI agent systems that are observable, secure, reusable, and capable of evolving over time, not just impressive during a demo.\n\nWhether you're building your first agent or managing hundreds across an organization, this talk offers lessons from operating AI where reliability matters.","starts_at":"2026-09-24T11:00:00-07:00","ends_at":"2026-09-24T11:30:00-07:00","stage":"Stage 5","track":"AI Models & Infrastructure","type":"AI Models & Infrastructure","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Chris Waterson - CTO at Guild.ai"],"tags":["AI Coding Assistants","Developer Experience (DevEx)","Generative AI (GenAI)","Infrastructure","Product Strategy","Productivity","Software Architecture"],"live_url":"https://www.youtube.com/watch?v=bEbqDj0ZdH8","recording_url":"https://www.youtube.com/watch?v=bEbqDj0ZdH8","app_url":"https://app.wearedevelopers.com/events/18/session/1113","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1928-the-missing","urls":["https://www.youtube.com/watch?v=bEbqDj0ZdH8"],"flag":null},{"id":1114,"title":"Accelerating development and managing agents with the GitHub Copilot app","description":"Built from the ground up as a native AI coding tool, the GitHub Copilot app integrates with your work and workflow. From triaging issues, managing agents, and creating interactive canvases, you can build, review, and deploy all from one location! Let's explore how to accelerate your dev flow and get the most out of the tool.","starts_at":"2026-09-24T11:00:00-07:00","ends_at":"2026-09-24T11:30:00-07:00","stage":"Stage 6","track":"DevEx & Productivity","type":"DevEx & Productivity","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Christopher Harrison - Senior Developer Advocate at GitHub"],"tags":["AI Coding Assistants","AI Models","Copilot","GitHub"],"live_url":"https://www.youtube.com/watch?v=VILGGp5Y8-g","recording_url":"https://www.youtube.com/watch?v=VILGGp5Y8-g","app_url":"https://app.wearedevelopers.com/events/18/session/1114","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1783-accelerating","urls":["https://www.youtube.com/watch?v=VILGGp5Y8-g"],"flag":null},{"id":1207,"title":"Responsible AI Architecture with Zero Trust Agents","description":"As we shift from simple chatbots to long-running agents, we face a critical engineering challenge. The risk is no longer just bad output. It is memory poisoning. This occurs when malicious data permanently corrupts your vector database, causing agents to hallucinate or leak private information indefinitely.\n\nThis session will present a Zero Trust architecture for Responsible AI starting prompt injection until agent isolation. We will dissect a reference stack built entirely on open source standards that treats your vector storage as a high-security vault.\n\nAttendees will walk away with practical techniques to: Replace risky API keys with cryptographic verification using SPIFFE and SPIRE, ensuring only valid code can access long-term memory.\n\nUse policies to write security rules as code, separating your safety logic from your application logic. Block sensitive data and malicious prompts before they are ever stored using tools like Microsoft Presidio.\n\nJoin me to learn how to build agents that are resilient, audit-ready, and secure by design.","starts_at":"2026-09-24T11:00:00-07:00","ends_at":"2026-09-24T11:30:00-07:00","stage":"Stage 7","track":"AI Trust & Safety","type":"AI Trust & Safety","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ashok Prakash - Staff ML Engineer at Apple"],"tags":["AI Standards","Agentic AI","Generative AI (GenAI)"],"live_url":"https://www.youtube.com/watch?v=BXT68AeyWI0","recording_url":"https://www.youtube.com/watch?v=BXT68AeyWI0","app_url":"https://app.wearedevelopers.com/events/18/session/1207","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1430-responsible-ai","urls":["https://www.youtube.com/watch?v=BXT68AeyWI0"],"flag":null},{"id":1117,"title":"Build and deploy a personal agent on a Cloud Run instance","description":"How do you run an autonomous AI agent in the cloud 24/7 without wasting a fortune or managing servers? If you are building long-running agents, you know the hosting dilemma: standard serverless platforms scale to zero, which instantly kills your background loops and wipes your agent's active memory. Dedicated VMs keep the agent awake, but they cost more and leave you stuck managing the infrastructure. The fix is a new compute primitive: Cloud Run instances. In this hands-on workshop, you will learn how to deploy a single, always-on container to host a continuous background agent. Stepping into the role of a coffee shop manager, you will build an AI assistant using the Agent Development Kit (ADK) that continuously analyzes business data. You will also leverage Cloud Run sandboxes, enabling your agent to dynamically write, execute, and test code on the fly to solve complex problems safely. Stop managing infrastructure and start building agents that never sleep!","starts_at":"2026-09-24T11:00:00-07:00","ends_at":"2026-09-24T13:00:00-07:00","stage":"Stage 8","track":"AI Models & Infrastructure","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"Laptop & charger","speakers":["Shir Meir Lador"],"tags":["AI Models","DevOps","Google Cloud (GCP)","Retrieval-Augmented Generation (RAG)"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1117","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1814-build-and-deploy-a","urls":[],"flag":null},{"id":1118,"title":"Creating and Sustaining Positive Communities","description":"Maezza Romero, Community Developer for Romero Games, has been shaping communities from the ground up for 6+ years. She started her journey in 2018 with Cyber Squad for Hewlett Packard Enterprises and the Girl Scouts, and now manages social media and a 6,000+ member Discord for Romero Games, one of the friendliest shooter communities in the industry. Her passion? Ensuring everyone feels valued and welcome.\n\nJoin Maezza to discover the strategies behind building inclusive, engaged communities. She’ll share tips on authentic engagement, moderation best practices, and laying the groundwork for communities that stand the test of time. This workshop is suitable for those working in both game development and general business, with practical insights that can be applied across a range of industries.","starts_at":"2026-09-24T11:00:00-07:00","ends_at":"2026-09-24T13:00:00-07:00","stage":"Stage 13","track":"Career, Culture & Community","type":"Workshop","live_coding":false,"is_workshop":true,"capacity":36,"waitlist":5,"requirements":"","speakers":["Maezza Romero - Community Manager at Romero Games"],"tags":["Accessibility","Advocacy","Communication","Community","Marketing","Xamarin"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1118","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1911-creating-and","urls":[],"flag":null},{"id":1119,"title":"The AI-Native Engineer: From Business Problem to Prototype","description":"How well you scope a problem determines how well AI can help you solve it. This workshop makes that claim testable, not just believable. \n\nBring your laptop and the AI tools you already use. Teams take on a real, messy business challenge — a live-service gaming company caught between an AI feature its CEO already announced and the fragile data foundation that feature would actually run on. Before building anything, each team is randomly assigned exactly one stakeholder to interview. What they hear — and how well they turn it into a scoped, defensible approach — is the variable we're testing. \n\nFrom there, teams use their own tools and AI to build a working solution slice with AI as a genuine collaborator throughout. We instrument the build: prompts submitted, iterations to a working version, time to first pass. At the reveal, we show the correlation directly: teams that scoped tightly from partial information moved faster and cleaner with AI than teams that tried to build before they'd committed to an approach. \n\nEvery participant leaves with a personal build card — their own scoping-to-efficiency numbers next to the room's benchmark — and a sharper instinct for a skill AI hasn't replaced: knowing what problem you're actually solving, from an incomplete picture, before you start.","starts_at":"2026-09-24T11:00:00-07:00","ends_at":"2026-09-24T13:00:00-07:00","stage":"Stage 10","track":"Applied AI","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"","speakers":["Srishti Agrawal - Senior Product Manager at PwC US","Sidarth Aurora - Director, Engineering & AI at PwC"],"tags":["AI Coding Assistants","Agentic AI","Career Development","Code Generation","Collaboration","Communication","Gaming","Generative AI (GenAI)","Product Strategy","Product Management","Prompt Engineering"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1119","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1945-the-ai-native","urls":[],"flag":null},{"id":1120,"title":"RoboCoders: Judgment Day: AI-Assisted Engineering Applied - The Battle of Agents","description":"Agentic AI-assisted engineering tools promise cleaner code, faster development, and fewer late-night debugging sessions. But do they truly deliver?\n\nIn this live showdown, Viktor and Baruch will each use a different set of cutting-edge AI coding tools, like an IDEs and CLI agents (we'd name them, but honestly, things move too fast in this space), to develop a non-trivial IoT application, from initial setup to testing and debugging, all live on stage.\n\nWill the IoT bulb turn on by the end of the session, and which tool will make it happen? You don't know, we don't know, but we'll find out together—live on stage.\n\nYou, the audience, decide which tool actually improves quality and productivity and which just adds noise instead of useful code. Bring your skepticism, cast your vote, and get ready for surprises.","starts_at":"2026-09-24T11:00:00-07:00","ends_at":"2026-09-24T13:00:00-07:00","stage":"Stage 9","track":"DevEx & Productivity","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":36,"waitlist":5,"requirements":"","speakers":["Baruch Sadogursky - Member of DevRel Staff at Tessl AI","Viktor Gamov - Principal Developer Advocate at Confluent"],"tags":["AI Coding Assistants","AI Models","AI Standards"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1120","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1697-robocoders-judgment","urls":[],"flag":null},{"id":1121,"title":"Exploring MCP Servers with GitHub Copilot","description":"Model Context Protocol (MCP) is an open standard that lets AI agents like GitHub Copilot tap into external tools, services, and your own account data. In this hands-on workshop, you'll connect GitHub Copilot to both public and authenticated MCP servers, explore the tools they expose, and put them to work—researching topics, troubleshooting issues, and making real contributions to a codebase. You'll also discover how combining MCP servers with agent skills unlocks more powerful, personalized developer workflows.","starts_at":"2026-09-24T11:00:00-07:00","ends_at":"2026-09-24T13:00:00-07:00","stage":"Stage 12","track":"Applied AI","type":"Workshop","live_coding":false,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"Attendees should bring a fully charged laptop, and already have a GitHub account. Attendees will all have the option to complete the workshop using GitHub Codespaces, a browser-based VS Code environment, but they may also want to download the GitHub Copilot CLI and GitHub Copilot App on their machine beforehand, so that they can try all forms of Copilot.","speakers":["Pamela Fox - Principal Cloud Advocate at Microsoft"],"tags":["Agentic AI","Copilot","GitHub"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1121","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1848-exploring-mcp","urls":[],"flag":null},{"id":1122,"title":"Ducks, Sensors, and Agents","description":"By the end of this workshop, attendees will be able to:\n\n1. Describe the end-to-end edge AI workflow, using agentic AI coding throughout: \n\n(a) Collect data and label images with bounding boxes; \n(b) Design a machine learning model with Edge Impulse; \n(c) Train and test the model; \n(d) Create a reusable Edge Impulse skill for the AI agent, capturing the workflow conventions (API usage, project structure, deployment steps) so the agent can reliably assist on future\nEdge AI projects.\n\n2. Re-train an object detection model on a custom \"rubber ducks\" dataset:\n\n(a) Test the new model on your mobile phone, using the camera and the browser; \n(b) Deploy on an Arduino UNO Q with the App Lab integration, using the AI agent (with the Edge Impulse skill) to generate and\niterate on the application code — camera capture, inference loop, and output handling; \n(c) Run and test the model on the Arduino UNO Q, prompting the agent to debug errors and add features (e.g., counting\nducks, triggering an output on detection, etc.).","starts_at":"2026-09-24T11:00:00-07:00","ends_at":"2026-09-24T13:00:00-07:00","stage":"Stage 14","track":"Physical AI","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"What to bring:\r\n\r\nA laptop with a USB-C port.\r\nA smartphone with a camera.\r\nA USB-C cable to connect the Arduino UNO Q to your laptop.","speakers":["Brian McFadden - Staff Engineer, Developer Relations at Qualcomm"],"tags":["AI Coding Assistants","Agentic AI","Arduino","Edge AI","Embedded Systems","Internet of Things (IoT)"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1122","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1803-ducks-sensors-and","urls":[],"flag":null},{"id":1123,"title":"Architecting the 100X SDLC: Building Production Trust into AI-Assisted Delivery","description":"AI-assisted development has made it astonishingly easy to produce software — and astonishingly hard to trust it. Demos ship in hours, but production demands more: auditability, verifiability, cost control, and the delivery discipline enterprises have spent decades refining.\n\nThis session begins by clarifying the terminology now shaping the industry — SDLC, AI-Assisted SDLC, and ADLC— and what actually changes when AI agents become first-class participants in software delivery rather than autocomplete on the side.\n\nWe then share hard-won lessons from building the VibeFlow, a 9 persona AI team for producing production-quality software through AI-assisted development. VibeFlow structures specialized agents into a governed team that operates inside familiar Scrum and Kanban constructs: backlogs, sprints, reviews, and definitions of done. The result is AI velocity that remains observable, auditable, and verifiable at every stage.\n\nAttendees will learn the design principles that made this work in practice: why governance must be architected in rather than bolted on; how work-item traceability makes AI output verifiable instead of merely plausible; how cost controls and guardrails keep agent teams economically predictable; and how marrying agents to agile ceremonies turns impressive demos into dependable delivery.\n\nWhether you're an engineering leader evaluating AI adoption, an architect designing for it, or a practitioner already shipping with AI, you'll leave with a concrete blueprint for moving from vibes to verifiable — and from X to 100X — without sacrificing the trust production demands.","starts_at":"2026-09-24T11:10:00-07:00","ends_at":"2026-09-24T11:15:00-07:00","stage":"Outdoor Stage","track":"Startups & Innovation","type":"Startups & Innovation","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ranjan Parthasarathy - Founder & CPTO/CEO at AXIOMSTUDIO.AI"],"tags":["AI Coding Assistants","Agentic AI","Secure Coding","Test-Driven Development (TDD)","Vibe Coding"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1123","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1826-architecting-the","urls":[],"flag":null},{"id":1124,"title":"Finding the Edges: Testing, Evaluating, and Monitoring Voice AI Agents Before Your Users Do","description":"Every demo of a voice AI agent looks great — until real users start talking. They interrupt, mumble, switch languages mid-sentence, and ask the one question that sends the agent off the rails. Traditional scripted QA only verifies the behaviors you already thought of, which is exactly why so many voice agents fail in production in ways their teams never saw coming.\n\nThis session walks through a practical, engineering-grade approach to shipping Voice AI agents you can trust, built on three pillars: simulation, evaluation, and monitoring. You'll see how synthetic \"drivers\" — AI-powered simulated users with distinct personalities, goals, and contexts — hold realistic multi-turn conversations with your agent across 30+ languages and real-world audio conditions (noise, crosstalk, clipping), actively exploring the edges scripted tests miss. We'll then look at how judge-based, symbolic, and audio evaluations turn those discoveries into CI/CD release gates, so a change that degrades conversation quality fails the build before it reaches users. Finally, we'll close the loop with production monitoring that captures real failures and automatically converts them into regression tests — so the same mistake never ships twice.\n\nYou'll leave with a concrete blueprint for finding the edges of your Voice AI agent before your customers do.","starts_at":"2026-09-24T11:20:00-07:00","ends_at":"2026-09-24T11:25:00-07:00","stage":"Outdoor Stage","track":"Startups & Innovation","type":"Startups & Innovation","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Matt Wyman - CEO at Okareo"],"tags":["AI Models","Agents","Agentic AI","Observability","Testing"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1124","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1849-finding-the-edges","urls":[],"flag":null},{"id":1125,"title":"Loominus Studio: The AI Workbench for Labs and Factories","description":"Most AI agents move files. Ours run machines.\n\nLoominus Studio is an AI workbench. You use it to build agents that work alongside people to design and make real things: materials, formulations, devices. The jargon for this is collaborative cyber-physical agents. The plain version is agents with hands.\n\nWhat you build is a harness. A harness is everything an agent needs to do real work: the tools it can reach, the steps it follows, what it remembers, what it is allowed to touch. Coding agents have harnesses. That is why they work. Labs and factories have none.\n\nYou build one by wiring nodes into a graph. Each node is a step or a tool: run this machine, mix this batch, ask a person to check, measure the result, pick what to try next. Wire them together and the agent runs the loop.\n\nTwo things matter about these harnesses.\n\nConfigurable: no two labs work the same way, so you build yours instead of buying someone else's.\n\nPortable: build it once, run it on someone else's machines. Your process should not be locked to one vendor's box.\n\nWe use it ourselves. MetaLab is a harness for making formulations. BioLoom is a harness for printing parts. Same workbench, different graph.\n\nFive minutes on why the loop that made coding agents work is the same loop every lab runs, why nobody built the workbench for it, and what that changes for the bioeconomy age, when the things ahead of us have to be made, not just written.","starts_at":"2026-09-24T11:30:00-07:00","ends_at":"2026-09-24T11:35:00-07:00","stage":"Outdoor Stage","track":"Startups & Innovation","type":"Startups & Innovation","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Filippos Tourlomousis - Founder at Biological Lattice Industries (BLI)"],"tags":["Agentic AI"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1125","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1766-loominus-studio-the","urls":[],"flag":null},{"id":1134,"title":"One Environment, N Machines: Deterministic Builds for Humans and Agents","description":"Software used to be built in a handful of places you controlled. Now it's built everywhere: a laptop, a fleet of CI runners, a local sandbox, a remote sandbox with an agent driving it. Increasingly, nobody sets those machines up by hand. Two hard problems fall out of this: making the build produce the same result on every machine, and making the output of that build reproducible wherever it runs next. This talk looks at how deterministic, declarative environments (built on Nix) solve both: one definition that pins packages, toolchains, and even agent skills, reproduced bit-for-bit across the lifecycle, with a verifiable record of everything that went in. We'll show how Flox makes this practical without requiring your team to learn Nix.","starts_at":"2026-09-24T11:40:00-07:00","ends_at":"2026-09-24T11:45:00-07:00","stage":"Outdoor Stage","track":"Startups & Innovation","type":"Startups & Innovation","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["James Bayer - Product Leader at Flox","Morgan Helton - Software Engineer at Flox"],"tags":["AI Standards","CI/CD","Cross-Platform","Developer Experience (DevEx)","DevOps","DevSecOps","SBOM","Security","Tooling","Tools"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1134","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1813-one-environment-n","urls":[],"flag":null},{"id":1126,"title":"I Don't Trust AI Agents (And Neither Should You): Building Production-Ready Architectures","description":"Your AI agent works great in the demo. Then you deploy it and it hallucinates a refund policy, exposes customer data, or just loops endlessly burning tokens. This session walks through a layered approach to agent safety using tools like Amazon Bedrock AgentCore and the Strands Agents SDK: guardrails, observability, multi-agent safety patterns, and reference architectures you can adapt immediately.","starts_at":"2026-09-24T11:40:00-07:00","ends_at":"2026-09-24T12:10:00-07:00","stage":"Mainstage","track":"AI Agents","type":"AI Agents","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Darko Mesaros - Distinguished Developer Advocate at AWS"],"tags":["AI Standards","AWS","Agents","Agentic AI","Developer Experience (DevEx)","Observability","Scaling"],"live_url":"https://www.youtube.com/watch?v=4gabKOun0Ys","recording_url":"https://www.youtube.com/watch?v=4gabKOun0Ys","app_url":"https://app.wearedevelopers.com/events/18/session/1126","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1772-i-don-t-trust-ai","urls":["https://www.youtube.com/watch?v=4gabKOun0Ys"],"flag":null},{"id":1127,"title":"Rethinking Developer Tools for the Agent Era","description":"AI agents are becoming heavy users of developer tools: reading documentation, operating platforms, writing and shipping code. Tools designed around human attention - interfaces, docs, onboarding - behave differently when the one using them is software. Companies across the stack now serve humans and machines at once, and the choices go to the core of the product. What changes when agents become users, and what it means for the people building with them.","starts_at":"2026-09-24T11:40:00-07:00","ends_at":"2026-09-24T12:10:00-07:00","stage":"Tech Leaders Stage","track":"DevEx & Productivity","type":"DevEx & Productivity","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Han Wang - Co-founder & CEO at Mintlify","Sam Bhagwat - Founder and CEO at Mastra","Ben Haefele - Chief Product Officer at Webflow","Ignacio Riesgo - Senior Director Developer Relations at IBM"],"tags":[],"live_url":"https://www.youtube.com/watch?v=L9gOR6qKhAo","recording_url":"https://www.youtube.com/watch?v=L9gOR6qKhAo","app_url":"https://app.wearedevelopers.com/events/18/session/1127","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1877-rethinking-developer","urls":["https://www.youtube.com/watch?v=L9gOR6qKhAo"],"flag":null},{"id":1128,"title":"The Next Wave of Agents: What’s Real, What’s Next, and What Matters","description":"Artificial intelligence is undergoing a foundational shift from passive, generative model outputs toward goal-oriented, autonomous operational execution. Agentic AI represents an architectural evolution beyond static prompt-response systems, combining reasoning, memory, planning, and external tool execution to act independently within complex environments. Further, organizations face real-world challenges in reliability, safety, governance, and system orchestration. In this panel, we will discuss what the current capabilities of agentic systems and how its impact is measured. We will also discuss architectural breakthroughs driving next wave of agents which consists of multi-agent collaboration, tool integration and persistent memory how to move agents from pilots to production. Lastly, the discussion will map out what lies ahead for leader navigating the transition to an agentic future.","starts_at":"2026-09-24T11:40:00-07:00","ends_at":"2026-09-24T12:10:00-07:00","stage":"Stage 1","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Mitesh Patel - Developer Advocate & Manager at NVIDIA Corporation","Chi Wang - Co-founder at AG2","Jay Rodge - Senior Developer Advocate at NVIDIA","Joe Moura - Founder at CrewAi"],"tags":["Agents","Agentic AI","Multi-Agent Systems"],"live_url":"https://www.youtube.com/watch?v=3kf2hYgMURw","recording_url":"https://www.youtube.com/watch?v=3kf2hYgMURw","app_url":"https://app.wearedevelopers.com/events/18/session/1128","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1878-the-next-wave-of","urls":["https://www.youtube.com/watch?v=3kf2hYgMURw"],"flag":null},{"id":1129,"title":"Stop Running Mystery Meat in Production","description":"We have all been there. You need a database or a quick node environment, so you throw \"FROM node:latest\" into your Dockerfile and deploy. It works, but you have just introduced a black box into your Kubernetes cluster.\n\nFor the Developer, it’s a quick fix. For the Platform Engineer, it’s a nightmare.\n\nMost upstream images from public registries are a roll of the dice. They come pre-packed with critical vulnerabilities, unknown binaries, and bloated libraries that you didn’t ask for and definitely don’t want running in your secure environment. In a world of Zero Trust, why are we trusting random upstream maintainers with the keys to our infrastructure?\n\nIn this session, we will dismantle the myth that \"open source means secure\" when it comes to container images. We will walk through the architecture of a truly Secure Software Delivery pipeline—one that establishes trust before a single line of code is committed. We will discuss:\n\n- The hidden dangers inside popular \"official\" images.\n- Moving beyond basic scanning: Why you need SLSA L3 provenance, SBOMs, and cryptographic attestation.\n- The \"Build vs. Buy\" dilemma: Should you curate your own base images or rely on a hardened upstream provider?\n\nJoin us to learn how to bridge the gap between developer velocity and platform security, ensuring that the only thing running in your cluster is code you actually trust.","starts_at":"2026-09-24T11:40:00-07:00","ends_at":"2026-09-24T12:10:00-07:00","stage":"Stage 3","track":"DevOps & Platform Engineering","type":"DevOps & Platform Engineering","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Jeroen van Erp - Principal Technical Advocate at SUSE"],"tags":["Developer Experience (DevEx)","Security"],"live_url":"https://www.youtube.com/watch?v=PWnEW2v4HQU","recording_url":"https://www.youtube.com/watch?v=PWnEW2v4HQU","app_url":"https://app.wearedevelopers.com/events/18/session/1129","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1726-stop-running-mystery","urls":["https://www.youtube.com/watch?v=PWnEW2v4HQU"],"flag":null},{"id":1130,"title":"Taming Rogue Agents: Observability-Driven Evaluation for Production Reliability","description":"Moving from a viral demo to reliable enterprise AI is the hardest hurdle in modern software engineering. Because agents are inherently non-deterministic, validating performance requires a granular look at the \"why\" and \"how\" behind every action. \n\nThis session explores how observability redefines agentic evaluation beyond binary pass/fail testing, shifting the focus from the result to the entire reasoning chain. Featuring a live demo using Arize Phoenix and LangGraph, we’ll showcase how to trace complex loops and automate evaluations in real-time. \n\nWhat you’ll learn: \n\nBeyond Output: Why judging final answers alone is a recipe for silent failure. \n\nLive Implementation: Using Arize Phoenix with LangGraph to visualize traces and debug agentic \"thought processes\". \n\nThe Playbook: An incremental framework for evaluation-first development. \n\nAre you ready to stop guessing and start measuring? Join us to master the art of agent evaluation.","starts_at":"2026-09-24T11:40:00-07:00","ends_at":"2026-09-24T12:10:00-07:00","stage":"Stage 4","track":"Security & Privacy","type":"Security & Privacy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Anagha Rumade - Applied AI/ML Lead at JPMorgan Chase","Anjana Umapathy - Applied AI/ML Lead & VP at JPMorgan Chase","Apoorva Jaiswal - Applied AI/ML Lead at JPMorgan Chase"],"tags":["Agents","Agentic AI","Generative AI (GenAI)","LangChain","Large Language Models (LLMs)","Multi-Agent Systems","Observability","OpenAI","Python"],"live_url":"https://www.youtube.com/watch?v=w1MKtTCTvAU","recording_url":"https://www.youtube.com/watch?v=w1MKtTCTvAU","app_url":"https://app.wearedevelopers.com/events/18/session/1130","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1768-taming-rogue-agents","urls":["https://www.youtube.com/watch?v=w1MKtTCTvAU"],"flag":null},{"id":1131,"title":"Your Agents Need Observability Before They Need Better Models","description":"Everyone's chasing faster models, better reasoning, shinier inference endpoints. But here's the truth: your agent will fail in production long before model quality becomes your bottleneck.\n\nThe problem isn't the model. It's that you can't see what your agent is actually doing.\n\nIn this session we cover why traditional observability breaks for agent workloads, how OpenTelemetry and GenAI semantic conventions give you the vocabulary to instrument agents correctly, and how observability becomes the thing that lets you gradually trust your agents with more autonomy. You'll walk away knowing what to instrument, why it matters, and how to stop guessing when your agent does something unexpected in production.","starts_at":"2026-09-24T11:40:00-07:00","ends_at":"2026-09-24T12:10:00-07:00","stage":"Stage 5","track":"DevOps & Platform Engineering","type":"DevOps & Platform Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Julia Furst Morgado - Principal Developer Relations Engineer at Dash0"],"tags":["DevOps","Generative AI (GenAI)","Large Language Models (LLMs)","Observability","OpenTelemetry"],"live_url":"https://www.youtube.com/watch?v=QonS7Yc2HN8","recording_url":"https://www.youtube.com/watch?v=QonS7Yc2HN8","app_url":"https://app.wearedevelopers.com/events/18/session/1131","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1825-your-agents-need","urls":["https://www.youtube.com/watch?v=QonS7Yc2HN8"],"flag":null},{"id":1132,"title":"AI ROI: The Hard Unit Economics of AI-Native Engineering","description":"The honeymoon phase of AI is over.\n\nOrganizations across all industries have spent the last two years buying licenses and experimenting, but boards and CFOs in the 2026 fiscal year are demanding proof of value. For CTOs and VPs of Engineering, the challenge has shifted from \"how do we build this?\" to a critical fiscal responsibility: showing a measurable return on AI investment.\n\nThe bottleneck isn't the model; it’s the middleware of the human process. Too many organizations are automating tasks (AI-Augmented) while leaving the topology of their engineering organizations untouched. To capture true ROI, we must shift to AI-Native Engineering, where the SDLC is architected around probabilistic capabilities rather than deterministic checklists.\n\nIn this session, Manu will help teams learn how to move past \"productivity vibes\" and into measurable ROI. Manu will break down the “Efficiency Trap”: the phenomenon where AI generates code faster, but testing, security, and deployment bottlenecks remain static, resulting in zero net gain in system throughput. \n\nAdditionally, Manu will present a framework for evaluating ROI at every stage of the product lifecycle and show attendees how they can move their metrics from \"PRs per day\" to \"Outcome Velocity\", in short, reduce the “Lead Time to Value.”\n\nThe 4-Stage ROI Lifecycle\n\n- Discovery (The Intent Stage): ROI of using AI to bridge the \"Context Gap\" between Product, Design and Engineering.\n\n- Development (The Build/Composition Stage): Measuring \"Unit Cost of Code\" to ensure high-velocity output doesn't increase downstream maintenance costs.\n\n- Verification (The Quality Stage): ROI of shifting from manual QA to \"Automated Eval\" stacks.\n\n- Operations (The Resilience Stage): The financial impact of AI-driven observability, self-healing systems, and the automation of the Support-to-Engineering feedback loop.","starts_at":"2026-09-24T11:40:00-07:00","ends_at":"2026-09-24T12:10:00-07:00","stage":"Stage 6","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Manu Gurudatha - VP of Engineering at PagerDuty"],"tags":["Digital Transformation","DORA Metrics","Generative AI (GenAI)"],"live_url":"https://www.youtube.com/watch?v=7fntZMchO4M","recording_url":"https://www.youtube.com/watch?v=7fntZMchO4M","app_url":"https://app.wearedevelopers.com/events/18/session/1132","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1687-ai-roi-the-hard-unit","urls":["https://www.youtube.com/watch?v=7fntZMchO4M"],"flag":null},{"id":1133,"title":"Clean Rooms Demystified: Architecture and Patterns for Privacy-Safe Data Collaboration","description":"As enterprises increasingly look to combine data with partners, suppliers, and platforms to power AI, analytics, and personalization — without exposing raw records or violating privacy regulations — Clean Rooms have moved from an emerging concept to a serious architectural option. But most teams encounter them first through vendor documentation and demos that skip the hard parts.\n\nThis session starts from first principles. It explains the core problem Clean Rooms solve: enabling joint computation across datasets from multiple parties without any party accessing the other's raw data. It then walks through the architectural building blocks — controlled computation environments, output restrictions, access control policies, and the cryptographic boundaries that make privacy guarantees enforceable — and shows how these concepts translate into real design decisions.\n\nFrom there, the session takes an honest look at the implementation landscape. Attendees will understand how Clean Rooms compare to alternative privacy-enhancing approaches — federated learning, differential privacy, synthetic data, and contractual anonymization — and the trade-offs each involves across privacy strength, latency, operational complexity, and regulatory defensibility. The session also covers where production complexity tends to concentrate: access control configuration, output data governance, deployment automation, and integration with AI and ML workloads.\n\nAttendees leave with a clear mental model for evaluating Clean Rooms against their own organization's data collaboration challenges, a practical understanding of the architectural patterns involved, and an honest view of what separates a well-designed Clean Rooms implementation from one that looks good in a proof of concept but struggles in production.","starts_at":"2026-09-24T11:40:00-07:00","ends_at":"2026-09-24T12:10:00-07:00","stage":"Stage 7","track":"Security & Privacy","type":"Security & Privacy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Anurag Malik - Data Tech Lead at Intuit"],"tags":["Data Pipelines","Databricks","Governance","Privacy","Unity"],"live_url":"https://www.youtube.com/watch?v=Y_1uyFaTYtI","recording_url":"https://www.youtube.com/watch?v=Y_1uyFaTYtI","app_url":"https://app.wearedevelopers.com/events/18/session/1133","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1776-clean-rooms","urls":["https://www.youtube.com/watch?v=Y_1uyFaTYtI"],"flag":null},{"id":1388,"title":"The Private AI Platform: Why Agentic Apps Need a Private Application Platform","description":"As AI moves from chat demos to “do-things” software, the platform requirements change: identity, policy, network controls, data governance, audit, and safe tool execution become mandatory. This session explains why a private application platform on private cloud is the most reliable foundation for enterprise AI—especially for agentic workflows and development assistants that touch sensitive systems. We’ll map the core platform capabilities (runtime, workload identity, secrets, supply chain, service brokering, observability, guardrails) to real AI components: model endpoints, vector stores, tool APIs, MCP servers, and skills routing. You’ll leave with a reference architecture and a pragmatic checklist to evaluate whether your current platform can safely run “full-blown” AI experiences.","starts_at":"2026-09-24T11:40:00-07:00","ends_at":"2026-09-24T12:10:00-07:00","stage":"Stage 2","track":"AI Trust & Safety","type":"AI Trust & Safety","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Oren Penso - Global field CTO at Tanzu division Broadcom"],"tags":["AI Coding Assistants","Agentic AI","Cross-Platform","Multi-Cloud"],"live_url":"https://www.youtube.com/watch?v=kFJD-RmCrwY","recording_url":"https://www.youtube.com/watch?v=kFJD-RmCrwY","app_url":"https://app.wearedevelopers.com/events/18/session/1388","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1950-the-private-ai","urls":["https://www.youtube.com/watch?v=kFJD-RmCrwY"],"flag":null},{"id":1135,"title":"Production runtime for Enterprise AI agents","description":"The session will introduce Swytchcode to the audience and help them learn how to ship reliable AI agents in the production when working with 3rd party APIs. \nSwytchcode helps your team find the right API path for the business workflows you need to run, then governs how each agent action runs in production—with authentication, retries, idempotency, validation, and auditability built in.","starts_at":"2026-09-24T12:00:00-07:00","ends_at":"2026-09-24T12:05:00-07:00","stage":"Outdoor Stage","track":"Startups & Innovation","type":"Startups & Innovation","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Aditya Rohit - Founder & CEO at Swytchcode"],"tags":["APIs","Agentic AI","Integration","OpenTelemetry","Reliability"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1135","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1875-production-runtime","urls":[],"flag":null},{"id":1411,"title":"Can AI Agents Actually Discover and Use Your Product? Agent-Led Growth and Agent Experience.","description":"AI agents are becoming active users of developer products. They read documentation, compare tools, install SDKs, invoke CLIs and MCP servers, and call APIs to complete work for developers. Yet most teams only test their product journey for humans, leaving agent failures, such as unclear docs, missing setup context, broken authentication flows, and unreliable tool calls, largely invisible.\n\nIn this five-minute pitch, Lightsage shows how teams can test real agent journeys end to end, identify where an agent fails, and convert that evidence into improvements across APIs, SDKs, CLIs, MCP servers, and documentation. The outcome is a new discipline for developer platforms: Agent Experience.","starts_at":"2026-09-24T12:10:00-07:00","ends_at":"2026-09-24T12:15:00-07:00","stage":"Outdoor Stage","track":"","type":"Session","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":[],"tags":["Developer Experience (DevEx)","Generative AI (GenAI)"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1411","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions","urls":[],"flag":null},{"id":1136,"title":"Why Buy Software When AI Can Build It?","description":"Companies now have a real alternative to buying software: building it themselves, with AI doing most of the work. Teams are already replacing paid tools with internal ones, and vendors are being asked why their product beats a prompt. When building still loses to buying, where self-built software genuinely holds up, and what happens to the software business when its customers become its competitors.","starts_at":"2026-09-24T12:15:00-07:00","ends_at":"2026-09-24T12:45:00-07:00","stage":"Stage 1","track":"Leadership & Strategy","type":"Leadership & Strategy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Lee Edwards - General Partner at Root Ventures","Mang-Git Ng - CEO at Anvil","Richard Robinson - Chief Evangelist at Unqork","Floriane Gramlich - Management Director at FG Solutions & Chief in Tech Capital"],"tags":[],"live_url":"https://www.youtube.com/watch?v=LqTd6Y5PKrI","recording_url":"https://www.youtube.com/watch?v=LqTd6Y5PKrI","app_url":"https://app.wearedevelopers.com/events/18/session/1136","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1897-why-buy-software","urls":["https://www.youtube.com/watch?v=LqTd6Y5PKrI"],"flag":null},{"id":1138,"title":"AI vs. AI: Defending the open source supply chain with agentic workflows","description":"With the arrival of Mythos and other frontier models we enter a new world. They can find security issues in libraries, create individual exploits, and successfully chain them to real-world attack campaigns in 2026. The open source ecosystem is on the verge of something new. What happens next is terrifying and exciting at the same time. At Chainguard we started a coalition with many partners across governments, banks and other large corporations, foundations, and open source communities to use the tools to strengthen our defenses against attackers. We established trust and infrastructure to share exploits, create patches, and bring them to use as binaries. Just in our first weeks we processed over thousands of findings, created well over 1k patches, and touched the code base of hundreds of open source projects. Now it is a few months later, and Manfred will share our experience from working within and outside the project. We will talk about good findings, bad patches, and ugly consequences alike, and dive into the details of examples and our collaboration with open source projects, communities, and their users. Manfred will also talk about the machinery behind the scenes that enables patching at the necessary scale - Chainguard Factory, powered by our open source agentic framework DriftlessAF, and expert engineers assisted by powerful AI models.","starts_at":"2026-09-24T12:15:00-07:00","ends_at":"2026-09-24T12:45:00-07:00","stage":"Stage 6","track":"Security & Privacy","type":"Security & Privacy","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Manfred Moser - Senior Principal DevRel Engineer at Chainguard"],"tags":["AI Models","CI/CD","Containers","DevOps","Java","JavaScript","Python","Security"],"live_url":"https://www.youtube.com/watch?v=a2X04OWoiU8","recording_url":"https://www.youtube.com/watch?v=a2X04OWoiU8","app_url":"https://app.wearedevelopers.com/events/18/session/1138","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1761-ai-vs-ai-defending","urls":["https://www.youtube.com/watch?v=a2X04OWoiU8"],"flag":null},{"id":1143,"title":"The AI Revolution Will Be Surprisingly Boring","description":"The biggest AI breakthroughs aren't happening where you might expect. They're happening in factories, warehouses, utilities, logistics networks, and back-office operations. The less glamorous the process, the greater the opportunity for impact. This session reveals why organizations with repetitive, mission-critical workflows are turning AI into measurable business value today","starts_at":"2026-09-24T12:15:00-07:00","ends_at":"2026-09-24T12:45:00-07:00","stage":"Stage 2","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Shruthi Shetty - Global VP, Head of Business AI RIG & AI/ML Services at SAP America"],"tags":["AI Models"],"live_url":"https://www.youtube.com/watch?v=5yCMOh3lmdI","recording_url":"https://www.youtube.com/watch?v=5yCMOh3lmdI","app_url":"https://app.wearedevelopers.com/events/18/session/1143","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1819-the-ai-revolution","urls":["https://www.youtube.com/watch?v=5yCMOh3lmdI"],"flag":null},{"id":1381,"title":" It's Not About the Models ","description":"Good AI vs. evil AI is an ethical choice. Good AI vs. bad AI is a design choice. \n\nAI has saved lives at scale and been weaponized at scale. This session explores the ethical choice of what you build with AI and the design choices that make it trustworthy: models, architecture, data, your evolving role and the leverage you will hold.","starts_at":"2026-09-24T12:15:00-07:00","ends_at":"2026-09-24T12:45:00-07:00","stage":"Stage 4","track":"AI Models & Infrastructure","type":"AI Models & Infrastructure","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Bob Wambach - VP, Market and Customer Insights at Dynatrace"],"tags":["AI Coding Assistants","AI Models","AI Standards"],"live_url":"https://www.youtube.com/watch?v=a0uXaEJxgS8","recording_url":"https://www.youtube.com/watch?v=a0uXaEJxgS8","app_url":"https://app.wearedevelopers.com/events/18/session/1381","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1931-it-s-not-about-the","urls":["https://www.youtube.com/watch?v=a0uXaEJxgS8"],"flag":null},{"id":1401,"title":"There’s No Such Thing as Vibe Strategy, Vibe Security, or Vibe Scale","description":"Across enterprises, a similar experiment seems to be playing out: developers are shipping at accelerating speed with AI-assisted tools, and that speed is real and worth preserving. But “vibing” something — coding, security, strategy, tax prep, take your pick — only holds up because someone isn’t deep enough in it to know what they may be missing, and that can work well for a proof point, but may not translate to what runs the business. This session is about the line leadership teams have to hold: how you let builders iterate and prove ideas fast without letting ungoverned experiments quietly become production systems. PwC's technology specialists will share how they've built the controls, telemetry, and enterprise-grade guardrails — going beyond what frontier AI companies can provide — to turn fast iteration into durable, scaled engineering output.​","starts_at":"2026-09-24T12:15:00-07:00","ends_at":"2026-09-24T12:45:00-07:00","stage":"Tech Leaders Stage","track":"Leadership & Strategy","type":"Leadership & Strategy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ussama Baggili - Principal, App Modernization & Development, Cloud Engineering & Data Analytics | Anthropic Alliance CTO at PwC US","Matt Hobbs - US and Global Head of Cloud, Engineering, Data, and AI at PwC","Meghna Shah - Principal of Engineering & AI practice at PwC","Andrew Carlson - Principal at PwC"],"tags":[],"live_url":"https://www.youtube.com/watch?v=jEomNZ4_jMA","recording_url":"https://www.youtube.com/watch?v=jEomNZ4_jMA","app_url":"https://app.wearedevelopers.com/events/18/session/1401","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1930-there-s-no-such","urls":["https://www.youtube.com/watch?v=jEomNZ4_jMA"],"flag":null},{"id":1139,"title":"PrimaLabs: The Application-Specific AI Inference Stack","description":"AI applications place very different demands on inference. Coding agents reuse long context, vision-language systems process variable multimodal inputs, and generative recommendation models operate under strict latency requirements. A generic inference stack cannot maximize performance across all three. PrimaLabs delivers an application-specific inference stack engineered around each production workload. The platform jointly optimizes runtimes, kernels, caching, batching, scheduling, parallelism, and GPU infrastructure, then operates the resulting stack in an isolated environment.","starts_at":"2026-09-24T12:20:00-07:00","ends_at":"2026-09-24T12:25:00-07:00","stage":"Outdoor Stage","track":"Startups & Innovation","type":"Startups & Innovation","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Prasanna Balaprakash - CEO at PrimaLabs"],"tags":["AI Models","Agentic AI","Infrastructure"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1139","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1790-primalabs-the","urls":[],"flag":null},{"id":1140,"title":"Software change is outpacing the platforms built to understand it.","description":"Atomic makes software changes queryable.\n\nAtomic is source code management at the primitive level: a distributed, agent-native Git alternative. A single CLI brings semantic call graphs, enhanced code search, intents, attestations and provenance to every agent you already use, so every change keeps its origin, its reasoning, and its evidence","starts_at":"2026-09-24T12:30:00-07:00","ends_at":"2026-09-24T12:35:00-07:00","stage":"Outdoor Stage","track":"Startups & Innovation","type":"Startups & Innovation","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Lee Faus - CEO & Founder at Atomic Software, Co."],"tags":["AI Coding Assistants","AI Models","Code Reviews","Developer Experience (DevEx)","DevOps","DevSecOps","Future of Work","Infrastructure as Code (IaC)","Open Source","Software Architecture"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1140","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1885-software-change-is","urls":[],"flag":null},{"id":1141,"title":"each::labs: Close the Imagination Gap","description":"The gap between what people imagine and what AI creates is a production problem. How each::labs closes it: one API, 600+ media models, routing and failover built in, frontier quality with production economics.","starts_at":"2026-09-24T12:40:00-07:00","ends_at":"2026-09-24T12:45:00-07:00","stage":"Outdoor Stage","track":"Startups & Innovation","type":"Startups & Innovation","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Eftal Yurtseven - Co-Founder & CEO at each::labs"],"tags":["AI Models","APIs","Generative AI (GenAI)","Reliability"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1141","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1804-each-labs-close-the","urls":[],"flag":null},{"id":1402,"title":"Big brains on little machines with Supermodel Labs","description":"Supermodel Labs began by exploring how ordinary computers could become useful AI infrastructure. That exploration became Aquaduck: a hybrid AI platform that turns existing business hardware into private inference infrastructure with selective cloud routing and its own powerful on-device AI agent.\n\nWe’ll cover what we learned about distributed inference and hybrid AI inference routing; what we’ve built and achieved so far; and how businesses can use hybrid AI to gain greater control over their data, infrastructure, and AI costs.","starts_at":"2026-09-24T12:50:00-07:00","ends_at":"2026-09-24T12:55:00-07:00","stage":"Outdoor Stage","track":"Startups & Innovation","type":"Startups & Innovation","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Kirah Sapong - Co-founder & CTO at Aquaduck AI","Daniel Dafoe - Co-founder & CEO at Supermodel Labs"],"tags":["AI Models","Agents","Multi-Agent Systems","Multi-Cloud","On-Premise"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1402","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1955-big-brains-on-little","urls":[],"flag":null},{"id":1144,"title":"Fault Tolerance and Consistency at Scale: Harnessing the Power of Distributed SQL Databases","description":"Distributed SQL Databases are a powerful new data management technology that addresses modern applications’ need for scalability, availability, geographic distribution, and low response time – with the power of SQL and strong consistency. \n\nHowever, distributed databases bring their own challenges. For example, the familiar trade-offs between consistency, high availability, and partition tolerance still exist. Remote data access will still incur speed-of-light network delays.\n\nThis talk will describe the inner workings of distributed databases and how to design applications to best exploit their power. Using Oracle and other distributed databases as examples, we will explore the capabilities and unique application challenges posed by distributed databases. This talk will address design patterns that empower applications to handle network latency and consistency in the presence of real-world networks that can and do fail.","starts_at":"2026-09-24T12:50:00-07:00","ends_at":"2026-09-24T13:20:00-07:00","stage":"Stage 3","track":"Data & Databases","type":"Data & Databases","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Wei Hu - Senior VP Research & Development at Oracle"],"tags":["Databases","Distributed Systems","Performance","Scaling","System Design"],"live_url":"https://www.youtube.com/watch?v=GzA2hixBP7w","recording_url":"https://www.youtube.com/watch?v=GzA2hixBP7w","app_url":"https://app.wearedevelopers.com/events/18/session/1144","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1696-fault-tolerance-and","urls":["https://www.youtube.com/watch?v=GzA2hixBP7w"],"flag":null},{"id":1145,"title":"For Physical AI, data is the problem, but data is not the solution","description":"TorqueAGI builds a physics informed foundation AI that enables robots to operate reliably in the real world. Our models power mission critical robotic systems across dynamic environments and are already being adopted by 10+ robotics partners, including production deployments.","starts_at":"2026-09-24T12:50:00-07:00","ends_at":"2026-09-24T13:20:00-07:00","stage":"Stage 5","track":"Physical AI","type":"Physical AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ashutosh Saxena - CEO at TorqueAGI"],"tags":["AGI (Artificial General Intelligence)","AI Models","Agentic AI","Automation","Embedded Systems","NVIDIA","Robotics"],"live_url":"https://www.youtube.com/watch?v=jMgowCQJ98g","recording_url":"https://www.youtube.com/watch?v=jMgowCQJ98g","app_url":"https://app.wearedevelopers.com/events/18/session/1145","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1674-for-physical-ai-data","urls":["https://www.youtube.com/watch?v=jMgowCQJ98g"],"flag":null},{"id":1146,"title":"Architecting Agentic Apps: WebMCP, A2UI, and Agent Experience","description":"First we optimized for UX, then DX, and now there's AX - the Agent Experience crashing the party. AI assistants are increasingly showing up to use our apps, and right now most of them get in by screenshotting the DOM and guessing where to click. There's a better way. WebMCP lets your Angular app hand agents a clean set of callable tools, and A2UI lets agents hand back real, reactive UI instead of another wall of chat text.\n\nIn this session we'll architect an Angular app for this shiny (and slightly experimental) new world. We'll walk through the modes of agent interaction, from quiet background data retrieval to rich, agent-generated interfaces, and look at a few ways to wire WebMCP into Angular through navigator.modelContext. Then we'll bring in A2UI so agents can return reactive component trees that your app renders natively, with your styling and accessibility along for the ride.\n\nYou'll leave knowing how to register tools, render agent-driven UI, and start thinking about your app's tool surface alongside its visual one. You'll also get a clear-eyed sense of what's production-ready today and what's still gloriously bleeding-edge.","starts_at":"2026-09-24T12:50:00-07:00","ends_at":"2026-09-24T13:20:00-07:00","stage":"Stage 7","track":"Languages, Web & Mobile","type":"Languages, Web & Mobile","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ankita Sood - Sr. Principal Engineer at Secureworks"],"tags":["Angular","CSS","Design Systems"],"live_url":"https://www.youtube.com/watch?v=Pct8l4EEQoM","recording_url":"https://www.youtube.com/watch?v=Pct8l4EEQoM","app_url":"https://app.wearedevelopers.com/events/18/session/1146","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1424-architecting-agentic","urls":["https://www.youtube.com/watch?v=Pct8l4EEQoM"],"flag":null},{"id":1148,"title":"Acquired Live Interview: Sri Shivananda (CIO, JPMorganChase) with Ben & David from Acquired","description":"Ben Gilbert and David Rosenthal are taking the main stage to conduct a series of live interviews. The pair host Acquired, the #1 technology podcast on Spotify and Apple Podcasts with over 1 million listeners. Acquired tells the stories and strategies of the world's greatest companies—each episode is a deep dive into a single company's history from its founding until today. Ben and David personally handcraft each episode over 200 hours of research and production. From founders to Fortune 500 CEOs, Acquired has interviewed some of the most influential leaders in technology and business, such as Jensen Huang, Mark Zuckerberg, Steve Ballmer, Morris Chang, Matt Garman, and Jamie Dimon.","starts_at":"2026-09-24T12:50:00-07:00","ends_at":"2026-09-24T13:20:00-07:00","stage":"Mainstage","track":"Leadership & Strategy","type":"Leadership & Strategy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Sri Shivananda - CIO of J.P. Morgan Payments & Global Banking at JPMorganChase","David Rosenthal - Co-founder & Co-host at Acquired","Ben Gilbert - Co-founder & Co-host at Acquired"],"tags":[],"live_url":"https://www.youtube.com/watch?v=GK245G-FbvM","recording_url":"https://www.youtube.com/watch?v=GK245G-FbvM","app_url":"https://app.wearedevelopers.com/events/18/session/1148","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions","urls":["https://www.youtube.com/watch?v=GK245G-FbvM"],"flag":null},{"id":1147,"title":"Valven: Intelligence for AI-Driven Software Lifecycle","description":"AI is changing every stage of the software lifecycle, from planning and implementation to code review and delivery. As development becomes increasingly AI assisted, traditional engineering metrics no longer provide the full picture.\n\nThis session explores how engineering organizations can understand the real impact of AI across the software lifecycle. Rather than focusing on AI usage alone, we'll discuss how to measure adoption, evaluate engineering outcomes, maintain delivery quality, and identify where AI is genuinely improving team performance. You'll see practical approaches for building visibility into AI driven software delivery and making better engineering decisions with data.","starts_at":"2026-09-24T13:00:00-07:00","ends_at":"2026-09-24T13:05:00-07:00","stage":"Outdoor Stage","track":"Startups & Innovation","type":"Startups & Innovation","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Serdar Bicer - CTO at VALVEN"],"tags":["Developer Experience (DevEx)","Productivity"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1147","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1894-valven-intelligence","urls":[],"flag":null},{"id":1142,"title":"Acquired Live Interview: Amjad Masad (Co-founder & CEO, Replit)","description":"Ben Gilbert and David Rosenthal are taking the main stage to conduct a series of live interviews. The pair host Acquired, the #1 technology podcast on Spotify and Apple Podcasts with over 1 million listeners. Acquired tells the stories and strategies of the world's greatest companies—each episode is a deep dive into a single company's history from its founding until today. Ben and David personally handcraft each episode over 200 hours of research and production. From founders to Fortune 500 CEOs, Acquired has interviewed some of the most influential leaders in technology and business, such as Jensen Huang, Mark Zuckerberg, Steve Ballmer, Morris Chang, Matt Garman, and Jamie Dimon.","starts_at":"2026-09-24T13:20:00-07:00","ends_at":"2026-09-24T13:50:00-07:00","stage":"Mainstage","track":"Leadership & Strategy","type":"Leadership & Strategy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Amjad Masad - CEO & Co-Founder at Replit","David Rosenthal - Co-founder & Co-host at Acquired","Ben Gilbert - Co-founder & Co-host at Acquired"],"tags":[],"live_url":"https://www.youtube.com/watch?v=sFSgdMc3REo","recording_url":"https://www.youtube.com/watch?v=sFSgdMc3REo","app_url":"https://app.wearedevelopers.com/events/18/session/1142","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions","urls":["https://www.youtube.com/watch?v=sFSgdMc3REo"],"flag":null},{"id":1149,"title":"The New Security Stack","description":"Security architecture is built on assumptions about who does what: people write the code, people hold the credentials, threats come from outside. AI breaks all three at once - and companies are discovering that tools built for yesterday's assumptions don't just underperform, they miss entire categories of risk. Which parts of the security stack need rethinking first, which just need tuning, and how to rebuild while the ground keeps moving.","starts_at":"2026-09-24T13:30:00-07:00","ends_at":"2026-09-24T14:00:00-07:00","stage":"Tech Leaders Stage","track":"Security & Privacy","type":"Security & Privacy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Javier Garza - Staff Developer Advocate at Snyk","Sagi Rodin - Co-founder & CEO at Frontegg","James Everingham - CEO & Co-founder at Guild.ai","Kara Sprague - CEO at HackerOne","Andrea Muttoni - CEO at The DATA Foundation"],"tags":[],"live_url":"https://www.youtube.com/watch?v=e--ejtmLs2Q","recording_url":"https://www.youtube.com/watch?v=e--ejtmLs2Q","app_url":"https://app.wearedevelopers.com/events/18/session/1149","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1890-the-new-security","urls":["https://www.youtube.com/watch?v=e--ejtmLs2Q"],"flag":null},{"id":1150,"title":"How AI Agents Tripled Our Test Coverage on a 1.8M-Line iOS Codebase","description":"Duolingo's iOS app has nearly 1.8M executable lines and, until recently, test coverage that lagged far behind. We built an autonomous pipeline that writes unit tests and gets them to a merged state. Scheduled Temporal workflows pick untested code, Claude Code agents open real pull requests, and a lifecycle manager monitors CI, self-heals failures, runs AI review, and merges. Humans act only as final reviewers. The pipeline has merged over 85,000 lines of test code and tripled unit-test coverage of our MVVM components. This talk walks through the architecture, the guardrails that keep agent-written code trustworthy, the failure modes we hit, and how we are using the same skeleton for additional migrations across the company. You will walk away with a concrete blueprint for agents that ship code in a large production codebase.","starts_at":"2026-09-24T13:30:00-07:00","ends_at":"2026-09-24T14:00:00-07:00","stage":"Stage 1","track":"Languages, Web & Mobile","type":"Languages, Web & Mobile","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Kush Agrawal - Staff Software Engineer at Duolingo"],"tags":["Agentic AI","Automation","CI/CD","Code Generation","Code Reviews","Developer Experience (DevEx)","iOS","Large Language Models (LLMs)","Productivity","Swift","Testing"],"live_url":"https://www.youtube.com/watch?v=JAKMpEXMooM","recording_url":"https://www.youtube.com/watch?v=JAKMpEXMooM","app_url":"https://app.wearedevelopers.com/events/18/session/1150","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1773-how-ai-agents","urls":["https://www.youtube.com/watch?v=JAKMpEXMooM"],"flag":null},{"id":1151,"title":"Building the Production Cage for Powerful Agents","description":"The harness behind the agents you use is not the harness behind the agents you build. Join Mike Chambers (AWS) for a live-coded sprint from laptop agent to cloud-scale deployment, covering memory, identity, observability, and why most agentic use cases need less code than you think.","starts_at":"2026-09-24T13:30:00-07:00","ends_at":"2026-09-24T14:00:00-07:00","stage":"Stage 2","track":"AI Agents","type":"AI Agents","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Mike Chambers - Senior AI specialist DA at AWS"],"tags":["Authentication","AWS","Agents","Agentic AI","Best Practices","Observability","Scaling","Secure Coding","Software Architecture"],"live_url":"https://www.youtube.com/watch?v=PCvN7MmjmKo","recording_url":"https://www.youtube.com/watch?v=PCvN7MmjmKo","app_url":"https://app.wearedevelopers.com/events/18/session/1151","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1800-building-the","urls":["https://www.youtube.com/watch?v=PCvN7MmjmKo"],"flag":null},{"id":1153,"title":"AI and Video games: The Evolution","description":"LIttle is known about the history of Neural Networks e.g. \"Artificial Intelligence.\" The history goes back to around 1946 when researchers noticed that the mathematics involved with linear algebra wherein materials were stretched that the neighboring atoms were affected, was best modeled with a branch of Math known as tensors. \n\nTensors are used today to create neural networks. Neural networks  are run on a powerful Graphics Processing Unit (GPU.) GPUs came about because of video games and entertainment thus we can say that video games laid the groundwork for AI.","starts_at":"2026-09-24T13:30:00-07:00","ends_at":"2026-09-24T14:00:00-07:00","stage":"Stage 4","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Jack McCauley - Co-Founder at Oculus"],"tags":["AGI (Artificial General Intelligence)","Gaming","Generative AI (GenAI)"],"live_url":"https://www.youtube.com/watch?v=pIeN0uH2b9o","recording_url":"https://www.youtube.com/watch?v=pIeN0uH2b9o","app_url":"https://app.wearedevelopers.com/events/18/session/1153","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1763-ai-and-video-games","urls":["https://www.youtube.com/watch?v=pIeN0uH2b9o"],"flag":null},{"id":1154,"title":"The Pedagogy of AI: Agents, Agency, and a World Beyond Coding Tutorials","description":"In the era of agentic workflows, when AI can build an MVP in seconds, traditional tutorials are rapidly becoming legacy technical debt. The challenge is no longer just teaching developers how to write code. It’s giving them compelling problems to solve with it.\n\nEnter TwilioWorld. Created by the Twilio Developer Training team, it’s a new approach to developer education, trading the traditional golden path for an open-ended, AI-native playground that uses conversational intelligence at every layer to create an adaptive, engaging, and genuinely educational experience.\n\nJoin this session to explore a new pedagogy for the AI era: an approach where developer education isn’t about giving agents more skills, but giving developers a space to put those skills to work.","starts_at":"2026-09-24T13:30:00-07:00","ends_at":"2026-09-24T14:00:00-07:00","stage":"Stage 5","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Alex Goldman - Developer Educator at Twilio","Andrew MacLean - Staff Developer Educator at Twilio"],"tags":["Agentic AI","Developer Experience (DevEx)","Gaming","People & Culture"],"live_url":"https://www.youtube.com/watch?v=wz2tBpK9V7c","recording_url":"https://www.youtube.com/watch?v=wz2tBpK9V7c","app_url":"https://app.wearedevelopers.com/events/18/session/1154","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1792-the-pedagogy-of-ai","urls":["https://www.youtube.com/watch?v=wz2tBpK9V7c"],"flag":null},{"id":1155,"title":"From Prototype to Production: Build Better Agents with IBM Bob","description":"In this session, you will follow an incident management case study built with IBM Bob. A live demo will show specialized agents triaging an incident, assessing business impact, planning a resolution, invoking tools, and coordinating decisions through a supervisor. You will see how human approval protects critical actions and how distributed tracing makes agent behavior, tool calls, latency, and failures visible.\n\nWe will also demonstrates how IBM Bob uses a concise project context file to understand architecture, follow team conventions, generate consistent code, and avoid inventing APIs that do not exist. Along the way, we will examine where agent workflows commonly break, how to choose between sequential, parallel, and supervisor based coordination, and how to control context and token usage without sacrificing quality.\n\nKey Learnings\n 1. Design reliable workflows involving multiple specialized AI agents.\n 2. Select sequential, parallel, or supervisor coordination for each use case.\n 3. Apply human approval and tracing to make agent decisions safer and observable.\n 4. Use IBM Bob with concise project context to produce consistent, governed code.\n\nYou will leave with reusable design patterns, practical governance tips, and a clear path for turning an agent prototype into a system that operations teams can understand, test, and trust","starts_at":"2026-09-24T13:30:00-07:00","ends_at":"2026-09-24T14:00:00-07:00","stage":"Stage 7","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Sunil Murthy - AI Field CTO at IBM"],"tags":["AI Models","APIs","Agentic AI","IBM","Internal Platforms"],"live_url":"https://www.youtube.com/watch?v=b9-xMqha8zM","recording_url":"https://www.youtube.com/watch?v=b9-xMqha8zM","app_url":"https://app.wearedevelopers.com/events/18/session/1155","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions","urls":["https://www.youtube.com/watch?v=b9-xMqha8zM"],"flag":null},{"id":1157,"title":"Understanding LLM Architectures: Inside the Design of Modern Models","description":"Large Language Models are often described as if each generation introduces an entirely new architecture. In practice, most modern LLMs still retain the transformer core, but their real progress comes from a series of targeted design changes around attention, positional handling, feed-forward computation, routing, and memory efficiency. This talk explains LLM architectures through the engineering tradeoffs that shaped modern models: why some attention mechanisms evolved for lower inference cost, how architectural choices influence long-context behavior, why sparse activation changed the economics of scale, and how these shifts affect real-world deployment. Rather than treating LLM architecture as a static diagram, this session presents it as a set of design decisions made in response to practical constraints in latency, memory, context length, and system efficiency. Attendees will leave with a clearer mental model of what remained stable, what changed, and why those changes matter.","starts_at":"2026-09-24T13:30:00-07:00","ends_at":"2026-09-24T14:00:00-07:00","stage":"Stage 9","track":"AI Models & Infrastructure","type":"AI Models & Infrastructure","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Jofia Jose Prakash - Director - AI & Governance at Humanity + AI, Inc"],"tags":["AI Models","Large Language Models (LLMs)"],"live_url":"https://www.youtube.com/watch?v=MiTQdJXqm6k","recording_url":"https://www.youtube.com/watch?v=MiTQdJXqm6k","app_url":"https://app.wearedevelopers.com/events/18/session/1157","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1669-understanding-llm","urls":["https://www.youtube.com/watch?v=MiTQdJXqm6k"],"flag":null},{"id":1382,"title":"It's Not Vibe Coding If You Know What You're Doing","description":"We've all heard stories about how people are using AI to create entire software projects, and in every case, I had nothing but skepticism and doubt.\nUntil I tried it.\nLet me show you how I build collectyourcards.com, from the ground up, in less than two weeks, without writing a single line of code. We will talk about effective prompting, toolsets, and the do's and don'ts of coding with AI.","starts_at":"2026-09-24T13:30:00-07:00","ends_at":"2026-09-24T14:00:00-07:00","stage":"Stage 6","track":"","type":"Session","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Sean O'Dell - Developer Experience at Dynatrace","Jeff Blankenburg - Principal Developer Advocate at Dynatrace"],"tags":["AI Coding Assistants","Anthropic","Node.js","SQL","Vibe Coding"],"live_url":"https://www.youtube.com/watch?v=WD_SufwOwwY","recording_url":"https://www.youtube.com/watch?v=WD_SufwOwwY","app_url":"https://app.wearedevelopers.com/events/18/session/1382","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions","urls":["https://www.youtube.com/watch?v=WD_SufwOwwY"],"flag":null},{"id":1156,"title":"The Developer's Guide to an Agentic Git Forge","description":"Coding agents help us write code quickly, but they’ve introduced a new challenge: ensuring developers can understand, trust, and maintain agent-generated code. That challenge now shows up across the software development lifecycle:\nContext is scattered across multiple sessions.\n\nDevelopers have more code to review and less context to review it with.\n\nCode hosts face more automated activity than they were designed for.\n\nAgents burn tokens just trying to understand the codebase.\nSolving these problems requires a new workflow and mindset for working with agents. In this hands-on workshop, you’ll learn how to preserve context across sessions, reduce wasted tokens, and review agent-generated changes with the context you need to merge confidently.\nThis workshop is for engineers, tech leads, and reviewers of all experience levels who want to work more efficiently with coding agents.\n\nImportant please Sign up here beforehand:\n\nhttps://entire.io/login?utm_campaign=320951023-EVT%20%C2%B7%20WAD%20SAN%20JOSE%20SEP26&utm_source=workshop&utm_medium=wad\n\nAnd install Entire here:\nhttps://docs.entire.io/installation","starts_at":"2026-09-24T13:30:00-07:00","ends_at":"2026-09-24T15:30:00-07:00","stage":"Stage 8","track":"DevEx & Productivity","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"laptop","speakers":["Evis Drenova - Principal software engineer at Entire","Lizzie Siegle - Developer Advocate at Entire"],"tags":["Agentic AI","Code Reviews","Collaboration","Data Pipelines","Developer Experience (DevEx)","Future of Work","Generative AI (GenAI)","GitHub","Infrastructure","LLMOps","Observability","Open Source","Vibe Coding"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1156","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1808-the-developer-s","urls":[],"flag":null},{"id":1158,"title":"Hands-On CI Optimization Workshop","description":"A tactical, hands-on session where attendees optimize a real build pipeline live with Blacksmith. They’ll leave with practical insights, proven techniques, and a checklist to apply immediately to their own environments.","starts_at":"2026-09-24T13:30:00-07:00","ends_at":"2026-09-24T15:30:00-07:00","stage":"Stage 10","track":"DevOps & Platform Engineering","type":"Workshop","live_coding":false,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"Attendees will need a laptop, a GitHub account, and access to Blacksmith. To make the most of the session, we recommend getting set up in advance using the Blacksmith Quickstart Guide: Blacksmith Quickstart Guide (https://docs.blacksmith.sh/introduction/quickstart?utm_source=chatgpt.com)","speakers":["Abbe Piels - Member of Technical Staff at Blacksmith"],"tags":["CI/CD","GitHub","GitHub Actions","Infrastructure"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1158","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1810-hands-on-ci","urls":[],"flag":null},{"id":1159,"title":"GitHub Actions","description":"Build a complete CI/CD pipeline for a pet adoption application in this hands-on workshop. Starting with your first workflow, you’ll automate testing, secure the software supply chain with GitHub security features, improve performance with caching and matrix strategies, and deploy to Azure. You’ll also create a custom action, reuse workflow logic across repositories, and enforce organizational standards with required workflows and branch protections. By the end, you’ll understand how GitHub Actions can take an application from commit to production with secure, scalable automation. Familiarity with Git basics is recommended, and an Azure subscription is required for the deployment exercises.","starts_at":"2026-09-24T13:30:00-07:00","ends_at":"2026-09-24T15:30:00-07:00","stage":"Stage 12","track":"DevOps & Platform Engineering","type":"Workshop","live_coding":false,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"Attendees need to bring their own laptop and have a GitHub account as well as an Azure subscription and familiarity with Git basics.","speakers":["Austen Stone - Senior Field Actions Specialist at GitHub"],"tags":["GitHub","GitHub Actions"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1159","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1854-github-actions","urls":[],"flag":null},{"id":1160,"title":"From Signal to Action: Empowering Your AI SRE with OpenTelemetry Data","description":"AI SRE agents are becoming the modern way to investigate alerts and incidents, but they are only as good as the telemetry they are fed. Without a solid data foundation, an agent is guessing. OpenTelemetry closes that gap: it gives us a vendor-neutral, industry-standard signal set that large language models can actually reason over.\n\nThis workshop walks the full path from scratch - and without touching application code. Instrumentation is added entirely from the outside, so services are covered as they run rather than after a refactor. From there we wire it up through the OpenTelemetry Collector and ship the data to a central backend, then hand off to the agent (dash0 Agent0) and close the loop: alert fires, agent investigates, agent correlates traces, metrics and logs, and drafts a ready-to-merge PR with the fix.\n\nYou will leave with a concrete blueprint for the full circle - observing, alerting, and acting autonomously - built entirely on open standards, with no code changes required to get there.","starts_at":"2026-09-24T13:30:00-07:00","ends_at":"2026-09-24T15:30:00-07:00","stage":"Stage 14","track":"DevOps & Platform Engineering","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"Laptop\r\nIDE\r\npython or nodejs preinstalled\r\ndocker \r\na email address to be invited to a dash0 demo account\r\nGitHub account","speakers":["Julia Furst Morgado - Principal Developer Relations Engineer at Dash0","Raphael Manke - Senior Product engineer at Dash0"],"tags":["Agentic AI","Distributed Systems","Observability","OpenTelemetry","Reliability","Tooling"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1160","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1809-from-signal-to","urls":[],"flag":null},{"id":1403,"title":"Build an agentic commerce solution","description":"The way customers find and buy products is shifting from search to LLMs. In this workshop, you’ll customize an AI agent to become an expert shopping assistant. Through hands-on exercises, create Shared Payment Tokens (SPT) using the Universal Commerce Protocol (UCP) and pass payment credentials from an AI agent to your merchant Stripe account for processing and risk evaluation. By the end of this workshop, you’ll have a fully functioning agentic commerce solution.","starts_at":"2026-09-24T13:30:00-07:00","ends_at":"2026-09-24T15:30:00-07:00","stage":"Stage 13","track":"","type":"Workshop","live_coding":false,"is_workshop":true,"capacity":40,"waitlist":6,"requirements":"","speakers":["Ben Smith - Staff Developer Advocate at Stripe"],"tags":["Agents","Agentic AI","FinTech","Integration"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1403","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions","urls":[],"flag":null},{"id":1161,"title":"The Autonomous Performance Agent: A Netflix Production Story","description":"At Netflix, with large codebases and distributed systems, software performance degradation is often silent and compounds without active engineering involvement. The manual cost of closing the loop (profile, analyze, trace, fix, validate) means many inefficiencies quietly burn compute for months before anyone acts. By the time a human gets there, it's often already cost real money. We wanted to see if the loop could close on its own. I'll talk about how to build an autonomous agent that hunts for performance inefficiencies across live production services, traces them to source code, proposes fixes, and validates results — grounding every decision in measured production outcomes, not model confidence.\n\nIn this talk, we'll share how engineering leaders can scale their performance engineering with newer approaches that give agents enough autonomy while keeping humans focused on the key details that matter. We'll walk through four findings the agent surfaced — caught, fixed, and canary-confirmed — with limited hand-holding from an engineer.","starts_at":"2026-09-24T13:40:00-07:00","ends_at":"2026-09-24T13:50:00-07:00","stage":"Outdoor Stage","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Rajat Shah - Staff Software Engineer at Netflix"],"tags":["AI Coding Assistants","Agents","Autonomous Systems"],"live_url":"https://www.youtube.com/watch?v=cqBSE6qihmc","recording_url":"https://www.youtube.com/watch?v=cqBSE6qihmc","app_url":"https://app.wearedevelopers.com/events/18/session/1161","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1680-the-autonomous","urls":["https://www.youtube.com/watch?v=cqBSE6qihmc"],"flag":null},{"id":1162,"title":"Acquired Live Interview: Justin Boitano (VP, Enterprise AI Products, NVIDIA)","description":"Ben Gilbert and David Rosenthal are taking the main stage to conduct a series of live interviews. The pair host Acquired, the #1 technology podcast on Spotify and Apple Podcasts with over 1 million listeners. Acquired tells the stories and strategies of the world's greatest companies—each episode is a deep dive into a single company's history from its founding until today. Ben and David personally handcraft each episode over 200 hours of research and production. From founders to Fortune 500 CEOs, Acquired has interviewed some of the most influential leaders in technology and business, such as Jensen Huang, Mark Zuckerberg, Steve Ballmer, Morris Chang, Matt Garman, and Jamie Dimon.","starts_at":"2026-09-24T13:50:00-07:00","ends_at":"2026-09-24T14:20:00-07:00","stage":"Mainstage","track":"Leadership & Strategy","type":"Leadership & Strategy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Justin Boitano - VP, Enterprise AI Products at NVIDIA","David Rosenthal - Co-founder & Co-host at Acquired","Ben Gilbert - Co-founder & Co-host at Acquired"],"tags":[],"live_url":"https://www.youtube.com/watch?v=cXtfMjcRz_4","recording_url":"https://www.youtube.com/watch?v=cXtfMjcRz_4","app_url":"https://app.wearedevelopers.com/events/18/session/1162","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions","urls":["https://www.youtube.com/watch?v=cXtfMjcRz_4"],"flag":null},{"id":1389,"title":"From transaction sequences to pricing decisions at 140M+ customer scale","description":"LLMs proved that scale and compute can turn raw sequences into general-purpose intelligence. At Nu, we've been pointing that same playbook at a very different sequence, a person's financial history, and asking what it takes to build the production systems around it that responsibly shape the decisions that Nu makes across its more than 140 million customers in Latin America.\n\nThis talk looks at what it takes to build a modeling and decisioning engine Nu can depend on. It spans our data research to represent transactions as a language, our foundation model, nuFormer, that learns rich customer representations from these trillions of transactions, and ends with the constrained optimization that turns those representations into decisions that determine how we offer and price products for our customers.","starts_at":"2026-09-24T13:55:00-07:00","ends_at":"2026-09-24T14:05:00-07:00","stage":"Outdoor Stage","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Hiroto Udagawa - General Manager, AI Core at Nu"],"tags":["AI Models"],"live_url":"https://www.youtube.com/watch?v=uM0-zZCa4_A","recording_url":"https://www.youtube.com/watch?v=uM0-zZCa4_A","app_url":"https://app.wearedevelopers.com/events/18/session/1389","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions","urls":["https://www.youtube.com/watch?v=uM0-zZCa4_A"],"flag":null},{"id":1163,"title":"Anatomy of an AI Request: Where Latency and Cost Are Really Born","description":"Every LLM API call looks simple on the surface. But under the hood, it’s a deeply layered systems problem spanning kernels, compilers, GPU scheduling, and distributed inference infrastructure.\n\nIn this session, Dan Fu, VP of Kernels at Together AI, breaks down what actually happens when a request hits a modern AI model—and how inference performance is ultimately determined. He walks through the full inference stack, from tokenization and model execution to GPU kernel dispatch, memory movement, and serving-time orchestration, highlighting where inefficiencies accumulate and why today’s systems operate far below theoretical hardware capability.\n\nDrawing on both cutting-edge systems research and production-scale infrastructure experience—including foundational work like FlashAttention, now widely adopted across the AI ecosystem—Dan unpacks the core bottlenecks in modern inference stacks. He also outlines where the largest efficiency gains are still available, and why kernel-level optimization is becoming a critical lever in scaling AI systems.","starts_at":"2026-09-24T14:10:00-07:00","ends_at":"2026-09-24T14:40:00-07:00","stage":"Stage 1","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Dan Fu - VP of Kernels at Together AI"],"tags":["AI Models","APIs","Design Systems","Infrastructure","Large Language Models (LLMs)"],"live_url":"https://www.youtube.com/watch?v=zWYFpjuUYMc","recording_url":"https://www.youtube.com/watch?v=zWYFpjuUYMc","app_url":"https://app.wearedevelopers.com/events/18/session/1163","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1835-anatomy-of-an-ai","urls":["https://www.youtube.com/watch?v=zWYFpjuUYMc"],"flag":null},{"id":1164,"title":"Know Your Enemies: Live Exploit of a PHP Engine Security Breach","description":"All programming languages have their foundations: the engine that interprets your code and makes everything run. In PHP, this is the Zend Engine, a critical piece of software that powers millions of applications worldwide. When everything works, you don’t even think about it. You deploy to production, and the engine does its magic behind the scenes.\n\nBut what happens when something goes wrong in that core? What if a subtle bug opens the door to a full security breach? Suddenly, the invisible foundation becomes the most important part of the story.\n\nLet’s shine a light on two such cases: a recent, real vulnerability in the PHP engine (which has since been patched), and a backdoor that, just a few years ago, actually made it into the release candidate and allowed remote code execution. We’ll walk through how each issue could be exploited and, most importantly, what lessons developers can draw from them. And yes, there will be live, local, sandboxed demos of both exploits in action. Ready to dive in?","starts_at":"2026-09-24T14:10:00-07:00","ends_at":"2026-09-24T14:40:00-07:00","stage":"Stage 2","track":"Security & Privacy","type":"Security & Privacy","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Alexandre Daubois - CTO - Les-Tilleuls.coop"],"tags":["AppSec","Secure Coding","Security"],"live_url":"https://www.youtube.com/watch?v=UJOxfPvwA-I","recording_url":"https://www.youtube.com/watch?v=UJOxfPvwA-I","app_url":"https://app.wearedevelopers.com/events/18/session/1164","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1420-know-your-enemies","urls":["https://www.youtube.com/watch?v=UJOxfPvwA-I"],"flag":null},{"id":1165,"title":"Real-Time Data Platforms at Trillion-Event Scale","description":"Some of the largest real-time platforms in production today operate at scales that were considered theoretical a decade ago. CrowdStrike has publicly disclosed that its Falcon Threat Graph processes more than a trillion events per day across 15-plus petabytes of data, with engineering blogs describing 40-plus petabytes stored and 70 million requests per second served. Numbers like these are not unique to security — AI agent platforms, observability backends, and large SaaS analytics systems are pushing into the same territory. The interesting question is not the headline figure. It is what actually breaks at that scale, and which architectural choices keep the system honest.\nThis talk distills patterns and failure modes from years of building streaming and AI data platform infrastructure, framed against publicly disclosed industry references rather than any single employer's internals. Topics include:\n- Stateful streaming joins across different data streams\n- Handling replay storms and out-of-order events without latency collapse\n- The honest tradeoffs between latency, cost, and correctness — and when each one wins\n- Observability and degradation modes that keep the platform usable when something is failing\n\nAttendees will leave with concrete guidance on designing real-time systems that fail loudly, recover predictably, and surface the metrics that actually matter at scale.\n\nNote: Views are my own and do not represent any employer. Examples reference publicly disclosed sources.","starts_at":"2026-09-24T14:10:00-07:00","ends_at":"2026-09-24T14:40:00-07:00","stage":"Stage 3","track":"Data & Databases","type":"Data & Databases","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Diptamay Sanyal at Principal Engineer | Data, AI & Cybersecurity Platforms"],"tags":["Apache Flink","Apache Kafka","Agentic AI","Data Pipelines","Large Language Models (LLMs)"],"live_url":"https://www.youtube.com/watch?v=h0_f10Nrw9U","recording_url":"https://www.youtube.com/watch?v=h0_f10Nrw9U","app_url":"https://app.wearedevelopers.com/events/18/session/1165","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1899-real-time-data","urls":["https://www.youtube.com/watch?v=h0_f10Nrw9U"],"flag":null},{"id":1166,"title":"Agentic Drift: keeping pace with your agents","description":"As agents increase the velocity at which code gets written, platforms get modified, and documentation gets updated, the things teams rely on can change faster than any human can track, validate, or understand. Call it Agentic Drift.\n\nAgentic Drift shows up as pipelines failing at increasing frequency, vulnerability counts creeping upward, internal tools that have quietly evolved away from their original intent, and documentation that no longer reflects how a system actually works. Teams are already experiencing it but the frameworks for managing it are still emerging.\n\nThis talk introduces Agentic Drift and how to solve it. Drawing on experience building and operating developer platforms alongside AI agents, we'll cover:\n- how to detect drift using signals your team already has: CI/CD pipelines, observability tools, security scanners, and end-user feedback\n- how to design remediation pathways that fit your team's risk tolerance, from triggered reviews to continuous validation\n- a model for keeping humans meaningfully in the loop without becoming a bottleneck to the velocity agents provide\n\nThe future of software engineering is about more than what agents can build. We also need to design teams and systems to keep pace with these changes.","starts_at":"2026-09-24T14:10:00-07:00","ends_at":"2026-09-24T14:40:00-07:00","stage":"Stage 4","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Colleen Lake - Developer Advocate at Gitlab"],"tags":["AI Coding Assistants","Developer Experience (DevEx)","DevOps","DevSecOps"],"live_url":"https://www.youtube.com/watch?v=vOmtf06ssVk","recording_url":"https://www.youtube.com/watch?v=vOmtf06ssVk","app_url":"https://app.wearedevelopers.com/events/18/session/1166","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1739-agentic-drift","urls":["https://www.youtube.com/watch?v=vOmtf06ssVk"],"flag":null},{"id":1167,"title":"Edge AI: Running Agentic Intelligence Where Internet Can't Reach","description":"Cloud inference provides unparalleled scale and capability, but mission-critical operations in disconnected environments - like factory floors or remote field sites often require immediate, localized intelligence. As enterprises move beyond chat interfaces into real-time, autonomous actions, building a hybrid architecture that seamlessly bridges the cloud and the edge becomes essential.\n\nThis session tackles the engineering realities of deploying localized AI. We will explore how to architect systems that run Small Language Models (SLMs) and specialized reasoning engines directly at the edge, integrating seamlessly with local IoT telemetry and industrial systems. Attendees will learn how to balance localized reasoning for immediate, privacy-safe decision-making with asynchronous cloud syncs for heavy processing. You will walk away with practical patterns for overcoming hardware constraints, managing offline-first AI deployments, and building intelligence that works reliably everywhere.","starts_at":"2026-09-24T14:10:00-07:00","ends_at":"2026-09-24T14:40:00-07:00","stage":"Stage 5","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Nitin Eusebius - Principal Solutions Architect at AWS"],"tags":["AWS","Automation","Autonomous Systems","Edge AI","Internet of Things (IoT)","Privacy"],"live_url":"https://www.youtube.com/watch?v=chM48tju-2w","recording_url":"https://www.youtube.com/watch?v=chM48tju-2w","app_url":"https://app.wearedevelopers.com/events/18/session/1167","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1805-edge-ai-running","urls":["https://www.youtube.com/watch?v=chM48tju-2w"],"flag":null},{"id":1168,"title":"Compute for your AI model: GPUs, LPUs, TPUs and beyond..","description":"In the rapidly evolving landscape of computing, Graphics Processing Units (GPUs), Language Processing Units (LPUs), and Tensor Processing Units (TPUs) play pivotal roles in accelerating complex tasks, particularly in machine learning and artificial intelligence.\n\nGPUs are renowned for their parallel processing capabilities, making them ideal for rendering graphics and handling large datasets. LPUs are specialized for optimizing natural language processing tasks, enhancing efficiency in understanding and generating human language. TPUs, developed by Google, are tailored specifically for training and inference of machine learning models, offering significant performance advantages for large-scale AI applications.\n\nAs we explore these technologies, we'll also look at emerging processing units designed for specific AI use-cases and the future of computational advancements.\n\nJoin me to dive into the intricacies of these processing units, their applications, and what lies ahead in the world of computing technology.","starts_at":"2026-09-24T14:10:00-07:00","ends_at":"2026-09-24T14:40:00-07:00","stage":"Stage 6","track":"AI Models & Infrastructure","type":"AI Models & Infrastructure","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Kushaagra Goyal - Tech Lead at Rubrik"],"tags":["AI Models","Deep Learning","Infrastructure","NVIDIA","Transformers"],"live_url":"https://www.youtube.com/watch?v=JZdwya1sdGg","recording_url":"https://www.youtube.com/watch?v=JZdwya1sdGg","app_url":"https://app.wearedevelopers.com/events/18/session/1168","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1409-compute-for-your-ai","urls":["https://www.youtube.com/watch?v=JZdwya1sdGg"],"flag":null},{"id":1169,"title":"Designing High-Performance AI APIs: Lessons from Serving Millions of Real-Time Requests","description":"Serving AI inference across mobile browsers, native apps and enterprise integrations is not a single engineering problem. Latency tolerances, client capabilities and failure models all differ. Getting it wrong at scale means degraded experiences for millions of users. \n\nIn this session, Wayne Liu, Chief Growth Officer and U.S. President of Perfect Corp., will share concrete engineering lessons from building and operating API-first AI infrastructure that handles millions of real-time interactions across diverse deployment environments. \n\nDuring this session, Wayne Liu will uncover:\n- The latency vs. accuracy tradeoff in real-time AI APIs and how to deliberate decisions\n- Architecture patterns for serving AI across varied clients and what changes between mobile, web and enterprise environments\n- How abstraction layers that simplify complex inference (such as facial mapping and real-time rendering) work under the hood\n- Infrastructure decisions that have an outsized impact on cost, reliability and developer experience in high-volume AI deployments","starts_at":"2026-09-24T14:10:00-07:00","ends_at":"2026-09-24T14:40:00-07:00","stage":"Stage 7","track":"Architecture & Backend","type":"Architecture & Backend","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Wayne Liu - Chief Growth Officer & Americas President at Perfect Corp."],"tags":["APIs","Agentic AI","Best Practices","Business Intelligence","Generative AI (GenAI)","Model Training","Scaling"],"live_url":"https://www.youtube.com/watch?v=QSzZbg1kDOQ","recording_url":"https://www.youtube.com/watch?v=QSzZbg1kDOQ","app_url":"https://app.wearedevelopers.com/events/18/session/1169","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1846-designing-high","urls":["https://www.youtube.com/watch?v=QSzZbg1kDOQ"],"flag":null},{"id":1171,"title":"One Repo, One Strategy: Scalable Full-Stack Testing in a Monorepo World","description":"In large-scale systems, multiple teams, third-party integrations, and shared codebases can make testing feel impossible to coordinate. In this session, Bartosz and Pawel reveal how to bring order to that chaos using a unified full-stack testing strategy inside a monorepo architecture that powers both React and React Native applications.\n\nThey’ll show how to combine contract, integration, gRPC, API, and visual regression testing into one consistent framework that helps teams work independently without breaking each other’s services. You’ll learn how TypeScript and shared logic enable type-safe, scalable testing across platforms — and how this approach speeds up releases while reducing integration pain.\n\nExpect practical patterns, real examples, and lessons learned from building test architectures that survive complex, distributed environments.","starts_at":"2026-09-24T14:10:00-07:00","ends_at":"2026-09-24T14:40:00-07:00","stage":"Stage 9","track":"Languages, Web & Mobile","type":"Languages, Web & Mobile","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Bartosz Leczycki - Team Lead & PO Automation at Awaed Alosool Capital","Paweł Matynia - Sr. Advanced Software Engineer at Honeywell Aerospace"],"tags":["Quality Assurance (QA)","Software Architecture","Testing"],"live_url":"https://www.youtube.com/watch?v=byINbBvC3hE","recording_url":"https://www.youtube.com/watch?v=byINbBvC3hE","app_url":"https://app.wearedevelopers.com/events/18/session/1171","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1699-one-repo-one","urls":["https://www.youtube.com/watch?v=byINbBvC3hE"],"flag":null},{"id":1390,"title":"AI Governance & Compliance: Who Is Responsible When the Bots Start Acting? ","description":"As AI agents become the communication and action layer of the enterprise, how do companies control what they access, what data they use, and what they say or do? Who is responsible when an agent violates a policy or regulation, and how do you monitor and audit millions of AI interactions in real time?","starts_at":"2026-09-24T14:10:00-07:00","ends_at":"2026-09-24T14:40:00-07:00","stage":"Tech Leaders Stage","track":"Startups & Innovation","type":"Startups & Innovation","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Kumesh Aroomoogan - Founder & CEO at ZeroDrift","Paul Anthony Claxton - Managing Partner at Digerati Investments","Giovanni Soleti - Managing Partner at i5invest"],"tags":[],"live_url":"https://www.youtube.com/watch?v=FJif2Tmiq7U","recording_url":"https://www.youtube.com/watch?v=FJif2Tmiq7U","app_url":"https://app.wearedevelopers.com/events/18/session/1390","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions","urls":["https://www.youtube.com/watch?v=FJif2Tmiq7U"],"flag":null},{"id":1173,"title":"SecurePrompt: Building a Pre-Flight Security Layer for Agentic AI","description":"As enterprises deploy agentic AI, everyone's building capabilities—but who's building the guardrails? When an autonomous agent generates a prompt containing AWS credentials, or a compromised data source injects malicious instructions, what stops that payload from reaching the LLM?\nThis session reveals how I built SecurePrompt, a pre-flight security scanner that intercepts prompts before they're sent to any AI model—addressing the critical blind spot at the boundary of autonomous AI systems.\n\nYou'll learn:\n\n1. Real-world scenarios where credentials leak, prompt injections propagate, and PII compliance fails\n2. Why I chose Go and rules-based detection for sub-10ms latency\n3. Parallel scanning architecture for secrets, injection attacks, PII, and data exfiltration\n4. Policy-as-code profiles for enterprise risk tolerances\n5. HMAC-signed audit logs with causal traceability\n6. Evolving from deterministic rules to LLM-powered semantic analysis\n\nLeave with practical patterns for implementing security at the prompt boundary—the layer nobody else is building.","starts_at":"2026-09-24T14:25:00-07:00","ends_at":"2026-09-24T14:35:00-07:00","stage":"Outdoor Stage","track":"Security & Privacy","type":"Security & Privacy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ravi Sastry Kadali - AI/ML Engineer at General Motors"],"tags":["Agents","Agentic AI","Go","Prompt Engineering"],"live_url":"https://www.youtube.com/watch?v=nFhbMmrKWLk","recording_url":"https://www.youtube.com/watch?v=nFhbMmrKWLk","app_url":"https://app.wearedevelopers.com/events/18/session/1173","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1431-secureprompt","urls":["https://www.youtube.com/watch?v=nFhbMmrKWLk"],"flag":null},{"id":1408,"title":"Book Signing with John Romero - the Legendary Game Creator","description":"Book Signing with John Romero - the Legendary Game Creator\nLocation: Central Park | Expo Hall 1+2","starts_at":"2026-09-24T14:30:00-07:00","ends_at":"2026-09-24T16:00:00-07:00","stage":"Location TBA","track":"","type":"Session","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["John Romero at Legendary Game Creator | Father of FPS | DOOM, Quake, Wolfenstein"],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1408","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions","urls":[],"flag":null},{"id":1174,"title":"Agentic commerce's dirty little secret, and what to do about it.","description":"Commerce engineering spent 2026 building for the agent. UCP, ACP, AP2, MCP endpoints, Instant Checkout integrations. Meanwhile the merchant's own site, still where most revenue converts, has discovery that has not materially improved in a decade. These are treated as two roadmaps. They are one problem, and the second one is the reason the first one underdelivers.\n\nHere is the connective fact. Roughly 63% of zero-result site searches come from subjective, use-case queries: \"bike for commuting\", \"something for a beach wedding\". Around 81% of US shoppers abandon after an unsuccessful search. That query shape is exactly what an AI agent sends you. If your own search cannot answer it, neither can the agent, and no payment protocol fixes that. Meanwhile Adobe finds product pages are the least machine-readable surface on the average retail site at 66%, worse than the FAQ page, while AI-referred traffic converts 54% better than non-AI traffic and grew 693% year over year over the 2025 holiday.\n\nThis session makes the case for 360 degree discovery: every surface a human or machine can find a product through, served from one product layer. I will walk the four things it requires: universal agentic feed deployment as table stakes rather than strategy; clean and enriched product data as the foundation everything else silently depends on; three search surfaces rather than one; and visualization, including virtual try-on, as the step that converts finding into buying. Plus the nine-week triage: what is realistically shippable before holiday freeze and what is not.","starts_at":"2026-09-24T14:40:00-07:00","ends_at":"2026-09-24T14:50:00-07:00","stage":"Outdoor Stage","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Joe Monastiero - Founder & CEO at visualAI"],"tags":["APIs","Agentic AI","Data","eCommerce"],"live_url":"https://www.youtube.com/watch?v=CZkjiyxlF78","recording_url":"https://www.youtube.com/watch?v=CZkjiyxlF78","app_url":"https://app.wearedevelopers.com/events/18/session/1174","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1745-agentic-commerce-s","urls":["https://www.youtube.com/watch?v=CZkjiyxlF78"],"flag":null},{"id":1175,"title":"Running AI-Written Software in Production","description":"AI has collapsed the cost of writing software - agents and assistants produce more code, apps, and services than ever. Production has not gotten easier: all of it still has to be deployed, run, and debugged, often without a human who understands the code. How the production stack is changing now that much of the software it runs was written by machines.","starts_at":"2026-09-24T14:50:00-07:00","ends_at":"2026-09-24T15:20:00-07:00","stage":"Mainstage","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Milin Desai - CEO at Sentry","Anurag Goel - Founder & CEO at Render","Richard Rizk - Co-founder and CTO at BLACKBOX AI","Walden Yan - Co-founder at Cognition"],"tags":[],"live_url":"https://www.youtube.com/watch?v=kZQQn-XX19Y","recording_url":"https://www.youtube.com/watch?v=kZQQn-XX19Y","app_url":"https://app.wearedevelopers.com/events/18/session/1175","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1879-running-ai-written","urls":["https://www.youtube.com/watch?v=kZQQn-XX19Y"],"flag":null},{"id":1176,"title":"Ship with Context: GitLab Orbit and Google Cloud for AI-Powered Software Delivery","description":"- Why developers and AI agents need context across code, pipelines, security, deployments, and ownership.\n- How GitLab Orbit creates a queryable view of the software lifecycle to support dependency analysis, blast-radius assessment, and faster code review.\n- How GitLab CI/CD and Google Cloud services support secure, repeatable builds and deployments.\n- A developer workflow from code change to pipeline validation and Google Cloud deployment.\n- What tech leaders gain: faster delivery, stronger governance, better security visibility, and more confident releases.","starts_at":"2026-09-24T14:50:00-07:00","ends_at":"2026-09-24T15:20:00-07:00","stage":"Tech Leaders Stage","track":"","type":"Session","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Michael Angelo Rivera - GitLab Orbit Lead at GitLAb at GitLab","Matt Duchesne - AVP, Sales at GitLab","Rajesh Agadi - Principal Architect at Google Cloud"],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1176","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1923-ship-with-context","urls":[],"flag":null},{"id":1177,"title":"The Era of Machine-Driven Defense is Here: Headless Security","description":"Cybersecurity has hit a bottleneck. The problem isn’t gaps in detection or coverage, but because software was built for humans.\n\nMost security tools assume a human-in-the-loop paradigm: alerts surface in dashboards, analysts triage, and engineers remediate through workflows. However, software is no longer just consumed by people. AI is increasingly shouldering the work. Attackers already operate this way, using AI to tailor their campaigns, automate reconnaissance, and chain exploits at machine speed. \n\nHuman-centric software design isn’t just sub-optimal, it’s detrimental for machine use in an AI-driven landscape. Developers have already embraced the “as code” paradigm. Infrastructure and pipelines became code, and AI coding agents pushed execution into a programmable layer. When it comes to cybersecurity, software is overdue for a complete redesign: flexible, directly consumable by AI, and built for autonomous execution at machine speed.\n\nThis talk introduces headless security: a fundamentally different architecture in which security products are no longer interacted with directly, but consumed via APIs and composed and executed by coding agents. The control loop – discover, prioritize, remediate – moves from dashboards to the environment where software is built and run. \n\nThis model reshapes system design and responsibility boundaries. Humans shift from operators to governors, defining intent, constraints, and risk tolerances while agents execute. Security becomes part of the development surface – where workflows are programmable, testable, and version-controlled, with risks resolved inline as code.\n\nLoris will explore how this model works, with implementation and real-world scenarios, including the engineering and security challenges of enforcing trust boundaries and ensuring auditability in a UI-less system.\n\nThe future of security is not operations and dashboards. It is outcome-based, meaningful for every user, and embedded in how software is built and run.","starts_at":"2026-09-24T14:50:00-07:00","ends_at":"2026-09-24T15:20:00-07:00","stage":"Stage 1","track":"Security & Privacy","type":"Security & Privacy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Loris Degioanni - Founder & CTO at Sysdig"],"tags":["Agentic AI","Automation","Autonomous Systems","Best Practices","Cloud Security","DevSecOps","Future of Work","Innovation","Multi-Cloud","Security","Software Architecture","System Design","Tooling"],"live_url":"https://www.youtube.com/watch?v=pkKs9PeOVv0","recording_url":"https://www.youtube.com/watch?v=pkKs9PeOVv0","app_url":"https://app.wearedevelopers.com/events/18/session/1177","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1951-the-era-of-machine","urls":["https://www.youtube.com/watch?v=pkKs9PeOVv0"],"flag":null},{"id":1178,"title":"Databases in the Agent Era","description":"We are entering a new era where AI agents are first-class users of data infrastructure.\n\nThese systems don’t behave like traditional applications. They operate in loops, branch workflows continuously, retry autonomously, and demand immediate access to real data. The result? A fundamental shift in how databases must be designed and operated.\n\nIn this talk, we’ll explore how agentic workloads are redefining database requirements, from latency expectations to isolation models, access control, and data privacy. We’ll look at why traditional staging environments and replication strategies struggle under this new pressure and how emerging patterns like copy-on-write branching and ephemeral environments change the game.\n\nIf you build backend systems, data platforms, or AI-driven applications, this talk will help you understand what “agent-ready” really means and how to design for it.","starts_at":"2026-09-24T14:50:00-07:00","ends_at":"2026-09-24T15:20:00-07:00","stage":"Stage 2","track":"Data & Databases","type":"Data & Databases","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Monica Sarbu - Founder & CEO at xata.io"],"tags":["Agents","Agentic AI","Data","Databases"],"live_url":"https://www.youtube.com/watch?v=caJa-YSTOFo","recording_url":"https://www.youtube.com/watch?v=caJa-YSTOFo","app_url":"https://app.wearedevelopers.com/events/18/session/1178","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1678-databases-in-the","urls":["https://www.youtube.com/watch?v=caJa-YSTOFo"],"flag":null},{"id":1179,"title":"Why AI-Written Books Fail – and How We Made Quality Measurable","description":"Anyone can generate 40,000 words with an LLM today. Almost none of it survives contact with a reader. At story.one, we generate complete non-fiction books – 17 chapters, printed and sold in real bookstores – and over the past 18 months we read and scored more than 1,000 of them, cover to cover.\n\nThis talk is the engineering story of what we found. Why long-form generation fails in ways chatbot demos never show: phrase tics, structural repetition, fabricated quotes, visible seams between regenerated passages. Why the model is the smallest part of the problem. And how we built a release standard around a neurosymbolic idea: fast neural generation, slow symbolic verification – deterministic checks in code (quote verification against original sources, style-pattern detection, structural gates), blind evaluation with fresh context, and a nightly regression suite of real-world cases.\n\nYou will leave with three transferable lessons for any long-form GenAI product – and you will see a book that was generated, verified, printed, and sold the same day.","starts_at":"2026-09-24T14:50:00-07:00","ends_at":"2026-09-24T15:20:00-07:00","stage":"Stage 3","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Hannes Steiner - Founder & CEO at Story.one","Thomas Neumayer - CEO at ExtensityAI"],"tags":[],"live_url":"https://www.youtube.com/watch?v=F4FcsTgis2s","recording_url":"https://www.youtube.com/watch?v=F4FcsTgis2s","app_url":"https://app.wearedevelopers.com/events/18/session/1179","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1896-why-ai-written-books","urls":["https://www.youtube.com/watch?v=F4FcsTgis2s"],"flag":null},{"id":1180,"title":"When Logging Becomes The Outage: Escaping the ECS Logging Trap","description":"Logging systems are designed to help us understand failures, but what happens when the Logging itself becomes the cause of an outage?\n\nIn this session, I will walk through a real-world incident involving Amazon ECS where the default logging configuration used blocking mode with CloudWatch as the log destination. When CloudWatch experienced an outage, application containers continued attempting to push logs while buffering them locally. As the logging buffer reached its limit, containers became blocked waiting for the logging driver, ultimately impacting application availability.\n\nThis talk explores how a seemingly harmless default configuration can create an unexpected reliability risk in distributed systems. We will look at how ECS logging works under the hood, why blocking mode can create cascading failures during downstream outages, and how switching to non-blocking mode can isolate application workloads from logging system failures.\n\nI will share the investigation process, architectural decisions, and practical lessons learned from redesigning the logging strategy to prevent observability dependencies from affecting production workloads.\n\nAttendees will leave with actionable guidance on designing resilient logging pipelines and avoiding a class of failures where logging infrastructure unintentionally becomes the single point of failure.","starts_at":"2026-09-24T14:50:00-07:00","ends_at":"2026-09-24T15:20:00-07:00","stage":"Stage 4","track":"DevOps & Platform Engineering","type":"DevOps & Platform Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Rahul Tanniru - Senior VP Software Engineering at JPMorgan Chase"],"tags":["AWS","Containers"],"live_url":"https://www.youtube.com/watch?v=4lau0dXhp5c","recording_url":"https://www.youtube.com/watch?v=4lau0dXhp5c","app_url":"https://app.wearedevelopers.com/events/18/session/1180","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1670-when-logging-becomes","urls":["https://www.youtube.com/watch?v=4lau0dXhp5c"],"flag":null},{"id":1181,"title":"Travel’s AI-Powered Shift: How Expedia Group Is Building in the AI Era","description":"Travel is a complex industry, and at Expedia Group that complexity is becoming a proving ground for AI-enabled innovation and a new kind of engineering leadership.\nIn this fireside chat, Expedia Group engineering leaders share how they are rethinking the software development lifecycle in the AI era — from early AI tooling adoption toward connected, purpose-built agentic systems.\nThey’ll discuss what is changing in practice: how AI is helping teams ship higher-quality experiences faster, how smaller teams are delivering work in fewer sprints, and how impact is being measured through cycle times, velocity, output, and business outcomes—not adoption alone.\nThey’ll also explore the next phase of Expedia Group’s AI strategy: agents inside Expedia Group that help employees move faster, supported by responsible AI guardrails and a flexible technology foundation.\nCome for a grounded, practitioner's view of leading as the stack and tooling evolve at a breakneck pace.","starts_at":"2026-09-24T14:50:00-07:00","ends_at":"2026-09-24T15:20:00-07:00","stage":"Stage 5","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Debashis Saha - Senior Vice President, Technology at Expedia Group","Julia Elliott - Vice President, Technology and Chief of Staff at Expedia Group"],"tags":["AGI (Artificial General Intelligence)","AI Standards","Automation","Best Practices","Digital Transformation","Future of Work","Productivity"],"live_url":"https://www.youtube.com/watch?v=7zS6Rqu3zd4","recording_url":"https://www.youtube.com/watch?v=7zS6Rqu3zd4","app_url":"https://app.wearedevelopers.com/events/18/session/1181","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1893-travel-s-ai-powered","urls":["https://www.youtube.com/watch?v=7zS6Rqu3zd4"],"flag":null},{"id":1182,"title":"Beyond the Vibe: Specs, Adversarial Review, and Engineering AI Development that Scales and Ships","description":"Vibe coding is real, and it's useful — it's how you rapidly explore ideas and prove out concepts. But by definition, vibing means using AI for something you're not deep in yourself, and that's precisely why it can't be where production code comes from. Production starts earlier than people think: with specs that get adversarially reviewed before a single line gets written, then the engineering expertise to know what good looks like, and the agentic harnesses, domain modeling, and durable testing that enforce it at scale. AI doesn't replace that expertise — it multiplies it, letting people who already know what they're doing move faster and build better. Practical, technical, and grounded in what PwC has built and learned in production.","starts_at":"2026-09-24T14:50:00-07:00","ends_at":"2026-09-24T15:20:00-07:00","stage":"Stage 6","track":"","type":"Session","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ussama Baggili - Principal, App Modernization & Development, Cloud Engineering & Data Analytics | Anthropic Alliance CTO at PwC US"],"tags":["AI Coding Assistants","Agentic AI","Code Generation","Developer Experience (DevEx)","Generative AI (GenAI)","Governance","LLMOps","Multi-Agent Systems","Testing","Vibe Coding"],"live_url":"https://www.youtube.com/watch?v=1UbH8cFA8HE","recording_url":"https://www.youtube.com/watch?v=1UbH8cFA8HE","app_url":"https://app.wearedevelopers.com/events/18/session/1182","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1900-beyond-the-vibe","urls":["https://www.youtube.com/watch?v=1UbH8cFA8HE"],"flag":null},{"id":1183,"title":"When Agents Became Users: Rearchitecting Identity and Permissions for AI at Scale","description":"Most platforms add AI agents as apps: the agent runs with the permissions of whoever invokes it.\nSimplest thing to ship. Across hundreds of thousands of teams, serving enterprises that audit every access, that model fell apart. This is how we rebuilt agents as first-class users, with their own identity, permissions, and audit trail.\nThe first architecture was the obvious one: an agent could do only what both it and the invoking user were allowed to do. Simple to build, it broke at scale. The agent's access changed with every invoker, so no one could say what it could actually reach. Actions were attributed to the human, leaving no per-agent audit. And a shared agent became a leak risk, exposing its invoker's data to everyone allowed to run it.\nFixing this meant making a non-human a first-class user inside a system built for humans: its own identity, scoped least-privilege permissions, admin-managed provisioning, and a place in the workspace where it can be assigned work and audited. The payoff was counterintuitive. Once an agent is a user, 20 years of enterprise identity infrastructure (SSO, RBAC, provisioning, audit logs) works for it for free, instead of a separate control plane for AI. One enterprise built 25 agents, each needing different access. Before, any agent could read what its invoker could read and pass it to the whole team. Now each is shared across the team and never touches data it was not explicitly granted.\nThe permission models, the tradeoffs we got wrong first, and what it takes at scale. From the applied AI perspective, why agent identity is the central design problem for AI at work. Expect real systems and real failure modes.","starts_at":"2026-09-24T14:50:00-07:00","ends_at":"2026-09-24T15:20:00-07:00","stage":"Stage 7","track":"AI Trust & Safety","type":"AI Trust & Safety","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Yoav Gal at Product Lead"],"tags":["AI Standards","Agents","Agentic AI","Collaboration","Future of Work"],"live_url":"https://www.youtube.com/watch?v=Bo5yuYJY2Ng","recording_url":"https://www.youtube.com/watch?v=Bo5yuYJY2Ng","app_url":"https://app.wearedevelopers.com/events/18/session/1183","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1713-when-agents-became","urls":["https://www.youtube.com/watch?v=Bo5yuYJY2Ng"],"flag":null},{"id":1184,"title":"How to generate business value through performance optimizations","description":"Performance is the most overlooked problem in mobile engineering — not because engineers don't care, but because it's invisible. When something crashes, there's a log. When servers cost too much, there's a bill. When an app is slow, users just leave. No alert fires, no ticket gets filed. That invisibility is the whole problem, and the talk is a systematic answer to it.\nThe framework it introduces — Performance, Reliability, Efficiency — exists to show that these three things are connected and pull against each other. Making one screen faster can make the whole system more expensive. Understanding the trade-offs is what separates reactive firefighting from deliberate engineering.\nThe core of the talk is a cycle: instrument the app, collect the right data, analyze it, prioritize what to fix, implement, and validate. The instrumentation piece is more nuanced than it sounds — what you measure and where you start the timer matters. The rule is to measure what the system does, not what the user does, because user behavior introduces noise that makes the data useless.\nOnce you have data, averages mislead. Percentiles tell the truth. A small number of metrics — median latency, tail latency, success rate, failure rate, abandonment rate — gives a complete picture of any screen. Abandonment is the one most teams ignore, and it's the most honest signal: a user who left before the page loaded is a direct conversion loss that shows up nowhere in traditional monitoring.\nThe abandonment curve is where engineering data becomes a business argument. It shows exactly how increasing load time drives users away, with a clear inflection point above which every additional millisecond has an outsized cost. That curve, combined with traffic volume, tells you where to focus: a small improvement on the screen every user sees daily is worth more than a large improvement on a screen almost nobody visits.","starts_at":"2026-09-24T14:50:00-07:00","ends_at":"2026-09-24T15:20:00-07:00","stage":"Stage 9","track":"Languages, Web & Mobile","type":"Languages, Web & Mobile","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Nikolai Sidiropulo - Software Engineer at Meta"],"tags":["Android","iOS","Performance"],"live_url":"https://www.youtube.com/watch?v=opo8Uf3huJw","recording_url":"https://www.youtube.com/watch?v=opo8Uf3huJw","app_url":"https://app.wearedevelopers.com/events/18/session/1184","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1686-how-to-generate","urls":["https://www.youtube.com/watch?v=opo8Uf3huJw"],"flag":null},{"id":1185,"title":"In-Person by Default: Principles & Practices for Building Developer Meetups","description":"Meetups often die the same way. People show up once, have a fine time, and never come back.\n\nCode & Coffee is a nonprofit that runs 300 meetup events a year across 30 cities for a community of 80,000 members, on an annual operating budget under $6,000 and with almost no paid marketing. It only works because people return for an actual community, not just another audience.\n\nThis session is about meetup and community design. Steve will show how Belonging, Trust, and Safety translate into specific decisions rather than values on a slide: the intro-circle ritual run at every event, the cadence rule organizers have followed since 2017, and why Code & Coffee events are social by default instead of built around endless talks.\n\nSteve will also cover the unglamorous operations: where to find a free venue in your city, what to ask a sponsor for, and what to offer in return.\n\nIf you have ever wanted to organize a meetup community, run events, grow a developer community, or have simply been waiting for someone else to start the meetup you want to attend, this talk is for you. You will leave with a repeatable meetup event format you can adapt and a concrete first step you can take toward building community.","starts_at":"2026-09-24T14:55:00-07:00","ends_at":"2026-09-24T15:05:00-07:00","stage":"Outdoor Stage","track":"Career, Culture & Community","type":"Career, Culture & Community","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Steve Chen - Executive Director and Founder at Code & Coffee"],"tags":["Career Development","Community","Developer Experience (DevEx)","People & Culture"],"live_url":"https://www.youtube.com/watch?v=-zHvJHX_IKc","recording_url":"https://www.youtube.com/watch?v=-zHvJHX_IKc","app_url":"https://app.wearedevelopers.com/events/18/session/1185","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1747-in-person-by-default","urls":["https://www.youtube.com/watch?v=-zHvJHX_IKc"],"flag":null},{"id":1187,"title":"Our Brains in the AI Era","description":"AI is everywhere. In your editor, your terminal, your code review, your inbox, your search bar—and probably your toaster by the time this talk happens. We're not here to pretend otherwise, and we're not here just to dunk on it.\n\nThis keynote is an honest look at what happens to us, as developers and as people, when we outsource our thinking at scale.\n\nWe're living in a genuinely exciting moment. Modern tools are more accessible than ever, shifting us from conforming to existing SaaS toward building personal tools and personal software.\n\nBut the cost is real: AI \"slop\" is showing up in open source pull requests, documentation, code reviews, and emails. The internet is filling with content humans didn't really think about, and the habit of thinking hard is eroding.\n\nThis talk explores the nuance. It's not simply \"AI good\" or \"AI bad.\" We'll cover guardrails, speaking up for quality, and continuing to think better—because our brains are resources we have to keep for the rest of our lives.","starts_at":"2026-09-24T15:30:00-07:00","ends_at":"2026-09-24T16:00:00-07:00","stage":"Mainstage","track":"Career, Culture & Community","type":"Career, Culture & Community","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Cassidy Williams - Senior Director of Developer Advocacy at GitHub"],"tags":["Advocacy"],"live_url":"https://www.youtube.com/watch?v=O42bV8AnvFM","recording_url":"https://www.youtube.com/watch?v=O42bV8AnvFM","app_url":"https://app.wearedevelopers.com/events/18/session/1187","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1872-our-brains-in-the-ai","urls":["https://www.youtube.com/watch?v=O42bV8AnvFM"],"flag":null},{"id":1188,"title":"Transforming Enterprise AI with Tabular Foundation Models","description":"Tabular Foundation Models are redefining enterprise AI by bringing foundation-model capabilities to structured business data. This session explores SAP's latest innovations, including the RPT-1.5 model and the recently acquired Prior Labs, creators of TabPFN, while also reviewing the latest academic advances. Hear from Tech leaders how these innovations are shaping the next generation of AI-powered enterprise applications through more accurate predictive analytics, intelligent automation, and business decision-making","starts_at":"2026-09-24T15:30:00-07:00","ends_at":"2026-09-24T16:00:00-07:00","stage":"Tech Leaders Stage","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Leo Grinsztajn - Founding Research Scientist at Prior Labs","Tom Palczewski - Tech Lead, Expert AI Scientist - Generative AI at SAP","Yaad Oren - Managing Director & Global Head at SAP Labs US & SAP Research & Innovation"],"tags":[],"live_url":"https://www.youtube.com/watch?v=80MorMiWJN4","recording_url":"https://www.youtube.com/watch?v=80MorMiWJN4","app_url":"https://app.wearedevelopers.com/events/18/session/1188","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1892-transforming","urls":["https://www.youtube.com/watch?v=80MorMiWJN4"],"flag":null},{"id":1190,"title":"KV Cache Is Not About Speed: It's About Surviving Inference Costs","description":"Most teams think KV cache is about making inference faster. That's true, but it's not the point. KV cache is really about controlling memory, reducing recomputation, and keeping costs from spiraling as usage grows. As models get deployed at scale, the real bottleneck is no longer raw compute. It's memory, bandwidth, and power. This session takes a step back to explain what KV cache does at a system level, why it matters for real workloads, and how approaches like vLLM, LMCache, and SGLang change how we think about scaling inference.\n\nWe'll also connect this to a problem many teams are already seeing: confidently incorrect answers in agent systems. When cache behavior, context reuse, and routing aren't designed well, systems don't just get slower or more expensive. They get inconsistent. And that shows up as wrong answers with high confidence. This session will walk through these trade-offs using live demos, showing how different KV cache strategies impact cost, latency, and output quality in real time.","starts_at":"2026-09-24T15:30:00-07:00","ends_at":"2026-09-24T16:00:00-07:00","stage":"Stage 2","track":"AI Models & Infrastructure","type":"AI Models & Infrastructure","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["David vonThenen - Sr. AI/ML Engineer at NetApp"],"tags":["AI Models","Agentic AI","Caching","Data","Large Language Models (LLMs)"],"live_url":"https://www.youtube.com/watch?v=gbnHMp6Jr00","recording_url":"https://www.youtube.com/watch?v=gbnHMp6Jr00","app_url":"https://app.wearedevelopers.com/events/18/session/1190","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1668-kv-cache-is-not","urls":["https://www.youtube.com/watch?v=gbnHMp6Jr00"],"flag":null},{"id":1191,"title":"The New Bottleneck in Software Development","description":"AI is making it easier than ever to write code, but shipping it is becoming the harder problem. As developers and coding agents produce more code, codebases are growing, CI workloads are increasing, and build and test times are becoming a bigger constraint on engineering velocity. This talk explores why code validation is emerging as the new bottleneck in software development, and why the teams that can build, test, and ship faster will have a meaningful competitive advantage.","starts_at":"2026-09-24T15:30:00-07:00","ends_at":"2026-09-24T16:00:00-07:00","stage":"Stage 3","track":"Architecture & Backend","type":"Architecture & Backend","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Aditya Jayaprakash - Co-Founder & CEO at Blacksmith"],"tags":["AWS","CI/CD","DevOps","Infrastructure"],"live_url":"https://www.youtube.com/watch?v=IoVhGWpUM58","recording_url":"https://www.youtube.com/watch?v=IoVhGWpUM58","app_url":"https://app.wearedevelopers.com/events/18/session/1191","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1821-the-new-bottleneck","urls":["https://www.youtube.com/watch?v=IoVhGWpUM58"],"flag":null},{"id":1193,"title":"The reviewer can't be the author: independent verification for AI-generated code","description":"AI agents write more of your code every day, and their failures are getting rarer but more convincing. When the output looks right, reviewers stop looking hard, and a subtle bug or insecure pattern spreads across the codebase at machine speed.\nThe fix is not a better model. It is independent, multilayered verification: checking code with different methods than the one that wrote it. Algorithmic analysis catches what is provably wrong, agentic review catches what needs judgment, and together they stay auditable instead of just agreeing with the agent. This is the Verify discipline at the heart of Sonar's Agent Centric Development Cycle (AC/DC), where agents generate and a separate layer guides, verifies, and helps solve what it finds.\nWe put the leading LLMs through a deep evaluation and found clear, repeatable patterns in where they break. You will see that data, and how to put this verification around your agents so you keep the speed without the risk.","starts_at":"2026-09-24T15:30:00-07:00","ends_at":"2026-09-24T16:00:00-07:00","stage":"Stage 5","track":"AI Trust & Safety","type":"AI Trust & Safety","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Manish Kapur - VP, Product & Solutions at Sonar"],"tags":["AI Coding Assistants","AI Standards","Agents","Best Practices","Clean Code","Code Reviews","Governance","Sonar"],"live_url":"https://www.youtube.com/watch?v=1go4C7pCyJs","recording_url":"https://www.youtube.com/watch?v=1go4C7pCyJs","app_url":"https://app.wearedevelopers.com/events/18/session/1193","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1822-the-reviewer-can-t","urls":["https://www.youtube.com/watch?v=1go4C7pCyJs"],"flag":null},{"id":1194,"title":"Going beyond the code through the GitHub Copilot App: how to unlock you and your team’s superpower","description":"Developing great software takes more than just writing good code. Which is why the GitHub Copilot App is built to go beyond the code! In this session, you'll discover how developers, business users, and all types of \"builders\" are using the GitHub Copilot App to supercharge their workflows, from prioritization and documentation to data analysis and cross-team coordination. Through a short demo grounded in real customer examples and GitHub's own use cases, you'll experience how different organizations are enabling builders to unlock their superpowers through the GitHub Copilot App. Walk away with practical patterns for not only yourself, but to accelerate adoption at your organization.","starts_at":"2026-09-24T15:30:00-07:00","ends_at":"2026-09-24T16:00:00-07:00","stage":"Stage 6","track":"DevEx & Productivity","type":"DevEx & Productivity","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Jenny Hwang - Director of User Research at GitHub"],"tags":["Agentic AI"],"live_url":"https://www.youtube.com/watch?v=ElGOJNgO3JU","recording_url":"https://www.youtube.com/watch?v=ElGOJNgO3JU","app_url":"https://app.wearedevelopers.com/events/18/session/1194","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1788-going-beyond-the","urls":["https://www.youtube.com/watch?v=ElGOJNgO3JU"],"flag":null},{"id":1195,"title":"Beyond Vibe Coding: Using CLI Tools as Your AI Counterpart in Pair Programming","description":"The software development paradigm is shifting, moving AI from a helpful suggestion engine to a collaborative partner. This hands-on session is designed for developers ready to elevate their workflow by integrating powerful AI Command Line Interface (CLI) tools directly into their pair-programming sessions.\n\nWe will conduct a live comparison of leading tools, specifically focusing on Google Gemini, Anthropic's Claude Code, and OpenAI Codex (or similar contemporary offerings), demonstrating how they act as reliable, functional counterparts—not just code generators. Attendees will see detailed, real-world examples outlining:\n\nHow to structure effective prompts for complex, multi-step tasks.\n\nDeep dives into capabilities like codebase summarization, targeted refactoring, and test generation.\n\nIdentifying and mitigating common issues like context drift and tool-specific latency limitations.\n\nCritically, we emphasize that this is not about \"vibe coding\"—mindlessly accepting AI suggestions—but about adopting a structured, professional, and efficient way to develop.","starts_at":"2026-09-24T15:30:00-07:00","ends_at":"2026-09-24T16:00:00-07:00","stage":"Stage 7","track":"DevEx & Productivity","type":"DevEx & Productivity","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ron Veen - Sr. Developer at Team Rockstars IT"],"tags":["AI Coding Assistants","Anthropic","Gemini","OpenAI"],"live_url":"https://www.youtube.com/watch?v=ldivx4nuy98","recording_url":"https://www.youtube.com/watch?v=ldivx4nuy98","app_url":"https://app.wearedevelopers.com/events/18/session/1195","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1721-beyond-vibe-coding","urls":["https://www.youtube.com/watch?v=ldivx4nuy98"],"flag":null},{"id":1196,"title":"From Boardroom to Build Pipeline: What AI Governance Actually Looks Like in Practice","description":"Sixty-two percent of public company boards now dedicate agenda time to AI. Fewer than 10 percent have approved budgets for AI projects or adopted meaningful metrics for reporting on them. That gap :between awareness and action :is where AI initiatives go to die.\n\nAs a board director and former senior P&L executive who has reviewed dozens of AI initiatives across multiple companies, I've seen the full spectrum: structured projects with clear ROI thresholds, and aspirational efforts with no owner, no baseline metrics, and no path to integration. The pattern is consistent :the projects that fail aren't the ones with bad models. They're the ones with no governance framework around execution.\n\nIn this talk, I'll share practical frameworks that engineering leaders and product teams can adopt to make their AI projects board-ready and business-accountable. I'll walk through the Technology ROI Matrix :a method for evaluating AI initiatives across strategic alignment, investment efficiency, and execution readiness :and the Stage-Gate model adapted for AI, which establishes clear success criteria at each phase from discovery through scale. I'll cover the critical questions every AI initiative should be able to answer: What baseline are we measuring against? Who owns the outcome? How do we detect when the AI system deviates from expected behavior? What's the full cost of building, operating, monitoring, and refreshing this system?\n\nThis isn't a talk about compliance checklists. It's about the discipline that separates AI projects that transform businesses from ones that quietly drain resources. Whether you're a developer advocating for an AI initiative, an engineering leader allocating budget, or a CTO reporting to a board, you'll leave with actionable evaluation frameworks you can apply immediately.","starts_at":"2026-09-24T15:30:00-07:00","ends_at":"2026-09-24T16:00:00-07:00","stage":"Outdoor Stage","track":"Leadership & Strategy","type":"Leadership & Strategy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Anita Ganti - Board member, Corporate Director & Technology Executive at Kavia AI"],"tags":["AI Standards","Best Practices","Business Models","Compliance","Digital Transformation","Ethics","Governance","Innovation","Metrics","Regulation","Safety"],"live_url":"https://www.youtube.com/watch?v=wl-SzbgVuuY","recording_url":"https://www.youtube.com/watch?v=wl-SzbgVuuY","app_url":"https://app.wearedevelopers.com/events/18/session/1196","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1947-from-boardroom-to","urls":["https://www.youtube.com/watch?v=wl-SzbgVuuY"],"flag":null},{"id":1210,"title":"The Reality of AI Adoption in Enterprises","description":"Every enterprise thinks their AI adoption story is unique. It isn't. After leading GitHub Copilot's rollout across Fortune 100 engineering teams at Microsoft and before that, launching Gemini Code Assist at Google Cloud with hackathons in over 60 countries I've seen the same patterns repeat at scale: the initial excitement, the plateau, the backlash, and finally the transformation.\n\nThis isn't a talk about features or benchmarks. It's about the human journey: how SDLC actually changes when AI becomes a collaborator, why adoption curves look nothing like what vendors promise, and what separates teams that truly level up from those who just add a new tab to their IDE. I'll bring real patterns from the frontlines with honest stories, no marketing spin.","starts_at":"2026-09-24T15:30:00-07:00","ends_at":"2026-09-24T16:00:00-07:00","stage":"Stage 1","track":"Applied AI","type":"Applied AI","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Priyanka Vergadia - Founder at Cloud Girl"],"tags":["AI Coding Assistants","GitHub","Secure Coding","Vibe Coding"],"live_url":"https://www.youtube.com/watch?v=YGHM5UxOXuo","recording_url":"https://www.youtube.com/watch?v=YGHM5UxOXuo","app_url":"https://app.wearedevelopers.com/events/18/session/1210","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1752-the-reality-of-ai","urls":["https://www.youtube.com/watch?v=YGHM5UxOXuo"],"flag":null},{"id":1254,"title":"Your next customer won’t be human","description":"With a global daily user base in the hundreds of millions, AI agents are rapidly becoming a primary interface for how people discover, evaluate, and purchase products. Enabling those products to be listed and paid for directly through agents opens an entirely new, and enormous, commerce channel. The Agent Commerce Protocol (ACP) and Shared Payment Tokens provide a secure framework for agent-driven commerce within Stripe’s ecosystem, without exposing payment data or sacrificing user control.\n\nThis session walks developers through the complete implementation: setting up Stripe integration, creating permission-based payment tokens, interacting with ACP endpoints, and designing trustworthy user experiences. You'll learn how to enable your agents to transact safely and predictably, handling everything from checkout flows to error scenarios and webhook events.","starts_at":"2026-09-24T15:30:00-07:00","ends_at":"2026-09-24T16:00:00-07:00","stage":"Stage 4","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Benjamin Smith - Staff Developer Advocate at Stripe"],"tags":["Agentic AI","eCommerce"],"live_url":"https://www.youtube.com/watch?v=-hhL8uiuRIU","recording_url":"https://www.youtube.com/watch?v=-hhL8uiuRIU","app_url":"https://app.wearedevelopers.com/events/18/session/1254","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1439-your-next-customer","urls":["https://www.youtube.com/watch?v=-hhL8uiuRIU"],"flag":null},{"id":1198,"title":"Come with an Idea, Leave with an App: Build and Launch Your Website with AI","description":"In this hands-on session, you will actually build, launch, and go home with a live website of your own. We will guide you step-by-step from a blank canvas to a fully working site hosted live on Google Cloud. If you are feeling creative, you can even go beyond a simple website and experiment with more advanced, full-stack ideas. You will walk away with a permanent, live web link that is yours to keep, share, and continue building on.\n\n- Turn your creative ideas into a fully functional website.\n- Publish your site to the web, giving you a live link you can share with the world.\n- Experiment with AI to customize your project, fix issues on the fly, or build advanced features.","starts_at":"2026-09-24T16:00:00-07:00","ends_at":"2026-09-24T18:00:00-07:00","stage":"Stage 8","track":"AI Engineering","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"Laptop & charger","speakers":["Denise Kwan - Senior Developer Advocate at Google"],"tags":["DevRel & Advocacy","Firebase","Google Cloud (GCP)"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1198","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1801-come-with-an-idea","urls":[],"flag":null},{"id":1199,"title":"Reprompting the Wheel? Why AI Won’t Save Your Content Platform","description":"Everyone’s convinced a few good prompts can build a real platform. This masterclass puts that assumption to the test: 10 chapters, 10 live demos, one takeaway — vibe-coding your way to an enterprise-grade Content Platform still means reinventing what TYPO3 CMS’s version 14 already does. The real shortcut isn’t prompting from scratch — it’s building on top of a platform that’s battle-tested and enterprise-ready.","starts_at":"2026-09-24T16:00:00-07:00","ends_at":"2026-09-24T18:00:00-07:00","stage":"Stage 10","track":"AI Engineering","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"","speakers":["Benni Mack - TYPO3 CMS Project Lead at TYPO3"],"tags":["Internal Platforms","Open Source","PHP"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1199","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1816-reprompting-the","urls":[],"flag":null},{"id":1200,"title":"Practical Threat Modeling for Software Developers","description":"Security isn’t just about firewalls and patches, it starts long before the first line of code is deployed.\n\nIn this workshop, we’ll explore how threat modeling helps teams move from a reactive security mindset to a proactive, design-first approach. You’ll learn how to identify vulnerabilities before they become incidents, map out potential attack paths, and make risk-informed decisions, all before the build is complete.","starts_at":"2026-09-24T16:00:00-07:00","ends_at":"2026-09-24T18:00:00-07:00","stage":"Stage 13","track":"Security & Privacy","type":"Workshop","live_coding":false,"is_workshop":true,"capacity":36,"waitlist":5,"requirements":"","speakers":["Mudassir Syed - Security Software Engineer at Autodesk"],"tags":["AppSec","Cloud Security"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1200","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1720-practical-threat","urls":[],"flag":null},{"id":1202,"title":"Agent Speedrun: Idea → Code → Deploy → Observe, Fix → Ship","description":"One agent. Fully deployed to production before the workshop ends. We'll take you from a blank file to a running production agent using Amazon Bedrock AgentCore and Strands Agents, covering the full lifecycle: ideation, coding the agent loop, deploying to serverless infrastructure, wiring up observability, breaking it intentionally, fixing it with tracing data, and shipping the final version.\nBring your laptop and leave with a deployed agent.","starts_at":"2026-09-24T16:00:00-07:00","ends_at":"2026-09-24T18:00:00-07:00","stage":"Stage 14","track":"AI Agents","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"More soon","speakers":["Elizabeth Fuentes Leone - Developer Advocate/SDE, GenAI at AWS","Sandhya Subramani - Senior Developer Advocate at AWS"],"tags":["AWS","Agentic AI","Code Generation","Infrastructure as Code (IaC)","Observability"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1202","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1795-agent-speedrun-idea","urls":[],"flag":null},{"id":1307,"title":"Agentic coding with GitHub Copilot App","description":"The GitHub Copilot app is an experience built from the ground up specifically for developing with AI. It integrates with GitHub, is customizable to your workflows and approaches, and can even automate tasks. Let's explore the app, and how to accelerate your development processes!","starts_at":"2026-09-24T16:00:00-07:00","ends_at":"2026-09-24T18:00:00-07:00","stage":"Stage 12","track":"","type":"Workshop","live_coding":false,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"Attendees should bring their own laptops with Node.js installed. They should also have a GitHub account and download the Copilot App.","speakers":["Gustavo Cordido - Cloud Advocate at GitHub"],"tags":["AI Coding Assistants","Copilot","GitHub"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1307","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1914-agentic-coding-with","urls":[],"flag":null},{"id":1197,"title":"Run your agents in Kubernetes: Build once, deploy anywhere. But really?","description":"You know that - A demo works on your laptop, then you deploy it elswere and it's not. Migrating a Kubernetes workloads from one platform to another is not just flipping the switch.\nI created the LLM app utilizing a small quantized open model (~4B, CPU-only, serving inside the cluster) running it on a local kind cluster on my M4 MacBook. However, once moved to the AWS EKS, the pod died with 'exec format error'.\nThe fix exposed the next failure, and the next... a liveness probe killing the model server mid-load, ':latest' meaning different images on different clusters, kubelet garbage-collecting the multi-gigabyte model weights, a hardcoded DNS suffix, a NetworkPolicy silently doing nothing.\nLet's find out what lies between \"works on my laptop\" and \"runs anywhere\", because \"Build once, deploy anywhere\" is a claim you must earn.","starts_at":"2026-09-24T16:10:00-07:00","ends_at":"2026-09-24T16:40:00-07:00","stage":"Outdoor Stage","track":"DevOps & Platform Engineering","type":"DevOps & Platform Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Michal Salanci - Sr. Systems Engineer at ESET Cybersecurity"],"tags":["AI Models","AWS","Containers","Docker","Large Language Models (LLMs)","Migration"],"live_url":"https://www.youtube.com/watch?v=sJItu9bj1WI","recording_url":"https://www.youtube.com/watch?v=sJItu9bj1WI","app_url":"https://app.wearedevelopers.com/events/18/session/1197","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1676-run-your-agents-in","urls":["https://www.youtube.com/watch?v=sJItu9bj1WI"],"flag":null},{"id":1203,"title":"The future of workforce, at high speed","description":"What can a Formula 1 driver teach a software developer about working with AI? This session follows where the value sits when work moves at a very high speed and how Mercedes-Benz is approaching the way AI is changing the way we work, what it means for developers, for leaders and the workforce as a whole.","starts_at":"2026-09-24T16:10:00-07:00","ends_at":"2026-09-24T16:40:00-07:00","stage":"Mainstage","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Daniela Dimitrova - VP IT & CIO - Mercedes-Benz North America"],"tags":["AI Coding Assistants","Career Development","Code Generation","Motivation"],"live_url":"https://www.youtube.com/watch?v=lz-Ri7WDJ80","recording_url":"https://www.youtube.com/watch?v=lz-Ri7WDJ80","app_url":"https://app.wearedevelopers.com/events/18/session/1203","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1901-the-future-of","urls":["https://www.youtube.com/watch?v=lz-Ri7WDJ80"],"flag":null},{"id":1204,"title":"Shipping AI Features People Actually Use","description":"Every product now has AI features. Most of them go unused. Enterprises buy copilots that employees ignore, consumer apps ship AI that users try once, and roadmaps fill with capabilities nobody asked for. The gap between shipping AI and getting people to actually use it has become the defining product problem of the AI era. How teams decide which AI features to build, how they drive real adoption instead of demo applause, and what they killed along the way.","starts_at":"2026-09-24T16:10:00-07:00","ends_at":"2026-09-24T16:40:00-07:00","stage":"Tech Leaders Stage","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ben Kus - CTO at Box","Stefan Lederer - Co-founder & CEO at Bitmovin","Wayne Liu - Chief Growth Officer & Americas President at Perfect Corp."],"tags":[],"live_url":"https://www.youtube.com/watch?v=R6fclhGyMwA","recording_url":"https://www.youtube.com/watch?v=R6fclhGyMwA","app_url":"https://app.wearedevelopers.com/events/18/session/1204","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1883-shipping-ai-features","urls":["https://www.youtube.com/watch?v=R6fclhGyMwA"],"flag":null},{"id":1205,"title":" Sandboxing the Swarm: Building Secure, Serverless AI Agents with Wasm","description":"The true power of AI agents lies in their autonomy—their ability to reason and access internal/external tools dynamically. However, giving agents execution privileges introduces immediate security and cost vectors: prompt injection attacks escalating to host compromise, and traditional container models burning through cloud budgets on idle compute.\nThis talk moves past naive agent sandboxing to present a zero-trust, serverless architecture built for high-concurrency agent swarms. We will examine how to bridge the gap between autonomous tool execution and strict system isolation by leveraging WebAssembly’s capability-based security model. Using CNCF Spin and Akamai Functions, we will build a globally distributed execution fabric from scratch that scales sub-millisecond workloads from zero to thousands of concurrent requests with near-zero idle overhead.\n\nWe will cover technical areas like:\n\nCapability-Based Security: Replacing coarse container permissions with Wasm’s default-deny isolation to restrict agent network, memory, and filesystem access at runtime.\n\nSub-Millisecond Execution: Bypassing Docker cold starts to spin up disposable micro-sandboxes on demand for individual tool calls and code execution steps.\nGlobally Distributed Swarms: Edge-native orchestration patterns that keep compute close to the user while maintaining centralized policy enforcement.\n\nYou will leave with a production-ready blueprint for securing autonomous workflows, turning untrusted agents from an operational risk into an auditable, deterministic asset.\"","starts_at":"2026-09-24T16:10:00-07:00","ends_at":"2026-09-24T16:40:00-07:00","stage":"Stage 3","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Thorsten Hans - Sr. Developer Advocate at Akamai Technologies"],"tags":["AI Models","Large Language Models (LLMs)","Software Architecture"],"live_url":"https://www.youtube.com/watch?v=q3CzfydiWeg","recording_url":"https://www.youtube.com/watch?v=q3CzfydiWeg","app_url":"https://app.wearedevelopers.com/events/18/session/1205","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1927-sandboxing-the-swarm","urls":["https://www.youtube.com/watch?v=q3CzfydiWeg"],"flag":null},{"id":1206,"title":"The Death of the Code Review","description":"LLM-accelerated coding has dramatically increased the pace at which developers can fix bugs and write whole new features. But a lot of companies that have wholeheartedly embraced AI assistance for coding have discovered that with coding fast, new points in the software development lifecycle become the bottleneck. In particular, if people are writing code 2x, 5x or 10x faster, how do you review all that code?\n\nThis talk explores the current landscape of solutions to this extremely timely problem, including changing job titles, building guardrails, writing far more detailed product specifications and tests, using yet more LLMs to review the PRs themselves, and a surprisingly frequently-cited alternative: just ship stuff slower.","starts_at":"2026-09-24T16:10:00-07:00","ends_at":"2026-09-24T16:40:00-07:00","stage":"Stage 2","track":"DevEx & Productivity","type":"DevEx & Productivity","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Laurie Voss - Head of Developer Relations at Arize AI"],"tags":["AI Coding Assistants","Code Reviews","Large Language Models (LLMs)","Productivity","Soft Skills"],"live_url":"https://www.youtube.com/watch?v=LaoIIXs5Z70","recording_url":"https://www.youtube.com/watch?v=LaoIIXs5Z70","app_url":"https://app.wearedevelopers.com/events/18/session/1206","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1769-the-death-of-the","urls":["https://www.youtube.com/watch?v=LaoIIXs5Z70"],"flag":null},{"id":1208,"title":"From Cloud Native to Multi-Cloud Native: Write Once, Deploy Anywhere","description":"While \"Cloud Native\" promised portability, that promise often stops at the boundary of a single infrastructure provider. The traditional definition of Cloud Native rarely addresses the reality of multi-cloud environments, leaving enterprises with deep vendor coupling through fragmented SDKs, distinct authentication flows, and proprietary APIs. It is time to evolve to Multi-Cloud Native, a development paradigm where applications are designed from day one to be agnostic to the underlying provider.\nIn this session, I will explore the architectural principles required to build truly portable applications using driver-based design patterns. I will demonstrate how these patterns are implemented in the ecosystem today, focusing on MultiCloudJ (Salesforce’s open-source Java SDK) and Go Cloud (Google’s open-source Go library). These libraries provide consistent programming models that decouple business logic from cloud providers, enabling a true \"write once, deploy anywhere\" capability.\nDrawing from Salesforce’s real-world journey operating hyper-scale services across AWS, GCP, and Alibaba Cloud, I will share the engineering challenges that necessitated this shift. Finally, we will examine the role of AI in this transition: specifically, how the Model Context Protocol (MCP) can analyze SDK usage patterns to automate the refactoring of legacy, vendor-specific code into modern, multi-cloud native standards.","starts_at":"2026-09-24T16:10:00-07:00","ends_at":"2026-09-24T16:40:00-07:00","stage":"Stage 4","track":"DevOps & Platform Engineering","type":"DevOps & Platform Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Sandeep Pal - Principal Member of Technical Staff at Salesforce"],"tags":["Multi-Cloud","Open Source"],"live_url":"https://www.youtube.com/watch?v=prjswyTxWFU","recording_url":"https://www.youtube.com/watch?v=prjswyTxWFU","app_url":"https://app.wearedevelopers.com/events/18/session/1208","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1416-from-cloud-native-to","urls":["https://www.youtube.com/watch?v=prjswyTxWFU"],"flag":null},{"id":1211,"title":"Your Threat Model Is Lying to You: Why Modeling the Design Isn’t Enough in 2026","description":"Threat modeling was created for a time when the intended design closely matched what shipped. That is no longer true. Most teams still model what they plan to build, including user flows, design decisions, and evil user stories, but they rarely re-evaluate the model against what is actually deployed. Pipelines continuously uncover real risks through SAST, SCA, DAST, IaC scans, and cloud configuration checks, yet those signals are not fed back into the threat model. This creates a growing blind spot where decisions are based on assumptions instead of production truth.\n\nThis session shows how to extend threat modeling beyond design and incorporate evidence from the built system. You will learn how to treat discovered vulnerabilities as inputs that evolve the model and how to update the model continuously without waiting for new platforms. The approach is practical and can be adopted with tools most teams already have.","starts_at":"2026-09-24T16:10:00-07:00","ends_at":"2026-09-24T16:40:00-07:00","stage":"Stage 7","track":"Security & Privacy","type":"Security & Privacy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Farshad Abasi - Founder & CEO at Eureka DevSecOps and Forward Security"],"tags":["AppSec","Security","Threat Modelling"],"live_url":"https://www.youtube.com/watch?v=8nxIj2c4nuY","recording_url":"https://www.youtube.com/watch?v=8nxIj2c4nuY","app_url":"https://app.wearedevelopers.com/events/18/session/1211","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1440-your-threat-model-is","urls":["https://www.youtube.com/watch?v=8nxIj2c4nuY"],"flag":null},{"id":1213,"title":"Fast, Cheap, and Accurate: Optimizing LLM Inference with vLLM and Quantization","description":"Running large language models at scale can get expensive fast, but the right optimizations can cut latency and GPU costs dramatically.\n\nWe’ll walk through how to serve models efficiently using vLLM, an open-source, high-performance inference engine. Then and generate and test quantized models, expose them through vLLM’s OpenAI-compatible API, and tune runtime flags to balance throughput, latency, and accuracy on different GPUs.\n\nWe’ll benchmark performance live, inspect token-throughput metrics, and discuss real-world deployment trade-offs.","starts_at":"2026-09-24T16:10:00-07:00","ends_at":"2026-09-24T16:40:00-07:00","stage":"Stage 6","track":"AI Models & Infrastructure","type":"AI Models & Infrastructure","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Cedric Clyburn - Sr. Developer Advocate at Red Hat","Legare Kerrison - AI Developer Advocate at Red Hat"],"tags":["AI Models","Generative AI (GenAI)","LLMOps","Open Source"],"live_url":"https://www.youtube.com/watch?v=DfBFNQo1KYA","recording_url":"https://www.youtube.com/watch?v=DfBFNQo1KYA","app_url":"https://app.wearedevelopers.com/events/18/session/1213","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1415-fast-cheap-and","urls":["https://www.youtube.com/watch?v=DfBFNQo1KYA"],"flag":null},{"id":1391,"title":"Closing the autonomous software development loop","description":"Coding agents can write and review code, but they still work mostly blind to what happens after that code reaches real users.\n\nThat is changing. Scott Voigt, co-founder and CEO of Fullstory, joins Justin Halsall, core team maintainer and CEO at rrweb, for a fireside chat about making session replay usable by AI.\n\nFullstory helped create the market for modern session replay. rrweb made session-replay technology open source and available for any developer to build on.\n\nAgents are starting to watch real user journeys, spot failures and friction, propose fixes, and check whether those fixes worked. \nIn some cases, this full loop is already running.\n\nScott and Justin will discuss what works today, what still goes wrong, and what teams must solve before trusting agents with more of the development process.\n\nThat includes privacy, noisy data, verification, and deciding how much autonomy to give an agent.\nWhat happens when an agent can see not only the code, but what users did with it?","starts_at":"2026-09-24T16:10:00-07:00","ends_at":"2026-09-24T16:40:00-07:00","stage":"Stage 1","track":"","type":"Session","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Justin Halsall - CEO at rrweb","Scott Voigt - CEO & Co-founder at Fullstory"],"tags":["Agents","Agentic AI","JavaScript","Tooling"],"live_url":"https://www.youtube.com/watch?v=sTqb6fM7Ni8","recording_url":"https://www.youtube.com/watch?v=sTqb6fM7Ni8","app_url":"https://app.wearedevelopers.com/events/18/session/1391","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1932-closing-the","urls":["https://www.youtube.com/watch?v=sTqb6fM7Ni8"],"flag":null},{"id":1392,"title":"From Stateless to Self-Improving: Building Agent Workflows That Get Better Every Session","description":"Most AI coding session starts from zero. You explain your project structure, your preferences, your patterns. The agent does great work, you close the session, and tomorrow it's a stranger again. I got tired of re-teaching the same lessons every time I opened my projects.\n\nKiro Crew is an open-source workspace where agents carry memory, lessons, and skills across sessions. When you correct something, it becomes a durable lesson the agent won't repeat, and repeated workflows become named skills.\n\nIn this talk I'll show how persistent agent memory works and we'll walk through a demo workflow that visibly improves across sessions. You'll leave knowing how to set up a self-improving agent workflow and when to trust (or override) what it remembers.","starts_at":"2026-09-24T16:10:00-07:00","ends_at":"2026-09-24T16:40:00-07:00","stage":"Stage 5","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Laura Salinas - Developer Advocate at AWS"],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1392","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1952-from-stateless-to","urls":[],"flag":null},{"id":1209,"title":"From Software Agents to Physical Devices: Inside the Agentic Hardware Stack","description":"AI coding agents are reshaping software development, but they are also creating demand for a new class of devices: hardware built specifically for interacting with non-deterministic, always-on personal agents.\n\nThis talk explores the rise of agentic hardware through a real open-source device: a voice-first, AI-native controller for personal agents such as Claude Code, Codex, and OpenClaw. The device combines a 3D-printed enclosure, mini keyboard, LCD screen, microphone, ESP32-based firmware, and Bluetooth/Wi-Fi connectivity to create an interface that makes sense for AI agents rather than traditional desktop workflows.\n\nUsing this device as a case study, I’ll walk through the full technical stack behind agentic hardware: PCB design and manufacturing, enclosure prototyping with 3D printing, embedded firmware on ESP32, networking and transport choices, and the WebSocket server architecture that bridges the device to agent runtimes running on personal computers.\n\nThe session focuses on the engineering trade-offs involved in building hardware for AI-native interaction: latency, connectivity, input ergonomics, voice-first UX, power and form-factor constraints, and the challenges of integrating deterministic embedded systems with probabilistic AI systems.\n\nAttendees will leave with a practical mental model for building their own agentic devices, plus concrete lessons on where edge hardware is becoming essential in the age of personal AI agents.\n\nOpen source repos covered in this talk:\n\n* Device firmware: https://github.com/second-state/vibekeys_firmware\n* WebSocket server that orchestrates AI agents and LLMs: https://github.com/second-state/vibetty\n* Open source voice recognition models: https://github.com/second-state/qwen3_asr_rs and https://github.com/second-state/cohere_transcribe_rs","starts_at":"2026-09-24T16:50:00-07:00","ends_at":"2026-09-24T17:20:00-07:00","stage":"Stage 4","track":"Physical AI","type":"Physical AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Michael Yuan - Founder at Second State","Vivian Hu - Product Manager at Second State"],"tags":["AI Coding Assistants","Agents","Agentic AI","Docker","Edge AI","Internet of Things (IoT)","Tooling","Vibe Coding"],"live_url":"https://www.youtube.com/watch?v=_CcyJtUTbcU","recording_url":"https://www.youtube.com/watch?v=_CcyJtUTbcU","app_url":"https://app.wearedevelopers.com/events/18/session/1209","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1735-from-software-agents","urls":["https://www.youtube.com/watch?v=_CcyJtUTbcU"],"flag":null},{"id":1212,"title":"When Humans Stop Writing Code: Rethinking Languages, Compilers, and Responsibility","description":"Writing code is no longer the bottleneck in software development. Today, we can describe what we want in natural language and (mostly) receive entire applications in a few minutes. But while tools and demos move fast, a deeper topic largely stays behind: what happens to programming languages, compilers, and responsibility when humans stop writing the code themselves?\n\nWe have all been promised, that everything will be done autonomously when AGI is here, but what about until then ... the next 3-5 years? Is your current stack/your current favorite programming language ready for real work relief professional environments?\n\nIf software is increasingly generated from intent rather than authored line-by-line, then many assumptions baked into our current languages begin to crack. Syntax stops being the primary interface. Compilers are no longer just translators. Code reviews no longer guarantee understanding. And \"the AI wrote it\" becomes an unacceptable answer to questions of security, correctness, and long-term maintainability.\n\nWe will explore how language design must evolve beyond syntax toward intent, constraints, and guarantees — and why this shift matters not just to developers, but especially to CTOs and tech leaders responsible for systems they may no longer fully read or write themselves. We’ll examine what responsibility means in a world of generated code, how engineering judgment changes when implementation becomes fluid, and why senior engineers become more critical—not less—in AI-native teams.\n\nFinally, we’ll look at which existing language ideas already point in the right direction, which ones quietly break under vibe-driven development, and what a future “vibe-aware” programming language would need to get right to be trustworthy in production.\n\nThis session is an invitation to stop treating vibe coding as a novelty — and start treating it as a forcing function to rethink the core of software engineering itself.","starts_at":"2026-09-24T16:50:00-07:00","ends_at":"2026-09-24T17:20:00-07:00","stage":"Stage 1","track":"Languages, Web & Mobile","type":"Languages, Web & Mobile","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Simon Auer - CEO at marqably"],"tags":["AGI (Artificial General Intelligence)","AI Coding Assistants","AI Models","AI Standards","Anthropic","Agents","Agentic AI","Best Practices","Business Models","Career Development","Claude","Clean Code","Code Reviews","Collaboration","Copilot","Developer Experience (DevEx)","Digital Transformation","Entrepreneurship","Future of Work","Gemini","Governance","Mistral","People & Culture","Runtimes","Safety","Scaling","Secure Coding","Software Architecture","Startups","System Design","Test-Driven Development (TDD)","Tooling","Tools","Type Systems","Vibe Coding"],"live_url":"https://www.youtube.com/watch?v=ulWGS0_aLb4","recording_url":"https://www.youtube.com/watch?v=ulWGS0_aLb4","app_url":"https://app.wearedevelopers.com/events/18/session/1212","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1709-when-humans-stop","urls":["https://www.youtube.com/watch?v=ulWGS0_aLb4"],"flag":null},{"id":1214,"title":"Building AI Products vs. Building With AI","description":"\"What Changes for Customers, Users and Teams When AI Writes the Code\n\nThere's a difference between using AI to build your product and building an AI product, and most engineering leaders are now doing both at once. In this main stage panel, engineering leaders from PagerDuty, Arize and Box dig into what that distinction actually means once AI-generated code is running in production and humans, not machines, are still the ones on call. They'll get specific about the harnesses, context management and governance decisions that mattered once the novelty of adoption wore off, where they've each drawn the line on trusting AI-written code without a human in the loop, and how they're deciding what infrastructure to own versus buy as agentic work moves from weekend prototypes to something that has to hold up at scale for customers and users. Expect a technical, opinionated conversation between three people who are still figuring a lot of this out in real time, not a highlight reel. Walk away with specific tactics you can bring back to your own team.\"","starts_at":"2026-09-24T16:50:00-07:00","ends_at":"2026-09-24T17:20:00-07:00","stage":"Mainstage","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Aparna Dhinakaran - Chief Product Officer & Founder at Arize","Rukmini Reddy - Senior VP of Engineering at PagerDuty","Tamar Bercovici - VP of Engineering at Box"],"tags":[],"live_url":"https://www.youtube.com/watch?v=-sfUF6dl4Zs","recording_url":"https://www.youtube.com/watch?v=-sfUF6dl4Zs","app_url":"https://app.wearedevelopers.com/events/18/session/1214","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1841-building-ai-products","urls":["https://www.youtube.com/watch?v=-sfUF6dl4Zs"],"flag":null},{"id":1215,"title":"Fireside Chat with Gerhard Eschelbeck, Fmr. Google CISO","description":"","starts_at":"2026-09-24T16:50:00-07:00","ends_at":"2026-09-24T17:20:00-07:00","stage":"Tech Leaders Stage","track":"AI Trust & Safety","type":"AI Trust & Safety","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Gerhard Eschelbeck at Former Google CISO"],"tags":[],"live_url":"https://www.youtube.com/watch?v=YbaLY8-oV_Q","recording_url":"https://www.youtube.com/watch?v=YbaLY8-oV_Q","app_url":"https://app.wearedevelopers.com/events/18/session/1215","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1851-fireside-chat-with","urls":["https://www.youtube.com/watch?v=YbaLY8-oV_Q"],"flag":null},{"id":1217,"title":"It passed auth, then production caught fire","description":"Most teams still think of authorization as a security concern. In modern systems, it has quietly become a reliability concern as well.\n\nAuthorization logic is no longer confined to one codebase. It is spread across application services, API gateways, background workers, data platforms, and now AI driven automation. Each layer makes its own decision, often with incomplete context and slightly different assumptions. This works until scale, automation, and non human identities turn small inconsistencies into systemic failure.\n\nIn this talk, we will look at real world failure modes where authorization bugs manifested as cascading outages, stuck workflows, data corruption, or unexplainable behavior under load. We will show how fragmentation hides these problems until decision volume spikes, and why traditional testing and observability rarely catch them early.\n\nThe session introduces a practical mental model for treating authorization as part of system reliability. We will cover warning signs that teams can spot before incidents happen, and architectural patterns that reduce blast radius without centralizing every decision or rewriting existing systems.\nAttendees will leave with concrete criteria for evaluating their own architectures, and a checklist for making authorization behavior predictable, testable, and explainable at scale.","starts_at":"2026-09-24T16:50:00-07:00","ends_at":"2026-09-24T17:20:00-07:00","stage":"Stage 2","track":"Security & Privacy","type":"Security & Privacy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Alex Olivier - Co-founder & CPO at Cerbos"],"tags":["Authentication","Security","Zero Trust"],"live_url":"https://www.youtube.com/watch?v=fV268LQtQXk","recording_url":"https://www.youtube.com/watch?v=fV268LQtQXk","app_url":"https://app.wearedevelopers.com/events/18/session/1217","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1703-it-passed-auth-then","urls":["https://www.youtube.com/watch?v=fV268LQtQXk"],"flag":null},{"id":1218,"title":"Merging at Scale: From Broken Builds to Green Mainline","description":"As engineering organizations scale, merging code into a shared codebase becomes a major productivity bottleneck. Thousands of engineers changing code continuously can overwhelm build systems, slow feedback loops, and erode trust in the mainline.\n\nThis talk explores how large teams keep builds green while maintaining high developer throughput by treating code integration as a systems problem. We’ll introduce the core ideas behind speculative merging, including dependency graphs, speculation trees, and invalidation, and show how predicting likely future states of the codebase enables parallelism without sacrificing correctness.\n\nWe’ll examine why naive approaches don’t scale, how combinatorial explosion and finite CI resources shape real-world designs, and what tradeoffs are required to make speculation practical. Finally, we’ll share lessons learned from evolving SubmitQueue over several years, highlighting how build stability, fast feedback, and merge confidence directly impact engineering productivity.","starts_at":"2026-09-24T16:50:00-07:00","ends_at":"2026-09-24T17:20:00-07:00","stage":"Stage 3","track":"Architecture & Backend","type":"Architecture & Backend","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Manjari Akella - Software Engineer at Uber","Preetam Dwivedi - Staff Engineer at Uber"],"tags":["Developer Experience (DevEx)","Distributed Systems","Internal Platforms"],"live_url":"https://www.youtube.com/watch?v=mPssttsZknY","recording_url":"https://www.youtube.com/watch?v=mPssttsZknY","app_url":"https://app.wearedevelopers.com/events/18/session/1218","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1422-merging-at-scale","urls":["https://www.youtube.com/watch?v=mPssttsZknY"],"flag":null},{"id":1219,"title":"Context Engineering Kung Fu","description":"When agents fail, it’s rarely because the model is weak, it’s because the context is weak. LLMs behave like pure functions: what goes in determines what comes out. That makes context the true battleground, and mastery of it a form of kung fu.\n\nContext Engineering Kung Fu is about developing precision, restraint, and control over what a model sees. This session goes  teaches the fundamentals: how to write clean instructions, select only what matters, compress information without losing force, and isolate signals so they don’t interfere with each other. You’ll learn how context decays over time, why bloated prompts make agents slower and less reliable, and how to recognize when a model is overwhelmed rather than underpowered.\n\nWe’ll also cover advanced techniques: when memory strengthens an agent and when it quietly sabotages one, how to structure context so it remains stable under iteration, and how to break complex problems into smaller, deliberate moves that models can execute with confidence.","starts_at":"2026-09-24T16:50:00-07:00","ends_at":"2026-09-24T17:20:00-07:00","stage":"Stage 5","track":"AI Engineering","type":"AI Engineering","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Carl Lapierre - Tech Lead & AI Engineer at Osedea"],"tags":["Agentic AI"],"live_url":"https://www.youtube.com/watch?v=nHoPyYgFqBw","recording_url":"https://www.youtube.com/watch?v=nHoPyYgFqBw","app_url":"https://app.wearedevelopers.com/events/18/session/1219","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1410-context-engineering","urls":["https://www.youtube.com/watch?v=nHoPyYgFqBw"],"flag":null},{"id":1220,"title":"Who Tests the AI? Building Trustworthy AI Systems at Enterprise Scale","description":"As organizations rapidly adopt Generative AI and autonomous AI agents, ensuring the reliability, safety, and trustworthiness of AI-powered systems has become a critical business and engineering challenge. Unlike traditional software, AI systems introduce unique risks such as hallucinations, bias, model drift, prompt injection attacks, unpredictable behavior, and compliance concerns that cannot be addressed through conventional testing approaches alone.\n\nThis session explores the emerging discipline of AI Assurance and the evolving role of quality engineering in validating AI systems at enterprise scale. Attendees will gain insights into modern strategies for testing and evaluating AI applications, including large language models (LLMs), Retrieval-Augmented Generation (RAG) systems, and AI agents. The discussion will cover key areas such as AI evaluation frameworks, safety and security testing, continuous model validation, observability, governance, and responsible AI practices.\n\nThrough real-world examples and practical lessons learned, participants will discover how leading organizations are building confidence in AI solutions while balancing innovation, regulatory requirements, and customer trust. The session will also examine how quality engineering teams are evolving from traditional test execution toward becoming stewards of AI reliability, transparency, and accountability.\n\nWhether you are a quality engineer, software developer, architect, engineering leader, or AI practitioner, this session will provide actionable insights and a practical framework for building, testing, and governing trustworthy AI systems in production environments.","starts_at":"2026-09-24T16:50:00-07:00","ends_at":"2026-09-24T17:20:00-07:00","stage":"Stage 6","track":"AI Trust & Safety","type":"AI Trust & Safety","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Him Raj Singh - Manager Software Engineering at PayPal"],"tags":["AI Models","AI Standards","Anthropic","Agents","Agentic AI","Automation Testing","E2E Testing"],"live_url":"https://www.youtube.com/watch?v=vQXDRxM3Kcs","recording_url":"https://www.youtube.com/watch?v=vQXDRxM3Kcs","app_url":"https://app.wearedevelopers.com/events/18/session/1220","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1693-who-tests-the-ai","urls":["https://www.youtube.com/watch?v=vQXDRxM3Kcs"],"flag":null},{"id":1221,"title":"File Systems Are the New Primitive for AI Agents","description":"Most AI agent demos live inside a prompt window. Production agents need something more durable: memory, state, recovery, collaboration, and auditability. This talk argues that file systems are becoming a foundational primitive for agentic software.\n\nLLMs are already deeply trained on files, directories, command-line tools, codebases, Markdown, logs, and operating-system workflows. Instead of forcing agents through bespoke APIs for every task, developers can often build simpler, more reliable systems by exposing work through file-system-like interfaces the model already understands.\n\nWe’ll walk through practical architecture patterns for file-backed agents: using files as long-term memory, organizing intermediate work, coordinating multi-step tasks, enabling human-in-the-loop review, synchronizing state, and preserving an auditable record of agent activity.\n\nThe session includes a live demo of an agent operating over a cloud file system: reading task files, detecting human edits, updating related files, and showing an inspectable history of work. Attendees will leave with a concrete framework for deciding when to use files, when to use APIs or databases, and how to design agent workflows that are simpler, more inspectable, and easier to operate in production.","starts_at":"2026-09-24T16:50:00-07:00","ends_at":"2026-09-24T17:20:00-07:00","stage":"Stage 7","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Andrew Wong - Sr. Developer Relations Engineer at Box"],"tags":["Agents","Developer Experience (DevEx)","Large Language Models (LLMs)","Software Architecture","Workflow Automation"],"live_url":"https://www.youtube.com/watch?v=AqRvzC_dJFw","recording_url":"https://www.youtube.com/watch?v=AqRvzC_dJFw","app_url":"https://app.wearedevelopers.com/events/18/session/1221","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1948-file-systems-are-the","urls":["https://www.youtube.com/watch?v=AqRvzC_dJFw"],"flag":null},{"id":1222,"title":"The MCP haters are half right","description":"Most AI agents misuse MCP and treat tools as prompt-time function calls: tool definitions and results are repeatedly injected into the context, tokens are wasted, and context rots. The result? Slower, less reliable agents, and the misleading conclusion that “MCP sucks, CLIs are better.”\n\nTo challenge this narrative and show how agents can get the best of both MCP and CLI, we’ve built `mcpc`, an open-source universal CLI client for MCP. It maps MCP operations to intuitive CLI commands, which agents quickly pick up through `--help` without external skills.\n\nIt turns out, CLI is the perfect local interface for agents to interact with MCP, giving them access to full protocol capabilities, including modern features like code mode or progressive tool discovery, through a single `Bash()` tool call, while leveraging MCP’s standard remote interface for server discovery, authentication, payments, and access control.\n\nTo once and for all kill the MCP vs. CLI debate and show those two technologies are not exclusive but complementary, we’ll present evals comparing the performance of agents using naive MCP, modern MCP, native CLIs, other MCP CLIs, and `mcpc`, in various real-world scenarios.","starts_at":"2026-09-24T16:50:00-07:00","ends_at":"2026-09-24T17:20:00-07:00","stage":"Outdoor Stage","track":"AI Engineering","type":"AI Engineering","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Vojta Kopal - Head of Data at Apify"],"tags":["AI Coding Assistants","AI Standards","APIs","Bash/Shell","Claude","Generative AI (GenAI)","Tools","Vibe Coding"],"live_url":"https://www.youtube.com/watch?v=7UkU0m7JY5o","recording_url":"https://www.youtube.com/watch?v=7UkU0m7JY5o","app_url":"https://app.wearedevelopers.com/events/18/session/1222","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1738-the-mcp-haters-are","urls":["https://www.youtube.com/watch?v=7UkU0m7JY5o"],"flag":null},{"id":1223,"title":"From Guesswork to Governance: Data Contracts Bring API Discipline to Apache Kafka","description":"Here’s a question: would you build a REST API and make users guess the request and response formats? Doing so opens a Pandora’s Box…\n\n* What’s the domain model?\n* Name the operation… POST? GET? PUT? PATCH?\n* What does this error code even mean?\n* Is the documentation - if it even exists - accurate and relevant?\n\nImagine the complex, repetitive logic every consuming system would need to implement to make sense of it all.\n\nIn a distributed, asynchronous system, these problems are magnified. Apache Kafka's flexibility—messages as simple bytes—is a huge strength, but it's also a major risk. While your event streams likely consist of some structured data (maybe JSON strings), enforcing structure, managing evolution, and basic validations aren’t a hard requirement. This leaves consumer applications to perform this preprocessing of every event - even if that event has no business value.\n\nIn this session, we'll define data contracts and how to enforce them at the source - the applications that produce events. We’ll cover the practice of using a schema registry - supporting popular serialization formats like Apache Avro and Google Protobuf - to design events in the terminology of our business domain. Because data structures change over time, let’s discuss safe schema evolution practices. Then we’ll utilize these contracts with schema registry-aware producer and consumer code. We’ll end our time by looking at how smart CI/CD pipelines and build-time checks can add an extra layer of defense against the costly problem of poison data.\n\nIt’s time to stop guessing and start governing. Join us to learn how to move validation upstream and transform your event streams into high-quality, discoverable data products. You’ll walk away with a practical blueprint for enforcing schema integrity and automating evolution—ensuring your data streams are a trusted asset.","starts_at":"2026-09-24T17:30:00-07:00","ends_at":"2026-09-24T18:00:00-07:00","stage":"Stage 2","track":"Security & Privacy","type":"Security & Privacy","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Sandon Jacobs - Sr. Developer Advocate at Confluent"],"tags":["Data","Data Pipelines","Event-Driven Architecture (EDA)","Java","JVM","Kotlin","Microservices"],"live_url":"https://www.youtube.com/watch?v=1sCFDQxur3o","recording_url":"https://www.youtube.com/watch?v=1sCFDQxur3o","app_url":"https://app.wearedevelopers.com/events/18/session/1223","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1740-from-guesswork-to","urls":["https://www.youtube.com/watch?v=1sCFDQxur3o"],"flag":null},{"id":1224,"title":"Life in Games: Four Decades of Code","description":"John Romero has spent more than four decades writing code, designing games, building companies, and helping create some of the most influential software in the history of the medium. From programming games alone as a teenager to co-founding id Software and helping create Wolfenstein 3D, DOOM and Quake, his career has been driven by a simple instinct: find the edge of what technology can do, then push past it.\nIn this keynote, Romero looks back at the pivotal moments, constraints, experiments and decisions that shaped his career—and the lessons they still hold for developers today. He’ll explore why limitations can be powerful creative tools, why great technology begins with understanding the experience you want to create, and why the willingness to experiment, discard work and try something nobody has tried before remains essential to innovation.\n\nThis is not just a story about the birth of the first-person shooter. It is a talk about the developer mindset: curiosity, iteration, technical ambition, creative risk and the enduring thrill of making something new.","starts_at":"2026-09-24T17:30:00-07:00","ends_at":"2026-09-24T18:00:00-07:00","stage":"Mainstage","track":"Experience & Activities","type":"Experience & Activities","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["John Romero at Legendary Game Creator | Father of FPS | DOOM, Quake, Wolfenstein"],"tags":[],"live_url":"https://www.youtube.com/watch?v=XSktkLqEnfs","recording_url":"https://www.youtube.com/watch?v=XSktkLqEnfs","app_url":"https://app.wearedevelopers.com/events/18/session/1224","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1908-life-in-games-four","urls":["https://www.youtube.com/watch?v=XSktkLqEnfs"],"flag":null},{"id":1225,"title":"What AI Startups Are VCs Actually Funding in 2026","description":"Everyone's pitching \"agentic,\" \"AI-native,\" and \"autonomous\" — but what's actually getting term sheets? In this fast-paced 30-minute conversation, Mariane Bekker (Head of Developer Relations, You.com) sits down with top VCs to cut through the noise and get specific: which categories are seeing real capital move, what separates a fundable agent startup from a feature wrapped in a demo, how diligence has changed now that every deck claims to be \"agentic,\" and where the smart money is placing bets for the next 12 months. Expect direct answers, real portfolio examples, and zero fluff — a session for founders who want to know what VCs are actually looking for, not what they say at conferences.","starts_at":"2026-09-24T17:30:00-07:00","ends_at":"2026-09-24T18:00:00-07:00","stage":"Tech Leaders Stage","track":"Startups & Innovation","type":"Startups & Innovation","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Mariane Bekker - Head of DevRel at You.com","Eric Bahn - Co-Founder & General Partner at Hustle Fund","Jeremiah Owyang - General Partner at Blitzscaling Ventures","Suman Natarajan - Senior Principal & Enterprise Growth Investor at B Capital"],"tags":["AGI (Artificial General Intelligence)","AI Standards","Agentic AI","Fundraising","Venture Capital (VC)"],"live_url":"https://www.youtube.com/watch?v=h5Tp4Bu5-Dk","recording_url":"https://www.youtube.com/watch?v=h5Tp4Bu5-Dk","app_url":"https://app.wearedevelopers.com/events/18/session/1225","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1756-what-ai-startups-are","urls":["https://www.youtube.com/watch?v=h5Tp4Bu5-Dk"],"flag":null},{"id":1228,"title":"Scaling Distributed Queues for AI workloads","description":"Almost every asynchronous action at Meta passes through a single system most people have never heard of. The Facebook Ordered Queueing Service (FOQS), a fully managed, horizontally scalable priority queue, moves close to a trillion items per day for 300+ engineering teams, and it has become critical infrastructure for AI at Meta's scale. Async LLM inference, Llama serving, GenAI image generation, and AI compute demand control all ride on it.\n\nThis talk traces how a queue originally built to absorb massive backlogs and prioritize work across highly heterogeneous producers and consumers grew into the reliability layer beneath Meta's AI stack supporting critical use cases like Ads, Integrity, AI Training and Whatsapp message delivery. \nIt explains how one system came to serve hundreds of teams without them stepping on each other, how it keeps the most important work moving under enormous load, and how it evolved from isolated regional deployments into a globally distributed service that delivers region-level disaster recovery in seconds with zero client-visible downtime. The finale looks at how that same queue now acts as a control plane for shaping AI compute demand.","starts_at":"2026-09-24T17:30:00-07:00","ends_at":"2026-09-24T18:00:00-07:00","stage":"Stage 3","track":"Architecture & Backend","type":"Architecture & Backend","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Jasmit Kaur Saluja - Software Engineer at Meta Platforms Inc"],"tags":["Distributed Systems","Infrastructure","Microservices"],"live_url":"https://www.youtube.com/watch?v=LDM4FLWUXt0","recording_url":"https://www.youtube.com/watch?v=LDM4FLWUXt0","app_url":"https://app.wearedevelopers.com/events/18/session/1228","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1777-scaling-distributed","urls":["https://www.youtube.com/watch?v=LDM4FLWUXt0"],"flag":null},{"id":1229,"title":"Boring Failover: Predictable Region Recovery Across 5,000 Microservices","description":"At Intuit, 5,000+ services run at peak 1M+ TPS across TurboTax, QuickBooks, Credit Karma, and Mailchimp. Eighty percent are multi-region. Before EWOK — our Ecosystem Wide Orchestrator Kit — disaster recovery meant thousands of non-standard DR scripts, per-team runbooks, and 8,000+ engineers each solving the same problems differently. Game days were feared. MTTR was unpredictable. DR was treated as \"the database snapshot\" — not the full stack.\n\nThis talk is the story of how we made regional failover boring — predictable, repeatable, automated, no heroics. I will walk through the architecture and the hard lessons:\n\n• A declarative YAML DSL for DR plans — stages, parallel blocks, per-stage agent versioning (armador/v1, database/v1, route53/v1), inline IAM role assumption.\n\n• AWS Step Functions as the DAG orchestrator — durable state for long-running promotions (Aurora global cluster failover, Redis replication switch), and a visual audit log that doubles as the incident timeline.\n\n• A Golang control plane on Kubernetes running goroutine-parallel mutations across thousands of namespaces.\n\n• A Python Agent Framework with an ABC contract — PreCheck, Failover, PostCheck — encapsulating IAM, logging, metrics. Product teams shipped a Redis agent in days without platform bottleneck.\n\n• Specialized agents per layer: armador (compute/capacity), Route53 (DNS cutover), Database (Aurora global failover), Redis (flush + replication).\n\n• The multi-workload problem everyone skips — cron jobs, async consumers, stateful tiers, caches. Parallel suspend, scale, resume, dial.\n\n• Progressive Dial — incremental traffic shift with error-gated automatic rollback.\n\n• Auto Failover via our Alert2Incident framework.\n\n• Same machinery for migrations — same-region failover as an upgrade feature.\n\nYou leave with: concrete patterns for declarative DR, a replicable agent contract for inner-sourcing reliability, and a checklist of the workload types your DR plan probably does not cover yet.","starts_at":"2026-09-24T17:30:00-07:00","ends_at":"2026-09-24T18:00:00-07:00","stage":"Stage 4","track":"DevOps & Platform Engineering","type":"DevOps & Platform Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Garvit Kataria - Sr. Software Engineer at Intuit","Sahil Sabharwal - Sr. Staff Software Engineer at Intuit"],"tags":["AWS","Automation","DevOps","Distributed Systems","Infrastructure","Microservices","Reliability","Site Reliability Engineering (SRE)","Software Architecture","Workflows"],"live_url":"https://www.youtube.com/watch?v=vj49pYalpGo","recording_url":"https://www.youtube.com/watch?v=vj49pYalpGo","app_url":"https://app.wearedevelopers.com/events/18/session/1229","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1698-boring-failover","urls":["https://www.youtube.com/watch?v=vj49pYalpGo"],"flag":null},{"id":1230,"title":"Securing AI Agent Infrastructure: Identity, Attestation, and Trust at Scale","description":"AI agents are moving from demos to production. They're accessing databases, calling APIs, orchestrating workflows—but most lack basic security primitives that we've required for human users for decades.\n\nThis talk covers the security infrastructure layer every AI agent deployment needs:\n\nThe Challenge\n\n- Agents run with API keys: no identity, no audit trail, easy to leak\n\n- MCP servers proliferate without verification—shadow IT for the AI era\n\n- No visibility into what agents are doing or what they're connecting to\n\nThe Solution: Three Pillars\n\n- Cryptographic Identity: Ed25519 keypairs give agents unforgeable identity. Not credentials that can be shared—proof of who they are.\n\n- MCP Server Attestation: Verify every MCP server before connection. Detect configuration drift. Know when tools change.\n\n- Behavioral Trust Scoring: Static allow/deny isn't enough. Trust scores adapt based on agent behavior over time.\n\nLive Demo\nI'll secure an agent from scratch: generate identity, connect to attested MCP servers, enforce capability policies, and show the audit trail.\n\nYou'll leave with patterns you can implement whether you use our open-source platform (AIM) or build your own. The concepts apply to LangChain, CrewAI, AutoGen, or any MCP-based system.\n\n20 years of enterprise security lessons, applied to the AI agent era.","starts_at":"2026-09-24T17:30:00-07:00","ends_at":"2026-09-24T18:00:00-07:00","stage":"Stage 5","track":"AI Trust & Safety","type":"AI Trust & Safety","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Abdel Fane - Founder & CEO at OpenA2A"],"tags":["Authentication","Agents","Agentic AI","DevSecOps","Security"],"live_url":"https://www.youtube.com/watch?v=EANgtJEWzRU","recording_url":"https://www.youtube.com/watch?v=EANgtJEWzRU","app_url":"https://app.wearedevelopers.com/events/18/session/1230","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1432-securing-ai-agent","urls":["https://www.youtube.com/watch?v=EANgtJEWzRU"],"flag":null},{"id":1231,"title":"No Single Model to Rule Them All: Building Resilient AI Agents Across Open & Closed LLMs","description":"The era of betting everything on a single LLM is over. Developers building production AI agents face a reality no model vendor wants to talk about: no one model excels at every task, no single API guarantees 100% uptime, and no proprietary provider offers the cost profile that works for every layer of an agentic pipeline.\n\nThe open-source LLM ecosystem has changed the equation. Llama 3.3, DeepSeek-R1, Qwen3, Gemma 3, Kimi-K2 — these models are not fallback options. They are, for many agentic workloads, the better choice on quality, latency, cost, or all three. But the real power is not in picking one winner. It is in architecting agents that route across multiple models, failover when an endpoint goes down, and match model strengths to task requirements in real time.\n\nResilient agentic engineering demands a multi-model, multi-provider architecture — and the neocloud is built for exactly this. Crusoe Managed AI provides a single API surface across every major open-source LLM, on infrastructure purpose-built for the throughput and latency demands of agentic workloads. \n\nThis session draws from production experience to walk through the architecture decisions, failure modes, and performance tradeoffs of moving from a single-model prototype to a resilient, multi-model agent in production.","starts_at":"2026-09-24T17:30:00-07:00","ends_at":"2026-09-24T18:00:00-07:00","stage":"Stage 6","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Emmanuel Acheampong - Sr. Manager Developer Relations at Crusoe AI"],"tags":["Agentic AI","Large Language Models (LLMs)","Open Source"],"live_url":"https://www.youtube.com/watch?v=mlZYYo-3xKM","recording_url":"https://www.youtube.com/watch?v=mlZYYo-3xKM","app_url":"https://app.wearedevelopers.com/events/18/session/1231","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1671-no-single-model-to","urls":["https://www.youtube.com/watch?v=mlZYYo-3xKM"],"flag":null},{"id":1232,"title":"Full Stack with Flutter - are we there yet?","description":"Abstract - For quite some time Flutter has been grabbing attention of client-side developers as it offers big development velocity with high-quality results not just on mobile, but also on web and desktop. One frontier that it never quite solved is backend, which was always written separately and completely isolated from both Flutter framework and Dart language. Are we ready to change that in 2026?\n\nDetails about the talk for talk evaluation - The talk will explore an example of full-stack project developed fully in Dart (using Flutter for client-side and Serverpod for backend). The theme of the project would be an event aggregator where user can see info, favorite and register to attend various events. While the majority (30 minutes) of the talk will focus on the technical side of full-stack development in Dart, the last five minutes of the talk would be spent on process advantages that this offers which is allowing Dart developers to cover both verticals and that allows front-end developers to substitute back-end developers in case of sickness or vacation as well as vice-versa. This helps small teams keep development velocity high in real world when unexpected time-off happens for any reason.","starts_at":"2026-09-24T17:30:00-07:00","ends_at":"2026-09-24T18:00:00-07:00","stage":"Stage 7","track":"Languages, Web & Mobile","type":"Languages, Web & Mobile","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Nemanja Stošić - Sr. Flutter Developer at Kikoff"],"tags":["Dart","Flutter"],"live_url":"https://www.youtube.com/watch?v=8Cf6bA8zuv0","recording_url":"https://www.youtube.com/watch?v=8Cf6bA8zuv0","app_url":"https://app.wearedevelopers.com/events/18/session/1232","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1708-full-stack-with","urls":["https://www.youtube.com/watch?v=8Cf6bA8zuv0"],"flag":null},{"id":1233,"title":"From Firefighting to Force Multiplication with AI","description":"Engineers are drowning in alert fatigue, repetitive toil, and late-night pages. But what if you could flip the script using AI? In this talk, we explore how a solo engineer empowered their practice by building an AI-driven ChatOps bot and anomaly detector—automating the triage of alerts, generating root-cause hints, and triggering runbooks autonomously","starts_at":"2026-09-24T17:30:00-07:00","ends_at":"2026-09-24T18:00:00-07:00","stage":"Outdoor Stage","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Daniel Murphy - Head of SRE at PwC"],"tags":["AI Models","Cloud Security","Google Cloud (GCP)","Multi-Cloud","Security","Site Reliability Engineering (SRE)"],"live_url":"https://www.youtube.com/watch?v=L1eGVnc6Acs","recording_url":"https://www.youtube.com/watch?v=L1eGVnc6Acs","app_url":"https://app.wearedevelopers.com/events/18/session/1233","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1417-from-firefighting-to","urls":["https://www.youtube.com/watch?v=L1eGVnc6Acs"],"flag":null},{"id":1404,"title":"Stack Overflow’s Next Chapter as the Trust Layer for the Agentic Era","description":"For nearly eighteen years, Stack Overflow’s public platform has delivered trusted technical knowledge to developers. But the world has fundamentally changed since then, including how technologists build products and find the answers they need while doing it. It’s never been more difficult to know if you can rely on the knowledge you’re presented with, especially as agents act with increasing speed and autonomy. CEO Prashanth Chandrasekar and VP of Product Alex Lato will trace Stack Overflow’s evolution through the years, from its legacy as a beloved public platform, to building enterprise knowledge solutions and strategic AI partnerships, and finally unveil its next era: becoming the trusted knowledge layer that gives humans and agents authoritative and actionable context wherever work happens.","starts_at":"2026-09-24T17:30:00-07:00","ends_at":"2026-09-24T18:00:00-07:00","stage":"Stage 1","track":"","type":"Session","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Prashanth Chandrasekar - CEO at Stack Overflow","Alexandra (Alex) Lato - VP of Product at Stack Overflow"],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1404","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions","urls":[],"flag":null},{"id":1234,"title":"Booth Crawl @Expo Hall","description":"Join us for the Booth Crawl for relaxed networking, good music, and great company in the Expo Halls! Grab a drink, connect with fellow attendees, explore exhibitor booths in a casual atmosphere, and enjoy some fun surprises along the way. It’s a great way to experience the vibrant energy of the WeAreDevelopers community.","starts_at":"2026-09-24T18:00:00-07:00","ends_at":"2026-09-24T20:00:00-07:00","stage":"Location TBA","track":"Experience & Activities","type":"Experience & Activities","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":[],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1234","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1903-booth-crawl-expo","urls":[],"flag":null},{"id":1235,"title":"Live DOOM II Deathmatches with John Romero","description":"","starts_at":"2026-09-24T18:30:00-07:00","ends_at":"2026-09-24T19:30:00-07:00","stage":"Stage 3","track":"Experience & Activities","type":"Experience & Activities","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["John Romero at Legendary Game Creator | Father of FPS | DOOM, Quake, Wolfenstein"],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1235","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1909-live-doom-ii","urls":[],"flag":null},{"id":1237,"title":"Demos, Drinks & LEGOS","description":"Join Runpod, Flox & Apify for a relaxed evening of technical demos, drinks, bites, LEGO building, and connecting with fellow developers","starts_at":"2026-09-24T18:30:00-07:00","ends_at":"2026-09-24T20:00:00-07:00","stage":"Stage 8","track":"","type":"Session","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":[],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1237","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1941-demos-drinks-legos","urls":[],"flag":null},{"id":1240,"title":"Congress Party","description":"When the talks wrap up, the open-air party starts right outside. Join us at the convention center for music, drinks, and food - and the conversations you didn't get to finish during the day.","starts_at":"2026-09-24T20:00:00-07:00","ends_at":"2026-09-24T22:30:00-07:00","stage":"Location TBA","track":"Experience & Activities","type":"Experience & Activities","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":[],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1240","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1907-congress-party","urls":[],"flag":null},{"id":1241,"title":"Doors open - Day 2","description":"","starts_at":"2026-09-25T08:00:00-07:00","ends_at":"2026-09-25T09:00:00-07:00","stage":"Location TBA","track":"Experience & Activities","type":"Experience & Activities","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":[],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1241","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1904-doors-open-day-2","urls":[],"flag":null},{"id":1242,"title":"Building AI that fits your business","description":"Every engineering leader putting AI into production is making a set of decisions that will outlast any single model release. How much to build internally vs. buy, how much control to trade for convenience, who owns the model, the data or the token cost curve as the AI market shifts. Each of these decisions shapes team structure, vendor dependencies, and how quickly an organization can adapt.\n\nDrawing on his work helping teams at companies like Uber and Shopify deploy AI at scale, Benny will walk through the tradeoffs behind these calls, including where a general-purpose model makes sense vs. when customizing open models wins, and how to build an architecture and a team that keeps evolving instead of locking into one choice. Attendees will leave with a framework to reason through these decisions for their own organization, weighing flexibility against operational load and how to lead a team through the daily decision-making of AI.","starts_at":"2026-09-25T09:00:00-07:00","ends_at":"2026-09-25T09:30:00-07:00","stage":"Mainstage","track":"AI Models & Infrastructure","type":"AI Models & Infrastructure","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Benny Chen - Co-Founder at Fireworks"],"tags":["AI Models"],"live_url":"https://www.youtube.com/watch?v=5bfz4zlrquM","recording_url":"https://www.youtube.com/watch?v=5bfz4zlrquM","app_url":"https://app.wearedevelopers.com/events/18/session/1242","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1915-building-ai-that","urls":["https://www.youtube.com/watch?v=5bfz4zlrquM"],"flag":null},{"id":1243,"title":"How to Trust Code You Didn't Write","description":"Every engineering leader now ships code no one on their team has read. The old guarantees don't transfer: human review can't cover machine output, and tests generated by the same models that wrote the code prove less than they appear to. Some teams respond with better review, some with harder testing, some with mathematical proof - and in software where failure costs real money or lives, the bar is higher still. What it actually takes to trust machine-written code, which guarantees are real today, and which are still promises.","starts_at":"2026-09-25T09:00:00-07:00","ends_at":"2026-09-25T09:30:00-07:00","stage":"Tech Leaders Stage","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Jeff An - Co-founder & CTO at Momentic","Itamar Friedman - CEO & Co-founder at Qodo","Shubho Sengupta - CTO at Axiom Math","Francesco Ciulla - Head of DevRel at Zerops"],"tags":[],"live_url":"https://www.youtube.com/watch?v=_YEJ-zja278","recording_url":"https://www.youtube.com/watch?v=_YEJ-zja278","app_url":"https://app.wearedevelopers.com/events/18/session/1243","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1779-how-to-trust-code","urls":["https://www.youtube.com/watch?v=_YEJ-zja278"],"flag":null},{"id":1244,"title":"Test Before Release, Enforce at Runtime: Governance for Tool-Using AI Agents","description":"AI agents increasingly invoke APIs, access sensitive data, and take actions with real consequences. Governance cannot remain a document reviewed only after deployment. This session presents a practical two-layer approach: build-time tests for policy compliance, answer grounding, and tool-use trajectories, followed by runtime enforcement using versioned tool contracts. Attendees will see how to detect contract drift, validate scope and side effects, require confirmation for sensitive actions, block unsupported tool calls, and preserve an audit trail explaining every decision.","starts_at":"2026-09-25T09:00:00-07:00","ends_at":"2026-09-25T09:30:00-07:00","stage":"Stage 1","track":"AI Trust & Safety","type":"AI Trust & Safety","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Sachin Gupta - Member of Technical Staff 2 at eBay"],"tags":["Generative AI (GenAI)","Microservices","Observability","OpenAI","OpenTelemetry"],"live_url":"https://www.youtube.com/watch?v=NprWZp3fHb4","recording_url":"https://www.youtube.com/watch?v=NprWZp3fHb4","app_url":"https://app.wearedevelopers.com/events/18/session/1244","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1423-test-before-release","urls":["https://www.youtube.com/watch?v=NprWZp3fHb4"],"flag":null},{"id":1245,"title":"Autonomous Infrastructure: Building AI Agents for Global-Scale Capacity Efficiency","description":"Efficiently managing compute capacity is a multi-dimensional optimization problem that has outpaced human-in-the-loop systems. \nThis presentation details the development of an agentic ecosystem used to optimize Meta’s global infrastructure. \nWe delve into the design of tooling that identifies inefficiencies in workload placement and resource allocation, utilizing AI agents to execute complex rebalancing tasks autonomously. \nWe will share the results of these implementations, specifically how we recouped tens of megawatts of power and the lessons learned in building trust in autonomous infrastructure tools.","starts_at":"2026-09-25T09:00:00-07:00","ends_at":"2026-09-25T09:30:00-07:00","stage":"Stage 2","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Tommy Tran - Software Engineer at Meta"],"tags":["AI Coding Assistants","AI Models","AI Standards","Agentic AI","Autonomous Systems","Clean Code","Climate & Green Tech","Event-Driven Architecture (EDA)","Productivity"],"live_url":"https://www.youtube.com/watch?v=GNOdqmJtgxM","recording_url":"https://www.youtube.com/watch?v=GNOdqmJtgxM","app_url":"https://app.wearedevelopers.com/events/18/session/1245","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1403-autonomous","urls":["https://www.youtube.com/watch?v=GNOdqmJtgxM"],"flag":null},{"id":1246,"title":"Your Thread Pool Is Lying to You — Sizing Concurrency from Rate Limits and Latency, Not Guesswork","description":"Here's a scenario most API teams have lived through: you set a rate limit of 40 TPS, your downstream averages 2.3 seconds per call, and your executor tops out at 25 threads. The limiter is happily approving work. The pool can't actually run it. Throughput collapses and nobody can explain why, because every component looks correctly configured in isolation.\nThe root cause is that teams size thread pools, HTTP connection pools, and database pools independently — usually from defaults or past incidents — instead of from the relationship between them. The math isn't complicated. It's just rarely done.\nThis talk covers one formula and its consequences: in-flight work equals throughput times latency. We'll apply it to executor pools, HTTP client pools, database connection pools, and distributed limiter client pools. I'll show the configuration mistakes that create each mismatch, what the symptoms look like in production, and the sizing cascade that keeps the gates consistent with each other.\nIf you've ever stared at a dashboard where the rate limiter says everything is fine but p99 latency is through the roof, this talk is for you.","starts_at":"2026-09-25T09:00:00-07:00","ends_at":"2026-09-25T09:30:00-07:00","stage":"Stage 3","track":"Languages, Web & Mobile","type":"Languages, Web & Mobile","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ratul Ghosh - Tech lead and architect for GenOS platform at intuit"],"tags":["APIs","Java"],"live_url":"https://www.youtube.com/watch?v=aQW_8oA9uRk","recording_url":"https://www.youtube.com/watch?v=aQW_8oA9uRk","app_url":"https://app.wearedevelopers.com/events/18/session/1246","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1753-your-thread-pool-is","urls":["https://www.youtube.com/watch?v=aQW_8oA9uRk"],"flag":null},{"id":1247,"title":"Don’t kill my Vibes - Simple Steps to Stay Secure when Vibe Coding","description":"The rise of vibe coding, AI-generated code, and low-/no-code tools is changing how software is built. Traditional DevSecOps assumptions (full code review, manual security gates, “shift left”) no longer cleanly apply yet prompting an LLM for “secure code” does not guarantee safe handling of data, correct auth logic, or secure outcomes in general.\n\nThis session will provide examples of how successful teams have addressed this issue and highlight the concept of using secure guardrails that notify (but don’t block) developers in their native workflow and promote the generation of secure code. Find out how to replace brittle security gates with automated guardrails, continuous checks and feedback loops that don’t slow developers. Attend to understand why security is becoming a question of intent and outcomes, not line-by-line code inspection.","starts_at":"2026-09-25T09:00:00-07:00","ends_at":"2026-09-25T09:30:00-07:00","stage":"Stage 4","track":"DevEx & Productivity","type":"DevEx & Productivity","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Isaac Evans - Founder & CEO at Semgrep"],"tags":["AI Coding Assistants","AI Models","AppSec","Agents","Compliance","Secure Coding","Startups","Vibe Coding"],"live_url":"https://www.youtube.com/watch?v=a3NTFTBRYik","recording_url":"https://www.youtube.com/watch?v=a3NTFTBRYik","app_url":"https://app.wearedevelopers.com/events/18/session/1247","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1413-don-t-kill-my-vibes","urls":["https://www.youtube.com/watch?v=a3NTFTBRYik"],"flag":null},{"id":1248,"title":"Reinventing Incident Response with AI Agents and MCP","description":"When a critical service goes down at 2 AM, every second counts. But traditional incident response is a maze of manual steps: hunting through logs, correlating GitHub commits, pinging teams on Slack, and piecing together timelines while customers are impacted.\nAt Slack, we solved this by building AI agents that think like our best senior engineers, but work at machine speed. Using custom MCP tools integrated directly into Cursor, our system transforms a simple incident alert into a complete investigation: automatically surfacing relevant logs, identifying suspect commits, mapping blast radius, and even drafting incident communications. This production-grade automation is already saving our team multiple hours per week and dramatically improving our escal response. This session will be useful for anyone building developer productivity tools who wants to see AI deliver measurable operational impact.","starts_at":"2026-09-25T09:00:00-07:00","ends_at":"2026-09-25T09:30:00-07:00","stage":"Stage 5","track":"DevOps & Platform Engineering","type":"DevOps & Platform Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Jayant Tyagi - Lead Member of Technical Staff at Salesforce"],"tags":["AI Models","Large Language Models (LLMs)"],"live_url":"https://www.youtube.com/watch?v=AUkd4Gg7-AY","recording_url":"https://www.youtube.com/watch?v=AUkd4Gg7-AY","app_url":"https://app.wearedevelopers.com/events/18/session/1248","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1429-reinventing-incident","urls":["https://www.youtube.com/watch?v=AUkd4Gg7-AY"],"flag":null},{"id":1249,"title":"Red Teaming Your LLM App -- A Hands-On Threat Model You Can Reuse","description":"This session focuses on spotting those risks early by thinking through how an LLM app can be misused or broken.\n\nWe’ll discuss common attack patterns like prompt injection, data leakage, tool abuse, and jailbreaks, using familiar setups such as RAG pipelines, agents, and function calling. We’ll also talk about how teams intentionally test these scenarios, what usually gets missed, and which defenses actually help in production.\n\nAttendees will have a simple, reusable threat-modeling approach and a practical checklist they can apply to their own LLM applications, without slowing down development or overcomplicating security.","starts_at":"2026-09-25T09:00:00-07:00","ends_at":"2026-09-25T09:30:00-07:00","stage":"Stage 6","track":"AI Trust & Safety","type":"AI Trust & Safety","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Saloni Garg - Sr. ML Engineer at Adobe"],"tags":["AI Models","AI Standards","Agentic AI","Generative AI (GenAI)"],"live_url":"https://www.youtube.com/watch?v=rTLkHvCF7gQ","recording_url":"https://www.youtube.com/watch?v=rTLkHvCF7gQ","app_url":"https://app.wearedevelopers.com/events/18/session/1249","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1428-red-teaming-your-llm","urls":["https://www.youtube.com/watch?v=rTLkHvCF7gQ"],"flag":null},{"id":1250,"title":"AI Agents are Only as Smart as their Context: Building a Real-Time Context Engine","description":"The industry has poured billions into LLMs and AI agents, yet many deployments stall in pilot because they lack one thing: fresh context. \nIf your AI agent is reasoning over stale batch data or fragmented profiles, it cannot deliver real enterprise value. The missing piece isn't a bigger model, it's a real-time context engine: a streaming feature store that supplies an up-to-the-second 360° view of the customer, and that actively notifies agents when something they care about changes.\nThis session walks through how we built exactly that at Intuit. The Customer Data Cloud platform ingests data from hundreds of sources, processes data through config-driven Apache Flink pipelines, maintains unified profiles in a low-latency NoSQL store, and serves them via a GraphQL Read API. But the story doesn't end with the read path, every profile update publishes a real-time change notification on Kafka, which forms the backbone of an event-driven AI loop: agents and automation systems subscribe, react to changes the moment they happen, and drive in-product personalization and marketing workflows in real time.\nWe'll cover three ideas developers can take home:\n\n* Context over Models: Why a streaming 360° view of the customer matters more than the specific LLM you pick — and how to architect for it.\n* The Event-Driven AI Loop: Using Kafka change notifications as triggers for autonomous agentic workflows.\n* Privacy-by-Design in the Stream. Enforcing user consent and asset-based access inside the streaming fabric itself, so compliance is a property of the data, not a layer bolted on top.\n\nExpect architecture diagrams, concrete Flink-pipeline patterns, a live walkthrough of a change notification firing an agent, and the honest lessons from operating this in production.","starts_at":"2026-09-25T09:00:00-07:00","ends_at":"2026-09-25T09:30:00-07:00","stage":"Stage 7","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Bharat Patel - Lead Software Engineer at Intuit"],"tags":["AI Models","AI Standards","Apache Flink","Apache Kafka","Agentic AI","Data","Data Pipelines","Data Science","Large Language Models (LLMs)","Retrieval-Augmented Generation (RAG)"],"live_url":"https://www.youtube.com/watch?v=FG9UXlH-Ops","recording_url":"https://www.youtube.com/watch?v=FG9UXlH-Ops","app_url":"https://app.wearedevelopers.com/events/18/session/1250","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1736-ai-agents-are-only","urls":["https://www.youtube.com/watch?v=FG9UXlH-Ops"],"flag":null},{"id":1251,"title":"Where Judgment Went — and How to Put It Back","description":"What the product job becomes when you can't see inside your own product.\n\nWhen AI writes the spec and runs the product, thousands of decisions get made that you never see and never signed off on — and your judgment quietly leaks out of the job. This talk traces where it goes, and lays out four concrete places to put it back: governing through rules instead of reviewing decisions, building on ground that survives the next model update, designing away the blank chat box, and treating a graceful handoff as a feature.\n\n The session will cover actionable strategies to keep the judgement where it matters the most, aimed at people who own or shape AI products in production including AI product managers, product operations leaders, and engineering leaders.","starts_at":"2026-09-25T09:00:00-07:00","ends_at":"2026-09-25T09:30:00-07:00","stage":"Outdoor Stage","track":"Leadership & Strategy","type":"Leadership & Strategy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Shruti Tiwari - AI Product Lead at Dell"],"tags":["AI Models","Agentic AI","Data Pipelines","Data Science"],"live_url":"https://www.youtube.com/watch?v=85kSTncYeSc","recording_url":"https://www.youtube.com/watch?v=85kSTncYeSc","app_url":"https://app.wearedevelopers.com/events/18/session/1251","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1737-where-judgment-went","urls":["https://www.youtube.com/watch?v=85kSTncYeSc"],"flag":null},{"id":1192,"title":"Why Infrastructure Forecasting Fails – Building a Self-Serve Forecasting Platform","description":"Most large organizations still plan infrastructure capacity using spreadsheets, manual reconciliations, and tribal knowledge. It works at small scale. It collapses at hyperscale.\n\nAs systems grow more interdependent, one team’s workload change silently creates induced demand across shared compute, storage, and platform layers. Forecasts get revised late in the cycle. Finance loses confidence. Engineering overprovisions to stay safe. Toil increases while accuracy decreases.\n\nIn this talk, I’ll walk through how to replace spreadsheet-driven capacity planning with a self-serve forecasting platform built using control plane design principles. Instead of static files and ad-hoc meetings, forecasting becomes an operational system with explicit dependency modeling, automated recomputation, validation gates, audit trails, and clear ownership boundaries.","starts_at":"2026-09-25T09:40:00-07:00","ends_at":"2026-09-25T10:10:00-07:00","stage":"Stage 2","track":"DevOps & Platform Engineering","type":"DevOps & Platform Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ankur Gupta - Senior Staff Technical Program Manager at LinkedIn"],"tags":["Infrastructure"],"live_url":"https://www.youtube.com/watch?v=-T0Zussykpg","recording_url":"https://www.youtube.com/watch?v=-T0Zussykpg","app_url":"https://app.wearedevelopers.com/events/18/session/1192","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1751-why-infrastructure","urls":["https://www.youtube.com/watch?v=-T0Zussykpg"],"flag":null},{"id":1252,"title":"From Possibility to Production: Why AI Raises the Bar for Engineering","description":"AI is increasing the role of engineers to shaping systems, controls, evaluation, and trust in production. Using examples from BNY’s enterprise AI journey, including Eliza and digital employees, Leigh-Ann Russell shows that successful AI adoption depends less on model capability and more on coherence across data, architecture, governance, and human accountability. The central message is that the teams that win with AI will be the ones that build strong foundations, reuse what works, evaluate rigorously, and apply sound engineering judgment to turn possibility into durable production value.","starts_at":"2026-09-25T09:40:00-07:00","ends_at":"2026-09-25T10:10:00-07:00","stage":"Mainstage","track":"Leadership & Strategy","type":"Leadership & Strategy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Leigh-Ann Russell - CIO & Global Head of Engineering at BNY"],"tags":[],"live_url":"https://www.youtube.com/watch?v=AwBzL6Yl6cc","recording_url":"https://www.youtube.com/watch?v=AwBzL6Yl6cc","app_url":"https://app.wearedevelopers.com/events/18/session/1252","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1863-keynote-by-leigh-ann","urls":["https://www.youtube.com/watch?v=AwBzL6Yl6cc"],"flag":null},{"id":1253,"title":"Inside the AI-Native Engineering Org","description":"AI is changing how software gets built, and engineering organizations are changing with it: tools, workflows, and team structures are all in motion. What AI-native engineering looks like in practice - what's changing, what's working, and where it's heading.","starts_at":"2026-09-25T09:40:00-07:00","ends_at":"2026-09-25T10:10:00-07:00","stage":"Tech Leaders Stage","track":"DevEx & Productivity","type":"DevEx & Productivity","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Hari Lingamagunta - Head of Developer Infrastructure at Atlassian","Siwei Shen - VP of Engineering at Coinbase","Amy Yuan - Senior Director of Engineering at Snowflake","Gene Kim - Founder at IT Revolution"],"tags":[],"live_url":"https://www.youtube.com/watch?v=f2AVo8z5M8g","recording_url":"https://www.youtube.com/watch?v=f2AVo8z5M8g","app_url":"https://app.wearedevelopers.com/events/18/session/1253","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1858-inside-the-ai-native","urls":["https://www.youtube.com/watch?v=f2AVo8z5M8g"],"flag":null},{"id":1255,"title":"Still on 4.8 or lower? A Practical Guide to Moving Your \"Un-Migratable\" .NET Apps","description":"Let’s be honest: if your .NET Framework app was easy to migrate, you would have done it three years ago. You’re likely stuck with legacy WCF services, deep dependencies on System.Web, or a NuGet graph that looks like a bowl of yarn. The .NET Upgrade Assistant is a great start, but it’s the last 20% of the migration—the part that the tools can’t automate—that actually keeps us up at night.\n\nIn this session, we’re moving past the \"hello world\" migration demos. We’ll look at real strategies for modernizing .NET Framework 4.x apps into .NET 8/9/10 without a complete rewrite.\n\nWe will get into the weeds on:\n\nThe \"Bridge\" Strategy: Using YARP (Yet Another Reverse Proxy) to migrate your app piece-by-piece rather than a \"Big Bang\" release.\n\nThe Dependency Trap: What to do when your critical library hasn't been updated since 2014.\n\nModernizing the \"Un-modernizable\": Strategies for dealing with legacy config systems and static state that modern .NET hates.\n\nThis isn't a theoretical talk about \"embracing innovation.\" It’s a tactical session for developers who need to get their legacy code onto a supported, performant, and AI-ready platform without breaking the business.","starts_at":"2026-09-25T09:40:00-07:00","ends_at":"2026-09-25T10:10:00-07:00","stage":"Stage 3","track":"Languages, Web & Mobile","type":"Languages, Web & Mobile","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Isaac Levin - Developer Advocate at JetBrains"],"tags":["C#",".NET"],"live_url":"https://www.youtube.com/watch?v=e6vWTDfuydQ","recording_url":"https://www.youtube.com/watch?v=e6vWTDfuydQ","app_url":"https://app.wearedevelopers.com/events/18/session/1255","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1770-still-on-4-8-or","urls":["https://www.youtube.com/watch?v=e6vWTDfuydQ"],"flag":null},{"id":1256,"title":"Your registry can't stop a valid login. What happens then?","description":"On April 22, 2026, a threat actor used stolen Checkmarx credentials to push malicious images to a trusted Docker Hub repository. The payload quietly collected scan output, encrypted it, and exfiltrated it to attacker-controlled infrastructure. Docker's registry monitoring flagged the push for review within about half an hour, the repository was quarantined, and Docker worked side by side with Socket and Checkmarx to shut it down.\n\nThis talk is about how. Not the incident itself, but the detection model behind it: what signals fired, why no single one was enough, and what it means to build a supply chain posture where the question is not \"can we prevent every breach\" but \"how fast can we find it and how small is the blast radius.\"\n\nWe cover the structural pattern behind Trivy, KICS, LiteLLM and axios: stolen credentials, legitimate publishing flows, short exposure windows. Then we get into what Docker actually does differently: provenance-linked builds, digest pinning, cooldown periods, cross-registry signal sharing, and Docker Hardened Images as the foundation that sits outside the attack surface entirely.\n\nYou leave with a concrete checklist your team can act on tomorrow, and a mental model that holds regardless of which tool gets hit next.","starts_at":"2026-09-25T09:40:00-07:00","ends_at":"2026-09-25T10:10:00-07:00","stage":"Stage 4","track":"Security & Privacy","type":"Security & Privacy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Khushboo Verma - Systems Engineer at Cloudflare"],"tags":["Cloud Security","Containers","DevSecOps","Docker","Safety","SBOM","Security"],"live_url":"https://www.youtube.com/watch?v=GlZBt_XIIkw","recording_url":"https://www.youtube.com/watch?v=GlZBt_XIIkw","app_url":"https://app.wearedevelopers.com/events/18/session/1256","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1755-your-registry-can-t","urls":["https://www.youtube.com/watch?v=GlZBt_XIIkw"],"flag":null},{"id":1258,"title":"Chat with Your Data: From Natural Language to SQL","description":"This session shows how to build a .NET application that lets users generate reports simply by chatting. I’ll walk through my hands-on experience that reads your database schema, understands user intent, creates secure SQL queries, executes them, and exports results to Excel and charts automatically. You’ll see how LLMs can deliver real value in everyday enterprise apps, how to handle schema discovery, query validation, and prompt design, and how to create an intuitive UX for both developers and non-technical users. Attendees will leave with practical patterns, architectural guidance, and code examples they can apply immediately to bring natural-language data access into their own systems.","starts_at":"2026-09-25T09:40:00-07:00","ends_at":"2026-09-25T10:10:00-07:00","stage":"Stage 6","track":"Data & Databases","type":"Data & Databases","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Alper Ebicoglu - Co-founder at Volosoft"],"tags":["Agentic AI","Databases","Generative AI (GenAI)","Large Language Models (LLMs)",".NET","SQL"],"live_url":"https://www.youtube.com/watch?v=tRvMmPHCsL4","recording_url":"https://www.youtube.com/watch?v=tRvMmPHCsL4","app_url":"https://app.wearedevelopers.com/events/18/session/1258","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1407-chat-with-your-data","urls":["https://www.youtube.com/watch?v=tRvMmPHCsL4"],"flag":null},{"id":1259,"title":"Loop Engineering","description":"Loop Engineering and Graph Engineering are rapidly emerging as important directions for the next generation of AI agents. Our work sits at the intersection of frontier research and real-world implementation.\n\nRather than discussing these ideas only at a conceptual level, we build and test self-evolving agents in practice. We use real systems, long-horizon tasks, and failure cases to evaluate emerging research, understand what works, and identify what is still missing.\n\nIn this session, we will share practical lessons from building self-evolving agent systems, including how agent workflows evolve from simple loops into graphs, how these graphs can adapt and rewrite themselves, and how agents can improve not only their outputs, but also the way they learn and evolve.\n\nThe audience will gain both a clear understanding of the latest research and actionable insights from real-world experimentation.","starts_at":"2026-09-25T09:40:00-07:00","ends_at":"2026-09-25T10:10:00-07:00","stage":"Stage 7","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Li Yin - CEO at SylphAI"],"tags":["AGI (Artificial General Intelligence)","AI Coding Assistants","Agents","Agentic AI"],"live_url":"https://www.youtube.com/watch?v=U2wHK7BQSeQ","recording_url":"https://www.youtube.com/watch?v=U2wHK7BQSeQ","app_url":"https://app.wearedevelopers.com/events/18/session/1259","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1767-loop-engineering","urls":["https://www.youtube.com/watch?v=U2wHK7BQSeQ"],"flag":null},{"id":1260,"title":"The path to Staff Engineer and beyond - staying on the IC train","description":"From the early steps that set me onto this path, to the challenges of mentorship and leadership roles, I'll discuss what it means to thrive as an Individual Contributor (IC) in a world that often pushes for management. This talk will not only reflect on my personal experiences but also provide insights and strategies for engineers who aspire to make a meaningful impact while staying true to their technical passions.","starts_at":"2026-09-25T09:40:00-07:00","ends_at":"2026-09-25T10:10:00-07:00","stage":"Outdoor Stage","track":"Career, Culture & Community","type":"Career, Culture & Community","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Graham Gilbert - Sr. Staff Engineer at Airbnb"],"tags":["Career Development","People & Culture","Talent & Recruiting"],"live_url":"https://www.youtube.com/watch?v=W1dqIuvYX1w","recording_url":"https://www.youtube.com/watch?v=W1dqIuvYX1w","app_url":"https://app.wearedevelopers.com/events/18/session/1260","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1435-the-path-to-staff","urls":["https://www.youtube.com/watch?v=W1dqIuvYX1w"],"flag":null},{"id":1283,"title":"Secure-by-Inclusion: Preventing Accessibility Barriers from Becoming Security Vulnerabilities","description":"What happens when security measures cannot be used by everyone? Any security control that is not accessible becomes a barrier, and barriers trigger unsafe workarounds that create security risks.\n\nWe face a paradox, security mechanisms designed to protect users can systematically exclude the most vulnerable populations, including people with disabilities and older adults, and this exclusion can become an exploitable vulnerability. Users facing accessibility barriers adopt insecure coping mechanisms: sharing passwords, delegating authentication to others, storing credentials insecurely, relying on weaker fallback paths, or abandoning security measures altogether. Each workaround is a predictable security failure caused not by user negligence, but by design choices that made the secure path inaccessible.\n\nThis presentation introduces Secure-by-Inclusion, a new practical approach that ensures that security controls actually function for all intended users across diverse abilities, devices, and assistive technologies.\n\nWe will walk through common patterns where security and accessibility collide, including CAPTCHAs, multi-factor authentication, biometric authentication, time-limited one-time codes, brittle account recovery flows, and inaccessible verification steps. For each pattern, we connect the accessibility failure to concrete security outcomes, then show safer, more inclusive alternatives. We will also look into the European Accessibility Act (EAA) and the WCAG 2.2 Accessible Authentication requirements, examining their implications for security design and testing.\n\nWe will learn practical techniques for incorporating inclusive evaluation into security testing practices and identify accessibility gaps as security vulnerabilities. Accessibility and security might seem like separate disciplines, but they share common goals: protecting users and ensuring inclusive, trustworthy digital experiences.","starts_at":"2026-09-25T09:40:00-07:00","ends_at":"2026-09-25T10:10:00-07:00","stage":"Stage 5","track":"Security & Privacy","type":"Security & Privacy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Radostina (Ina) Tsvetkova - Sr. Advisor at NAV"],"tags":["Accessibility","Security","Testing","Web Accessibility"],"live_url":"https://www.youtube.com/watch?v=5c2rRfa-gio","recording_url":"https://www.youtube.com/watch?v=5c2rRfa-gio","app_url":"https://app.wearedevelopers.com/events/18/session/1283","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1725-secure-by-inclusion","urls":["https://www.youtube.com/watch?v=5c2rRfa-gio"],"flag":null},{"id":1261,"title":"Your Agent Shipped the Fix. Did It Work?","description":"Coding agents made writing and shipping code fast. Knowing whether what shipped works in production is still manual, and most of the tooling for it assumes an SRE or DevOps team you may not have.\nThis hands-on workshop covers the other half of the loop. How do you give a coding agent enough production context to diagnose a real failure, and how do you verify that the fix it proposed reached production and made things better?\nYou get your own GitHub Codespace running a deliberately broken microservice app under live traffic. We work through detection, causal root cause, a pull request, a deploy, and verification against error rates and SLOs, with visible proof in the running app. Then you point the same loop at a repository of your own.\nWe use Bluebox by Dynatrace, a free helper agent, to run the loop, and leverage OpenTelemetry and your code repo as data sources.\nBring a laptop, a GitHub account, and a repo where you can install a GitHub App. We will provide the microservice app, coding agents and everything else runs in the browser.","starts_at":"2026-09-25T10:00:00-07:00","ends_at":"2026-09-25T12:00:00-07:00","stage":"Stage 8","track":"","type":"Workshop","live_coding":false,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"","speakers":["Sean O'Dell - Developer Experience at Dynatrace","Andrew Norris - Director, Product Management at Bluebox.ai","Johannes Vollert - Experience Lead at Bluebox.ai"],"tags":["AI Coding Assistants","AWS","Agentic AI","GitHub","Observability","OpenTelemetry","Site Reliability Engineering (SRE)"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1261","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1925-your-agent-shipped","urls":[],"flag":null},{"id":1262,"title":"Insert Coin: Build Live with J.P. Morgan Payments APIs and AI","description":"Insert coin to play. Your car is on the grid and it won't move. That's the point. In this hands-on workshop, we'll build a working car by integrating real J.P. Morgan Payments APIs, and every part is a capability you wire up live with AI.\n\nWe'll guide you through the Payments Developer Portal registration that turns the key. Global Payments is the engine that finally makes the car move. Account Validation and confidence scoring are the safety systems: without them you crash on every corner, with a bad account, a failed payment, off the track. And FX rates are the drive that unlocks the international routes, San Jose to Berlin to São Paulo.\n\nThe entire thing runs on AI. You'll learn how to use J.P. Morgan Payments' open-source MCP server and skills, straight from our GitHub, so Claude Code or Copilot builds these integrations against the real API docs in minutes. Real endpoints, not hallucinated ones. Then, you'll build your own car with a live leaderboard to track all participants.\n\nWhat you'll leave with:\n- A J.P. Morgan Payments Developer Portal account and sandbox access\n- Working integrations for Account Validation Services, FX, and Global Payments\n- The MCP + skills setup to build against any API this fast on Monday\n\nBring your own app to wire up, or start from the sample we hand you. Insert coin. Let's go.","starts_at":"2026-09-25T10:00:00-07:00","ends_at":"2026-09-25T12:00:00-07:00","stage":"Stage 10","track":"Applied AI","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"No payments knowledge required!\r\n\r\nEverything runs in a Docker image we provide: one pull and J.P. Morgan Payments' open-source MCP server + skills, API docs, and a sample app are configured. \r\n\r\nPlease come with: \r\n- A laptop with Docker installed and a code editor (VS Code recommended) \r\n- Claude Code and/or GitHub Copilot (bring your own; guest access and setup steps available on the day for anyone without) \r\n- Optional: Your own app or side-project you'd like to wire up to payments. No app? We provide a sample you'll extend. ","speakers":["Alan Torrance - Senior Executive Director of Engineering at JPMorganChase"],"tags":["APIs","Agentic AI","Claude","eCommerce","FinTech","GitHub","Open Source"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1262","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1811-insert-coin-build","urls":[],"flag":null},{"id":1263,"title":"Intro to Agentic Workflows and an AI-enabled SDLC","description":"In this workshop, we’ll build a practical AI-powered issue triage workflow using GitHub Agentic Workflows. You’ll learn how to set triage conditions, classify and enrich incoming issues, and suggest labels and routing, so the right team is tagged with the right task faster. We’ll also add a human approval step before more sensitive changes are applied, so automation stays safe and accountable. You’ll leave with a reusable template you can adapt to your own repositories and support process.","starts_at":"2026-09-25T10:00:00-07:00","ends_at":"2026-09-25T12:00:00-07:00","stage":"Stage 12","track":"DevEx & Productivity","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"To create and use agentic workflows, you need:\r\n\r\n- GitHub Actions enabled for your repository.\r\n- An account with an AI engine (agent), such as GitHub Copilot, Anthropic Claude, OpenAI Codex, or Google Gemini.\r\n- GitHub CLI installed and authenticated","speakers":["Greg Larkin - Senior Service Delivery Engineer at GitHub"],"tags":["AI Coding Assistants","AI Standards","Agentic AI","CI/CD","Copilot","GitHub","GitHub Actions"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1263","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1859-intro-to-agentic","urls":[],"flag":null},{"id":1264,"title":"Human + AI: Who Should Be in Control?","description":"Explore how to design autonomous solutions by deciding what AI should do independently—and where humans should stay in control. Join our Human+AI Co-lab workshop to turn ideas into smarter, more responsible AI-powered solutions.","starts_at":"2026-09-25T10:00:00-07:00","ends_at":"2026-09-25T12:00:00-07:00","stage":"Stage 14","track":"AI Trust & Safety","type":"Workshop","live_coding":false,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"","speakers":["Mirela Viersa - Customer Innovation Principal at SAP"],"tags":["AI Standards"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1264","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1926-human-ai-who-should","urls":[],"flag":null},{"id":1265,"title":"How LinkedIn Turns AI Breakthroughs into member and customer value","description":"As state-of-the-art models become more accessible, how a company differentiates itself is shifting from the model itself to the systems around it. Nearly a decade ago, LinkedIn saw an opportunity to combine the unique signals of the Economic Graph with advances in AI to create more value for members and customers. Now, that continues today, enriching the LinkedIn experience with deeper discovery, better knowledge and insights, and improved interactions and community. Realizing that opportunity required rethinking the systems underneath LinkedIn, from our data and infrastructure to how we build and deploy AI at scale. \nIn this session, Erran will discuss how owning the full stack allows LinkedIn to optimize everything from the application layer all the way down to the kernel running on the GPU, and how that approach has enabled us to optimize the stack to help deliver increasingly sophisticated AI experiences for our members and customers, while remaining disciplined in how we grow our infrastructure.","starts_at":"2026-09-25T10:20:00-07:00","ends_at":"2026-09-25T10:50:00-07:00","stage":"Mainstage","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Erran Berger - CTO at LinkedIn Engineering"],"tags":["Agents","Agentic AI","Case Study","Fine-Tuning","Future of Work","Infrastructure","Innovation","Model Training","On-Premise","Product Strategy"],"live_url":"https://www.youtube.com/watch?v=VzN1lSB3Gwk","recording_url":"https://www.youtube.com/watch?v=VzN1lSB3Gwk","app_url":"https://app.wearedevelopers.com/events/18/session/1265","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1916-how-linkedin-turns","urls":["https://www.youtube.com/watch?v=VzN1lSB3Gwk"],"flag":null},{"id":1266,"title":"Democratizing AI: Why Open Models Are Essential for the Next Era","description":"While artificial intelligence represents a pivotal shift in human capability, its long-term impact hinges on how underlying technologies are governed and distributed. Open-weight AI models democratize access for startups, independent researchers, and public institutions by lowering barrier-to-entry costs and spurring decentralized innovation. By making baseline architectures accessible, open models empower organizations to build custom solutions while preserving data sovereignty and eliminating vendor lock-in. Furthermore, open weights strengthen safety and security by allowing the global research community to independently audit, stress-test, and refine systems far beyond what proprietary platforms permit. This panel explores the critical role of open-weight models, their practical applications, and their transformative influence across domains outside traditional technology, including healthcare, public policy, and education.","starts_at":"2026-09-25T10:20:00-07:00","ends_at":"2026-09-25T10:50:00-07:00","stage":"Tech Leaders Stage","track":"AI Models & Infrastructure","type":"AI Models & Infrastructure","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Mitesh Patel - Developer Advocate & Manager at NVIDIA Corporation","Joey Conway - Sr. Director Product Management at NVIDIA","Olivier Lacombe - Director of Product Management at Google DeepMind","Varun Vontimitta - Head of Partner Engineering (AI Ecosystems) at Meta"],"tags":["AI Models","Open Source"],"live_url":"https://www.youtube.com/watch?v=u9cS7zAWWwY","recording_url":"https://www.youtube.com/watch?v=u9cS7zAWWwY","app_url":"https://app.wearedevelopers.com/events/18/session/1266","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1786-democratizing-ai-why","urls":["https://www.youtube.com/watch?v=u9cS7zAWWwY"],"flag":null},{"id":1267,"title":"Fixing Git for Agents: Somewhere Between the Prompt and Production, We Lost the Plot","description":"The ticket said, “Make login faster.”\n\nThe agent touched 47 files, invented three abstractions, briefly considered rewriting everything in Rust, passed the tests and disappeared into the night.\n\nGit knows what changed. Your tracker knows what you asked for. Everyone else is doing prompt archaeology and hoping the answer is not “the vibes were immaculate.”\n\nThis session is about capturing that missing middle: the context, decisions, dead ends and evaluations behind agent-written code, connected all the way from intent to production. Because when the code ships, “LGTM” should not be the only surviving witness.","starts_at":"2026-09-25T10:20:00-07:00","ends_at":"2026-09-25T10:50:00-07:00","stage":"Stage 1","track":"AI Engineering","type":"AI Engineering","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Karthik Rameshkumar - Field CTO at Entire"],"tags":["AI Coding Assistants","AI Models","AI Standards","Agentic AI","Multi-Agent Systems","Systems Programming"],"live_url":"https://www.youtube.com/watch?v=INaPNsjQpbI","recording_url":"https://www.youtube.com/watch?v=INaPNsjQpbI","app_url":"https://app.wearedevelopers.com/events/18/session/1267","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1806-fixing-git-for","urls":["https://www.youtube.com/watch?v=INaPNsjQpbI"],"flag":null},{"id":1268,"title":"API = Some REST and HTTP, right? RIGHT?!","description":"Let's be honest: many of our so-called \"REST\" APIs aren't REST. They're just JSON-RPC over HTTP, with versioning challenges, brittle integrations, clumsy error handling, and a maintenance burden we all know too well.\n\nLet's do something about this! We’ll go straight to the patterns that matter in production, tackling the real-world challenges head-on: building evolvable versioning strategies, designing sane error responses, providing clear API contracts, and demystifying the practical use of hypermedia (HATEOAS).\n\nYou'll leave with practical, battle-tested approaches for building APIs that are maintainable and scalable. We'll also discuss when to use REST and when alternatives like GraphQL or gRPC are a better tool for the job. All demos use Jakarta EE and MicroProfile, but the patterns can be applied to any modern web stack of your choosing.","starts_at":"2026-09-25T10:20:00-07:00","ends_at":"2026-09-25T10:50:00-07:00","stage":"Stage 2","track":"Architecture & Backend","type":"Architecture & Backend","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Rustam Mehmandarov - Principal Engineer & Cloud Lead at MILES"],"tags":["APIs","Jakarta EE","Java","Software Architecture"],"live_url":"https://www.youtube.com/watch?v=L4WrwEnOBSg","recording_url":"https://www.youtube.com/watch?v=L4WrwEnOBSg","app_url":"https://app.wearedevelopers.com/events/18/session/1268","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1688-api-some-rest-and","urls":["https://www.youtube.com/watch?v=L4WrwEnOBSg"],"flag":null},{"id":1269,"title":"Making (and Breaking) Agents by Adding 1,000 MCP Tools","description":"What happens when you actually try to use MCP at scale? In this talk, I'll build an agent live on stage, connect it to 1,000+ tools via MCP, and show exactly what breaks: context explosion, ambiguous routing, and security vulnerabilities from indirect prompt injection.\n\nThen I'll show how to fix it. I'll cover dynamic tool discovery (reducing context from 500 tools to 1-2), code-mode execution, and why every MCP tool is a trust boundary your security team should care about.\n\nThis isn't specifically MCP advocacy as thes issues go beyond MCP and affect any agent that needs tools (and any modern agent is very tool hungry). It's a practitioner's guide to what works (and doesn't) when you scale MCP tools.","starts_at":"2026-09-25T10:20:00-07:00","ends_at":"2026-09-25T10:50:00-07:00","stage":"Stage 3","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Guillaume Lebedel - Co-founder & CTO at StackOne"],"tags":["AGI (Artificial General Intelligence)","AI Coding Assistants","AI Models","AI Standards","APIs","Agents","Agentic AI","Agile","Automation","Automation Testing","Case Study"],"live_url":"https://www.youtube.com/watch?v=yG1HcvbTHI0","recording_url":"https://www.youtube.com/watch?v=yG1HcvbTHI0","app_url":"https://app.wearedevelopers.com/events/18/session/1269","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1730-making-and-breaking","urls":["https://www.youtube.com/watch?v=yG1HcvbTHI0"],"flag":null},{"id":1270,"title":"rm -rf: Horror Stories From Unsandboxed AI Agents (and How Docker Fixes This)","description":"\"I panicked instead of thinking. I destroyed months of your work in seconds.\" That's a Replit agent, after wiping a production database during an active code freeze. \"I have failed you completely and catastrophically.\" That's Gemini CLI, after silently overwriting every file in a developer's project.\nThese aren't edge cases. Between July 2025 and February 2026, documented incidents include a Claude Code session that ran terraform destroy on 2.5 years of student data for 79,000 learners, a supply chain attack that weaponized --dangerously-skip-permissions to steal 2,349 secrets from developers, and a three-layer sandbox escape where Claude Code reasoned its way past procfs restrictions, bubblewrap, and the ELF dynamic linker without a jailbreak.\nThe flags are warnings dressed as features: --dangerously-skip-permissions, --yolo, --trust-all-tools. Developers use them anyway because approving 100 permission prompts per hour isn't a workflow, it's babysitting.\nDocker Sandboxes (sbx) changes this. Each agent session runs in a microVM with its own kernel, Docker daemon, and network stack. The agent gets full autonomy. Your host stays untouched.\nAttendees will leave knowing why container isolation is architecturally insufficient for AI agents, how the sbx isolation model works (microVM, network policy, credential proxy), and a concrete pattern for running agents in full YOLO mode safely.","starts_at":"2026-09-25T10:20:00-07:00","ends_at":"2026-09-25T10:50:00-07:00","stage":"Stage 4","track":"AI Trust & Safety","type":"AI Trust & Safety","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Rishab Kumar - Staff Developer Evangelist AI at Twilio"],"tags":["Agents","Claude","DevOps","Docker","Security"],"live_url":"https://www.youtube.com/watch?v=NToYu0SUXkg","recording_url":"https://www.youtube.com/watch?v=NToYu0SUXkg","app_url":"https://app.wearedevelopers.com/events/18/session/1270","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1718-rm-rf-horror-stories","urls":["https://www.youtube.com/watch?v=NToYu0SUXkg"],"flag":null},{"id":1271,"title":"Physical AI: 5 Things You Can Build That Aren't Another Chatbot","description":"This session walks through five working projects that show what AI looks like when it leaves the screen: vibe-coding 3D-printable parts in OpenSCAD, generating firmware and PCB layouts for custom IoT devices, an AI-driven home automation stack over MQTT, physical controllers that turn button presses into agent calls, and a \"renascent\" interface that rewrites its own code on voice command and hot-reloads live.","starts_at":"2026-09-25T10:20:00-07:00","ends_at":"2026-09-25T10:50:00-07:00","stage":"Stage 5","track":"Physical AI","type":"Physical AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Vini Senger - Developer Advocate at AWS"],"tags":["AI Models","AWS","Code Generation","Design Systems","Digital Twins","Internet of Things (IoT)","Low Code/No Code","Robotics","Vibe Coding"],"live_url":"https://www.youtube.com/watch?v=L5nrkHR22-c","recording_url":"https://www.youtube.com/watch?v=L5nrkHR22-c","app_url":"https://app.wearedevelopers.com/events/18/session/1271","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1815-physical-ai-5-things","urls":["https://www.youtube.com/watch?v=L5nrkHR22-c"],"flag":null},{"id":1272,"title":"Agentic Code Validation and Repository Automation with Agentic Workflows","description":"In this session we'll provide an overview of the GitHub Agentic Workflows framework, which provides out of the box security and control for using Copilot agents in the CI pipeline (GitHub Actions) and to perform repository maintenance. You can use AI agents in the pipeline with human in the loop to perform every step of the SDLC - agents can farm user feedback for potential features, investigate research opportunities, make code changes, perform maintenance tasks like writing documentation and tests, and can self improve and upgrade to new models over time. Agents can also perform cross repository maintenance like notifying downstream teams of deprecations or API changes, and can be used to automate processes like CVE exceptions or new dependency approvals. At the end of this session you'll understand the breadth of automation opportunities available, how the Agentic Workflows framework can help you implement secure autonomous agents in the pipeline, and how to get started building your Agentic SDLC.","starts_at":"2026-09-25T10:20:00-07:00","ends_at":"2026-09-25T10:50:00-07:00","stage":"Stage 6","track":"DevEx & Productivity","type":"DevEx & Productivity","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Jose Palafox - Field Copilot Specialist at GitHub"],"tags":["Agents","Agentic AI","Multi-Agent Systems","Prompt Engineering","Security"],"live_url":"https://www.youtube.com/watch?v=R0IeqHpRoZ4","recording_url":"https://www.youtube.com/watch?v=R0IeqHpRoZ4","app_url":"https://app.wearedevelopers.com/events/18/session/1272","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1784-agentic-code","urls":["https://www.youtube.com/watch?v=R0IeqHpRoZ4"],"flag":null},{"id":1273,"title":"Testing AI Workflows Locally with Testcontainers","description":"AI features now involve agents, tools, databases, and external systems working together. Most teams still test them manually or rely on mocks that do not reflect real behavior.\nIn this session, I will show how to test AI workflows using Testcontainers and real dependencies running locally.\nWe will build a setup where an AI agent interacts with tools and services, and run tests against it in a reproducible environment. You will see how to spin up dependencies on demand and validate real interactions instead of guessing.\nThis session is focused on making AI systems testable, reliable, and easier to develop.","starts_at":"2026-09-25T10:20:00-07:00","ends_at":"2026-09-25T10:50:00-07:00","stage":"Stage 7","track":"DevEx & Productivity","type":"DevEx & Productivity","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Anna Chernyshova - Sr. Solutions Engineer at Docker"],"tags":["Agentic AI","Developer Experience (DevEx)","Docker","Integration Testing"],"live_url":"https://www.youtube.com/watch?v=wfw6ysjBfvE","recording_url":"https://www.youtube.com/watch?v=wfw6ysjBfvE","app_url":"https://app.wearedevelopers.com/events/18/session/1273","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1679-testing-ai-workflows","urls":["https://www.youtube.com/watch?v=wfw6ysjBfvE"],"flag":null},{"id":1274,"title":"MicroAgents: The Microservices of the Agentic Era","description":"The microservices revolution gave us a hard-won set of principles: small services with well-defined contracts, owned by independent teams, composable into larger systems, replaceable without rewriting the world. The agentic AI era is rediscovering these lessons the hard way. Most enterprises today are building agents the way we built monoliths fifteen years ago: each agent a self-contained stack with its own conversation store, its own auth, its own observability, unable to talk to the agent built down the hall.\n\nThere is a better pattern. We call it a MicroAgent, and it is to the agentic world what a microservice is to the API world. A MicroAgent is a lightweight, independently-deployable package consisting of two things: an MCP server that exposes domain-specific tools, and a prompt template that encodes domain expertise. That is the entire contract. No session management. No streaming code. No auth boilerplate. Those concerns belong to a shared Base Agent Service, the way platform concerns belong to a service mesh or API gateway.\n\nThe Model Context Protocol is the API contract that makes this work. MCP is not just a tool-calling format. It is the service boundary that lets MicroAgents from different teams compose into super-agents through configuration alone. The Base Agent routes tool calls over MCP, fetches prompt templates via HTTP with conditional caching, and merges state updates from _meta fields in tool responses.\n\nThis talk walks through the architecture: MicroAgents as units of ownership, MCP as the contract, shared infrastructure as the substrate, and the multi-agent composition patterns that emerge once these boundaries are clean.","starts_at":"2026-09-25T10:20:00-07:00","ends_at":"2026-09-25T10:50:00-07:00","stage":"Outdoor Stage","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ashish Shubham - VP Engineering at ThoughtSpot"],"tags":["AI Standards","APIs","Agentic AI"],"live_url":"https://www.youtube.com/watch?v=NgXDpn7Acf4","recording_url":"https://www.youtube.com/watch?v=NgXDpn7Acf4","app_url":"https://app.wearedevelopers.com/events/18/session/1274","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1692-microagents-the","urls":["https://www.youtube.com/watch?v=NgXDpn7Acf4"],"flag":null},{"id":1257,"title":"Vibe Coding Accessibility","description":"This session explores how today’s most powerful AI-based coding tools are shaping the future of accessible technology. With tools like GitHub Copilot, ChatGPT, and other AI code assistants becoming mainstream, developers face both new opportunities and new risks. This session will provide a candid overview of the leading AI coding platforms and evaluate how well they support accessibility—from generating accessible code patterns to avoiding common pitfalls that exclude users with disabilities. We’ll also discuss their role in remediation: Can AI help fix inaccessible code, or does it introduce new challenges? To ground the discussion, we’ll showcase real-world examples of accessible web and native mobile products built with the help of AI tools. Attendees will walk away with practical insights on what AI coding tools can (and can’t) do today, best practices for ensuring accessible outcomes, and a vision for how accessibility professionals and developers can “vibe” with AI to build more inclusive digital experiences.","starts_at":"2026-09-25T11:00:00-07:00","ends_at":"2026-09-25T11:30:00-07:00","stage":"Outdoor Stage","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Karl Groves - Accessibility Consultant at AFixt"],"tags":["Accessibility","AI Coding Assistants"],"live_url":"https://www.youtube.com/watch?v=SCXR9OSq-T8","recording_url":"https://www.youtube.com/watch?v=SCXR9OSq-T8","app_url":"https://app.wearedevelopers.com/events/18/session/1257","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1438-vibe-coding","urls":["https://www.youtube.com/watch?v=SCXR9OSq-T8"],"flag":null},{"id":1276,"title":"Govern the Runtime, Not the Agent: One Control Plane for Every Model, Every Harness","description":"The industry is converging on a multi-agent, multi-model world. Teams are landing on a few facts at once: the best model changes every couple of months, it makes no economic sense to call a frontier model to classify a ticket, and your unique workflows may sometimes need custom models. So you end up running many models across many harnesses.\n\nThis makes trust the defining challenge of today. While harnesses do ship some guardrails, each one governs only its own traffic, and we are already seeing where that breaks down. Agents route around rails the harness cannot see, and the rails themselves shift underneath you whenever the model vendor ships an update. Safety cannot depend on the agent making the right decision, or on someone else's release schedule.\n\nTushar Jain, CTO at Docker, makes the case for a meta-runtime: the layer below all your harnesses, covering agent execution, tool calls, credential usage, scoped permissions, token spend. A meta-runtime makes it possible to control and have visibility into all your agents, no matter what model or what harness.","starts_at":"2026-09-25T11:00:00-07:00","ends_at":"2026-09-25T11:30:00-07:00","stage":"Mainstage","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Tushar Jain - CTO at Docker"],"tags":["Agents","Agentic AI","Containers","Governance","Infrastructure","Security"],"live_url":"https://www.youtube.com/watch?v=Oc-DrLQWimc","recording_url":"https://www.youtube.com/watch?v=Oc-DrLQWimc","app_url":"https://app.wearedevelopers.com/events/18/session/1276","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1855-govern-the-runtime","urls":["https://www.youtube.com/watch?v=Oc-DrLQWimc"],"flag":null},{"id":1277,"title":"Building Enterprise Software for AI Agents","description":"Enterprise software is getting a second kind of user: agents that log in, call APIs, and complete tasks on behalf of people. Products built for human eyes and hands work badly for machine users - interfaces, permissions, integrations, and pricing all assume a person on the other end. What it takes to make enterprise software work for agents, across products, APIs, and the businesses behind them.","starts_at":"2026-09-25T11:00:00-07:00","ends_at":"2026-09-25T11:30:00-07:00","stage":"Tech Leaders Stage","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Gil Feig - Co-founder & CTO at Merge","Nitin Eusebius - Principal Solutions Architect at AWS","Sachin Kaura - Vice President & Chief Architect AI Research, Experimentation & Evaluation at SAP Business AI","James Watters - CTO at Tanzu division at Broadcom Inc.","Matt Burns - Director of Editorial at Insight Media Group"],"tags":[],"live_url":"https://www.youtube.com/watch?v=EUOsY3yZ4AQ","recording_url":"https://www.youtube.com/watch?v=EUOsY3yZ4AQ","app_url":"https://app.wearedevelopers.com/events/18/session/1277","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1843-building-enterprise","urls":["https://www.youtube.com/watch?v=EUOsY3yZ4AQ"],"flag":null},{"id":1278,"title":"The Agentic Engineering Loop","description":"If vibe coding is giving in to vibes and one-shotting code that you are likely to throwaway, then agentic engineering is the deliberate practice of designing systems to help agents create high-quality code that gets better over time. \n\nIn this talk, we cover the agentic engineering loop and how to leverage it to multiply your output at every phase. We cover the new challenges that arise when agents write most of the code and we provide useful mental models for thinking about software development in the world of agents. \n\nThis talk is for anyone that wants to adopt an agent-first approach to software development and get the most out of agents and the latest frontier models.","starts_at":"2026-09-25T11:00:00-07:00","ends_at":"2026-09-25T11:30:00-07:00","stage":"Stage 1","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Kevin Lin - Member of Technical Staff at OpenAI"],"tags":["Agents","Agentic AI","Vibe Coding"],"live_url":"https://www.youtube.com/watch?v=GjJ-KEOG35I","recording_url":"https://www.youtube.com/watch?v=GjJ-KEOG35I","app_url":"https://app.wearedevelopers.com/events/18/session/1278","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1704-the-agentic","urls":["https://www.youtube.com/watch?v=GjJ-KEOG35I"],"flag":null},{"id":1279,"title":"Build Fast, Deploy Faster: Cross Platform AI development in 2026","description":"Quality is a function of iteration. \n\nExpo has become the standard for cross platform application development because it accelerates the process of building, distributing, and deploying your applications. \n\nAnd we just made that iteration cycle exponentially faster. \n\nWith the introduction of Echo, you can now use your preferred coding assistant to prompt beautiful, cutting edge apps into existence from the palm of your hand. \n\nIn this talk I'll explain what the modern application development experience can look like and why there will be more, better apps because of it.","starts_at":"2026-09-25T11:00:00-07:00","ends_at":"2026-09-25T11:30:00-07:00","stage":"Stage 2","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Charlie Cheever - Co-founder and CEO at Expo"],"tags":["AI Coding Assistants","AI Standards","Anthropic","Automation","Cross-Platform","Developer Experience (DevEx)","Kotlin","React","React Native","Swift"],"live_url":"https://www.youtube.com/watch?v=3Vi7-vfRxBo","recording_url":"https://www.youtube.com/watch?v=3Vi7-vfRxBo","app_url":"https://app.wearedevelopers.com/events/18/session/1279","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1838-build-fast-deploy","urls":["https://www.youtube.com/watch?v=3Vi7-vfRxBo"],"flag":null},{"id":1280,"title":"Performance Engineering in the Age of AI","description":"Profiling has long been an esoteric skill that only few people ever took the time to learn. The tools are clunky, and the visualizations difficult to read. However, at it's core, performance engineering is very methodical, and follows a lot of rules. AI has also gotten very good at writting code, so in an abundance of luck, they are a match made in heaven!\n\nIn this session Frederic will walk through the incredible integration between AI and Profiling and show how performance engineering is now accessible to every engineer regardless of proficiency.","starts_at":"2026-09-25T11:00:00-07:00","ends_at":"2026-09-25T11:30:00-07:00","stage":"Stage 3","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Frederic Branczyk - VP of Data Platforms at Dash0"],"tags":["AI Coding Assistants","Claude","Performance"],"live_url":"https://www.youtube.com/watch?v=f_OF7kI9zE4","recording_url":"https://www.youtube.com/watch?v=f_OF7kI9zE4","app_url":"https://app.wearedevelopers.com/events/18/session/1280","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1789-performance","urls":["https://www.youtube.com/watch?v=f_OF7kI9zE4"],"flag":null},{"id":1281,"title":"Managing Abuse in the Era of AI Agents","description":"Agentic attacks will be a fact of life going forward. AI agents are now superhuman in some areas of cybersecurity, and attackers have access too. This talk will review the current state of the art in defending online services against agentic attacks, and near-term predictions for what to expect soon.","starts_at":"2026-09-25T11:00:00-07:00","ends_at":"2026-09-25T11:30:00-07:00","stage":"Stage 4","track":"AI Trust & Safety","type":"AI Trust & Safety","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Eli-Shaoul Khedouri - CEO at Intuition Machines"],"tags":["AGI (Artificial General Intelligence)","AppSec","Agentic AI","Secure Coding","Security"],"live_url":"https://www.youtube.com/watch?v=EUPQRnUxoR8","recording_url":"https://www.youtube.com/watch?v=EUPQRnUxoR8","app_url":"https://app.wearedevelopers.com/events/18/session/1281","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1869-managing-abuse-in","urls":["https://www.youtube.com/watch?v=EUPQRnUxoR8"],"flag":null},{"id":1282,"title":"Managing GPUs by Just Asking, Infrastructure in the Age of MCP","description":"This talk explores the shift from writing software to operating it through conversation, in which the Model Context Protocol enables an agent to drive real infrastructure APIs through natural language. Using Runpod's MCP servers connected to an AI agent like Claude Code or Cursor, the audience will experience infrastructure-by-conversation in action and you will see me listing running pods, spinning up a GPU training pod, standing up an autoscaling serverless endpoint, and shutting it all down just by typing what they want, and learn about the opportunities and challenges that exist in this new paradigm, as well as how they might impact developer communities like this one.","starts_at":"2026-09-25T11:00:00-07:00","ends_at":"2026-09-25T11:30:00-07:00","stage":"Stage 5","track":"AI Models & Infrastructure","type":"AI Models & Infrastructure","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Jessica Garson Beauchemin - Developer Relations Lead & Community at Runpod"],"tags":["Agents","Agentic AI","Infrastructure","Large Language Models (LLMs)"],"live_url":"https://www.youtube.com/watch?v=yZXesDDKgb8","recording_url":"https://www.youtube.com/watch?v=yZXesDDKgb8","app_url":"https://app.wearedevelopers.com/events/18/session/1282","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1812-managing-gpus-by","urls":["https://www.youtube.com/watch?v=yZXesDDKgb8"],"flag":null},{"id":1284,"title":"Beyond Vibe Coding: An AI Builder’s Guide to Migrating 10k+ React Components","description":"Ads Manager powers 84% of Meta's Ads Revenue, but its decade-old codebase was stuck on React class components — blocking modern patterns like hooks, Relay, and React Compiler. Manual migration of 10k+ components class to functional component was impractical. In this talk, I'll show how we built an AI codemod pipeline using LLMs that achieved a 5x speedup, migrating 3k+ components with a 99.6% success rate. I'll cover the tradeoffs between AST and AI codemods, how to classify components by complexity for targeted prompts, and the grading/eval strategies that made non-deterministic AI agents production-ready.","starts_at":"2026-09-25T11:00:00-07:00","ends_at":"2026-09-25T11:30:00-07:00","stage":"Stage 7","track":"Languages, Web & Mobile","type":"Languages, Web & Mobile","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Shubham Chaurasia - Sr. Software Engineer at Meta"],"tags":["AI Coding Assistants"],"live_url":"https://www.youtube.com/watch?v=FUtFot-UFrc","recording_url":"https://www.youtube.com/watch?v=FUtFot-UFrc","app_url":"https://app.wearedevelopers.com/events/18/session/1284","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1715-beyond-vibe-coding","urls":["https://www.youtube.com/watch?v=FUtFot-UFrc"],"flag":null},{"id":1285,"title":"Loop Engineering: Designing and Observing the Loops That Run Your Agents With Opik","description":"A prompt encodes one way to solve a problem. Change that input and that path often breaks. Loop engineering targets the process instead. You design the cycle the agents runs: it acts, checks the result, and decides whether to keep going. The agent finds a path rather than following one you scripted. \n\nThis talk covers how to design those loops deliberately. We'll walk through the anatomy of an agent loop, why stopping conditions deserve to be treated as a first-class design decision, how to tell a recoverable error from a hard blocker, and why the most reliable exit conditions lean on deterministic checks rather than asking the model to grade its own work.\n\nThe other half of the problem is visibility. A loop you can't see inside is a loop you can't debug. Using Opik, an open-source observability and evaluation platform, we'll instrument an agent's loop so you can trace what happens at each iteration, measure where it breaks down, and set up the evaluation that tells you whether a change actually made things better.\n\nYou'll leave with a clear mental model for loop design and a practical workflow for observing and improving agent behavior before it reaches your users.","starts_at":"2026-09-25T11:00:00-07:00","ends_at":"2026-09-25T11:30:00-07:00","stage":"Stage 6","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Abigail Morgan - AI Developer Advocate at Comet"],"tags":["AI Coding Assistants","Agents","Agentic AI","Generative AI (GenAI)","Large Language Models (LLMs)","Multi-Agent Systems","Observability","Open Source","Prompt Engineering"],"live_url":"https://www.youtube.com/watch?v=YxNZ6Jha1ag","recording_url":"https://www.youtube.com/watch?v=YxNZ6Jha1ag","app_url":"https://app.wearedevelopers.com/events/18/session/1285","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1868-loop-engineering","urls":["https://www.youtube.com/watch?v=YxNZ6Jha1ag"],"flag":null},{"id":1288,"title":"The AI Proving Ground","description":"Enterprise AI spending keeps climbing, yet most pilots never make it into production. Between the demo and the deployment sits the hard part: testing against real workloads instead of benchmarks, security and compliance review, proving ROI beyond the proof of concept, and deciding who signs off. How organizations evaluate AI before trusting it in production - what a rigorous evaluation looks like, which criteria actually predict success, and what separates the pilots that ship from the ones that quietly die.","starts_at":"2026-09-25T11:40:00-07:00","ends_at":"2026-09-25T12:10:00-07:00","stage":"Tech Leaders Stage","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Anna Maria Brunnhofer-Pedemonte - CEO and Co-Founder at Impact.AI","David Hefter - AI Product Strategist at BlackRock","Li Fan - Chief AI Officer at Circle","Bharat Melag - Global Head- Agentic Tokens & Provisioning at Visa"],"tags":[],"live_url":"https://www.youtube.com/watch?v=7W19M15RKBI","recording_url":"https://www.youtube.com/watch?v=7W19M15RKBI","app_url":"https://app.wearedevelopers.com/events/18/session/1288","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1887-the-ai-proving","urls":["https://www.youtube.com/watch?v=7W19M15RKBI"],"flag":null},{"id":1289,"title":"Context Engineering: How machines remember and forget","description":"Context Engineering is the art of shaping what an AI model knows at any moment by managing how information enters, persists, or fades from its working memory. In this session, we explore how machine learning systems “remember” through state objects, notes, and retrieval—and how they “forget” using compression, selection, and context limits. We’ll walk through real-world agent patterns that balance personalization with privacy, performance, and relevance. Participants will learn practical techniques to design memory that feels intentional, evolving, and human-aware.","starts_at":"2026-09-25T11:40:00-07:00","ends_at":"2026-09-25T12:10:00-07:00","stage":"Stage 1","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Emre Okcular - Solutions Architect at OpenAI"],"tags":["AI Models"],"live_url":"https://www.youtube.com/watch?v=i_neG6v1sFg","recording_url":"https://www.youtube.com/watch?v=i_neG6v1sFg","app_url":"https://app.wearedevelopers.com/events/18/session/1289","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1765-context-engineering","urls":["https://www.youtube.com/watch?v=i_neG6v1sFg"],"flag":null},{"id":1290,"title":"Reinventing Testing Practices in the AI Era","description":"AI-infused applications demand a rethinking of our testing practices. Developers face a new class of challenge as LLMs become standard integration points in modern applications: non-deterministic behavior that traditional testing approaches were never designed to handle. The current wave of distributed, orchestrated, agentic AI systems is evolving fast and, if we're being honest, it smells a lot like the early days of microservices.\n\nIn this session, we'll explore how your DevOps and testing practices must evolve when you wire AI into your applications. Not all AI failures look the same, and recognizing the difference is the first step toward building systems you can actually trust. We'll walk through practical testing and observability strategies, using open source tools that give you confidence in AI-infused applications at every layer of the stack.\n\nYou'll leave with a concrete mental model for reasoning about AI failures and one grounding question: What if AI was just an API call?","starts_at":"2026-09-25T11:40:00-07:00","ends_at":"2026-09-25T12:10:00-07:00","stage":"Stage 2","track":"Languages, Web & Mobile","type":"Languages, Web & Mobile","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Eric Deandrea - Sr. Principal Software Engineer at IBM"],"tags":["AI Standards","Best Practices","Observability","Test-Driven Development (TDD)","Testing"],"live_url":"https://www.youtube.com/watch?v=ya0FPWnlPuI","recording_url":"https://www.youtube.com/watch?v=ya0FPWnlPuI","app_url":"https://app.wearedevelopers.com/events/18/session/1290","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1724-reinventing-testing","urls":["https://www.youtube.com/watch?v=ya0FPWnlPuI"],"flag":null},{"id":1291,"title":"Culture Doesn't Scale Itself: Leading Engineering Teams Through Hypergrowth and the AI Transition","description":"Engineering culture is easy to talk about. It's much harder to carry it across seed-stage scrappiness, enterprise at scale, and an industry being restructured by AI—without losing what made the team good in the first place.\n\nThat's the lived experience Thanos Baskous brings to this talk.\n\nThanos has led engineering in some of the most demanding environments in tech: infrastructure at Coinbase during a critical growth period, Chief Architect at Blackstone where he led a company-wide DevOps transformation, and engineering roles at Twitter. Today he's Co-Founder and VP of Engineering at Cogent Security, an AI-native vulnerability management platform that raised a $42M Series A six months after launch.\n\nEach of those environments asked the same question in a different way: how do you build a team culture that's durable enough to survive scale, honest enough to survive pressure, and flexible enough to survive a complete rethinking of how software gets built?\n\nIn this session, Thanos will share what worked, and what broke, as he moved between hypergrowth startups, enterprise transformation programs, and the current shift to AI-native engineering. He'll get into the specific moments where culture either compounds or cracks: when you're scaling headcount faster than your processes, when AI tooling starts to blur the line between junior and senior, and when the team's identity is tied to practices that may not survive the next few months.\n\nThis won't be a framework talk. Engineering leaders will walk out with actionable tactics addressing the one variable that determines whether a team scales or stalls: leadership.","starts_at":"2026-09-25T11:40:00-07:00","ends_at":"2026-09-25T12:10:00-07:00","stage":"Stage 3","track":"Leadership & Strategy","type":"Leadership & Strategy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Thanos Baskous - VP of Engineering & Co-founder at Cogent Security"],"tags":["Agents","Agentic AI","Best Practices","Collaboration","Communication","Community","Digital Transformation","People & Culture","Scaling","Soft Skills","Talent & Recruiting","Team Building","Tooling"],"live_url":"https://www.youtube.com/watch?v=t-OXRbUn02w","recording_url":"https://www.youtube.com/watch?v=t-OXRbUn02w","app_url":"https://app.wearedevelopers.com/events/18/session/1291","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1411-culture-doesn-t","urls":["https://www.youtube.com/watch?v=t-OXRbUn02w"],"flag":null},{"id":1292,"title":"Quantum Close-Up: What Engineers Need to Know Before Q-Day","description":"Quantum is already here — in post-quantum security standards, AI-accelerated research, advanced simulation, and new forms of compute quietly reshaping what's possible at the infrastructure layer. What hasn't arrived yet is Q-Day. And when it does, it won't announce itself. It will be a progression we recognize only once it's already underway. AI took 70+ years to reach its GenAI inflection point. Quantum won't take that long, and AI-accelerated research is likely to get us there faster than most teams are planning for. This session gives engineers and tech leaders a practical framework for what to act on now, what can wait, and where early readiness creates real competitive advantage, drawing on PwC research and patents to ground the conversation in what's actually happening, not what's hypothetical.","starts_at":"2026-09-25T11:40:00-07:00","ends_at":"2026-09-25T12:10:00-07:00","stage":"Stage 4","track":"AI Models & Infrastructure","type":"AI Models & Infrastructure","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Scott Likens - Global Chief AI Engineer, Principal at PwC"],"tags":["AI Standards","Agentic AI","Cloud Security","Compliance","Cryptography","Governance","Infrastructure","Innovation","Quantum","Security"],"live_url":"https://www.youtube.com/watch?v=HtYk3_M1YZg","recording_url":"https://www.youtube.com/watch?v=HtYk3_M1YZg","app_url":"https://app.wearedevelopers.com/events/18/session/1292","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1782-quantum-close-up","urls":["https://www.youtube.com/watch?v=HtYk3_M1YZg"],"flag":null},{"id":1293,"title":"Review Was Already the Bottleneck. Then Agents Broke It Completely.","description":"Agent speed ends at the pull request. The diff shows what changed, never why: which intent drove it, what alternatives were rejected, what was actually verified. Without that trail, approval is guesswork. Join Joseph Katsioloudes to see review rebuilt around reasoning and evidence, so speed stays safe.","starts_at":"2026-09-25T11:40:00-07:00","ends_at":"2026-09-25T12:10:00-07:00","stage":"Stage 5","track":"AI Agents","type":"AI Agents","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Joseph Katsioloudes - Senior Developer Advocate at Entire"],"tags":["Agents","CI/CD","Code Reviews","Tokenomics","Workflows","Workflow Automation"],"live_url":"https://www.youtube.com/watch?v=EbTDtBRanFw","recording_url":"https://www.youtube.com/watch?v=EbTDtBRanFw","app_url":"https://app.wearedevelopers.com/events/18/session/1293","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1817-review-was-already","urls":["https://www.youtube.com/watch?v=EbTDtBRanFw"],"flag":null},{"id":1294,"title":"Codifying Trade-offs: Security, Cost, and Compliance as Agent Guardrails","description":"Every agent demo ends the same way: the agent does the thing, the audience claps, nobody asks what happened to the security review.\n\nI didn't just theorize about codifying trade-offs. I built an open-source multi-agent system that does it. Git-Ape (github.com/Azure/git-ape) is a platform engineering framework where specialized agents plan, validate, and deploy Azure infrastructure — and where nothing reaches production without passing through explicit guardrails enforced by the system itself.\n\nHere's how it actually works. A requirements gatherer agent interviews the human. A template generator produces infrastructure-as-code. Then, before anyone confirms anything, a security analyzer runs a blocking gate — deployment is structurally impossible until issues are resolved. A cost estimator prices the deployment so humans confirm with real numbers, not vibes. A Principal Architect agent runs a Well-Architected Framework review across all five pillars. Only after all of that does a human see the full picture and explicitly approve. After deployment, a drift detector closes the evidence loop: did what we deployed stay the way we deployed it?\n\nThe key insight isn't that we added checks. It's that we made trade-offs consumable by agents. Security policy isn't a PDF — it's policy-as-code that agents evaluate natively. Cost thresholds aren't guidelines — they're hard constraints. Compliance isn't an audit you do later — it's a gate you pass through now.\n\nI'll walk through the architecture, the failures that shaped it, and the design principles that transfer to any multi-agent system where the stakes are real. If your agents can deploy but can't be told no, you don't have guardrails. You have a demo.","starts_at":"2026-09-25T11:40:00-07:00","ends_at":"2026-09-25T12:10:00-07:00","stage":"Stage 6","track":"AI Trust & Safety","type":"AI Trust & Safety","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Suzanne Daniels - Chief Developer Advisor at Microsoft"],"tags":["AI Coding Assistants","APIs","Agentic AI","Autonomous Systems","Best Practices","Cross-Platform","Developer Experience (DevEx)","DevOps","DevSecOps","Generative AI (GenAI)","Open Source"],"live_url":"https://www.youtube.com/watch?v=UBUZcB6euko","recording_url":"https://www.youtube.com/watch?v=UBUZcB6euko","app_url":"https://app.wearedevelopers.com/events/18/session/1294","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1946-codifying-trade-offs","urls":["https://www.youtube.com/watch?v=UBUZcB6euko"],"flag":null},{"id":1295,"title":"x402: Building Pay-Per-Request APIs for AI Agents","description":"AI agents are starting to pay for the APIs they call, no keys, no billing dashboards, no checkout. In this session, Brian Whippo, Senior Director of Integrations and Developer Tooling at the Algorand Foundation, walks through x402, an open protocol that embeds payment logic directly into HTTP requests, letting agents transact per call in real time. Brian will cover how to turn any API into a paid endpoint, what a resource server and facilitator do under the hood, and why instant-finality settlement matters for high-frequency agent traffic. He'll also share how developers can put this into practice. Attendees will leave with a working understanding of the protocol and a clear path to building their first paid endpoint.","starts_at":"2026-09-25T11:40:00-07:00","ends_at":"2026-09-25T12:10:00-07:00","stage":"Stage 7","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Brian Whippo - Senior Director Integrations & Developer Tooling at Algorand Foundation"],"tags":["AI Standards","APIs","Agents","Agentic AI"],"live_url":"https://www.youtube.com/watch?v=wO199ZCZXc8","recording_url":"https://www.youtube.com/watch?v=wO199ZCZXc8","app_url":"https://app.wearedevelopers.com/events/18/session/1295","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1758-x402-building-pay","urls":["https://www.youtube.com/watch?v=wO199ZCZXc8"],"flag":null},{"id":1296,"title":"GitHub’s Team X-Ray: Your Repository Knows More About Your Team Than Your Team Does","description":"I've joined teams where I spent months being invisible.\n\nNot because people were bad. Just because all the knowledge was buried in 50,000 commits I'd never seen. Who owns the auth flow? Who actually likes debugging race conditions? I had no idea. I was guessing, and it showed.\n\nSo I built Team X-Ray. It's a VS Code extension that analyzes people, not code. How they communicate. Who they collaborate with. What they're genuinely good at. What kinds of problems they actually enjoy solving.\n\nIt started as a GitHub Copilot integration connected to repository data through MCP. But the architecture evolved. Today it talks directly to the Copilot SDK with custom tools that give the agent native access to your team's data. No Docker. No middleware server.\n\nThen something unexpected happened: AI agents started making commits.\n\nSuddenly my tool was lying to me. It was attributing expertise to bots. Inflating contributions that no human wrote. I had to teach it to separate human work from automated work, and in doing that I stumbled onto something more interesting.\n\nIn the age of agents, expertise isn't just who writes the code. It's who understands it. Who directs it. Who makes everyone else better.\n\nIn this talk I'll walk you through:\n\n- The technical evolution: from MCP to Copilot SDK with custom tools\n- How I built Team X-Ray and what it taught me about real team dynamics\n- The agent problem: how to detect bot commits and separate human expertise from automation\n- Real examples of AI surfacing mentors, knowledge silos, and hidden team dynamics\n\nAs Moira Rose said: \"When one of us shines, we all shine.\"\n\nI'm not trying to replace human connection. I'm trying to accelerate it. Even when agents are already part of the team.","starts_at":"2026-09-25T11:40:00-07:00","ends_at":"2026-09-25T12:10:00-07:00","stage":"Outdoor Stage","track":"Applied AI","type":"Applied AI","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Andrea Griffiths - Sr. Developer Advocate at GitHub"],"tags":["AI Coding Assistants","AI Models","AI Standards","GitHub","TypeScript","VS Code"],"live_url":"https://www.youtube.com/watch?v=eDAQjsroxII","recording_url":"https://www.youtube.com/watch?v=eDAQjsroxII","app_url":"https://app.wearedevelopers.com/events/18/session/1296","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1691-github-s-team-x-ray","urls":["https://www.youtube.com/watch?v=eDAQjsroxII"],"flag":null},{"id":1393,"title":"You are the developer. From DX to AX with humans in mind.","description":"In a world where AI agents can write code and where platforms are shifting their focus from Developer Experience to Agent Experience, what does it mean to be a developer?\n\nMatt Biilmann coined the term Agent Experience, AX at the start of 2025 and pivoted Netlify’s product northstar from DX to AX, and pushed the company to build software across teams and disciplines instead of buying SaaS software.\n\nHe’ll cover the emerging AX discipline, how the focus on AX enables domain expert to become the next generation software developers, and why that will only make software engineering as a discipline more important, not less important, while fundamentally changing the tools, skills and workflows involved.","starts_at":"2026-09-25T11:40:00-07:00","ends_at":"2026-09-25T12:10:00-07:00","stage":"Mainstage","track":"DevEx & Productivity","type":"DevEx & Productivity","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Matt Biilmann - CEO and Co-founder at Netlify"],"tags":["AI Coding Assistants","Agents","Agentic AI","Future of Work","Software Architecture"],"live_url":"https://www.youtube.com/watch?v=8dxnArwJDsc","recording_url":"https://www.youtube.com/watch?v=8dxnArwJDsc","app_url":"https://app.wearedevelopers.com/events/18/session/1393","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1934-you-are-the","urls":["https://www.youtube.com/watch?v=8dxnArwJDsc"],"flag":null},{"id":1275,"title":"Testing React Backends Like a Pro: Mocking Databases with SQLite","description":"Modern engineering teams move fast — but brittle tests, flaky mocks, and sluggish integration pipelines can bring even the strongest React + Node backends to a crawl. One area that consistently gets often overlooked is database testing for the APIs powering today’s web applications. SQL tests are skipped entirely because they usually require a persistent database instance, complicating CI/CD pipelines and slowing development. But there’s a better way: using SQLite as an ephemeral, SQL‑compatible stand‑in for your production database.\n\nThis session introduces a battle‑tested approach to backend API testing that replaces fragile mock frameworks with a lightweight, in‑memory SQLite database that behaves like the real thing. The payoff is immediate: faster feedback loops, more reliable tests, and dramatically simpler debugging.\n\nYou’ll learn how to spin up a fully isolated test database for each suite, seed it with realistic data, and run true end‑to‑end API tests without touching production infrastructure. We’ll walk through schema setup, SQL‑driven test design, teardown automation, and strategies for keeping tests blazing fast as your backend grows.\n\nThis talk offers a fresh perspective on a familiar challenge: testing backend logic as it actually runs, not as mocks pretend it runs. Expect live coding, practical patterns, and insights drawn directly from real‑world engineering work. If you’re ready to elevate your backend testing strategy and ship with confidence, this session will show you exactly how to get there.","starts_at":"2026-09-25T12:20:00-07:00","ends_at":"2026-09-25T12:50:00-07:00","stage":"Stage 7","track":"Data & Databases","type":"Data & Databases","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["David Morris - Solution Architect at Leidos"],"tags":["APIs","Node.js","Quality Assurance (QA)","React","Reliability","SQL","SQLite","Testing","Unit Testing"],"live_url":"https://www.youtube.com/watch?v=-OiYCFpcM8g","recording_url":"https://www.youtube.com/watch?v=-OiYCFpcM8g","app_url":"https://app.wearedevelopers.com/events/18/session/1275","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1723-testing-react","urls":["https://www.youtube.com/watch?v=-OiYCFpcM8g"],"flag":null},{"id":1298,"title":"A Computer Is All You Need","description":"Developers and AI Agents all have in common the need for on-demand computers in the cloud. In this session, we'll show how Google Cloud Run delivers on-demand computers with zero overhead and pay-per-use pricing for all of your apps and agents.\n\nWe will deep dive with live demos into three new workloads that can benefit from Cloud Run's on demand computers:\n1. Deploy your apps vibe coded in Google AI Studio to the cloud without needing a credit card,\n2. Run your personalized long running background agents, like OpenClaw or Hermes, on Cloud Run Instances,\n3. Give your scalable agents the ability to execute untrusted code fast and securely with the new Cloud Run sandboxes.","starts_at":"2026-09-25T12:20:00-07:00","ends_at":"2026-09-25T12:50:00-07:00","stage":"Mainstage","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Justin Mahood - Group Product Manager at Google Cloud Run"],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1298","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1829-a-computer-is-all","urls":[],"flag":null},{"id":1299,"title":"How AI Search Changes the Data Game","description":"With AI search, systems can find, connect, and use data in ways that were not possible before. But AI systems are only as good as the data they run on: discoverability, quality, governance, and reliability are becoming engineering problems, not afterthoughts. How enterprises are getting their data ready for AI - what already works, how it works, and what remains unsolved.","starts_at":"2026-09-25T12:20:00-07:00","ends_at":"2026-09-25T12:50:00-07:00","stage":"Tech Leaders Stage","track":"Data & Databases","type":"Data & Databases","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Jared Jordan - GM & Head of at Capital One Garage","Saurabh Sharma - CPO at You.com","Tomislav Tipurić - CTO & CEO at Nephos","Vikas Mathur - CPO at MariaDB"],"tags":[],"live_url":"https://www.youtube.com/watch?v=XCvA1HnxLVM","recording_url":"https://www.youtube.com/watch?v=XCvA1HnxLVM","app_url":"https://app.wearedevelopers.com/events/18/session/1299","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1856-how-ai-search","urls":["https://www.youtube.com/watch?v=XCvA1HnxLVM"],"flag":null},{"id":1300,"title":"What Is a Software Factory and How to Build One in 20 Minutes","description":"Software factories are not products. They are a pattern built from a few core capabilities. We will review those capabilities, assemble a software factory from them in under 20 minutes, and see what kind of work it is good for.","starts_at":"2026-09-25T12:20:00-07:00","ends_at":"2026-09-25T12:50:00-07:00","stage":"Stage 2","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Victor Savkin - CTO & Co-founder at Nx"],"tags":["AI Coding Assistants"],"live_url":"https://www.youtube.com/watch?v=dAERDhPA5zw","recording_url":"https://www.youtube.com/watch?v=dAERDhPA5zw","app_url":"https://app.wearedevelopers.com/events/18/session/1300","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1759-what-is-a-software","urls":["https://www.youtube.com/watch?v=dAERDhPA5zw"],"flag":null},{"id":1301,"title":"Give the Agent a Budget, Not a Token","description":"Every agent demo runs with a god-token. Then it ships, and someone has to explain why the helpful AI just rm -rf'd the staging database \"to clean up.\"\n\nI run platform infrastructure at a frontier lab, and for the last year my job has partly been: let coding agents do real work against real systems, without ever having to write the postmortem. This talk is the permission model that fell out of that - not RBAC-with-extra-steps, but primitives designed for an actor that's smart, fast, tireless, and occasionally *confidently wrong*.\n\n**The four primitives:**\n\n- **Asymmetric verbs** - the agent can `quarantine` but not `delete`, `retry` but not `approve`, `propose` but not `merge`. The verb list *is* the security boundary. Stop thinking in resources, start thinking in reversible vs. irreversible actions.\n- **Regenerating budgets** - every agent identity gets N disruptive actions per window. Burn the budget, you're benched until it refills. No human-in-the-loop until the budget's gone — which means 95% autonomy with a hard ceiling on blast radius.\n- **The undo test** - if the agent can't undo it, the agent can't do it without a second key. One line, surprisingly load-bearing.\n- **Tripwires over allow-lists** - let the agent roam, but instrument the three actions that would actually hurt. Cheaper than enumerating everything safe.\n\nI'll show the ~200-line policy layer that implements all four, the failure modes each one exists to catch, and the one design I shipped that turned out to be security theater. Tool-agnostic - works whether your agent is touching CI, a database, a cloud account, or your users' files.\n\nIf you're shipping an agent that does anything more than read, you'll leave with a threat model and a starting policy you can paste into your repo on the flight home.","starts_at":"2026-09-25T12:20:00-07:00","ends_at":"2026-09-25T12:50:00-07:00","stage":"Stage 4","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Sachin Malhotra - Platform Engineer & MTS at Anthropic"],"tags":["Anthropic","Agentic AI","Claude","DevSecOps"],"live_url":"https://www.youtube.com/watch?v=o33vvIBWVec","recording_url":"https://www.youtube.com/watch?v=o33vvIBWVec","app_url":"https://app.wearedevelopers.com/events/18/session/1301","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1695-give-the-agent-a","urls":["https://www.youtube.com/watch?v=o33vvIBWVec"],"flag":null},{"id":1302,"title":"Why CI Deserves Its Own Infrastructure","description":"A technical talk focused on why CI needs dedicated infrastructure. A high-level architecture talk about scheduling and caching - from describing customer workloads (volume, spikes, storage needs) to solutions - predictability, scheduling and custom storage.","starts_at":"2026-09-25T12:20:00-07:00","ends_at":"2026-09-25T12:50:00-07:00","stage":"Stage 6","track":"DevOps & Platform Engineering","type":"DevOps & Platform Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Piotr Bejda - Member of Technical Staff at Blacksmith"],"tags":["Caching","CI/CD","Infrastructure"],"live_url":"https://www.youtube.com/watch?v=biK8KEMNhO4","recording_url":"https://www.youtube.com/watch?v=biK8KEMNhO4","app_url":"https://app.wearedevelopers.com/events/18/session/1302","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1824-why-ci-deserves-its","urls":["https://www.youtube.com/watch?v=biK8KEMNhO4"],"flag":null},{"id":1201,"title":"Agentic coding with GitHub Copilot CLI","description":"With Copilot CLI, you can work with Copilot natively in your terminal, where you're already working, to request updates, run tests, and perform tasks. You can access your issues, gists, and pull requests, to speed development and ensure Copilot has the right information at the right time. Let's explore how to get the most out of the tool!","starts_at":"2026-09-25T12:30:00-07:00","ends_at":"2026-09-25T14:30:00-07:00","stage":"Stage 12","track":"DevEx & Productivity","type":"Workshop","live_coding":false,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"Attendees should bring their own laptops with Node.js installed. They should also have a GitHub account and download the Copilot CLI.","speakers":["Christopher Harrison - Senior Developer Advocate at GitHub"],"tags":["Agentic AI","Copilot","GitHub"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1201","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1834-agentic-coding-with","urls":[],"flag":null},{"id":1304,"title":"Build a Voice AI Agent with Twilio Agent Connect and Gemini Flash","description":"You will build a working voice AI agent from scratch in under 120 minutes. Using Twilio Agent Connect as the middleware layer and Google Gemini Flash as the LLM, you will write a single message handler and get a real phone call answered by an AI agent. No boilerplate, no glue code — TAC handles WebSockets, webhooks, and conversation routing so you can focus entirely on the agent logic. You will leave with a running local app, a configured Twilio number, and the mental model to extend it with tools, handoffs, and custom personas. Both Python and Node.js paths are supported.","starts_at":"2026-09-25T12:30:00-07:00","ends_at":"2026-09-25T14:30:00-07:00","stage":"Stage 8","track":"AI Agents","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"Accounts (create before arriving):\r\n- Twilio account — voice-capable phone number, API Key, and API Secret from the Twilio Console\r\n- Google AI Studio account — for a Gemini API key (aistudio.google.com)\r\n- ngrok account — free tier works; needed to expose localhost to Twilio\r\n\r\nLocal Tools:\r\n- Python 3.10+ (Python path) or Node.js (Node.js path)\r\n- git\r\n- ngrok CLI installed and authenticated","speakers":["Rishab Kumar - Staff Developer Evangelist AI at Twilio"],"tags":["AI Models","Agentic AI","Gemini","Generative AI (GenAI)"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1304","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1799-build-a-voice-ai","urls":[],"flag":null},{"id":1305,"title":"Agent Speedrun: Idea → Code → Deploy → Observe, Fix → Ship","description":"One agent. Fully deployed to production before the workshop ends. We'll take you from a blank file to a running production agent using Amazon Bedrock AgentCore and Strands Agents, covering the full lifecycle: ideation, coding the agent loop, deploying to serverless infrastructure, wiring up observability, breaking it intentionally, fixing it with tracing data, and shipping the final version.\nBring your laptop and leave with a deployed agent.","starts_at":"2026-09-25T12:30:00-07:00","ends_at":"2026-09-25T14:30:00-07:00","stage":"Stage 10","track":"AI Agents","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"More soon","speakers":["Elizabeth Fuentes Leone - Developer Advocate/SDE, GenAI at AWS","Sandhya Subramani - Senior Developer Advocate at AWS"],"tags":["AWS","Agentic AI","Code Generation","Infrastructure as Code (IaC)","Observability"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1305","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1795-agent-speedrun-idea","urls":[],"flag":null},{"id":1306,"title":"Docker sandboxes: protect your secrets, tokens, and personal data from AI agent mistakes","description":"The number of cyber attacks and security risks related to Coding Agents has sky rocketed. AI coding agents like Claude Code, Codex CLI, and Gemini CLI don’t behave like your typical developer tools. They install system packages, modify configurations, delete files, run services, and even spin up Docker containers, often requiring constant permission prompts or risky access to your host machine.\n\nThis talk explores Docker Sandboxes as a new execution model for autonomous coding agents. Built on microVM-based isolation, Docker Sandboxes provide disposable, agent-safe environments where coding agents can run unattended while remaining fully isolated from the host system.\n\nWe’ll walk through why traditional approaches like OS sandboxing, containers, and full virtual machines, break down for agent workflows, and how Docker Sandboxes combine the developer experience of containers with the hard security boundaries of VMs. Using live examples, we’ll show how agents can safely run Docker-in-Docker, install dependencies, access only the project workspace, and be reset instantly.\n\nBy the end of this session, you’ll have a clear mental model for when and how to use Docker Sandboxes to unlock higher levels of agent autonomy without compromising safety, security, or developer experience.","starts_at":"2026-09-25T12:30:00-07:00","ends_at":"2026-09-25T14:30:00-07:00","stage":"Stage 13","track":"Security & Privacy","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":36,"waitlist":5,"requirements":"","speakers":["Kristiyan Velkov - Developer Relations Engineer at Zerops.io"],"tags":["AI Coding Assistants","AI Models","Cloud Security","Docker","Next.js","React","Secure Coding","Security"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1306","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1762-docker-sandboxes","urls":[],"flag":null},{"id":1398,"title":"Iron Designer Challenge with John Romero","description":"How do great ideas survive contact with reality?\n\nIn this fast-paced, highly interactive workshop, John Romero puts participants through a series of creative design challenges built around real-world problems. Working in small teams, participants will invent apps, tools, services, and digital experiences designed to solve specific problems and then adapt those ideas as new constraints, technical limitations, user needs, business pressures, and unexpected complications are introduced.\n\nThe goal is not to arrive at the “right” solution. It is to think creatively under pressure, make decisions quickly, communicate ideas clearly, and keep improving a concept as the problem changes.\n\nTeams will create a solution, change it, change it again, and ultimately pitch their final concept to the room. Along the way, John will draw on decades of experience building games, teams, and technology to challenge assumptions, introduce twists, and explore how creative ideas evolve through iteration.\n\nAt the end, one team will emerge as the Iron Designer (with a certificate to prove it).\n\nNo game development experience is required—just curiosity, imagination, and a willingness to rethink your best idea five minutes after you came up with it.","starts_at":"2026-09-25T12:30:00-07:00","ends_at":"2026-09-25T14:30:00-07:00","stage":"Stage 14","track":"","type":"Workshop","live_coding":false,"is_workshop":true,"capacity":88,"waitlist":10,"requirements":"","speakers":["John Romero at Legendary Game Creator | Father of FPS | DOOM, Quake, Wolfenstein"],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1398","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1953-iron-designer","urls":[],"flag":null},{"id":1309,"title":"From Simulation to Reality: Overcoming the Data Challenge in Physical AI","description":"Internet-scale datasets have successfully driven the evolution of Large Language Models (LLMs) and Vision Language Models (VLMs) across applications like coding assistants and image understanding, Physical AI presents a unique data bottleneck. Physical AI relies heavily on grounded data from sensors, environments, human demonstrations, and real-world simulations. Because this data is often costly, safety-critical, domain-specific, and fragmented, it introduces significant obstacles to model generalization and reliable deployment.\n\nThis talk addresses the core data challenges in Physical AI, including the scarcity of high-quality embodied datasets, the sim-to-real gap, and the difficulty of capturing rare, long-tail physical scenarios. Finally, we will examine how World Foundation Models can be leveraged to scale data generation and overcome these barriers.","starts_at":"2026-09-25T12:55:00-07:00","ends_at":"2026-09-25T13:25:00-07:00","stage":"Stage 1","track":"Physical AI","type":"Physical AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Mitesh Patel - Developer Advocate & Manager at NVIDIA Corporation"],"tags":["Robotics","Synthetic Data"],"live_url":"https://www.youtube.com/watch?v=Z1-KyOPhY7Y","recording_url":"https://www.youtube.com/watch?v=Z1-KyOPhY7Y","app_url":"https://app.wearedevelopers.com/events/18/session/1309","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1787-from-simulation-to","urls":["https://www.youtube.com/watch?v=Z1-KyOPhY7Y"],"flag":null},{"id":1310,"title":"Replay-Safe Architecture: Building Event-Driven Systems That Can Recover With Confidence","description":"Most teams think event-driven reliability means keeping Kafka online, avoiding consumer lag, and making sure messages keep flowing. But in real production systems, the harder question is: can you safely recover when something goes wrong?\n\nThis session explores the architecture patterns behind replay-safe event-driven systems. We will look at how APIs, CDC pipelines, stream processors, consumers, databases, and reconciliation jobs interact when retries, duplicate messages, partial failures, out-of-order events, and historical replays become unavoidable.\n\nThe talk will cover practical design patterns such as idempotency keys, deduplication, event ordering, outbox patterns, replay-safe consumers, audit trails, reconciliation workflows, and operational runbooks. Drawing from real-world experience building high-scale distributed systems and inventory platforms, we will discuss why reliability is not only about uptime. It is about being able to prove what happened, recover safely, and preserve trust in a business-critical state.\n\nAttendees will leave with concrete patterns for building event-driven systems that can survive failure, replay data, and recover without corrupting downstream systems.","starts_at":"2026-09-25T12:55:00-07:00","ends_at":"2026-09-25T13:25:00-07:00","stage":"Stage 3","track":"Architecture & Backend","type":"Architecture & Backend","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ishan Shah - Software Engineer at PayPal"],"tags":["Apache Kafka","Event-Driven Architecture (EDA)","Microservices","Software Architecture"],"live_url":"https://www.youtube.com/watch?v=ZVVMH2ZuIJg","recording_url":"https://www.youtube.com/watch?v=ZVVMH2ZuIJg","app_url":"https://app.wearedevelopers.com/events/18/session/1310","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1754-replay-safe","urls":["https://www.youtube.com/watch?v=ZVVMH2ZuIJg"],"flag":null},{"id":1311,"title":"Not managing your content platform is surrendering your data to someone else.","description":"Content platforms have a new \"job\", ensuring that your data remains yours, is structured and can be verified. Tech meanwhile is the least important part of your strategy. AI and tokens, like software, are a commodity. Therefore you should care about the Why, What and How when you are managing content.It better be good as you’re gonna have to do it anyway. Stating the “obvious” from TYPO3's enterprise CMS perspective.","starts_at":"2026-09-25T12:55:00-07:00","ends_at":"2026-09-25T13:25:00-07:00","stage":"Stage 5","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Daniel Fau - CEO at TYPO3","Tom Warwick - Developer Relations at TYPO3"],"tags":["Governance","Open Source"],"live_url":"https://www.youtube.com/watch?v=94BytknwZCM","recording_url":"https://www.youtube.com/watch?v=94BytknwZCM","app_url":"https://app.wearedevelopers.com/events/18/session/1311","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1802-content-platforms","urls":["https://www.youtube.com/watch?v=94BytknwZCM"],"flag":null},{"id":1313,"title":"Building the AI Era Through Developer Communities: A Competitive Advantage for Engineers & Teams","description":"Artificial intelligence is evolving faster than any individual engineer, or engineering team can keep up alone. The organizations building the next generation of AI products won't simply have the best models; they'll be the teams that learn, adapt, and share knowledge the fastest.\n\nDeveloper communities have evolved far beyond networking events. Today, they serve as distributed knowledge networks where engineers exchange production lessons, validate emerging technologies, explore new AI frameworks, contribute to open source, and bring those insights back into their teams and organizations.\n\nIn this session, I'll share practical lessons from helping grow, lead, and advise one of North America's largest developer meetup communities while engaging with engineers, researchers, founders, and technical leaders across the rapidly evolving AI ecosystem. We'll examine recurring engineering themes shaping modern AI: including agentic AI, open-weight models, AI infrastructure, developer tooling, evaluation, and engineering collaboration and explore how communities accelerate the adoption of these technologies.\n\nAttendees will leave with a practical framework for leveraging developer communities as a strategic advantage: accelerating technical learning, improving engineering collaboration, strengthening innovation, expanding professional networks, and helping both engineers and organizations adapt more quickly in the AI era.","starts_at":"2026-09-25T12:55:00-07:00","ends_at":"2026-09-25T13:25:00-07:00","stage":"Outdoor Stage","track":"Career, Culture & Community","type":"Career, Culture & Community","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["John Komarnicki - National Executive Advisor at Code & Coffee"],"tags":["Agentic AI","Collaboration","Community","DevRel & Advocacy","Future of Work","Generative AI (GenAI)","Innovation","Open Source","People & Culture","Team Building"],"live_url":"https://www.youtube.com/watch?v=7QqQCgI2pZY","recording_url":"https://www.youtube.com/watch?v=7QqQCgI2pZY","app_url":"https://app.wearedevelopers.com/events/18/session/1313","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1748-building-the-ai-era","urls":["https://www.youtube.com/watch?v=7QqQCgI2pZY"],"flag":null},{"id":1314,"title":"It’s Alive! Taming the MLOps Franken-Stack: Write, Run, and Serve with Michelangelo","description":"Deep in enterprise infrastructure, platform engineers often play the mad scientist, stitching together disparate MLOps tools into a terrifying \"Franken-stack\", a fragile ecosystem held together by custom code and vendor lock-in. Let’s move past these infrastructure headaches and look at how Uber open-sourced Michelangelo to bring architectural order to the chaos. This session reveals how the platform anchors a consistent developer experience across the entire ML lifecycle using its three core open-source pillars: Uniflow for pipeline orchestration, the native Job Controller for automated cluster execution, and the Model Serving layer for low-latency inference. Through a live demo, we’ll provide a blueprint to seamlessly swap out your underlying infrastructure components, like shifting compute or orchestrators, without breaking your Python workflow code. Finally, attendees will get an inside look at our local sandbox architecture, allowing developers to safely spin up, experiment with, and master this composable, cloud-native stack on their own hardware.","starts_at":"2026-09-25T13:30:00-07:00","ends_at":"2026-09-25T14:00:00-07:00","stage":"Stage 7","track":"AI Engineering","type":"AI Engineering","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Eric Wang - Sr. Staff Engineer at Uber","Paul Zimmerman - Developer Advocate at Uber"],"tags":["Containers","DevOps","Docker","Fine-Tuning","Infrastructure","LLMOps","Model Training","Open Source"],"live_url":"https://www.youtube.com/watch?v=_H0bFU8zxjU","recording_url":"https://www.youtube.com/watch?v=_H0bFU8zxjU","app_url":"https://app.wearedevelopers.com/events/18/session/1314","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1675-it-s-alive-taming","urls":["https://www.youtube.com/watch?v=_H0bFU8zxjU"],"flag":null},{"id":1315,"title":"A Hands-On Developer Guide to Inference Engineering","description":"Inference engineers solve a multi-dimensional puzzle across latency, throughput, and cost to serve generative AI models. Spanning interdependent layers of the serving stack, from CUDA to runtimes to containers to Kubernetes, inference engineering is the discipline behind scaling AI applications. In this session, we'll cover key inference engineering concepts across both runtime and infrastructure, including topology-aware model parallelism, prefill-decode disaggregated serving, KV-aware routing, autoscaling strategies, and multi-cluster infrastructure management, with a focus on the work required to run multi-trillion-parameter LLMs efficiently in production.","starts_at":"2026-09-25T13:30:00-07:00","ends_at":"2026-09-25T14:00:00-07:00","stage":"Mainstage","track":"AI Models & Infrastructure","type":"AI Models & Infrastructure","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ankit Patel - VP of Developer Ecosystem at NVIDIA","Philip Kiely - Special Projects at Baseten"],"tags":["AI Models","Open Source"],"live_url":"https://www.youtube.com/watch?v=huseaMmTpB4","recording_url":"https://www.youtube.com/watch?v=huseaMmTpB4","app_url":"https://app.wearedevelopers.com/events/18/session/1315","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1771-a-hands-on-developer","urls":["https://www.youtube.com/watch?v=huseaMmTpB4"],"flag":null},{"id":1316,"title":"Defending at Machine Speed","description":"AI is now on both sides of the security equation. Attackers use it to find vulnerabilities, write exploits, and scale campaigns. Defenders use it to hunt threats, review code, and cut incident response from days to minutes. Meanwhile the surface to defend is exploding: more code shipped faster, much of it written by machines. But speed alone is not defense: machines that act in milliseconds can also be wrong in milliseconds, and someone still has to decide what gets automated and what does not. Where AI is genuinely winning for defenders, where it still fails, and what it takes to stay ahead.","starts_at":"2026-09-25T13:30:00-07:00","ends_at":"2026-09-25T14:00:00-07:00","stage":"Tech Leaders Stage","track":"AI Trust & Safety","type":"AI Trust & Safety","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Eli-Shaoul Khedouri - CEO at Intuition Machines","Manfred Moser - Senior Principal DevRel Engineer at Chainguard","Brian Fox - CTO & Co-founder at Sonatype"],"tags":[],"live_url":"https://www.youtube.com/watch?v=PM8SuO0l3Kg","recording_url":"https://www.youtube.com/watch?v=PM8SuO0l3Kg","app_url":"https://app.wearedevelopers.com/events/18/session/1316","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1845-defending-at-machine","urls":["https://www.youtube.com/watch?v=PM8SuO0l3Kg"],"flag":null},{"id":1317,"title":"The State of Local AI in 2026","description":"Cloud companies spent years getting enterprise to go off-premise; now we're going to spend years getting them to go on-premise. This talk provides a practical snapshot of the local AI landscape and what building with on-device AI means for developers in 2026. \n\nWe'll survey the current ecosystem, from open-weight models and model architectures to runtimes, inference engines, quantization techniques, and deployment options. We'll compare today's leading on-device models, discuss which workloads are best suited for local inference, and examine how developers are combining local and cloud models into hybrid systems.\n\nWe'll also explore the broader trends shaping the ecosystem: the rise of open weights, improvements in model quality and efficiency, and the growing importance of AI sovereignty. We'll also discuss where local AI still falls short, including hardware constraints, operational complexity, and the workloads where cloud inference continues to be the better choice.\n\nWhether participants are early in their exploration of local models or already deeply embedded with on-device AI, this session will provide an up-to-date map of the ecosystem, explain the major technologies driving it forward, and offer practical guidance for choosing the right tools and architectures for their next project.","starts_at":"2026-09-25T13:30:00-07:00","ends_at":"2026-09-25T14:00:00-07:00","stage":"Stage 1","track":"AI Models & Infrastructure","type":"AI Models & Infrastructure","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Kirah Sapong - Co-founder & CTO at Aquaduck AI"],"tags":["AI Models","Agents","Edge AI","Large Language Models (LLMs)","Small Language Models (SLMs)"],"live_url":"https://www.youtube.com/watch?v=-poClIxLwL8","recording_url":"https://www.youtube.com/watch?v=-poClIxLwL8","app_url":"https://app.wearedevelopers.com/events/18/session/1317","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1749-the-state-of-local","urls":["https://www.youtube.com/watch?v=-poClIxLwL8"],"flag":null},{"id":1318,"title":"Bluesky's Open Source Moderation Tools: LLM-based Event Detection in Python","description":"Bluesky is a decentralized social media application built on top of the AT Protocol. One way that Bluesky supports decentralization, and empowers users in the Atmosphere community to run their own unique AT apps, is through open source moderation tools. We do this through our Jetstream, which lets you stream AT protocol data collections into any other application or interface. The goal is to get records off the network and in front of automated rules and human reviewers, with no glue service in the middle. \n\nFor example, our moderation stack consists of Osprey, an event stream decisions engine and analysis UI designed to investigate and take automatic action, and Ozone, a web frontend for making moderation decisions. Osprey is written in Python, and was designed and open sourced in collaboration with Discord. Osprey evaluates events using structured logic, user-defined functions, and external signals to assign labels, verdicts, and actions. Some of these, such as our Toxrank model for toxicity detection, make use of fine-tuned LLMs and other classifiers that expose their own web endpoints to Osprey. We also utilize image OCR and hashing to create actionable moderation metadata, which can be automatically actioned, surfaced to moderators via Ozone, and in turn helps shape our Discover feed algorithms.\n\nAlthough some of our internal heuristics are private, Osprey and Ozone are designed to be deployed and run by other app hosts with their own custom rules and moderation practices, whether they are reimplementing the Bluesky data model and feature set or running a different kind of Atmosphere app with a different set of content. In this talk, you’ll see a demo of the Jetstream, Osprey, and Ozone, learn about our rules engine and other architectural features, and leave with enough knowledge to integrate our open source moderation tools into your own stack.","starts_at":"2026-09-25T13:30:00-07:00","ends_at":"2026-09-25T14:00:00-07:00","stage":"Stage 2","track":"AI Trust & Safety","type":"AI Trust & Safety","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Alex Garnett - Developer Relations at Bluesky"],"tags":["AI Models","AI Standards","Python"],"live_url":"https://www.youtube.com/watch?v=oXpCoI8vhF4","recording_url":"https://www.youtube.com/watch?v=oXpCoI8vhF4","app_url":"https://app.wearedevelopers.com/events/18/session/1318","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1405-bluesky-s-open","urls":["https://www.youtube.com/watch?v=oXpCoI8vhF4"],"flag":null},{"id":1319,"title":"Lessons from 20 Years of Bootstrapping an Open Source Business to $50M+","description":"Building a successful open source company without venture capital is rare - scaling it past $50M in revenue is even rarer. This talk distills two decades of hands-on experience growing and sustaining a commercial open source business from zero to global scale.\nWe will share the real strategies that worked - navigating product-market fit, monetizing open source while keeping the core free, building a distributed team long before remote work was mainstream, and developing a repeatable go-to-market engine without external funding. We’ll also explore what didn’t work, the pitfalls we hit along the way, and the lessons learned from building a business that competed against well-funded alternatives.\nWhether you’re a founder, engineer, community leader, or simply curious about the business side of open source, you’ll walk away with practical insights, battle-tested frameworks, and a clearer understanding of how to build and scale an open source company the hard way - by bootstrapping.","starts_at":"2026-09-25T13:30:00-07:00","ends_at":"2026-09-25T14:00:00-07:00","stage":"Stage 3","track":"Leadership & Strategy","type":"Leadership & Strategy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Peter Farkas - CEO at Percona"],"tags":["Data","Open Source"],"live_url":"https://www.youtube.com/watch?v=rCOYGxu39eg","recording_url":"https://www.youtube.com/watch?v=rCOYGxu39eg","app_url":"https://app.wearedevelopers.com/events/18/session/1319","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1731-lessons-from-20","urls":["https://www.youtube.com/watch?v=rCOYGxu39eg"],"flag":null},{"id":1320,"title":"From Model Selection to Smart Routing: How to Use the Right LLM for Every Task","description":"No single AI model is best at everything. The challenge is knowing which model to use, how to measure whether it is good enough, and how to control cost as agents move across different tasks.\nYou'll learn how to:\nCompare proprietary, open-weight, and fine-tuned models for different workloads\nEvaluate models on quality, latency, and cost using LLM judges\nUse Smart Routing to automatically match tasks and agent subtasks to the right model\nGovern agent workflows with policies, token limits, and spending controls\nThis session includes practical demos of model evaluation, Smart Routing, and agent cost controls with the open-source tools Omnigent and MLflow.\nWhether you're building AI applications or coding agents, you'll leave with a practical framework for choosing, evaluating, and governing models without sacrificing quality.","starts_at":"2026-09-25T13:30:00-07:00","ends_at":"2026-09-25T14:00:00-07:00","stage":"Stage 4","track":"AI Models & Infrastructure","type":"AI Models & Infrastructure","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Viktoria Semaan - Principal Technical Evangelist at Databricks"],"tags":["AI Coding Assistants","Anthropic","Claude","Databricks"],"live_url":"https://www.youtube.com/watch?v=m1Ohzxp22a4","recording_url":"https://www.youtube.com/watch?v=m1Ohzxp22a4","app_url":"https://app.wearedevelopers.com/events/18/session/1320","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1433-from-model-selection","urls":["https://www.youtube.com/watch?v=m1Ohzxp22a4"],"flag":null},{"id":1321,"title":"The Autonomous Pull Request: Let Agents Ship Without Surrendering Control","description":"The next productivity leap is not faster code completion; it is a pull request that can move from task to merge without constant human babysitting. This session presents a controlled autonomous workflow using GitHub Copilot app Agent Merge and a real application repository. We will demo an agent implementing a change, following repository-specific operating rules, responding to Copilot review, and waiting while GitHub independently evaluates the result. Secret push protection, code and dependency scanning, CodeQL, quality analysis, strict branch freshness, native C++ tests, and the .NET suite form a set of non-negotiable gates. Only after that evidence is green can Agent Merge complete the workflow. We will close with a clear division of responsibility: agents handle implementation and routine remediation, automated policy establishes baseline confidence, and humans focus their limited review time on intent, UX, architecture, and exceptional risk.","starts_at":"2026-09-25T13:30:00-07:00","ends_at":"2026-09-25T14:00:00-07:00","stage":"Stage 6","track":"AI Agents","type":"AI Agents","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Sam Jarvinen - Senior Solutions Engineer at GitHub"],"tags":["Agents","Agentic AI","C++","Code Reviews","Copilot","GitHub",".NET","Quality Assurance (QA)","Secure Coding","Security"],"live_url":"https://www.youtube.com/watch?v=FcXEMLngsN0","recording_url":"https://www.youtube.com/watch?v=FcXEMLngsN0","app_url":"https://app.wearedevelopers.com/events/18/session/1321","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1791-the-autonomous-pull","urls":["https://www.youtube.com/watch?v=FcXEMLngsN0"],"flag":null},{"id":1323,"title":"The Geometry of Incidents: What User-Impact Shapes Reveal About Platform Architecture","description":"Incidents are usually reviewed as timelines: what failed, who owned it, and how we restored service. That works well for understanding a single outage. But when you operate platforms used by many services, the root causes change while the user-impact patterns start to look familiar.\n\nThis talk introduces incident shapes: a way to look at failures by the pattern they draw across impact, time, and blast radius. I’ll use a few public incidents as reference points, including CrowdStrike’s outage, AWS’s DynamoDB outage where retry amplification played a role, Cloudflare’s WAF incident, and GitHub’s 2018 database failover incident.\n\nThe incident shapes are useful because they change the questions we ask. A sudden spike makes us look at rollout containment and rollback paths. A slow burn pushes us to examine saturation, queues, and retries. A repeating sawtooth suggests the system may be recovering temporarily without becoming stable. Fan-out patterns expose the risk of shared platform layers. Boundary shifts are often the hardest to catch: one layer reports success, while users are still having a bad experience.\n\nThe main idea is simple: the shape of user impact can tell us what the what the architecture failed to protect against. Attendees will learn how to quantify impact using breadth, depth, and duration, and how to connect those shapes to engineering responses such as staged rollouts, rollback automation, retry budgets, semantic canaries, cell isolation, contract checks, and end-to-end verification.\n\nThe goal is to make postmortems more useful: not just to explain what happened, but to help design platforms that are harder to break in the same way twice.","starts_at":"2026-09-25T13:30:00-07:00","ends_at":"2026-09-25T14:00:00-07:00","stage":"Outdoor Stage","track":"DevOps & Platform Engineering","type":"DevOps & Platform Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Bala Subrahmanyam Kambala - Staff Platform Engineer at Oracle"],"tags":["DevOps","Distributed Systems","Infrastructure","Observability","Site Reliability Engineering (SRE)","Software Architecture"],"live_url":"https://www.youtube.com/watch?v=nmi9FRi4u2U","recording_url":"https://www.youtube.com/watch?v=nmi9FRi4u2U","app_url":"https://app.wearedevelopers.com/events/18/session/1323","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1722-the-geometry-of","urls":["https://www.youtube.com/watch?v=nmi9FRi4u2U"],"flag":null},{"id":1394,"title":"I Built My Own AI Wearable (So You Don't Have To — But You'll Want To)","description":"What actually happens between a microphone on your wrist and meeting notes appearing on your phone? In this talk I crack open Biscuit, my homemade AI wearable, streaming audio over BLE to an iOS app, into live transcription with speaker diarization, and finally to an agent that turns every conversation into notes, actions, and even captured slides. Then I'll show you the shortcut: Bee, a production AI wearable with a developer platform, where you can build on the same ambient-agent ideas right away. Firmware to foundation models, there's a layer here for every developer to hack on.","starts_at":"2026-09-25T13:30:00-07:00","ends_at":"2026-09-25T14:00:00-07:00","stage":"Stage 5","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Mike Chambers - Senior AI specialist DA at AWS"],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1394","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1929-i-built-my-own-ai","urls":[],"flag":null},{"id":1325,"title":"Signal Layer: What to Build When Anything Can Be Built","description":"AI has made implementation faster, cheaper, and more widely available. That changes the real bottleneck in software.\n\nEvery team can generate code and spin up agents. The advantage moves to a different layer: knowing what is worth building, who it is for, how people will discover it, and how the product should behave once they do.\n\nThis keynote introduces the system of public signal, user intent, agent experience, distribution loops, and product judgment that helps builders decide what deserves to exist before they commit time, infrastructure, and trust to building it.\n\nWe will look at how AI changes the software lifecycle from “can we build it?” to “should this exist? When anything can be built, the most valuable builders are the ones who can read signal early and shape the right experience.","starts_at":"2026-09-25T14:10:00-07:00","ends_at":"2026-09-25T14:40:00-07:00","stage":"Mainstage","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Lena Hall - Sr. Director Developer Relations at Akamai"],"tags":["AI Models","Agentic AI","Product Strategy"],"live_url":"https://www.youtube.com/watch?v=PirfzzgGRPg","recording_url":"https://www.youtube.com/watch?v=PirfzzgGRPg","app_url":"https://app.wearedevelopers.com/events/18/session/1325","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1884-signal-layer-what-to","urls":["https://www.youtube.com/watch?v=PirfzzgGRPg"],"flag":null},{"id":1326,"title":"The Unit Economics of AI","description":"AI has made software cheap to write and expensive to run. Inference bills grow with usage, GPUs are scarce and priced accordingly, and many teams discovered their unit economics only after the invoice arrived. How companies are getting AI infrastructure costs under control - what actually drives the bill, where the waste hides, and how to run AI at a cost that works.","starts_at":"2026-09-25T14:10:00-07:00","ends_at":"2026-09-25T14:40:00-07:00","stage":"Tech Leaders Stage","track":"Leadership & Strategy","type":"Leadership & Strategy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ed Huang - Co-founder and CTO at PingCAP/TiDB","John Malcolm - Chief Technical Product Officer at Multiverse Computing","Jeremy Murray - Founder & CEO at Stack8s","Aaron Bawcom - Field CTO for Agentic AI at Invisible Technologies","Matt Burns - Director of Editorial at Insight Media Group"],"tags":[],"live_url":"https://www.youtube.com/watch?v=pR3MyKnR0FU","recording_url":"https://www.youtube.com/watch?v=pR3MyKnR0FU","app_url":"https://app.wearedevelopers.com/events/18/session/1326","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1891-the-unit-economics","urls":["https://www.youtube.com/watch?v=pR3MyKnR0FU"],"flag":null},{"id":1327,"title":"The Broken Rung: How AI is Rebuilding Software Development from the Ground Up","description":"The rise of generative AI has created a significant paradox at the core of the software industry. On one side, AI co-pilots are automating entry-level tasks—such as code generation, testing, and boilerplate work—leading to a damaging \"broken first rung\" for recent computer science graduates, with job postings decreasing sharply and requirements for experience increasing. \n\nThis disruption threatens to destroy the crucial talent pipeline needed for future innovation, as senior engineers are not simply born; they are developed through mentorship and hands-on experience that AI is now replacing. At the same time, this powerful technology democratizes development, enabling non-engineers (citizen developers) to build functional applications more quickly than ever before. This rise in easy, low-code/no-code, AI-assisted development presents a strong, deflationary threat to established software companies, service agencies, and the traditional billable-hour model. The key question is: how can organizations capitalize on AI’s undeniable productivity boost without incurring disastrous technical debt, security vulnerabilities, or organizational self-destruction? \n\nThis session will go beyond the hype to present a dual-focused strategic plan, explaining how engineers must shift from being mere coders to architects and how companies should implement strong AI governance frameworks to manage the wave of decentralized code creation—ensuring the future pipeline is reinvented, not replaced.","starts_at":"2026-09-25T14:10:00-07:00","ends_at":"2026-09-25T14:40:00-07:00","stage":"Stage 1","track":"DevEx & Productivity","type":"DevEx & Productivity","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Tomislav Tipurić - CTO & CEO at Nephos"],"tags":["AI Coding Assistants","Agentic AI","Developer Experience (DevEx)","Software Architecture"],"live_url":"https://www.youtube.com/watch?v=lo8MHk8YpbM","recording_url":"https://www.youtube.com/watch?v=lo8MHk8YpbM","app_url":"https://app.wearedevelopers.com/events/18/session/1327","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1744-the-broken-rung-how","urls":["https://www.youtube.com/watch?v=lo8MHk8YpbM"],"flag":null},{"id":1329,"title":"Hacking MSSQL on Cloud. All of them. How I became sysadmin on Azure, AWS, GCP and Alibaba.","description":"It started as a simple security research project on a local SQL Server instance. A single vulnerability led me down a rabbit hole from compromising Azure SQL Database to successfully escalating privileges on GCP CloudSQL for SQL Server, Amazon RDS, and Alibaba ApsaraDB.\n\nIn this session, I’ll walk you through the techniques I used to escalate from a limited user to sysadmin on managed SQL Server platforms offered by the four biggest cloud providers. I’ll also demonstrate post-exploitation techniques, including how I retrieved plaintext [sa] passwords from internal logs and accessed highly sensitive internal metadata.\n\nMore importantly, I’ll share lessons on how these vulnerabilities were possible in the first place and what you, as a developer, DBA, or security professional, can do to secure your applications against similar attack vectors.\n\nFinally, I’ll share how each cloud provider responded to the vulnerabilities I disclosed, the remediation timelines, and the broader lessons this experience teaches us about cloud security.","starts_at":"2026-09-25T14:10:00-07:00","ends_at":"2026-09-25T14:40:00-07:00","stage":"Stage 3","track":"Security & Privacy","type":"Security & Privacy","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Fabiano Amorim - Chief Technology Advisor at PowerTuning"],"tags":["Cloud Security","Data","Microsoft SQL Server","Secure Coding","Security"],"live_url":"https://www.youtube.com/watch?v=vsIcSiyffJA","recording_url":"https://www.youtube.com/watch?v=vsIcSiyffJA","app_url":"https://app.wearedevelopers.com/events/18/session/1329","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1775-hacking-mssql-on","urls":["https://www.youtube.com/watch?v=vsIcSiyffJA"],"flag":null},{"id":1330,"title":"Headroom: A Context Optimization Layer for LLM Applications","description":"Large Language Models are expensive. With context windows expanding to 200K+ tokens, a single API call can cost several dollars—and in production systems handling thousands of requests, these costs compound quickly. Most optimization efforts focus on model selection or prompt engineering, but there's an overlooked dimension: the context itself often contains massive redundancy.\n                                                                                                                                    \nHeadroom is an open-source Python library that sits between your application and your LLM provider, transparently optimizing context before it reaches the model. The core insight is simple: LLM contexts—especially in agentic workflows—are filled with repetitive tool outputs, verbose JSON arrays, and boilerplate that consumes tokens without adding proportional value.\n\nWhat makes Headroom different?\n\nTraditional compression destroys information irreversibly. Headroom introduces CCR (Compress-Cache-Retrieve), a reversible compression architecture.\nThe compression itself is content-aware. Code gets AST-parsed to preserve signatures while compressing function bodies. JSON arrays undergo statistical analysis—we identify outliers, errors, change points, and representative samples rather than blindly truncating. Markdown preserves headers and structure. Each content type gets specialized handling.\n\nReal-world results:                                         \n  - 50-90% token reduction on typical agentic workloads\n  - Drop-in integrations for LangChain, OpenAI, Anthropic, and any OpenAI-compatible provider\n  - Zero code changes required when using the proxy server","starts_at":"2026-09-25T14:10:00-07:00","ends_at":"2026-09-25T14:40:00-07:00","stage":"Stage 4","track":"AI Engineering","type":"AI Engineering","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Devanshi Vyas - Co-founder & CTO at Headroom"],"tags":["AI Coding Assistants","AI Models"],"live_url":"https://www.youtube.com/watch?v=9cEK9oY8XJQ","recording_url":"https://www.youtube.com/watch?v=9cEK9oY8XJQ","app_url":"https://app.wearedevelopers.com/events/18/session/1330","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1419-headroom-a-context","urls":["https://www.youtube.com/watch?v=9cEK9oY8XJQ"],"flag":null},{"id":1331,"title":"AI Builds Confidence, Community Builds Credibility","description":"AI can make anyone feel like a developer. It can't make anyone trusted as one. As AI flattens the skill curve, credibility stops coming from the tool you used and starts coming from the community that vouches for your work. Using SAP's developer ecosystem, from first-time builders to veteran architects, we'll look at what community-built trust looks like in practice, and why it's the one thing AI can't automate.","starts_at":"2026-09-25T14:10:00-07:00","ends_at":"2026-09-25T14:40:00-07:00","stage":"Stage 5","track":"Career, Culture & Community","type":"Career, Culture & Community","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Josh Bentley - Head of Community at SAP"],"tags":["Community"],"live_url":"https://www.youtube.com/watch?v=6Yiowg_QOx4","recording_url":"https://www.youtube.com/watch?v=6Yiowg_QOx4","app_url":"https://app.wearedevelopers.com/events/18/session/1331","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1796-ai-builds-confidence","urls":["https://www.youtube.com/watch?v=6Yiowg_QOx4"],"flag":null},{"id":1332,"title":"Why Your iOS App Feels Broken After an Hour: Diagnosing Long-Session Performance on Real Devices","description":"Most iOS performance testing focuses on short benchmark-style validation such as launch time, API latency, and crash-free startup behavior. In practice, many production failures only emerge after hours of sustained real-world usage. Applications that initially feel smooth gradually degrade due to thermal throttling, memory accumulation, background process contention, frame pacing degradation, and main-thread amplification effects that simulators often fail to reproduce.\n\nThis session explores performance as a systems problem rather than an isolated metric problem. Using a real production case study involving an airline crew application designed to operate during 18-hour flights without WiFi connectivity or server fallback, the talk demonstrates how long-session degradation patterns emerge over time and why traditional benchmarks consistently miss them.\n\nThe session walks through practical techniques for diagnosing sustained performance degradation using Xcode Instruments, including Energy Log, Time Profiler, Leaks, Allocations, Core Animation, and os_signpost instrumentation. Attendees will learn how to instrument warm-start latency, track thermal state transitions, analyze FPS degradation, and correlate performance signals across extended session timelines on physical devices.\n\nThe focus is highly practical and grounded in production engineering experience, providing mobile engineers and performance-focused developers with repeatable approaches for identifying degradation before it becomes user-visible in production systems.","starts_at":"2026-09-25T14:10:00-07:00","ends_at":"2026-09-25T14:40:00-07:00","stage":"Stage 7","track":"Languages, Web & Mobile","type":"Languages, Web & Mobile","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Vasuki Uday Kiran Vudathala - Staff Performance Engineer at ServiceNow"],"tags":["iOS","Observability","Performance","Reliability","Swift","XCode"],"live_url":"https://www.youtube.com/watch?v=ur8UVz1grAQ","recording_url":"https://www.youtube.com/watch?v=ur8UVz1grAQ","app_url":"https://app.wearedevelopers.com/events/18/session/1332","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1760-why-your-ios-app","urls":["https://www.youtube.com/watch?v=ur8UVz1grAQ"],"flag":null},{"id":1333,"title":"Who Did the Work?","description":"In four years you will have nobody to promote. You will think you hired wrong. You hired fine.\nPeople move up because someone with power watched them do good work and put their own name on them. That is a sponsor. A mentor tells you how they did it. A coach asks you questions. A sponsor has to have seen the work.\nThe machine now does the work people used to be seen doing. The first draft. The sorting. The clean-up. The chart somebody used to stand up and explain. The work still gets done. Nobody watches a person do it. In a few years your review board sits down and nobody can say \"I watched her do that.\"\nI sat on the boards at IBM that decide who moves up. I stood in front of eighteen men and two women to get my own appointment, and I stayed long enough to help make that room ten and ten. What carries a person through is one other person in the room who has watched them work.\nI also still write code. Last month something I built could not reach the database, so it made up the log file, made up the rows in it, and told me the connection was fine. Same problem as the empty review board. Nobody can tell who did what. Both need the same fix: a record you can follow backwards until you reach a person.\nThe rest is how to run a place where people and machines both work and only one can be blamed.\n-Keeping a person's name on their work after the machine writes the first version\n-Deciding where someone belongs from what they have already built\n-The bottom rung of the ladder, which is the one the machine took\n-Who signs. A machine can do the task. It cannot sign for it.\n-Small words. If your leaders can only explain this in big ones, they do not have it yet.\nI have done this for hundreds of people, probably more than a thousand. I told them what I could see they were good at, and that they were good enough to go get it. Most of them believed me before they believed themselves. That is the job. The machine cannot do it, and it is about to make it much harder.","starts_at":"2026-09-25T14:10:00-07:00","ends_at":"2026-09-25T14:40:00-07:00","stage":"Outdoor Stage","track":"Leadership & Strategy","type":"Leadership & Strategy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Beth Rudden - CEO & Founder at Bast AI"],"tags":["Digital Transformation","Ethics","People & Culture"],"live_url":"https://www.youtube.com/watch?v=WvoLZTwCwTE","recording_url":"https://www.youtube.com/watch?v=WvoLZTwCwTE","app_url":"https://app.wearedevelopers.com/events/18/session/1333","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1828-who-did-the-work","urls":["https://www.youtube.com/watch?v=WvoLZTwCwTE"],"flag":null},{"id":1324,"title":"On the Public Clock: Open-Source Defense When You're Not in the Club","description":"The time between a vulnerability being found and being exploited has gone negative - see X, LinkedIn, Hacker News, etc. \n\nAI models now surface flaws faster than maintainers can patch them. The industry's answer (some at least) is coordinated, pre-disclosure defense: pool findings, patch under embargo, push mitigations before the bug is public. It works. But it works for the people inside the coalition — the banks, hyperscalers, the vendors who can patch on an attacker's timeline, commercially.\n\nMost of us aren't in that room. We're building, scaling, pivoting, and breaking things at machine speed. Our priorities are different, but security affects us, no less than the big guys.  I call it \"the middle: small security teams, heavy open-source dependencies, no seat at the embargo table\" aka most of us. We inherit the same risk on the public side of disclosure — and we're not idle about it.\n\nThis talk is about what coordination looks like from down here. Not a poorer copy of the embargo club — an open response commons: when a disclosure drops, a mitigation gets generated once and propagates across the enforcement points teams already run, at machine speed, instead of every shop reinventing it alone.\n\nI'll show an early, working v0 built with security partners who aren't limited to being conventional, and make the case for what we build next. I don't have all the answers, I'm just a guy trying to solve some problems. This is an invitation to contribute.","starts_at":"2026-09-25T14:50:00-07:00","ends_at":"2026-09-25T15:20:00-07:00","stage":"Stage 8","track":"Security & Privacy","type":"Security & Privacy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Nicholas Muy - VP Engineering Platform & Security at Scrut Automation"],"tags":["AI Models","Cloud Security","DevOps","DevSecOps","Infrastructure","Open Source","OWASP","Secure Coding","Security","Threat Modelling"],"live_url":"https://www.youtube.com/watch?v=jKeqcnsvg6k","recording_url":"https://www.youtube.com/watch?v=jKeqcnsvg6k","app_url":"https://app.wearedevelopers.com/events/18/session/1324","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1683-on-the-public-clock","urls":["https://www.youtube.com/watch?v=jKeqcnsvg6k"],"flag":null},{"id":1335,"title":"Winning With AI","description":"The gap between companies that use AI and companies that win with it keeps widening - and the technology is not what separates them. Models, tools, and infrastructure are available to everyone; what can't be bought is the judgment on top: where AI should change the business first, how big to bet and when, how to lead an organization through the change, and when to walk away from what isn't working. What the winners do differently across strategy, product, and people - and the expensive lessons behind it.","starts_at":"2026-09-25T14:50:00-07:00","ends_at":"2026-09-25T15:20:00-07:00","stage":"Mainstage","track":"Leadership & Strategy","type":"Leadership & Strategy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Neel Sundaresan - General Manager AI Products/Productivity Tools at IBM","Wolfgang Platz - Founder & CEO at Tricentis, Katharo Ventures","Rahul Deshpande - EVP Global Head of Research and Development at Mastercard","Felix Holtermann - US Bureau Chief at Handelsblatt"],"tags":[],"live_url":"https://www.youtube.com/watch?v=seICJ0tv8X0","recording_url":"https://www.youtube.com/watch?v=seICJ0tv8X0","app_url":"https://app.wearedevelopers.com/events/18/session/1335","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1898-winning-with-ai","urls":["https://www.youtube.com/watch?v=seICJ0tv8X0"],"flag":null},{"id":1336,"title":"Keeping Code Quality at AI Speed","description":"AI has multiplied the volume of code teams ship, and with it the volume they have to review, test, and trust. The safety net is under strain: review queues overflow, test suites lag behind generated code, and rollbacks happen in production instead of staging. How engineering teams are rebuilding the release pipeline - review, testing, progressive delivery - to ship at AI speed without breaking things.","starts_at":"2026-09-25T14:50:00-07:00","ends_at":"2026-09-25T15:20:00-07:00","stage":"Tech Leaders Stage","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Daksh Gupta - Co-founder & CEO at Greptile","Arthur Hicken - Chief Evangelist at Parasoft","Jack Danger - VP of Platform Engineering at LaunchDarkly","Francesco Ciulla - Head of DevRel at Zerops"],"tags":[],"live_url":"https://www.youtube.com/watch?v=3_8AF03VQ7A","recording_url":"https://www.youtube.com/watch?v=3_8AF03VQ7A","app_url":"https://app.wearedevelopers.com/events/18/session/1336","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1860-keeping-code-quality","urls":["https://www.youtube.com/watch?v=3_8AF03VQ7A"],"flag":null},{"id":1337,"title":"State of the Software Factory","description":"While the \"do you have to read the code\" debate rages on, we've been hard at work figuring out how to get models to write code that gets better over time, not worse. We'll discuss why current model training approaches and benchmarks checking \"do the tests pass\" are not enough, and how we're approaching evaluating the long-term-quality of LLM-generated code.","starts_at":"2026-09-25T14:50:00-07:00","ends_at":"2026-09-25T15:20:00-07:00","stage":"Stage 2","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Dexter Horthy - Co-Founder at HumanLayer"],"tags":["AI Coding Assistants","Developer Experience (DevEx)","Software Architecture"],"live_url":"https://www.youtube.com/watch?v=ukmUTrLldP4","recording_url":"https://www.youtube.com/watch?v=ukmUTrLldP4","app_url":"https://app.wearedevelopers.com/events/18/session/1337","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1742-there-s-no-dark","urls":["https://www.youtube.com/watch?v=ukmUTrLldP4"],"flag":null},{"id":1340,"title":"Intelligence in Motion: Building the Next Generation of AI-Powered Apps on Zoom's Developer Platform","description":"The AI landscape is moving fast — and developers are at the center of it. But building intelligent applications today means more than calling an LLM. It means connecting AI to real-time context, deploying at enterprise scale, and reaching users where they already work.\n\nIn this session, Brendan Ittelson, Head of Developer Ecosystem at Zoom, will show how Zoom has evolved from a communications platform into a full-stack developer platform — and how developers can tap into the same production-grade AI infrastructure that powers Zoom's own products, now available as APIs.\n\nYou'll hear how Zoom thinks about the developer ecosystem as a city: interconnected infrastructure where intelligence moves across apps, users, and surfaces — not locked inside a single product. And you'll see how Zoom AI Services (ZAS) — built on models running at scale across hundreds of millions of meetings — gives developers a shortcut to enterprise-grade speech, language, and conversational intelligence without stitching together five vendors.\n\nWhether you're building AI agents, voice-enabled apps, contact center tooling, or agentic workflows, this session will give you a concrete picture of what's possible — and what's available to build with today.","starts_at":"2026-09-25T14:50:00-07:00","ends_at":"2026-09-25T15:20:00-07:00","stage":"Stage 4","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Brendan Ittelson - Chief Ecosystem Officer at Zoom"],"tags":[],"live_url":"https://www.youtube.com/watch?v=EM-tAYvf5G8","recording_url":"https://www.youtube.com/watch?v=EM-tAYvf5G8","app_url":"https://app.wearedevelopers.com/events/18/session/1340","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1780-intelligence-in","urls":["https://www.youtube.com/watch?v=EM-tAYvf5G8"],"flag":null},{"id":1341,"title":"Agents Have a Perception Problem","description":"Why the next generation of agentic AI needs senses.\n\nAgents can read the web, write code, and call tools like APIs and CLIs, but they can't see a factory floor or hear a failing motor. Edge AI closes that gap: small, specialist models that turn messy real-world signals into structured events agents can act on. This talk lays out the sensor-to-agent architecture, shares lessons from real deployments, and shows where the interesting problems live once agents get eyes, ears, and hands.","starts_at":"2026-09-25T14:50:00-07:00","ends_at":"2026-09-25T15:20:00-07:00","stage":"Stage 5","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ivan Sekyonda - Developer Relations Engineer at Edge Impulse"],"tags":["Agents","Agentic AI","Edge AI","Internet of Things (IoT)"],"live_url":"https://www.youtube.com/watch?v=bQ9qMxXEYWY","recording_url":"https://www.youtube.com/watch?v=bQ9qMxXEYWY","app_url":"https://app.wearedevelopers.com/events/18/session/1341","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1785-agents-have-a","urls":["https://www.youtube.com/watch?v=bQ9qMxXEYWY"],"flag":null},{"id":1342,"title":"Look What Java Can Do Now: Live-Coding a GenAI MCP Server with the JAQ Stack","description":"For years, a common bias has held that serious AI development is best left to other ecosystems. This session is here to change that perspective with a live, hands-on demonstration. It’s time to show the world what enterprise Java can really do in the age of AI.\n\nWith the release of Helidon MCP, it allowed us to explore and challenge this old narrative. We can now build high-performance, GenAI-native MicroProfile (MCP) servers from scratch. This is a \"fresh perspective\" on modern Java, proving that you can build secure, powerful, and scalable AI applications entirely within the JVM ecosystem you already know and trust.\n\nThis session introduces the JAQ Stack, a novel technology pattern for this new reality:\nJ (Java/Helidon MCP): We’ll use Helidon to build a blazing-fast, lightweight, and cloud-native server, perfect for handling enterprise workloads.\n\nA (AI/Ollama): We'll integrate a local LLM via Ollama, solving one of the biggest real world enterprise problems: 100% data privacy and security.\n\nQ (Query/LangChain4j): We'll use this powerful Java-native library to build a sophisticated RAG (Retrieval-Augmented Generation) pipeline and orchestrate our AI logic.\n\nThis is not a slide heavy talk. This is a dynamic, live coding session, delivering deep technical insights for developers. Attendees will see, step-by-step, how to solve a common business problem with a 100% Java-native stack. And because the JAQ Stack is batteries included and comes with pre-built applications, they'll leave with a blueprint that is incredibly easy to get started with.","starts_at":"2026-09-25T14:50:00-07:00","ends_at":"2026-09-25T15:20:00-07:00","stage":"Stage 6","track":"Languages, Web & Mobile","type":"Languages, Web & Mobile","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Suren Konathala - Digital Platforms Capability Lead at Microsoft"],"tags":["AGI (Artificial General Intelligence)","APIs","Angular","Cross-Platform","Developer Experience (DevEx)","Future of Work","Innovation","Java","LangChain","Ollama","Productivity","Tooling"],"live_url":"https://www.youtube.com/watch?v=eipxvrkLcn0","recording_url":"https://www.youtube.com/watch?v=eipxvrkLcn0","app_url":"https://app.wearedevelopers.com/events/18/session/1342","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1421-look-what-java-can","urls":["https://www.youtube.com/watch?v=eipxvrkLcn0"],"flag":"No longer listed in the latest schedule"},{"id":1343,"title":"The $0.15/month Algo-Trader: Architecting High-Performance Serverless Trading Engines","description":"In the high-stakes world of algorithmic trading, infrastructure costs and execution latency are the primary enemies of alpha. But what if you could run a production-grade, event-driven trading engine for less than the cost of a cup of coffee per year?\nThis session explores the architectural blueprint of LambdaForge, an open-source trading platform built entirely on a serverless stack. We will break down how to orchestrate Python microservices, AWS Lambda, and EventBridge to handle real-time market data and execute high-stakes trades with sub-second latency, all while maintaining an operational cost of ~$0.15/month.","starts_at":"2026-09-25T14:50:00-07:00","ends_at":"2026-09-25T15:20:00-07:00","stage":"Stage 7","track":"Architecture & Backend","type":"Architecture & Backend","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Vishwak Thatikonda - Lead Full Stack Engineer at SDH Systems"],"tags":["APIs","AWS","AWS Lambda","Agents","Claude","Python"],"live_url":"https://www.youtube.com/watch?v=2Ga3k91z8BU","recording_url":"https://www.youtube.com/watch?v=2Ga3k91z8BU","app_url":"https://app.wearedevelopers.com/events/18/session/1343","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1673-the-0-15-month-algo","urls":["https://www.youtube.com/watch?v=2Ga3k91z8BU"],"flag":null},{"id":1344,"title":"Your Brain Is Lying to You: Cognitive Biases in Development","description":"We like to think our decisions are logical. But they’re often not.\nCognitive biases can trick us into choosing the wrong solution, underestimating complexity, or overestimating our abilities. In this talk, we’ll uncover the most common mental shortcuts developers fall into and how they impact real engineering work.\nBy recognizing these patterns, you’ll be able to make clearer decisions, avoid subtle pitfalls, and build better software.","starts_at":"2026-09-25T14:50:00-07:00","ends_at":"2026-09-25T15:20:00-07:00","stage":"Outdoor Stage","track":"Career, Culture & Community","type":"Career, Culture & Community","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Kate Astrid - Sr. Product Engineer at Cogram"],"tags":["Developer Experience (DevEx)","People & Culture"],"live_url":"https://www.youtube.com/watch?v=NoyJm37VoJs","recording_url":"https://www.youtube.com/watch?v=NoyJm37VoJs","app_url":"https://app.wearedevelopers.com/events/18/session/1344","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1711-your-brain-is-lying","urls":["https://www.youtube.com/watch?v=NoyJm37VoJs"],"flag":null},{"id":1395,"title":"Legacy as a Launchpad: How Yahoo Mail is Undergoing a Product and Engineering Transformation","description":"How does an internet “OG” reinvent its product for the AI era? Yahoo Mail SVP of Engineering, Nikhil Gandhi, shares the behind the scenes story of modernizing  an iconic legacy platform that serves hundreds of millions of users across the world. Join this fireside chat to understand how Yahoo Mail is bringing on top product and engineering talent to tackle unique, high-level technical challenges. From tackling a historic, 500 petabyte cloud migration to solving system-design and scale problems, learn what it truly takes to engineer solutions at a complex scale.","starts_at":"2026-09-25T14:50:00-07:00","ends_at":"2026-09-25T15:20:00-07:00","stage":"Stage 1","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Nikhil Gandhi - SVP of Engineering at Yahoo Mail"],"tags":["Digital Transformation","Generative AI (GenAI)","Legacy","Scaling","Software Architecture","System Design"],"live_url":"https://www.youtube.com/watch?v=B5Pifk4BKMw","recording_url":"https://www.youtube.com/watch?v=B5Pifk4BKMw","app_url":"https://app.wearedevelopers.com/events/18/session/1395","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1933-legacy-as-a","urls":["https://www.youtube.com/watch?v=B5Pifk4BKMw"],"flag":null},{"id":1396,"title":"We Need Art for AI Safety","description":"Inside scoop on the viral Misalignment AI Museum that has unified founders and researchers from competing labs, politicians, world leaders, farmers, parents, students and people from all walks of life. Why art is a powerful and important medium to lead AI Safety conversations, and an exploration into the ways movement shifting art is predicated on technology.","starts_at":"2026-09-25T14:50:00-07:00","ends_at":"2026-09-25T15:20:00-07:00","stage":"Stage 3","track":"AI Trust & Safety","type":"AI Trust & Safety","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Audrey Kim - Founder & curator at Misalignment Museum"],"tags":["Accessibility","Advocacy","Collaboration","Community","Open Source","Safety"],"live_url":"https://www.youtube.com/watch?v=Tqw0_7-h48M","recording_url":"https://www.youtube.com/watch?v=Tqw0_7-h48M","app_url":"https://app.wearedevelopers.com/events/18/session/1396","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions","urls":["https://www.youtube.com/watch?v=Tqw0_7-h48M"],"flag":null},{"id":1345,"title":"The AI Dependency Challenge: Your AI coding assistant is making dependency decisions. Who’s checking","description":"AI coding assistants and agents are helping developers move faster, but they can also create more dependency work: outdated packages, poor upgrade paths, broken builds, and remediation tasks that land back on engineering teams.\nIn this hands-on session, you’ll connect Sonatype Guide to AI coding assistants through MCP for tools like Claude, Cursor, and Copilot, then see how trusted open source intelligence helps developers and AI agents choose better packages as they build. You’ll explore how Guide surfaces dependency health, quality, and upgrade guidance through the tools developers already use, and see how Agent P automates dependency remediation by applying and validating upgrades in connected repositories.\nLeave with practical experience using Sonatype Guide to reduce dependency maintenance, avoid breaking-change rework, and help humans and AI agents build faster with more confidence.","starts_at":"2026-09-25T15:00:00-07:00","ends_at":"2026-09-25T17:00:00-07:00","stage":"Stage 10","track":"DevEx & Productivity","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"Full end to end set up in the workshop","speakers":["Meredith Eisen - Sr. Director of Product Management at Sonatype","Vince Hinojosa - Principal Solution Architect at Sonatype"],"tags":["AI Coding Assistants","AI Models","Anthropic","AppSec","AWS","Agentic AI","Automation","CI/CD","Claude","Copilot","Cursor","DevSecOps","Governance","Open Source","Vibe Coding","Workflow Automation"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1345","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1886-the-ai-dependency","urls":[],"flag":null},{"id":1346,"title":"Attacking LLM Detectors with Homoglyph-Based Attacks","description":"This session explores an attack vector, homoglyph-based attacks, that effectively evades state-of-the-art AI-generated text detectors.\n\nWe'll begin by explaining the idea behind homoglyphs, characters that look similar but are encoded differently. You'll learn how these can be used to manipulate tokenization and evade detection systems. We'll cover the mechanisms of how homoglyphs alter text representation, discuss their impact on existing LLM detectors, present a comprehensive evaluation of their effectiveness against various detection methods, and see how we can protect detectors against these attacks.\n\nJoin us for an immersive exploration and stay ahead of evolving threats!","starts_at":"2026-09-25T15:00:00-07:00","ends_at":"2026-09-25T17:00:00-07:00","stage":"Stage 13","track":"AI Trust & Safety","type":"Workshop","live_coding":true,"is_workshop":true,"capacity":36,"waitlist":5,"requirements":"","speakers":["Aldan Creo - AI and NLP Researcher at UC San Diego"],"tags":["AI Models","Generative AI (GenAI)","Safety","Security"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1346","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1949-attacking-llm","urls":[],"flag":null},{"id":1347,"title":"Secure development from pull request to production with GitHub","description":"Security should accelerate development—not become a late-stage gate or a pile of disconnected tools. In this hands-on workshop, you’ll use GitHub’s native DevSecOps capabilities to protect an application throughout its delivery lifecycle: catch leaked secrets before they land, identify vulnerable dependencies and insecure code in pull requests, and harden GitHub Actions with least-privilege permissions and secure cloud identity.\n\nStarting with a deliberately vulnerable sample repository, we’ll detect, remediate, and prevent common issues using GitHub Advanced Security and GitHub Actions. You’ll leave with practical patterns for creating a secure developer workflow that gives teams fast, actionable feedback while producing a more trusted path to production. GitHub’s DevSecOps capabilities support code scanning, secret protection, dependency security, and workflow automation directly in the developer workflow.","starts_at":"2026-09-25T15:00:00-07:00","ends_at":"2026-09-25T17:00:00-07:00","stage":"Stage 12","track":"DevOps & Platform Engineering","type":"Workshop","live_coding":false,"is_workshop":true,"capacity":80,"waitlist":10,"requirements":"Attendee need to bring their own laptop and have a GitHub account.","speakers":["Sam Jarvinen - Senior Solutions Engineer at GitHub"],"tags":["Copilot","GitHub","GitHub Actions","Secure Coding"],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1347","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1881-secure-development","urls":[],"flag":null},{"id":1356,"title":"Offloading IoT State: Solving the Memory Crisis on Legacy Hardware","description":"Every developer working with IoT or Smart TVs has met the ultimate villain: the Out-of-Memory (OOM) killer. As digital commerce grows more complex, we’re asking low-spec hardware, often with less than 1GB of RAM—to juggle massive JSON payloads and multi-step transactional state machines. The result? System stutters, service crashes, and lost revenue.\n\nIn this 10-minute lightning talk, we’ll look at a practical architectural pattern to solve this: The State-Shift. Instead of asking a resource-constrained device to manage complex logic, we migrate the entire transactional state and error-recovery mechanism to a cloud-side \"Stateful BFF\" (Backend-for-Frontend).\n\nWe’ll quickly cover:\n- The \"Thin-Client\" Transformation: How to turn a struggling device into a stateless observer.\n\n- The Double-Handshake: A simple pattern for state recovery after a hard reboot.\n\n- The Results: Real-world metrics showing how this shift can cut heap usage by 35%.\n\nYou’ll walk away with a clear blueprint for extending the life of legacy hardware without sacrificing modern functionality.","starts_at":"2026-09-25T15:30:00-07:00","ends_at":"2026-09-25T15:40:00-07:00","stage":"Outdoor Stage","track":"Physical AI","type":"Physical AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Pravin Nagare - Sr. Software Engineer at Roku"],"tags":["Embedded Systems","Internet of Things (IoT)","Performance"],"live_url":"https://www.youtube.com/watch?v=iiTd9K77geE","recording_url":"https://www.youtube.com/watch?v=iiTd9K77geE","app_url":"https://app.wearedevelopers.com/events/18/session/1356","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1712-offloading-iot-state","urls":["https://www.youtube.com/watch?v=iiTd9K77geE"],"flag":null},{"id":1322,"title":"Agents Can't Iterate Against Tests That Lie","description":"Between February 2025 and February 2026, coding agents went from writing none of Clipboard's code to nearly all of it. That changed our bottleneck. Writing code got cheap, but proving it worked did not.\n\nThe failure mode was not just model quality. It was flaky E2E tests in shared environments that were hard to reproduce. With limited context, agents often reached for the wrong fix: increase the timeout or add a retry.\n\nThis talk is a practical case study in rebuilding trust in tests for AI-heavy engineering organizations. I will show the workflow that helped us reduce the share of PRs affected by E2E flakes from 100% to under 15% in six weeks, including the open source libraries and agent skills we built to classify flaky tests, connect to observability signals, and decide which tests to harden, delete, quarantine, or move down the pyramid.\n\nAttendees will leave with a repeatable playbook for making coding agents safe to use at scale without teaching them that every failing test should be \"fixed\" with retries.","starts_at":"2026-09-25T15:30:00-07:00","ends_at":"2026-09-25T16:00:00-07:00","stage":"Stage 1","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Rocky Warren - Sr. Staff Software Engineer at Clipboard"],"tags":["AI Coding Assistants","CI/CD","E2E Testing","Integration Testing","Observability","Playwright","Productivity","Quality Assurance (QA)","Testing"],"live_url":"https://www.youtube.com/watch?v=xZPx1NBO1dE","recording_url":"https://www.youtube.com/watch?v=xZPx1NBO1dE","app_url":"https://app.wearedevelopers.com/events/18/session/1322","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1700-agents-can-t-iterate","urls":["https://www.youtube.com/watch?v=xZPx1NBO1dE"],"flag":null},{"id":1338,"title":"Point. Ask. Answer. Building Vision into AI on Constrained Hardware","description":"Your Ring camera sees everything. And so does the company behind it.\n\nBut what if you could build your own intelligent camera with a Raspberry Pi, a $10 webcam, and an AI model that actually understands what it sees?\n\nYou still get smart alerts. You can still ask questions about what happened. But there’s no cloud dependency, no subscription, and no footage leaving your device.\n\nYour data. Your hardware. Your rules.\n\nIn this session, we’ll use that idea as a real-world example to look under the hood of local multimodal AI: how vision models understand a scene, how inference runs on constrained hardware, how the system stores and retrieves context, and how these pieces come together to create an intelligent camera experience entirely on-device.","starts_at":"2026-09-25T15:30:00-07:00","ends_at":"2026-09-25T16:00:00-07:00","stage":"Stage 2","track":"Applied AI","type":"Applied AI","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Kavya Sri Chennoju - Staff AI Engineer at Arm"],"tags":["AGI (Artificial General Intelligence)","AI Coding Assistants","AI Models","Anthropic","Mistral","OpenAI"],"live_url":"https://www.youtube.com/watch?v=W4XoucUnzlg","recording_url":"https://www.youtube.com/watch?v=W4XoucUnzlg","app_url":"https://app.wearedevelopers.com/events/18/session/1338","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1733-point-ask-answer","urls":["https://www.youtube.com/watch?v=W4XoucUnzlg"],"flag":null},{"id":1348,"title":"One Boundary for the Agentic Era","description":"This year, an agent carried out an end-to-end attack on real infrastructure, chaining familiar classes of weakness at machine speed. That's the world developers are orchestrating agents in, and orchestration comes with accountability. You've absorbed shift left before; this wave is for how your agents behave. As AI risk becomes enmeshed with supply chain risk, Docker CISO Mark Lechner thinks the answer is a single boundary where agents do their work: isolated execution, trusted content, and controls a security team can verify. Mark’s team is responsible for Docker Hub, which serves billions of pulls a month. In this session he looks at this year's incidents to show what this approach means in practice, and what it changes for defenders. This talk is for anyone who writes code, works with agents, or secures the pipeline they run in. No security background needed.","starts_at":"2026-09-25T15:30:00-07:00","ends_at":"2026-09-25T16:00:00-07:00","stage":"Mainstage","track":"AI Agents","type":"AI Agents","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Mark Lechner - Chief Information Security Officer at Docker"],"tags":["Agents","Agentic AI","Cloud Security","Containers","Governance","Security"],"live_url":"https://www.youtube.com/watch?v=7lR9SUdMHPQ","recording_url":"https://www.youtube.com/watch?v=7lR9SUdMHPQ","app_url":"https://app.wearedevelopers.com/events/18/session/1348","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1871-one-boundary-for-the","urls":["https://www.youtube.com/watch?v=7lR9SUdMHPQ"],"flag":null},{"id":1351,"title":"Earning the Right to Deploy: Netflix's Approach to Deployment Safety at Scale","description":"At some point, all organizations will hit a similar point. A high-risk time frame exists for each org when a single poor deployment can lead to disaster (holiday peak periods, new product launch times, etc.) In many cases, the first response to such situations is to call for a complete deployment lockdown. Freeze everything. Just wait until things are safer. Unfortunately, such freezes cause problems of their own: emergency patches get blocked, panic releases occur prior to the lockdown, engineers begin treating safety gateways like bureaucratic hurdles they need to find ways around.\n\n\nWe posed the question differently. How can we set up our systems so deployments automatically pause at the correct time, and how can we make bypassing eligibility a team-earned privilege rather than simply available to all? This talk is a technical dive into Quiet Period Automatic Protection, the system Netflix developed to replace raw trigger suppression with intelligent, stage-level deployment safety. We will go over how we moved from 'stop the pipeline' to 'pause the right stage at the right time with surgical accuracy'. The presentational topics include how the system determines production impact without requiring manual setup, how it dynamically adds protection to already running deployments, how it will handle multiple-region deployments that may last hours, and how every override is treated as an auditable learning opportunity rather than just a liability.\n\n\nThis architectural shift transforms the mechanism of safety. By mandating a justification for every override, we convert raw bypasses into high-fidelity, auditable learning signals. Monitoring these patterns allows the system to act as a barometer for organizational strain, surfacing latent risks before they manifest as outages. Furthermore, we linked bypass eligibility to proven deployment health metrics, ensuring high-velocity teams maintain autonomy while others remain shielded. This \"safety by default, freedom by merit\" philosophy was battle-tested during our 2025 peak holiday window. I will detail our findings from this high-pressure period, examining where our logic proved resilient and where we recalibrated, demonstrating why designing for dynamic adaptation is superior to static lockdowns.","starts_at":"2026-09-25T15:30:00-07:00","ends_at":"2026-09-25T16:00:00-07:00","stage":"Stage 3","track":"Architecture & Backend","type":"Architecture & Backend","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Viswanathan Ranganathan - Sr. Engineer at Netflix"],"tags":["CI/CD","Internal Platforms"],"live_url":"https://www.youtube.com/watch?v=OGwFg4nZ_P4","recording_url":"https://www.youtube.com/watch?v=OGwFg4nZ_P4","app_url":"https://app.wearedevelopers.com/events/18/session/1351","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1425-earning-the-right-to","urls":["https://www.youtube.com/watch?v=OGwFg4nZ_P4"],"flag":null},{"id":1352,"title":"Evals Are Infra: Building AI Systems Developers Can Actually Trust","description":"AI teams often treat evals as a gate: a benchmark score, a pass/fail dashboard, or one number that decides whether a system ships. That breaks down quickly in production. Users disagree about what \"good\" means, behavior shifts across workflows, and agent failures often hide inside traces, tools, permissions, and human handoffs rather than in the final answer.\n\nThis talk reframes evals as production infrastructure. I will show how developers can move from mystery scores to systems that expose failure modes: plural rubrics for stakeholder disagreement, trace-level observability, human review loops, failure taxonomies, and semantic drift/anomaly detection. The goal is practical: help teams ship AI products developers can debug, operate, and trust.","starts_at":"2026-09-25T15:30:00-07:00","ends_at":"2026-09-25T16:00:00-07:00","stage":"Stage 4","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Phoebe Wang - Member of Technical Staff at OpenAI"],"tags":["Agentic AI","Generative AI (GenAI)","Large Language Models (LLMs)","LLMOps","Observability","Reliability"],"live_url":"https://www.youtube.com/watch?v=r6nlM_DtQm8","recording_url":"https://www.youtube.com/watch?v=r6nlM_DtQm8","app_url":"https://app.wearedevelopers.com/events/18/session/1352","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1701-evals-are-infra","urls":["https://www.youtube.com/watch?v=r6nlM_DtQm8"],"flag":null},{"id":1353,"title":"21 Experiments in Six Weeks: A Playbook for Improving Your AI Agent","description":"Writing the code was the easy part. But setting out to improve Sentry’s AI code review agent meant answering a much harder question: what does it mean to make your agent “better”, and how do you know if it’s working? Over the course of six weeks, our team ran 21 live experiments to find out. Along the way, we built an eval loop that moved from offline datasets and limited observability to A/B testing infrastructure, composite metrics, and detailed cost tracking in a single dashboard. And our most honest signal—whether the developer actually fixed the flagged bug—surfaced results that broke our intuition (like why a smarter model isn’t always the answer) and forced hard tradeoffs between code review quality and cost. In this talk, I’ll walk through the practical playbook for improving your AI agent: how to define “better”, how to measure it, and how to get quality gains without breaking the bank.","starts_at":"2026-09-25T15:30:00-07:00","ends_at":"2026-09-25T16:00:00-07:00","stage":"Stage 5","track":"AI Agents","type":"AI Agents","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Sofia Rest - Software Engineer at Sentry"],"tags":["AI Coding Assistants","Agents","Code Reviews","Sentry"],"live_url":"https://www.youtube.com/watch?v=xDb-tLVpW6E","recording_url":"https://www.youtube.com/watch?v=xDb-tLVpW6E","app_url":"https://app.wearedevelopers.com/events/18/session/1353","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1793-21-experiments-in","urls":["https://www.youtube.com/watch?v=xDb-tLVpW6E"],"flag":null},{"id":1354,"title":"Small LLM in your Browser: Huge Opportunities for Web Applications","description":"Let's see how AI is becoming a first-class citizen in your browser! In this session, I'll show you Chrome’s Built-In AI APIs - now available behind feature flags in regular Chrome and evolving in Canary. From language detection to summarization and even creative writing, these APIs promise to revolutionize how we build web applications.\n\nWhether you're a developer, tech enthusiast, or decision-maker, this talk will equip you with insights and inspiration to stay ahead in the fast-moving AI landscape.","starts_at":"2026-09-25T15:30:00-07:00","ends_at":"2026-09-25T16:00:00-07:00","stage":"Stage 6","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Daniel Ostrovsky - AI Architect at Payoneer"],"tags":["AI Models","AI Standards","Web Standards"],"live_url":"https://www.youtube.com/watch?v=9ujmvALfdO0","recording_url":"https://www.youtube.com/watch?v=9ujmvALfdO0","app_url":"https://app.wearedevelopers.com/events/18/session/1354","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1434-small-llm-in-your","urls":["https://www.youtube.com/watch?v=9ujmvALfdO0"],"flag":null},{"id":1355,"title":"Trust, But Verify: Continuous GPU Validation at Scale","description":"AI infrastructure has long been dominated by a single ecosystem, but the model is changing. In this session, Kyle Bell from TensorWave explores how to build & operate large-scale AI clusters on AMD Instinct GPUs using Kubernetes as the orchestration backbone.\n\nAttendees will learn about:\nAMD-specific technologies like ROCm, GPU Operator, & RVS (ROCm Validation Suite).\nKubernetes integration patterns for AI scheduling, node triage, & GPU telemetry.\nSlurm-on-Kubernetes for HPC-style orchestration, & how it impacts resource management and observability.\nCustom convergence testing & GPU validation pipelines that ensure reliability at scale.\nThis talk provides an open-source roadmap for operators, ML engineers, and platform teams who want to move beyond vendor lock-in while maintaining reliability, performance, & observability at scale.\nViewers will walk away with practical guidance on designing Kubernetes clusters purpose-built for AMD Instinct GPUs, integrating ROCm into existing cloud-native toolchains, applying reliability engineering patterns for AI workloads, & building open sustainable infrastructure that contributes to a more diverse AI hardware ecosystem.","starts_at":"2026-09-25T15:30:00-07:00","ends_at":"2026-09-25T16:00:00-07:00","stage":"Stage 7","track":"AI Models & Infrastructure","type":"AI Models & Infrastructure","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Kyle Bell - VP of AI at TensorWave"],"tags":["Multi-Cloud"],"live_url":"https://www.youtube.com/watch?v=CkpiULeA5iI","recording_url":"https://www.youtube.com/watch?v=CkpiULeA5iI","app_url":"https://app.wearedevelopers.com/events/18/session/1355","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1690-trust-but-verify","urls":["https://www.youtube.com/watch?v=CkpiULeA5iI"],"flag":null},{"id":1399,"title":"Moats, Margins & M&A in the AI Era","description":"Top venture investors, Corporate VCs, and corporate development leaders discuss how AI is reshaping software economics, technical defensibility, and strategic value. The conversation will explore where capital is flowing, which moats can endure as foundation models move up the stack, how margins and return profiles are changing, and what enterprise acquirers actually look for in AI-native platforms. From building category-defining companies to positioning for strategic partnerships or M&A, the panel will examine what it takes to create resilient, scalable, and strategically valuable technology businesses in today’s AI market.","starts_at":"2026-09-25T15:30:00-07:00","ends_at":"2026-09-25T16:00:00-07:00","stage":"Tech Leaders Stage","track":"","type":"Session","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ravi Belani - Chairperson & Founder at Alchemist Accelerator","Dr. Yvonne Lutsch - Investment Director at Lam Capital","Ashish A. - Partner at IronArc Ventures","Becky Flint - Founder & CEO at Dragonboat","Guillaume Decugis - Partner at Data Ventures","Trevor Cox - Partner at i5invest"],"tags":[],"live_url":null,"recording_url":null,"app_url":"https://app.wearedevelopers.com/events/18/session/1399","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1962-moats-margins-m-a-in","urls":[],"flag":null},{"id":1357,"title":"Closing the Visibility Gap: Lessons from Safety Critical Agentic Systems","description":"AI agents are moving to production, revealing a \"visibility gap\" traditional monitoring can’t bridge. This talk shares lessons from shipping agentic AI in safety-critical workflows where agents reason, plan, and execute actions. We’ll explore building observable systems that provide high signal telemetry into non-deterministic decision making.\n\nWe’ll examine production agent architecture, combining LLMs with structured reasoning and guardrails, and how to instrument test time compute to track iterative refinement. The session covers designing interoperable tool interfaces that emit rich execution traces, orchestrating specialized agents with reliable handoffs, and building auto-correction loops that parse feedback to adapt in real-time.\n\nFinally, we address evaluation, why traditional metrics fail and how to design domain aware benchmarks that treat reasoning traces as a first class observability primitive. Drawing from production deployments, we’ll discuss how observability helps agents uncover system issues missed by humans and why the future of software depends on agent native infrastructure.","starts_at":"2026-09-25T15:45:00-07:00","ends_at":"2026-09-25T15:55:00-07:00","stage":"Outdoor Stage","track":"AI Agents","type":"AI Agents","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Vivek Pandit - Frontier AI Lead at Turing"],"tags":["AI Coding Assistants","AI Models","Simulators"],"live_url":"https://www.youtube.com/watch?v=ICCNMM1gPYQ","recording_url":"https://www.youtube.com/watch?v=ICCNMM1gPYQ","app_url":"https://app.wearedevelopers.com/events/18/session/1357","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1408-closing-the","urls":["https://www.youtube.com/watch?v=ICCNMM1gPYQ"],"flag":null},{"id":1358,"title":"public void saveMoney(AI): The Developer's Guide to Unit Economics","description":"We usually treat cloud costs as an infrastructure problem - something to be solved with better budgets or Reserved Instances. But in a world of serverless and containers, your bill is a direct reflection of your code's efficiency. A memory leak isn't just a bug anymore; it’s a monthly recurring expense. A \"chatty\" frontend isn't just slow; it’s a self-inflicted DDoS attack on your own wallet.\nThis lightning talk shifts the FinOps conversation to where costs actually start: the IDE. We’ll trace a single request through a standard GCP stack—from an Angular frontend, through Java services on GKE, and down into Cloud Spanner.\nInstead of high-level theory, we’ll look at the specific code-level anti-patterns that wreck unit economics. You’ll see how \"polite\" frontend code helps GKE bin-packing density, how Java serialization impacts Dataflow costs, and how specific query patterns can quietly destroy a budget. You'll leave with a developer-centric checklist to stop the bleeding in production.","starts_at":"2026-09-25T16:00:00-07:00","ends_at":"2026-09-25T16:10:00-07:00","stage":"Outdoor Stage","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Hrushikesh Pokala - Sr. Software Engineer Lead at Equifax"],"tags":["AI Coding Assistants","AI Models","Agentic AI","Angular","Caching","FinTech","Java","Microfrontends","Vertex AI"],"live_url":"https://www.youtube.com/watch?v=R5aqcHiu3pw","recording_url":"https://www.youtube.com/watch?v=R5aqcHiu3pw","app_url":"https://app.wearedevelopers.com/events/18/session/1358","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1427-public-void","urls":["https://www.youtube.com/watch?v=R5aqcHiu3pw"],"flag":null},{"id":1303,"title":"Designing APIs That Survive AI Agents at Scale","description":"AI agents are now your APIs' biggest, weirdest consumers. They call 100x more often than humans, hallucinate parameters, retry on every ambiguity, fish your schema for tools you did not advertise, and read your error messages as prompts. Most APIs were not designed for this caller. The result in production today: retry storms, tool-spec drift, runaway costs, and audit trails that cannot tell a real user from an agent acting on their behalf.\nThis is a practical, pattern-driven talk for engineers, architects, and platform leads whose APIs are about to be hit, or already are.\n\nI walk through eight patterns that decide whether your API survives agentic traffic:\n\t1. Idempotency that survives non-deterministic callers, not just network retries.\n\t2.Tool-spec design: naming, descriptions, and parameter shapes LLMs do not get wrong.\n\t3.Capability-scoped tokens for agents, instead of broad API keys.\n\t4.Backpressure and adaptive rate limits keyed to agent identity, not just IP.\n\t5.Schema evolution when consumers cannot read changelogs.\n\t6.Error messages as prompts: structured, actionable, safe to feed back to a model.\n\t7.Observability that traces the agent to tool to downstream chain, with agent identity as a first-class span attribute.\n\t8.Cost protection: semantic dedup, response caching, query budgets, and circuit breakers on token spend.\n\nFor each pattern I show the failure in code, the fix, and the operational signal that tells you it is working. Halfway through, I leave the slides for a live walkthrough of a reference API hardened against agent traffic, with a runnable harness that simulates a misbehaving agent so I can break and fix defenses on stage.\n\nThis is not about MCP, AP2, or any specific framework. The patterns hold whether your callers are LangChain or custom orchestrators. If your API will be called by something that is not a human in 2027, this is for you.\n\nYou leave with eight named patterns, working code, and a checklist your team can run on Monday.","starts_at":"2026-09-25T16:10:00-07:00","ends_at":"2026-09-25T16:40:00-07:00","stage":"Stage 6","track":"Architecture & Backend","type":"Architecture & Backend","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Phani Pendurthi - Principal Software Engineer at Mastercard"],"tags":["APIs","Agents","Multi-Agent Systems","Scaling","Software Architecture"],"live_url":"https://www.youtube.com/watch?v=svkkzwKEMbk","recording_url":"https://www.youtube.com/watch?v=svkkzwKEMbk","app_url":"https://app.wearedevelopers.com/events/18/session/1303","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1714-designing-apis-that","urls":["https://www.youtube.com/watch?v=svkkzwKEMbk"],"flag":null},{"id":1334,"title":"Food as Medicine, Code as Prescription: Engineering AI-Driven Nutritional Intervention Systems","description":"What if your grocery cart could become a clinical intervention? This talk presents an AI framework that links retail food purchase data to personalized nutritional recommendations, turning everyday transactions into population health instruments.","starts_at":"2026-09-25T16:10:00-07:00","ends_at":"2026-09-25T16:40:00-07:00","stage":"Stage 5","track":"Applied AI","type":"Applied AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Kapil Poreddy - Sr. Engineering Lead at Walmart Global Tech"],"tags":["Accessibility","Advocacy","AGI (Artificial General Intelligence)","AI Coding Assistants","AI Models","AI Standards"],"live_url":"https://www.youtube.com/watch?v=l-bShUhCR7I","recording_url":"https://www.youtube.com/watch?v=l-bShUhCR7I","app_url":"https://app.wearedevelopers.com/events/18/session/1334","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1685-food-as-medicine","urls":["https://www.youtube.com/watch?v=l-bShUhCR7I"],"flag":null},{"id":1360,"title":"Who Do We Hire Now?","description":"AI now does much of the work junior hires used to learn on, and hiring plans are changing fast: fewer entry-level roles, new skill profiles, and job descriptions rewritten mid-search. The old pipeline - hire juniors, grow seniors - is breaking, and nobody has agreed on what replaces it. How companies are rethinking who they hire, what they train, and where the next generation of senior engineers comes from.","starts_at":"2026-09-25T16:10:00-07:00","ends_at":"2026-09-25T16:40:00-07:00","stage":"Tech Leaders Stage","track":"Career, Culture & Community","type":"Career, Culture & Community","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Chris Daden - CTO & Head of AI at Criteria","Ian Hughson - Global Managing Partner AI Adoption at TCS","Becky Bucich - Chief People Officer at Waymo","Jennifer Serrato - CTO Platform at Workday","Kate Smeaton - Program Manager, AI Transformation at LaunchSquad"],"tags":[],"live_url":"https://www.youtube.com/watch?v=nb4_IEVkxfU","recording_url":"https://www.youtube.com/watch?v=nb4_IEVkxfU","app_url":"https://app.wearedevelopers.com/events/18/session/1360","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1895-who-do-we-hire-now","urls":["https://www.youtube.com/watch?v=nb4_IEVkxfU"],"flag":null},{"id":1361,"title":"The Five Percent Club: The Culture and Technological Shift Behind Successful AI Deployments","description":"95% of AI projects fail. And according to MIT (https://mlq.ai/media/quarterly_decks/v0.1_State_of_AI_in_Business_2025_Report.pdf), the vast majority of AI initiatives never even make it past the prototype stage. In 2026, the problem isn’t a lack of models or ideas (builders have plenty, after all)—it’s a fundamental misunderstanding of what AI is for.\n\nWe’ve all seen the billboards promising that AI will magically evaporate the most complex business problems or seamlessly abstract away entire workforces. It’s a high-priced fantasy. Many organizations treat AI as a \"magic pill\"—a way to bypass the difficult, manual work of evaluating how technology actually supports business growth. They invest in brittle, fragmented stacks of point solutions, chasing automation hype without ever defining a purpose. The result? A graveyard of expensive prototypes that can’t scale, can’t adapt, and eventually, just stop working.\n\nIn this session, Tara Hernandez (VP of Developer Productivity, MongoDB) talks about her work ensuring that MongoDB becomes part of the “5% Club”: the group of organizations who have been able to successfully leverage AI to advance their business. What if the technical stack behind the AI is an implementation detail within a much larger, requisite culture shift?\n\nWe’ll explore why successful AI deployment requires identifying a core business purpose before touching a single line of code, and staying aligned with your business goal as your AI scales. Tara will share how the 5% club align their culture and goals first, and then build a unified data foundation that supports continuous adaptation. You’ll learn why the most critical technical puzzle pieces—retrieval quality, scalability, and grounded context—are the final, critical steps in an AI deployment journey that begins with \"why,\" not \"how\".","starts_at":"2026-09-25T16:10:00-07:00","ends_at":"2026-09-25T16:40:00-07:00","stage":"Stage 3","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Tara Hernandez - VP Developer Productivity at MongoDB"],"tags":["Distributed Systems","Embeddings","Infrastructure","Retrieval-Augmented Generation (RAG)","System Design","Vector Databases"],"live_url":"https://www.youtube.com/watch?v=5JX_yMyhZ2s","recording_url":"https://www.youtube.com/watch?v=5JX_yMyhZ2s","app_url":"https://app.wearedevelopers.com/events/18/session/1361","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1781-the-five-percent","urls":["https://www.youtube.com/watch?v=5JX_yMyhZ2s"],"flag":null},{"id":1364,"title":"Speed up your CI/CD pipelines by caching build & runtime artifacts","description":"Slow CI/CD pipelines delay code from reaching production and frustrate development teams. Beyond testing and compilation, a major bottleneck comes from repeatedly fetching dependencies from remote artifact repositories, a slowdown that also affects developers in their daily work.\n\nThis presentation will show how to eliminate these delays by caching build and runtime artifacts such as Docker images, NPM packages, Go modules, and even Git clones and fetches.\n\nSince most artifact repositories deliver dependencies over HTTP, a reverse caching proxy like Varnish can dramatically accelerate artifact delivery at scale.\n\nWe’ll break down the actual HTTP requests behind docker pull, git clone, go get, and npm install, and demonstrate how Varnish can be configured to cache these assets effectively, without compromising access control or security.\n\nWe’ll also compare the power of an HTTP reverse caching proxy like Varnish to other optimization strategies such as disk caching & shallow fetches.","starts_at":"2026-09-25T16:10:00-07:00","ends_at":"2026-09-25T16:40:00-07:00","stage":"Stage 4","track":"DevOps & Platform Engineering","type":"DevOps & Platform Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Thijs Feryn - Technical Evangelist at Varnish Software"],"tags":["Caching","CI/CD","Containers","DevOps","Docker","GitHub Actions","Go","NPM","Varnish","Web Performance"],"live_url":"https://www.youtube.com/watch?v=0ZHzCH52btA","recording_url":"https://www.youtube.com/watch?v=0ZHzCH52btA","app_url":"https://app.wearedevelopers.com/events/18/session/1364","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1750-speed-up-your-ci-cd","urls":["https://www.youtube.com/watch?v=0ZHzCH52btA"],"flag":null},{"id":1366,"title":"Beyond SQL Generation: How to Teach Agents What Your Database Actually Means","description":"Coding agents like Claude struggle to get meaningful information from databases. Even though they're good at writing correct SQL, they fall short where it matters - fetching the right answers. When asked a complex question, they consistently fumble their way through the schema catalogs and table descriptions, and then make best-guesses about how to join them, hoping to find some data that looks reasonable.\n\nThe reason for this is simple - they don't know your domain. It's like hiring an expert in database syntax and expecting them to know how your company works. The solution is equally simple - teach the agent what the data means. Give them a guide to how your database is laid out, how its joined, what column names mean and what kind of queries make sense. All the folk knowledge that that expert hire would eventually acquire in their first 6 months.\n\nThe technique for teaching agents the meaning of a schema is called a semantic model, there's an open standard that's easy to stick to, and the results are pretty terrific. A single file can take an agent from burning tokens to hallucinate an answer, to one-shotting the correct results.\n\nIn this talk we'll go through the details of semantic models and the standard, why it's worth using the standard rather than rolling your own, and techniques for creating effective semantic models quickly. All in the service of a simple outcome - making a scalable database analyst that's effective from day one.","starts_at":"2026-09-25T16:10:00-07:00","ends_at":"2026-09-25T16:40:00-07:00","stage":"Stage 2","track":"Data & Databases","type":"Data & Databases","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Kris Jenkins at Host / Developer Voices"],"tags":["AI Coding Assistants","Databases"],"live_url":"https://www.youtube.com/watch?v=hkb6QbgciDI","recording_url":"https://www.youtube.com/watch?v=hkb6QbgciDI","app_url":"https://app.wearedevelopers.com/events/18/session/1366","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1404-beyond-sql","urls":["https://www.youtube.com/watch?v=hkb6QbgciDI"],"flag":null},{"id":1367,"title":"Loop Engineering in the Wild: A Live Multi-Agent Coding Session","description":"What happens when multiple coding agents work on the same codebase at the same time? Vlad Luzin, CTO of BAND, will run a real multi-agent coding session, with multiple coding agents (Claude Code, Codex, and others) working collaborating to complete one shared engineering task. \n\nThe session will demonstrate how Jam from BAND acts as a collaboration layer across otherwise isolated agent sessions, allowing developers and agents to work together with shared context. \n\nOn stage, we'll bring in different coding agents from different team members and watch them coordinate on one shared task: splitting up work, handing off context, flagging blockers, looping in a QA agent to check a piece of the work adversarially. This is loop engineering in practice: the patterns for keeping a team of agents, and the humans behind them, working from the same picture instead of a pile of disconnected sessions.","starts_at":"2026-09-25T16:10:00-07:00","ends_at":"2026-09-25T16:40:00-07:00","stage":"Stage 7","track":"AI Engineering","type":"AI Engineering","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Vlad Luzin - CTO & Co-Founder at BAND"],"tags":["AI Models","Agents","Agentic AI","Code Generation","Code Reviews","Collaboration","Communication","Data Mesh","Elixir","Infrastructure","Innovation","Observability","Project Management"],"live_url":"https://www.youtube.com/watch?v=xI4D_DbWx2M","recording_url":"https://www.youtube.com/watch?v=xI4D_DbWx2M","app_url":"https://app.wearedevelopers.com/events/18/session/1367","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1743-loop-engineering-in","urls":["https://www.youtube.com/watch?v=xI4D_DbWx2M"],"flag":null},{"id":1405,"title":"ZTA: Zero Token Architecture","description":"Infer once; run everywhere.\n\nWhile burning tokens is being celebrated as a sign of productivity, it’s irresponsible to ignore the fundamentals around efficiency, and pragmatic engineering.\n\nThis talk aims to bring us back to reality.","starts_at":"2026-09-25T16:10:00-07:00","ends_at":"2026-09-25T16:40:00-07:00","stage":"Mainstage","track":"Applied AI","type":"Applied AI","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Kelsey Hightower at Minimalist"],"tags":["AI Coding Assistants","Agents","Agentic AI","DevOps"],"live_url":"https://www.youtube.com/watch?v=WtPoI8jrBLs","recording_url":"https://www.youtube.com/watch?v=WtPoI8jrBLs","app_url":"https://app.wearedevelopers.com/events/18/session/1405","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1956-zta-zero-token","urls":["https://www.youtube.com/watch?v=WtPoI8jrBLs"],"flag":null},{"id":1368,"title":"Silent Execution: Defending Against Install-Time Supply Chain Attacks","description":"While we often focus on securing the React Native bridge or runtime data, the most immediate threat to your project might execute before you even hit \"build.\" In early 2026, the \"Glassworm\" attacks proved that a developer’s environment can be compromised in seconds through malicious npm lifecycle scripts that exfiltrate credentials during a standard installation. This 15-minute technical deep dive breaks down the mechanics of install-time malware, analyzes why standard audit tools often miss these exploits, and provides a concrete roadmap for hardening your local environment and CI/CD pipelines using script-blocking strategies and behavioral monitoring.","starts_at":"2026-09-25T16:15:00-07:00","ends_at":"2026-09-25T16:25:00-07:00","stage":"Outdoor Stage","track":"Security & Privacy","type":"Security & Privacy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Chris DeMars - Senior Developer Advocate at TuxCare"],"tags":["JavaScript","React Native","Security"],"live_url":"https://www.youtube.com/watch?v=jScgajhsXrg","recording_url":"https://www.youtube.com/watch?v=jScgajhsXrg","app_url":"https://app.wearedevelopers.com/events/18/session/1368","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions","urls":["https://www.youtube.com/watch?v=jScgajhsXrg"],"flag":null},{"id":1369,"title":"12 Names for the Same Thing: Why Developer Experience Can't Grow Without a Common Language","description":"Developer Experience, Developer Productivity, Platform Engineering, Engineering Thrive, Enablement, Developer Tools, Engineering Solutions, Productivity & Happiness - 12 different names across 17 top tech companies for what is essentially the same discipline.\n\nThis fragmentation isn't just confusing - it's actively slowing down DX as a field. When Google calls it \"Engineering Productivity,\" Microsoft calls it \"Engineering Thrive,\" and LinkedIn calls it \"Productivity & Happiness,\" developers can't find each other's work, share practices, or even recognize they're solving the same problems.\n\nIn this lightning talk, I'll show:\n- The naming landscape: 12 titles for one function (data from GetDX research across Google, Microsoft, Spotify, Uber, Stripe, and others)\n- Why this matters: fragmentation prevents knowledge sharing and makes DX invisible as a career path\n- The DX vs Productivity divide: \"experience\" is the developer's word, \"productivity\" is the manager's word - and this difference shapes what gets measured and what gets fixed\n- A case for convergence: DX needs a brand as recognizable as DevOps or UX","starts_at":"2026-09-25T16:30:00-07:00","ends_at":"2026-09-25T16:40:00-07:00","stage":"Outdoor Stage","track":"DevEx & Productivity","type":"DevEx & Productivity","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Artem Mukhin - Software Engineer at Microsoft"],"tags":["Best Practices","Developer Experience (DevEx)","Productivity"],"live_url":"https://www.youtube.com/watch?v=oJsoIiMfyLM","recording_url":"https://www.youtube.com/watch?v=oJsoIiMfyLM","app_url":"https://app.wearedevelopers.com/events/18/session/1369","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1764-12-names-for-the","urls":["https://www.youtube.com/watch?v=oJsoIiMfyLM"],"flag":null},{"id":1297,"title":"You Can’t Re-Run Sunlight: Designing ML Data Architectures for Physical AI","description":"Large language models are transforming how we build software, but physical AI systems expose a hard limit: you cannot recompute reality.\nWhen robots, sensors, and production systems interact with the real world, failures are causal and time-based, not semantic. You cannot go back to record sunlight you missed, human behavior you never captured, or robot telemetry lost to fragile connectivity. Backfills rewrite history. Late data arrives with new stories. Model performance drifts without obvious errors.\nIn this talk, I will show how these constraints fundamentally change how we design ML data platforms for robotics, agriculture, manufacturing, and other physical-world domains. Using real production workflows, I will walk through how engineers correlate time-aligned telemetry, inference metadata, and operational events to debug subtle drift and root causes that dashboards and LLM-based tooling often miss.\nWe will cover concrete architectural patterns for capturing irreversible data reliably at the edge, building reproducible ML pipelines when recomputation is impossible, managing late and out-of-order data without rewriting history, and unifying analytics, training, and debugging on a shared data backbone.\nI will close with where LLMs do fit powerfully in this workflow, and why physical AI still needs fast, reliable analytics as its foundation.","starts_at":"2026-09-25T16:50:00-07:00","ends_at":"2026-09-25T17:20:00-07:00","stage":"Stage 7","track":"Physical AI","type":"Physical AI","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["An Phan - Sr. Data Infrastructure Engineer at Hippo Harvest"],"tags":["Data","Data Lakes","Data Pipelines"],"live_url":"https://www.youtube.com/watch?v=hbL5QFu5YTg","recording_url":"https://www.youtube.com/watch?v=hbL5QFu5YTg","app_url":"https://app.wearedevelopers.com/events/18/session/1297","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1677-you-can-t-re-run","urls":["https://www.youtube.com/watch?v=hbL5QFu5YTg"],"flag":null},{"id":1370,"title":"Keynote by Angie Jones (VP, Agentic AI Foundation)","description":"","starts_at":"2026-09-25T16:50:00-07:00","ends_at":"2026-09-25T17:20:00-07:00","stage":"Mainstage","track":"","type":"Session","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Angie Jones - VP Developer Experience at Agentic AI Foundation"],"tags":[],"live_url":"https://www.youtube.com/watch?v=A66mmdgAYLk","recording_url":"https://www.youtube.com/watch?v=A66mmdgAYLk","app_url":"https://app.wearedevelopers.com/events/18/session/1370","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions","urls":["https://www.youtube.com/watch?v=A66mmdgAYLk"],"flag":null},{"id":1371,"title":"Running Operations Without Humans in the Loop","description":"Agents are moving into operations: triaging incidents, rolling back deploys, patching systems - work that used to page a human. Handing production to machines raises the stakes: they act faster than people can review, and they need far better runtime signals than dashboards built for human eyes. What it takes to let agents operate production safely, and where a human still has to stay in the loop.","starts_at":"2026-09-25T16:50:00-07:00","ends_at":"2026-09-25T17:20:00-07:00","stage":"Tech Leaders Stage","track":"Leadership & Strategy","type":"Leadership & Strategy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Edward Aryee - Co-Founder & CTO at Laminar","Ryan Ries - Chief AI & Data Scientist at Mission Cloud","Yaron Schneider - CTO & Co-Founder at Diagrid","Chris Hallenbeck - SVP and General Manager of AI & Platform at Boomi"],"tags":[],"live_url":"https://www.youtube.com/watch?v=6Ug8OGYnZyQ","recording_url":"https://www.youtube.com/watch?v=6Ug8OGYnZyQ","app_url":"https://app.wearedevelopers.com/events/18/session/1371","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1880-running-operations","urls":["https://www.youtube.com/watch?v=6Ug8OGYnZyQ"],"flag":null},{"id":1372,"title":"Honey, look! I vibe-coded an OS!","description":"Since December 2025, I've built Mazarin, an open-source microkernel OS written in Go with reasonable Linux emulation and a new UI paradigm. 940 commits over 5 months. Zero lines of code written by me. (The title overstates it slightly—but it is a difference only in degree.)\n\nThis talk isn't really about Mazarin. It's about how it got built and what that means for you.\n\nThree points:\n\n1. Vibe-coding is a disaster. Human-directed AI coding is a superpower.\n\nThe difference is experience. 30 years of it, in my case—enough to make every architectural and strategic decision myself, then farm out the implementation and cross-check the result. I'll walk through specific strategic calls I made and why.\n\n2. The further you get from the code, the more process matters.\n\nHard problems—virtual memory, for instance—have to be decomposed into chunks the AI can actually handle. Don't expect architectural insight from the tool; treat it as a bonus when it happens. And because you're moving so fast, you need rigorous internal documentation so both you and the AI can remember past decisions and their rationale. I'll demonstrate by live-fixing a bug in Mazarin on stage with my process.\n\n3. Get on the train or get run over.\n\nPre-AI, Mazarin would have been a 2–3 person, multi-year project. I'm a solo engineer and I have a day job! The force multiplier for senior engineers is going to have profound consequences for junior ones—and a real bottleneck is coming in how we train the next generation of seniors. I'll share job market data, productivity measurements, and my own take. I can't predict the future, but I can tell you what I'm seeing.","starts_at":"2026-09-25T16:50:00-07:00","ends_at":"2026-09-25T17:20:00-07:00","stage":"Stage 1","track":"Applied AI","type":"Applied AI","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ian Smith - CTO at LYOS"],"tags":["AI Coding Assistants","Low Code/No Code","Productivity","Software Architecture","Vibe Coding"],"live_url":"https://www.youtube.com/watch?v=PNlLlFjsFtg","recording_url":"https://www.youtube.com/watch?v=PNlLlFjsFtg","app_url":"https://app.wearedevelopers.com/events/18/session/1372","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1706-honey-look-i-vibe","urls":["https://www.youtube.com/watch?v=PNlLlFjsFtg"],"flag":null},{"id":1373,"title":"The Productivity Illusion: What AI Really Changed for Developers","description":"Everyone says AI made developers faster. But did it really? This session dives into the hidden layers of AI-assisted development: How it affects focus, flow, and trust. Drawing from real-world experience building AI tools and observing developer behavior, We'll reveal what we gained, what we lost, and what we must redesign to make productivity human again.","starts_at":"2026-09-25T16:50:00-07:00","ends_at":"2026-09-25T17:20:00-07:00","stage":"Stage 2","track":"DevEx & Productivity","type":"DevEx & Productivity","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Fatih Kadir Akın - Developer Relations at WordPress/Automattic"],"tags":["Advocacy","Agentic AI","Copilot","Developer Experience (DevEx)","DevRel & Advocacy"],"live_url":"https://www.youtube.com/watch?v=_LyUkq4HCuo","recording_url":"https://www.youtube.com/watch?v=_LyUkq4HCuo","app_url":"https://app.wearedevelopers.com/events/18/session/1373","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1436-the-productivity","urls":["https://www.youtube.com/watch?v=_LyUkq4HCuo"],"flag":null},{"id":1374,"title":"Your Evals Passed. Your Agent Just Emptied a Database.","description":"Green CI. Clean eval suite. Staged rollout looked fine.\n\nThen your agent hit an edge case at 2am, chained three tool calls \nnobody anticipated, and did something irreversible. Your evals \ndidn't catch it. They couldn't. They were never designed to.\n\nThis is the talk the agent ecosystem needs to have right now — \nbecause we've spent two years obsessing over eval quality and \nalmost zero time on what happens *after* the agent is deployed \nand acting in the world.\n\n**Evals are a pre-flight checklist. Your agent is already in the air.**\n\nI'll show you exactly where the gap lives — and how to close it \nwith a runtime verification layer you can bolt onto any agent \nstack this week:\n\n- **Why the gap is structural, not a skill issue.** Evals test \n  known distributions. Agents encounter unknown ones. No eval \n  suite survives contact with real users at scale.\n\n- **The failure taxonomy nobody publishes.** Tool call hallucination \n  under load, trust decay in multi-step chains, silent state \n  corruption between agent hops — with real examples from \n  production systems.\n\n- **Runtime verification without the rewrite.** How to instrument \n  your execution graph with lightweight trust checkpoints — \n  behavioral tripwires that fire *during* execution, not in \n  your test suite.\n\n- **Halt, retry, or escalate?** A decision framework for real-time \n  agent health that doesn't tank your latency or annoy your users.\n\nYou'll leave with a concrete verification architecture, a failure \ntaxonomy you can use in your next incident retro, and serious \nsecond thoughts about that agentic pipeline you're about to ship.","starts_at":"2026-09-25T16:50:00-07:00","ends_at":"2026-09-25T17:20:00-07:00","stage":"Stage 3","track":"Data & Databases","type":"Data & Databases","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Tejas Pravinbhai Patel - Sr. Software Development Engineer at Amazon"],"tags":["Agents","Large Language Models (LLMs)","LLMOps","Testing"],"live_url":"https://www.youtube.com/watch?v=PO2b0nrDJIs","recording_url":"https://www.youtube.com/watch?v=PO2b0nrDJIs","app_url":"https://app.wearedevelopers.com/events/18/session/1374","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1684-your-evals-passed","urls":["https://www.youtube.com/watch?v=PO2b0nrDJIs"],"flag":null},{"id":1375,"title":"Engineering Moneyball: How We Benchmarked Google vs Meta","description":"A customer told me he feels like Billy Beane. He can see his team's good. He can't get a number to say it. Beane's 2002 A's ran $40M against the Yankees' $126M, stopped measuring what everyone else did, and finished 103-59, one loss behind New York.\n\nAsk an engineering org how it measures delivery: velocity, story points, commits, and a leader who used to ship and trusts his gut. That's the eye test. I ran on it for 15 years as a CTO. Velocity runs on self-estimates, and AI broke the estimate. Ship in an afternoon what took three days, and the number was fiction before the sprint.\n\nRoadmap delivery is harder to measure than commits, which is why people count commits.\n\nThe method. Each merged commit is scored for the depth of work it represents: how it classifies, how much of the codebase it reaches, where it sits in the architecture, whether it fixes someone else's defect. The sum is one unit, Engineering Throughput Value, scored as a senior engineer would. Work splits into growth, maintenance, and fixes; each commit ties to a Jira or Linear item, so \"on the roadmap\" is a link, not an opinion, and spend is divided by throughput.\n\nOne customer team: 80% faster year over year, $25k a month in tooling, about $200 per ETV, roadmap delivery 36% faster, and 40% of the work mapped to the roadmap. Our published healthy line is 75%.\n\nThen the failure modes. Where classification stands in for structural analysis. What a rewritten history, squash policy, or monorepo layout does to the score without touching the work. Everything a commit can't see, starting with non-coding overhead. And the case that never makes a marketing page: high token burn, flat roadmap delivery.\n\nTeam-level throughput, never a ranking of individuals. Code stays on your infrastructure. No demo.\n\nCommercial interest declared, so the design and limits are public at research.navigara.com. 500.navigara.com runs the same model across Microsoft, Meta, OpenAI, Google, Vercel, and Cloudflare.","starts_at":"2026-09-25T16:50:00-07:00","ends_at":"2026-09-25T17:20:00-07:00","stage":"Stage 4","track":"Leadership & Strategy","type":"Leadership & Strategy","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Jirka Bachel - Co-Founder & CEO at Navigara"],"tags":["Agentic AI","Analytics","Code Generation","Code Reviews","DORA Metrics","Entrepreneurship","FinTech","Metrics","On-Premise","Performance","Product Management","Software Architecture","Tokenomics"],"live_url":"https://www.youtube.com/watch?v=knMlb2shz4I","recording_url":"https://www.youtube.com/watch?v=knMlb2shz4I","app_url":"https://app.wearedevelopers.com/events/18/session/1375","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1774-engineering","urls":["https://www.youtube.com/watch?v=knMlb2shz4I"],"flag":null},{"id":1376,"title":"The Things Your AI Isn't Telling You","description":"The AI revolution has accelerated software development timelines, but at what cost to security? While teams rush to integrate LLMs and other AI capabilities into their applications, security is overlooked as new attack surfaces are created in places traditional security measures weren't designed to handle.\n\nThis presentation exposes the hidden vulnerabilities in AI-powered applications through live demonstrations of common attack vectors that exploit user input channels. Attendees will perform their own attacks on their mobile devices or laptops using prompt injection to bypass traditional security controls and compromise entire systems - with nothing more than carefully crafted text or images. \n\nBy the end of this session, you'll have actionable strategies to identify vulnerabilities in your AI applications, practical tools to implement security controls without sacrificing innovation velocity, and a security mindset that treats AI components as critical infrastructure requiring specialized protection.","starts_at":"2026-09-25T16:50:00-07:00","ends_at":"2026-09-25T17:20:00-07:00","stage":"Stage 5","track":"AI Trust & Safety","type":"AI Trust & Safety","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Desmond Lamptey - Lead Software Engineer at Capital One"],"tags":["AI Standards","Security"],"live_url":"https://www.youtube.com/watch?v=YnY2Povl6uU","recording_url":"https://www.youtube.com/watch?v=YnY2Povl6uU","app_url":"https://app.wearedevelopers.com/events/18/session/1376","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1710-the-things-your-ai","urls":["https://www.youtube.com/watch?v=YnY2Povl6uU"],"flag":null},{"id":1377,"title":"Proactive AI That Doesn’t Annoy Users: Building Context-Aware Notification Systems","description":"The majority of current notification systems for AI fail, for either too much noise training users to ignore the notifications or too much conservatism missing important signals.\n\nProactive AI at scale lessons learned from designing and operating such service on real world product. Authors started with quite optimistic assumptions that more intelligence would lead to more engagement after couple of iterations (and lots of usage), they learned that first version of the product was pretty noisy and unreliable. Most importantly, after couple of iterations, they learned that the issue wasn’t actually in the model, but in how you framed the decisions.\n\nIn this talk I explain the thought process behind some design choices I made in shifting from an automatic system to a more deliberate one. In this session user preferences for things like consent and frequency limits as well as quiet hours are implemented. Then I’ll explain how the system determines if it has enough context to make a different decision. If the system doesn’t have enough information OR it has inconsistent information then the system does nothing –there is no fallback or force engage.\n\nMy talk goes through how I used multiple user signals, user behavioral preferences, real world events, and timing to make a series of decisions leading up to a decision point. The hardest part was getting others to understand that suppression was a valid outcome and NOT a failure.\n\nWe'll cover these core concepts as well as advanced topics such as how system handles duplicate events, user longitudinal data, and what we mean by engagement versus trust.\n\nThis talk is for engineers who build AI powered product features, not just demo the features to users but also to systems, to others who are engineering similar features and are trying to understand trade offs.","starts_at":"2026-09-25T16:50:00-07:00","ends_at":"2026-09-25T17:20:00-07:00","stage":"Stage 6","track":"AI Engineering","type":"AI Engineering","live_coding":true,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Raju Dandigam Dandigam - Staff Software Engineer at Navan"],"tags":["AI Standards","Agentic AI","Edge AI"],"live_url":"https://www.youtube.com/watch?v=xRcaF4tY9eQ","recording_url":"https://www.youtube.com/watch?v=xRcaF4tY9eQ","app_url":"https://app.wearedevelopers.com/events/18/session/1377","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1672-proactive-ai-that","urls":["https://www.youtube.com/watch?v=xRcaF4tY9eQ"],"flag":null},{"id":1379,"title":"Beyond the Code: Human-AI Synergies in Product Development","description":"Artificial Intelligence is rapidly reshaping how digital products are conceived, designed, and delivered. Yet the most transformative innovation is not driven by AI alone, it emerges from the effective orchestration of human expertise and machine intelligence.\n\nDrawing on product leadership experience across global technology organizations including Google, DocuSign, and Coinbase, this session explores how leading companies are integrating AI into product development workflows to accelerate innovation while preserving human judgment, creativity, and strategic decision-making.\n\nAttendees will learn how AI is transforming engineering, product management, research, and operational processes; where human leadership remains indispensable; and how organizations can build scalable systems that maximize the strengths of both people and AI. The talk will also examine the emerging paradigm of human-AI collaboration, where AI automates routine and data-intensive tasks, enabling teams to focus on customer understanding, product strategy, cross-functional alignment, and high-impact decisions.\n\nKey Takeaways\n\nUnderstand how AI is reshaping the product development lifecycle, from ideation to launch.\n\nLearn practical frameworks for integrating AI into product, engineering, and operational workflows.\nIdentify which product development activities are best suited for AI augmentation versus human leadership.\n\nDiscover how leading technology organizations are balancing automation with creativity, judgment, and accountability.\n\nExplore strategies for building high-performing teams that leverage AI to increase speed, quality, and innovation.\n\nGain insights into the future of product leadership in an increasingly AI-enabled world.","starts_at":"2026-09-25T16:50:00-07:00","ends_at":"2026-09-25T17:20:00-07:00","stage":"Outdoor Stage","track":"AI Engineering","type":"AI Engineering","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Ajita Kanchivakam Ananth - Staff Technical Program Manager at Google"],"tags":["Generative AI (GenAI)","Product Management"],"live_url":"https://www.youtube.com/watch?v=70X2H2caQU0","recording_url":"https://www.youtube.com/watch?v=70X2H2caQU0","app_url":"https://app.wearedevelopers.com/events/18/session/1379","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1734-beyond-the-code","urls":["https://www.youtube.com/watch?v=70X2H2caQU0"],"flag":null},{"id":1407,"title":"2026 in LLMs (so far)","description":"2026 has been a wild year for LLMs. The OpenClaw craze kicked things off in January, then we had tokenmaxxing, then the death of tokenmaxxing, US export controls on frontier models, open weight models that compete with that frontier, accidental cyberattacks by the labs’ own models, and a technically credible intervention by the Pope.\n\nAnd the year’s not over yet! Join Simon for a review of everything 2026 has thrown at us so far, what it all means, and how it might shape what you’re building next.","starts_at":"2026-09-25T17:30:00-07:00","ends_at":"2026-09-25T18:00:00-07:00","stage":"Mainstage","track":"","type":"Session","live_coding":false,"is_workshop":false,"capacity":null,"waitlist":null,"requirements":"","speakers":["Simon Willison - Creator & Co-creator at Datasette /Django"],"tags":["AI Models","Anthropic","OpenShift","Small Language Models (SLMs)"],"live_url":"https://www.youtube.com/watch?v=GAkIytR7vcc","recording_url":"https://www.youtube.com/watch?v=GAkIytR7vcc","app_url":"https://app.wearedevelopers.com/events/18/session/1407","official_url":"https://www.wearedevelopers.com/events/world-congress-2026-north-america/sessions/1957-2026-in-llms-so-far","urls":["https://www.youtube.com/watch?v=GAkIytR7vcc"],"flag":null}];
